      case PlusSortedSequence(left, _, _)::_ if left < addLeft ⇒
        val (count, next) = increaseWhile(prev, addLeft)
        addPlus(addLeft, next).let{case (c, n) ⇒ (c + count, n)}
      case _ ⇒ addPlus(addLeft.multiple, prev).let{case (c, n) ⇒ (c + 1, n)}
    }
