      case MinusSortedSequence(l, right, length)::MinusSortedSequence(left, r, len)::t if l.copy(exponent = l.exponent + 4) > r ⇒ MinusSortedSequence(left, right.copy(exponent = right.exponent + 2), length + len)::t
      case MinusSortedSequence(left, right, length)::t ⇒  MinusSortedSequence(left.copy(exponent = left.exponent + 2), right.copy(exponent = right.exponent + 2), length)::t
      case Nil ⇒ Nil
    }
  }
  case class PlusSortedSequence(left: NumberWithExponent, right: NumberWithExponent, length: Int)
  case class MinusSortedSequence(left: NumberWithExponent, right: NumberWithExponent, length: Int)
  case class NumberWithExponent(value: Long, exponent: Int) extends Ordered[NumberWithExponent] {
    override def compare(that: NumberWithExponent): Int = if (this.sign.compare(that.sign) != 0) this.sign.compare(that.sign) else if (this.sign > 0) toLog.compare(that.toLog) else that.toLog.compare(this.toLog)
    private val sign: Int = math.signum(value).toInt * (if (exponent % 2 == 1) -1:Int else 1: Int)
    private val toLog: Double = math.log(math.abs(value)) + math.log(2) * exponent
    def multiple: NumberWithExponent = NumberWithExponent(value, exponent + 1)
  }
  implicit class Extension[T](val value :T){
    def also(func: T ⇒ Unit): T = {
      func(value)
      value
    }
    def let[R](func: T ⇒ R): R = func(value)
