//A[i+1]を何回4倍したらA[i]以上になりますか。
//

int main(void){
	int n;
	cin>>n;
	ll a;
	vector<ll> A;
	rep(i,n){
		cin>>a;
		A.push_back(a);
	}
	//A.push_back(LINF);
	vector<vector<ll>> dp,dp2;
	//init
	rep(i,n){
		dp.push_back(vector<ll>());
		dp2.push_back(vector<ll>());
	}
	rep(i,15){
		dp[n-1].push_back(i);
		dp2[0].push_back(i);
	}
	REP(i,n-1){
		ll count = 0;
		ll a = A[i+1];
		while(a < A[i]){
			count++;
			a *= 4;
		}
		if(count == 0){
			a = A[i];
			while(a < A[i+1]){
				count--;
				a *= 4;
			}
		}
		rep(j,15){
			if(j + count < 0){
				dp[i].push_back(dp[i+1][0]);
			}
			else if(j + count < 15){
				dp[i].push_back(dp[i+1][j+count] + j);
			}else{
				dp[i].push_back(dp[i][j-1] * 2);
			}
		}
	}

	reps(i,n-1){
		ll count = 0;
		ll a = A[i-1];
		while(a < A[i]){
			count++;
			a *= 4;
		}
		if(count == 0){
			a = A[i];
			while(a < A[i-1]){
				count--;
				a *= 4;
			}
		}
		rep(j,15){
			if(j + count < 0){
				dp2[i].push_back(dp[i-1][0]);
			}
			else if(j + count < 15){
				dp2[i].push_back(dp[i-1][j+count] + j);
			}else{
				dp2[i].push_back(dp[i][j-1] * 2);
			}
		}
	}
	//cout<<"hoge"<<endl;

	ll ans = LINF;
	reps(i,n-1){
		ll memo = dp[i][0]*2 + dp2[i-1][0]*2 + (i-1+1);
		chmin(ans, memo);
	}
	//cout<<"hoge2"<<endl;
	chmin(ans, dp[0][0]*2);
	chmin(ans, dp2[n-1][0]*2 + n);
	cout<<ans<<endl;
	return 0;
}

