        v += 2;
      }
      if (f[j] < 29) {
        f[j] += v;
        pref += v;
      } else {
        pref += (long long)v * (j + 1);
        break;
      }
    }
    ans = min(ans, pref + suff[i + 1]);
  }
  printf("%lld\n", ans);
}

