            }
            node.cnt += overr[node.r];
            auto top = sta.back(); sta.pop_back();
            R[i] += node.cnt*(top.r-top.l)*2;
            node.r = top.r;
        }
    }

    ll ans = 1e18;
    rep(i,N+1) {
        chmin(ans,L[i]+R[i]);
    }

    cout << ans << ln;
}

