	int node[200006]; int N = 200002;
	void init() {
		fill(node, node + N+1, 0);
	}
	void add(int i, int x) {
		while (i <= N) {
			node[i] += x; i += i & -i;
		}
	}
	int sum(int x) {
		int s = 0;
		while (x > 0) {
			s += node[x]; x -= x & -x;
		}
		return s;
	}
};

int a[200006];
BIT b1;
int n; 

vector<int> solve() {
	b1.init();
	vector<int>ans(n);
	for (int i = n - 1; i > 0; i--) {
		b1.add(i, num(a[i - 1], a[i]));
		ans[i - 1] += ans[i];
		int k = num(a[i], a[i - 1]);
		while (k) {
			k--;
			int lb = i, ub = n+1;//ここだけ1-indexed!!
			if (b1.sum(200001)) {
				while (ub - lb > 1) {
					int mi = (ub + lb) / 2;
					if (b1.sum(mi))ub = mi;
					else lb = mi;
				}
				b1.add(ub, -1);
				ans[i - 1] += n - lb;
			}
			else {
				ans[i - 1] += n - i;
			}
		}
	}
	return ans;
}
