  }

  vector<vector<int>> dp(n, vector<int>(16));
  for (int i = 0; i < 16; i++) {
    dp[n - 1][i] = i;
  }

  for (int i = n - 2; i >= 0; i--) {
    int j1 = 0;
    int j2 = 0;
    long long c1 = a[i];
    long long c2 = a[i + 1];
    while (c1 <= c2 && j1 < 16) {
      dp[i][j1] = dp[i + 1][0] + j1;
      c1 *= 4;
      j1++;
    }

    while (j2 < 16 && c2 < c1) {
      c2 *= 4;
      j2++;
    }

    while (j1 < 16) {
      if (j2 > 15) {
        dp[i][j1] = dp[i + 1][15] + j2 * (n - 1 - i) + j1;
      }
      else {
        dp[i][j1] = dp[i + 1][j2] + j1;
      }
      j1++;
      j2++;
    }
  }
  int ans = 2 * dp[0][0];
  for (int i = 0; i < n; i++) {
    if (i == n - 1) {
      ans = min(n, ans);
    }
    else {
      if (a[i] < a[i + 1]) break;
      int steps = i + 1 + 2 * dp[i + 1][0];
      ans = min(steps, ans);
