  for(int i=n-2;i>=0;i--){
    for(int j=0;j<20;j++){
      int a=j-w[i];
      if(a<0)a=0;
      int r=a-19;if(r<0)r=0;
      dpf[i][j]=j+dpf[i+1][min(a,19LL)]+r*(n-i-1);
    }
  }
  reverse(v.begin(),v.end());
  vector<int> w2(n,0);//w[i]:v[i]とv[i+1]がギリギリ昇順になるためにv[i]に何回4をかけるか
  for(int i=0;i<n-1;i++){
    if(v[i]<v[i+1]){
      int tmp=v[i];
      while(tmp<=v[i+1])tmp*=4,w2[i]++;
      w2[i]--;
    }
    else{
      int tmp=v[i+1];
      while(v[i]>tmp)tmp*=4,w2[i]--;
    }
  }
  for(int j=0;j<20;j++)dpg[n-1][j]=j;
  for(int i=n-2;i>=0;i--){
    for(int j=0;j<20;j++){
      int a=j-w2[i];
      if(a<0)a=0;
      int r=a-19;if(r<0)r=0;
      dpg[i][j]=j+dpg[i+1][min(a,19LL)]+r*(n-i-1);
    }
  }
  int ans=LINF;
  for(int i=0;i<=n;i++){
    int a=dpf[i][0]*2;
    int b=dpg[n-i][0]*2;b+=i;
    //cout<<a<<" "<<b<<endl;
    chmin(ans,a+b);
  }
  cout<<ans<<endl;
}

