int dp[N][M][2],n,aa[N];
int rec(int idx,int mp,int si){
    if(mp>M-1)return oo;
    int &ret=dp[idx][mp][si];
    if(ret!=-1)return ret;
    if(idx==n)return ret=0;
    if(si==0){
        ll ad=aa[idx],oth=aa[idx-1]*(1LL<<mp);
        int p=0;
        while(p<M&&ad<oth&&OO/4>=ad)ad*=4,p+=2;
        if(p>=M||ad<oth)return ret=oo;
        ret=rec(idx+1,p,0)+p;
    }else{
        ret=rec(idx+1,0,0);
        ll ad=-aa[idx]*2,oth=-aa[idx-1]*(1LL<<mp);
        int p=1;
        while(p<M&&ad>=oth&&OO/4>=ad){
            ret=min(ret,rec(idx+1,p,1)+p);
            p+=2;
            ad*=4;
        }
    }
    return ret;
}
