    vint a(N + 1);
    {
        stack<pint> st;
        st.push({LLONG_MAX, 0});
        reps(i, N - 1) {
            int v = 0;
            while (A[i] > A[i - 1] << (v << 1)) { v++; }
            while (v <= 0 && A[i] << ((-v + 1) << 1) <= A[i - 1]) { v--; }
            a[i + 1] = a[i];
            int cur = i;
            while (v > 0) {
                if (v >= st.top().first) {
                    a[i + 1] += (cur - st.top().second) * v, cur = st.top().second, v -= st.top().first, st.pop();
                } else {
                    a[i + 1] += (cur - st.top().second) * v, cur = st.top().second, st.top().first -= v, v = 0;
                }
            }
            if (v < 0) { st.push({-v, i}); }
        }
    }
    reverse(A, A + N);

    int ans = min(a[N], a[N - 1] + 1);
    vint b;
    {
        stack<pint> st;
