inline bool change(int i,int j)
{
	if(a[i]<=a[j]) return 0;

	int ti=a[i],tj=a[j],cnt0=0,cnt1=0;
	while(ti>tj) ti*=-2,cnt0++;

	ti=a[i];tj=a[j];
	while(ti>tj) tj*=-2,cnt1++;

	if(cnt0<cnt1) while(a[i]>a[j]) a[i]*=-2,ans++; else while(a[i]>a[j]) a[j]*=-2,ans++;

	return 1;
}

int main()
{
	SF("%d",&n);
	rep(i,n) SF("%lld",&a[i]);

	rep(i,n-1) if(change(i,i+1))
	{
		repd(j,i) if(change(j,j+1)); else break;
	}

	PF("%d",ans);

	return 0;
}
