ll dp[MAX_N][32];

int solve()
{
    mult[0] = 1;
    for (int i = 1; i < 32; ++i)
    {
        mult[i] = mult[i - 1] * (-2ll);
    }
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i];
    }
    for (int i = 0; i < 32; ++i)
    {
        dp[1][i] = i;
    }
    for (int i = 2; i <= n; ++i)
    {
        for (int j = 0; j < 32; ++j)
        {
            dp[i][j] = INF;
            for (int x = 0; x < 32; ++x)
            {
                if (a[i - 1] * mult[x] <= a[i] * mult[j])
                {
                    dp[i][j] = min(dp[i][j], dp[i - 1][x] + j);
                }
            }
        }
    }
    ll ans = INF;
    for (int j = 0; j < 32; ++j)
    {
        ans = min(ans, dp[n][j]);
    }
    cout << ans << endl;
    return 0;
}

