int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    int N; cin >> N;
    vector<ll> A(N),B(N),C(N);
    for (int i=0;i<N;++i) cin >> A[i],B[i]=C[i]=A[i];
    vector<ll> left(N+1,0),right(N+1,0);
    left[1]=1;
    vector<pair<int,ll>> margin;
    for (int i=1;i<N;++i){
        ll cnt=0,m=0;
        if (B[i-1]<B[i]) while (B[i-1]<B[i]) B[i-1]<<=2LL,cnt+=2;
        else while (((B[i]<<m)<<2LL)<=B[i-1]) m+=2;
        left[i+1]=left[i]+1;
        int last=i;
        while (cnt&&margin.size()){
            left[i+1]+=cnt*(last-margin.back().first);
            last=margin.back().first;
            if (cnt<margin.back().second) cnt=0,margin.back().second-=cnt;
            else cnt-=margin.back().second,margin.pop_back();
        }
        left[i+1]+=cnt*last;
        if (m) margin.emplace_back(i,m);
    }
    margin.clear();
    for (int i=N-2;i>=0;--i){
        ll cnt=0,m=0;
        if (C[i+1]<C[i]) while (C[i+1]<C[i]) C[i+1]<<=2LL,cnt+=2;
        else while (((C[i+1]<<m)<<2LL)<=C[i]) m+=2;
        right[i]=right[i+1];
        int last=i;
        while (cnt&&margin.size()){
            right[i]+=cnt*(margin.back().first-last);
            last=margin.back().first;
            if (cnt<margin.back().second) cnt=0,margin.back().second-=cnt;
            else cnt-=margin.back().second,margin.pop_back();
        }
        right[i]+=cnt*(N-1-last);
        if (m) margin.emplace_back(i,m);
    }
    ll ans=INF;
    for (int i=0;i<N+1;++i) ans=min(ans,left[i]+right[i]);
    cout << ans << '\n';
}

