void calc(vector<double>& lg, vector<ll>& so, int n) {
	vector<pll> po;

	ll cou = 0;
	double cur = lg[n - 1];

	for (int i = n - 1; 0 <= i; i--) {
		double nex = lg[i];

		if (nex > cur) {
			int sa = ceil((nex - cur) / 2) * 2;

			int cpos = i;
			for (auto itr = po.rbegin(); itr != po.rend(); ++itr) {
				if (itr->second == 0) continue;
				if (itr->second >= sa) {
					itr->second -= sa;
					cou += (itr->first - cpos)*sa;
					sa = 0;
					break;
				}
				else {
					cou += (itr->first - cpos)*itr->second;
					sa -= itr->second;
					itr->second = 0;
				}
			}

			cou += sa * (n - 1 - cpos);
		}
		else if (cur - nex >= 2) po.push_back({ i, ((ll)((cur - nex) / 2)) * 2 });

		cur = nex;

		so[i] = cou;
	}
}

