vector<ll> f(const vector<ll>&a){
    int n = (int)a. size();
    vector<ll>res(n);
    vector<ll>yoyuu(n);
    stack<pair<ll,ll>>st;//id,num
    res[n-1] = 0;
    for(int i = n-1; i>= 1; i--){
        ll k = num(a[i-1],a[i]);
        res[i-1] = res[i] + k;
        ll t = i+1;
        while(st.size()){
            auto p = st.top();
            st.pop();
            if(p.second >= k){
                p.second-=k;
                st.push(p);
                k = 0;
                break;
            }else{
                res[i-1] += (p.first-t)*k;
                k-=p.second;
                t = p.first;
            }
        }
        res[i-1] += (n-t)*k;
        if(hoge(a[i-1],a[i]))st.emplace((ll)i,hoge(a[i-1],a[i]));
    }
    return res;
}
