    int n;
    while (cin >> n) {
        vector<int> a(n, 0);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }
        if (n == 1) {
            cout << 0 << endl;
            continue;
        }
        vector<lld> f(n + 1, 0);
        f[n] = 0LL;
        last = pool;
        root = build(0, n - 1, a, 0.L);
        for (int i = n - 1; i >= 0; --i) {
            const llf bar = log2(a[i]);
            f[i] = f[i + 1] + nond(root, i, bar).first;
            //fprintf(stderr, "f[%d] = %lld\n", i, f[i]);
        }
        vector<lld> g(n + 1, 0);
        g[0] = 0LL;
