const int maxn=2e5+10;
int b[maxn],f[maxn],g[maxn],pre[maxn],del[maxn];
ll a[maxn];
int main(){
	int n=read();
	REP(i,1,n) b[i]=read();
	REP(i,1,n) a[i]=b[i];
	pre[1]=1;
	f[1]=1;
	REP(i,2,n){
		f[i]=f[i-1]+1;
		pre[i]=i;
		if(a[i]<=a[i-1]){
			int u=(a[i-1]/a[i]);
			while(u>=4) u/=4,del[i]+=2;
		}
		else{
			int u=0;
			for(ll k=1;a[i-1]*k<a[i];k*=4,u+=2);
			while(pre[i]>1){
				f[i]+=u*(pre[i]-pre[pre[i]-1]);
				pre[i]=pre[pre[i]-1];
				del[pre[i]]-=u;
				if(del[pre[i]]>=0) break;
				u=-del[pre[i]];
			}
		}
	}
	REP(i,1,n) a[i]=b[i];
	pre[1]=1;
	DREP(i,n-1,1){
		g[i]=g[i+1];
		del[i]=0;
		pre[i]=i;
		if(a[i]<=a[i+1]){
			int u=(a[i+1]/a[i]);
			while(u>=4) u/=4,del[i]+=2;
		}
		else{
			int u=0;
			for(ll k=1;a[i+1]*k<a[i];k*=4,u+=2);
			while(pre[i]<n){
				g[i]+=u*(pre[pre[i]+1]-pre[i]);
				pre[i]=pre[pre[i]+1];
				del[pre[i]]-=u;
				if(del[pre[i]]>=0) break;
				u=-del[pre[i]];
			}
		}
	}
	int ans=1e9;
	REP(i,0,n) chkmin(ans,f[i]+g[i+1]);
	printf("%d\n",ans);
	return 0;
}

