int n;

ll a[MAX_N];

ll dp[MAX_LOG];

ll pref[2][MAX_LOG]; //even
ll suf[2][MAX_LOG]; //odd

double al[MAX_N];

int solve()
{
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i];
        al[i] = log2((double)a[i]);
        //cerr << al[i] << endl;
    }
    for (int i = 0; i < MAX_LOG; ++i)
    {
        dp[i] = i;
    }
    pref[1][0] = dp[0];
    for (int i = 1; i < MAX_LOG; ++i)
    {
        pref[1][i] = pref[1][i - 1];
        if (i % 2 == 0)
        {
            pref[1][i] = min(pref[1][i], dp[i]);
        }
    }
    suf[1][MAX_LOG - 1] = dp[MAX_LOG - 1];
    for (int i = MAX_LOG - 2; i >= 0; --i)
    {
        suf[1][i] = suf[1][i + 1];
        if (i % 2 == 1)
        {
            suf[1][i] = min(suf[1][i], dp[i]);
        }
        //cerr << i << ' ' << suf[1][i] << endl;
    }
    for (int i = 2; i <= n; ++i)
    {
        for (int k = 0; k < MAX_LOG; ++k)
        {
            pref[0][k] = pref[1][k];
            pref[1][k] = INF;
            suf[0][k] = suf[1][k];
            suf[1][k] = INF;
            dp[k] = INF;
        }
        for (int k = 0; k < MAX_LOG; ++k)
        {
            if (k % 2 == 0)
            {
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
                dp[k] = min(dp[k], suf[0][0] + k);
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
                int ind = floor(al[i] - al[i - 1] + k);
                if (ind >= 0)
                {
                    dp[k] = min(dp[k], pref[0][ind] + k);
                }
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
            }
            else
            {
                int ind = ceil(al[i] - al[i - 1] + k);
                if (ind <= n)
                {
                    dp[k] = min(dp[k], suf[0][max(0, ind)] + k);
                }
            }
        }
        pref[1][0] = dp[0];
        for (int k = 1; k < MAX_LOG; ++k)
        {
            pref[1][k] = pref[1][k - 1];
            if (k % 2 == 0)
            {
                pref[1][k] = min(pref[1][k], dp[k]);
            }
        }
        suf[1][MAX_LOG - 1] = dp[MAX_LOG - 1];
        for (int k = MAX_LOG - 2; k >= 0; --k)
        {
            suf[1][k] = suf[1][k + 1];
            if (k % 2 == 1)
            {
                suf[1][k] = min(suf[1][k], dp[k]);
            }
        }
    }
    ll ans = INF;
    for (int j = 0; j < MAX_LOG; ++j)
    {
        ans = min(ans, dp[j]);
    }
    cout << ans << endl;
    return 0;
}

