  if (i >= n)
    return 0;
  int& r = dp1[i][prv];
  if (r != -1)
    return r;
  int p = max((prv - arr[i] + 1) / 2, 0);
  return r = p + suff(i + 1, arr[i] + 2 * p);
}

int pref(int i, int prv)
{
  if (i < 0)
    return 0;
  int& r = dp2[i][prv];
  if (r != -1)
    return r;
  int p = max((prv - arr[i] + 1) / 2, 0);
  return r = p + pref(i - 1, arr[i] + 2 * p);
}

