using namespace std;

int log4(ll a, ll b) {
  assert (a <= b);
  if (a == b) {
    return 0;
  }
  int cnt = 0;
  while (true) {
    a *= 4;
    cnt += 1;
    if (a >= b) {
      return cnt;
    }
  }
  assert (false);
}

struct elm { int ind; ll num; };

int n;
vll calc(vll a) {
  vll accum(n+1, 0);
  rep (i, n) {
    accum[i+1] = accum[i] + a[i];
  }
  vll ret(n+1, 0);
  deque<elm> inc;
  inc.push_front((elm){n-1, a[n-1]});

  for (int i = n-1; i > 0; --i) {
    //ret[i-1];
    auto new_elm = (elm){i-1, a[i-1]};
    if (a[i-1] <= a[i]) {
      ret[i-1] = ret[i];
      inc.push_front(new_elm);
      continue;
    }
    int ub = upper_bound(all(inc), (elm){i-1, a[i-1]}, [](elm x, elm y) {
        return x.num < y.num;
        }) - begin(inc);;
    ll add = 0;
    rep (j, ub) {
      int kai = log4(inc[j].num, a[i-1]);
      int last_ind = n;
      if (begin(inc) + j+1 != end(inc)) {
        last_ind = inc[j+1].ind;
      }
      add += kai * (last_ind - inc[j].ind) * 2;
    }
    ret[i-1] = ret[i] + add;
    inc.erase(begin(inc), begin(inc) + ub);
    inc.push_front(new_elm);
  }
  return ret;
}

int main() {
  scan(n);
  vll a(n);
  scan(a);

  vll cnt1 = calc(a);
  auto b = a;
  reverse(all(b));
  vll cnt2 = calc(b);
  rep (i, n+1) {
    cnt2[i] = cnt2[i] + (n-i);
  }

  ll ans = LLONG_MAX;
  rep (i, n+1) {
    ans = min(ans, cnt1[i] + cnt2[n-i]);
  }
  print(ans);

  return 0;
}

