int N;
LL A[200111];

LL r_cst[200111];
LL l_cst[200111];

int cmp(LL x, LL xp, LL y, LL yp) {
    LL g = min(xp, yp);
    xp -= g;
    yp -= g;
    if (xp > 32) return 1;
    if (yp > 32) return -1;
    x <<= xp;
    y <<= yp;
    if (x > y) return 1;
    if (x == y) return 0;
    return -1;
}

struct Data {
    int len;
    LL s, sp;
    LL l, lp;
    Data(){};
    Data(int len_, LL s_, LL sp_, LL l_, LL lp_) {
	len = len_;
	s = s_;
	sp = sp_;
	l = l_;
	lp = lp_;
    }
};

void R() {
    stack<Data> st;
    st.emplace(1, A[N-1], 0, A[N-1], 0);

    for (int i=N-2; i>=0; i--) {
	LL cst = r_cst[i+1];
	Data d(1, A[i], 0, A[i], 0);

	while (!st.empty()) {
	    Data x = st.top();
	    if (cmp(d.l, d.lp, x.s, x.sp) > 0) {
		st.pop();
		int up = 2;
		while (cmp(d.l, d.lp, x.s, x.sp + up) > 0) {
		    up += 2;
		}
		cst += x.len * up;

		d = Data(d.len + x.len, d.s, d.sp, x.l, x.lp + up);
	    } else {
		break;
	    }
	}

	st.push(d);
	r_cst[i] = cst;
    }
}

void L() {
    stack<Data> st;
    st.emplace(1, A[0], 1, A[0], 1);
    l_cst[1] = 1;

    for (int i=1; i<N; i++) {
	LL cst = l_cst[i] + 1;
	Data d(1, A[i], 1, A[i], 1);
	while (!st.empty()) {
	    Data x = st.top();
	    if (cmp(d.l, d.lp, x.s, x.sp) > 0) {
		st.pop();
		int up = 2;
		while (cmp(d.l, d.lp, x.s, x.sp + up) > 0) {
		    up += 2;
		}
		cst += x.len * up;

		d = Data(d.len + x.len, d.s, d.sp, x.l, x.lp + up);
	    } else {
		break;
	    }
	}
	st.push(d);
	l_cst[i+1] = cst;
    }
}

void MAIN() {
    scanf("%d", &N);
    REP (i, N) scanf("%lld", A+i);



    R();
    L();

//    rprintf("%lld", r_cst, r_cst + N);
