using namespace std;
struct BIT
{
	int c[330001],type,n;
	BIT(int t,int sz):type(t),n(sz+20){}
	void add(int x,int d)
	{
		if(type)while(x)c[x]+=d,x-=x&-x;
		else while(x<=n)c[x]+=d,x+=x&-x;
	}
	int sum(int x)
	{
		if(x<0)return 0;
		int ans=0;
		if(type)while(x<=n)ans+=c[x],x+=x&-x;
		else while(x)ans+=c[x],x-=x&-x;
		return ans;
	}
};
