      cnt+=c;
      ahigh += cnt;
      precnt=cnt;
    }
    ahigh += midhigh;
    precnt=0;
    for(int i=midhigh;i<N-1;i++){
      ll x=1;
      ll cnt=0;
      while(A[i]>A[i+1]*x){
        x <<= 2;
        cnt += 2;
      }
      x = 1;
      ll c=0;
      while(A[i+1]>=A[i]*x){
        x <<= 2;
        c+=2;
      }
      c=max(0ll,c-2);
      c=max(0ll,precnt-c);
      cnt+=c;
      ahigh += cnt;
      precnt=cnt;
    }
    if(alow<=ahigh){
      high = midlow;
      ans = min(ans,alow);
    }else{
      low = midlow;
      ans = min(ans,ahigh);
    }
  }
  cout << ans << endl;
  return 0;
}

