				st.erase(it);
			} else {
				break;
			}
		}

		l[i] += ad;
	}

	ll ret = LLONG_MAX;

	for (int i = 0; i <= N; ++i) { //odd
		ll t = i;
		if (i > 0) {
			t = (t + l[i-1]);
		}
		if (i < N) {
			t = (t + r[i]);
		}

		ret = min(ret, t);
	}

	cout << ret << endl;

	return 0;
}

