int main() {
  int n;
  while (std::cin >> n) {
    std::vector<int64_t> a(n+2);
    std::vector<int64_t> prefix(n+2, -1), suffix(n+2, -1);
    for (int i = 1; i <= n; ++ i) std::cin >> a[i];
    prefix[0] = 0;
    if (a[1] <= 0) prefix[1] = 0;
    else prefix[1] = 1;
    for (int i = 2; i <= n; ++ i) {
      int64_t pre = a[i-1] <= 0 ? a[i-1] : a[i-1] * -2;
      int64_t cur = a[i] <= 0 ? a[i] : a[i] * -2;
      if (pre == 0 && cur < 0
          || prefix[i-1] == -1) {
        prefix[i] = -1;
        continue;
      }
      int64_t cnt = a[i] <= 0 ? 0 : 1;
      int64_t ops = 0;
      while (pre > cur) {
        ops += 2;
        pre *= 4;
      }
      prefix[i] = cnt + ops * (i-1) + prefix[i-1];
    }
    suffix[n+1] = 0;
    if (a[n] >= 0) suffix[n] = 0;
    else suffix[n] = 1;
    for (int i = n-1; i > 0; -- i) {
      int64_t suf = a[i+1] >= 0 ? a[i+1] : a[i+1] * -2;
      int64_t cur = a[i] >= 0 ? a[i] : a[i] * -2;
      if (suf == 0 && cur > 0 || suffix[i+1] == -1) {
        suffix[i] = -1;
        continue;
      }
      int64_t cnt = a[i] >= 0 ? 0 : 1;
      int64_t ops = 0;
      while (suf < cur) {
        ops += 2;
        suf *= 4;
      }
      suffix[i] = cnt + ops * (n-i) + suffix[i+1];
    }
    int64_t res = -1;
    for (int i = 0; i <= n; ++ i) {
//      std::cout << prefix[i] <<  "  " << suffix[i+1] << std::endl;
      int64_t temp = -1;
      if (prefix[i] != -1 && suffix[i+1] != -1) {
        temp = prefix[i] + suffix[i+1];
      }
      if (temp == -1) continue;
      if (res == -1) res = temp;
      else {
        res = std::min(res, temp);
      }
    }
    std::cout << res << std::endl;
  }
  return 0;
}

