int solve()
{
    mult[0] = 1;
    for (int i = 1; i < 16; ++i)
    {
        mult[i] = mult[i - 1] * 4;
    }
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i];
        al[i] = log2(a[i]);
    }
    for (int i = 0; i < 16; ++i)
    {
        dp2[n + 1][i] = 0;
        dp2[n][i] = 2 * i;
    }
    for (int i = n - 1; i >= 1; --i)
    {
        for (int k = 0; k < 16; ++k)
        {
            dp2[i][k] = INF;
            bool t = false;
            for (int j = 0; j < 16; ++j)
            {
                if (a[i] * mult[k] <= a[i + 1] * mult[j])
                {
                    dp2[i][k] = min(dp2[i][k], dp2[i + 1][j] + 2 * k);
                    t = true;
                }
            }
            if (!t)
            {
                int x = ceil(k - 15.0 + al[i] / 2.0 - al[i + 1] / 2.0);
                dp2[i][k] = min(dp2[i][k], dp2[i + 1][15] + 2 * (n - i) * x);
            }
        }
    }
