            {
                dp1[i][k] = INF;
                bool t = false;
                for (int j = 0; j < 16; ++j)
                {
                    if (a[i - 1] * mult[j] <= a[i] * mult[k])
                    {
                        dp1[i][k] = min(dp1[i][k], dp1[i - 1][j] + 2 * k);
                        t = true;
                    }
                }
                if (!t)
                {
                    int x = ceil(k - 15.0 + al[i] / 2.0 - al[i + 1] / 2.0);
                    dp1[i][k] = min(dp1[i][k], dp1[i - 1][15] + 2 * (i - 1) * x);
                }
            }
        }
        ans = min(ans, cur + dp1[i][0] + dp2[i + 1][0]);
    }
