        if(A[i-2] < A[i-1]){
            long long tmp = A[i-2];
            while(tmp < A[i-1]){
                tmp*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j <= 15; j++){
                if(j+cnt <= 15) dp_[i][j] = dp_[i-1][j+cnt]+ 1 + 2*j;
                else dp_[i][j] = dp_[i-1][15] + 2*(i-1)*(j+cnt-15) + 1 + 2*j;
            }
        }else{
            long long tmp1 = A[i-1];
            while(4*tmp1 <= A[i-2]){
                tmp1*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j <= cnt; j++){
                dp_[i][j] = dp_[i-1][0] + 2*j + 1;
            }
            for(int j = cnt+1; j <= 15; j++){
                dp_[i][j] = dp_[i-1][j-cnt] + 2*j + 1;
            }
        }
        //cout << endl;
    }
    long long ans = INT32_MAX;
    for(int i = 0; i <= N; i++){
        long long min1, min2;
        min1 = dp[i][0];
        min2 = dp_[i][0];

        for(int j = 0; j <=15; j++){
            min1 = min(min1, dp[i][j]);
            min2 = min(min2, dp_[i][j]);
            //cout << dp[i][j] << ' ' << dp_[i][j] << endl;
            //cout << min1 << ' ' << min2 << endl;
        }
        //cout << min1 << ' ' << min2 << endl;
        ans = min(ans, min1+min2);
    }
    cout << ans << endl;
}

