vll sums(vll arr) {
	int N = arr.size();
	maxPQ<pll> pq;
	vll ret(N);
	ll sum = 0;
	for (int i = N - 1; i >= 0; i--) {
		sum += arr[i];
		ll cnt = 1;
		while (! pq.empty()) {
			pll top = pq.top();
			if (top.first >= arr[i]) {
				pq.pop();
				sum -= (top.first - arr[i]) * top.second;
				cnt += top.second;
			}
			else {
				break;
			}
		}
		pq.push(mp(arr[i], cnt));
		ret[i] = sum;
	}
	return move(ret);
}

vll calc(vector<ld> B) {
	int N = B.size();
	vll ret(N);
	ld maxval = 0;
	rep(i, N) {
		ll t = maxval >= B[i] - EPS ? (ll)ceil((maxval - B[i] - EPS) / 2) : 0;
		B[i] += 2 * t;
		ret[i] += 2 * t;
		CHMAX(maxval, B[i]);
	}
	vll s = sums(ret);
	vll ss(N);
	ll ps = 0;
	for (int i = N - 1; i >= 0; i--) {
		ps += ret[i];
		ss[i] = ps - s[i];
	}
	return move(ss);
}

