	reverse(B.begin(), B.end());
	vll r2l = calc(B);
	ll ans = INFll;
	rep(i, N) {
		CHMIN(ans, i + l2r[i] + r2l[N - 1 - i]);
	}
	cout << ans << endl;
	return 0;
}

