        return _used[e.id];
    }
    bool used(int id) {
        return _used[id];
    }
    void del(edge<T> &e) {
        _used[e.id] = _used[e.id ^ 1] = 1;
    }
    void del(int id) {
        _used[id] = _used[id ^ 1] = 1;
