static inline bool defect(int lhs, int rhs) {
  int ll = 1, rl = 1;
  while ((ll << 1) <= lhs) ll <<= 1;
  while ((rl << 1) <= rhs) rl <<= 1;
  while (ll < rl) {
    ll <<= 1;
    lhs <<= 1;
  }
  while (rl < ll) {
    rl <<= 1;
    rhs <<= 1;
  }
  return lhs > rhs;
}

static inline int getlevel(int x) {
  int foo = 0;
  for (x >>= 1; x; x >>= 1) {
    foo++;
  }
  return foo;
}

int main() {
  ios_base::sync_with_stdio(0);
