        b[i] = 1;
      }
      //fprintf(stderr, "b[%d] = %d\n", i, b[i]);
    }
    vector<int> c(n, 0);
    for (int i = 0; i < n; ++i) {
      c[i] = getlevel(a[i]);
      //fprintf(stderr, "c[%d] = %d\n", i, c[i]);
    }
    vector<vector<lld>> f(n + 1, vector<lld>(15, 0x3f3f3f3f3f3f3f3fLL));
    f[n][0] = 0LL;
    for (int j = 0; j < 15; ++j) {
      f[n - 1][j] = j << 1;
    }
    for (int i = n - 2; i >= 0; --i) {
      for (int j = 0; j < 15; ++j) {
        int k = 0;
        while (c[i] + j * 2 > c[i + 1] + k * 2 - b[i]) {
          k++;
        }
        if (k < 15) {
          f[i][j] = f[i + 1][k] + j * 2LL;
        } else {
          f[i][j] = f[i + 1][14] + (n - i - 1) * 2LL * (k - 14) + j * 2LL;
        }
        //fprintf(stderr, "f[%d][%d] = %lld (k = %d)\n", i, j, f[i][j], k);
      }
    }
    vector<int> d(n, 0);
    for (int i = 0; i + 1 < n; ++i) {
      if (defect(a[i + 1], a[i])) {
        d[i] = 1;
      }
    }
    vector<vector<lld>> g(n + 1, vector<lld>(15, 0x3f3f3f3f3f3f3f3fLL));
    g[0][0] = 0LL;
    for (int j = 0; j < 15; ++j) {
      g[1][j] = j << 1;
    }
    for (int i = 2; i <= n; ++i) {
      for (int j = 0; j < 15; ++j) {
        int k = 0;
        while (c[i - 1] + j * 2 > c[i - 2] + k * 2 - d[i - 2]) {
          k++;
        }
        if (k < 15) {
          g[i][j] = g[i - 1][k] + j * 2LL;
        } else {
          g[i][j] = g[i - 1][14] + (i - 1) * 2LL * (k - 14) + j * 2LL;
        }
      }
    }
    lld foo = 0x3f3f3f3f3f3f3f3fLL;
    for (int i = 0; i <= n; ++i) {
      UPDMIN(foo, f[i][0] + g[i][0] + i);
    }
    cout << foo << endl;
  }
  return 0;
}

