int N;
vector<ll> A;

ll dp[200010][20];

int lg(ll A, int x, ll B) {
  for (int i = 0; i < x; i++) A *= 4;
  double dB = B;
  // A*4^x <= B*4^y
  for (int y = 0;; y++) {
    if (dB > A + 100 || A <= B) {
      return y;
    }
    dB *= 4;
    B *= 4;
  }
}

ll solve(int i, int x) {
  if (i == N - 1) return 0;
  if (x > 15) {
    return solve(i, 15) + (ll)(N - i - 1) * (x - 15);
  }
  ll& res = dp[i][x];
  if (res != -1) return res;
  int y = lg(A[i], x, A[i + 1]);
  return res = y + solve(i + 1, y);
}

int main() {
