int main() {
  int N;
  cin >> N;
  vector< double > A(N);
  for(int i = 0; i < N; i++) {
    cin >> A[i];
    A[i] = log(A[i]);
  }

  const double log4 = log(4);

  vector< int64 > suffix(N);
  {
    vector< double > add(N);
    for(int i = N - 2; i >= 0; i--) {
      int times = 0;
      for(int j = i + 1; j < N; j++) {
        if(A[j - 1] + add[j - 1] <= A[j] + add[j]) break;
        int uku = ceil(((A[j - 1] + add[j - 1]) - (A[j] + add[j])) / log4);
        if(uku % 2 == 1) uku++;
        add[j] += uku * log4;
        times += uku;
      }
      suffix[i] = suffix[i + 1] + times;
    }
  }


  vector< int64 > prefix(N);
  {
    vector< double > add(N);
    prefix[0] = 1;
    for(int i = 1; i < N; i++) {
      int times = 0;
      for(int j = i; j > 0; j--) {
        if(A[j - 1] + add[j - 1] >= A[j] + add[j]) {
          break;
        };
        int uku = ceil(((A[j] + add[j]) - (A[j - 1] + add[j - 1])) / log4);
        if(uku % 2 == 0) uku++;
        add[j - 1] += uku * log4;
        times += uku;

      }
      prefix[i] = prefix[i - 1] + times;
    }
  }

  int64 ret = min(prefix[N - 1], suffix[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, prefix[i - 1] + suffix[i]);
  }
  cout << ret << endl;

}

