                    auto a = seg.back();seg.pop_back();
                    auto newp = MP(MP(a.fi.fi,b.fi.se),a.se+b.se);
                    seg.PB(newp);
                }
                cost[1][i] = cnt;
            }

        }

        reverse(cost[1], cost[1]+n);
