void f_cnt(ll cnts[200005], V<ll> alist, ll n)
{
    ll a0 = alist[0] + 1LL;
    alist.insert(alist.begin(), a0);
    deque<t2> stack;
    stack.pb(t2(1, 1e18));
    ll now = 0LL;
    cnts[0] = 0LL;

    rep (i, n) {
        ll pidx = i;
        ll idx = i + 1;
        ll pa = alist[pidx];
        ll a = alist[idx];
        ll idx_orig = idx;

        ll lcnt = 0;

        if (pa >= a) {
            while (pa >= a * 4LL) {
                a *= 4LL;
                lcnt++;
            }
            if (lcnt) stack.push_back(t2(idx, lcnt));
            cnts[idx] = now;
            continue;
        }

        while (pa < a) {
            pa *= 4LL;
            lcnt++;
        }

        debug_printf("pidx=%lld idx=%lld\n", pidx, idx);

        while (stack.size()) {
            t2 idx_cnt = stack.back(); stack.pop_back();
            ll gidx = get<0>(idx_cnt);
            ll gcnt = get<1>(idx_cnt);
            if (gcnt >= lcnt) {
                debug_printf("++a lcnt=%lld idx=%lld gidx=%lld\n",
                             lcnt, idx, gidx);
                now += lcnt * (idx - gidx);
                gcnt -= lcnt;
                if (gcnt) stack.push_back(t2(gidx, gcnt));
                break;
            }
            debug_printf("++b lcnt=%lld idx=%lld gidx=%lld\n",
                         lcnt, idx, gidx);
            now += lcnt * (idx - gidx);
            lcnt -= gcnt;
            idx = gidx;
        }

        cnts[idx_orig] = now;
    }
}

