ll solve_neg(vi& a, int lo, int hi) {
    if (lo >= hi) return 0;
    assert(a[hi-1] > 0);
    Double last = log2l(a[hi-1]*2);
    ll ans = 1;
    for (int i=hi-2; i>=lo; --i) {
        assert(a[i] > 0);
        Double y = log2l(a[i]*2);
        Double _y = last - y;
        if (_y > 0) {
            ll r = (ll)ceill(_y/2);
            ans += 1+r*2;
            last = y + r*2;
        } else {
            ans += 1;
            last = y;
        }
    }
    return ans;
}

ll solve_pos(vi& a, int lo, int hi) {
    if (lo >= hi) return 0;
    assert(a[lo] > 0);
    Double last = log2l(a[lo]);
    ll ans = 0;
    for (int i=lo+1; i<hi; ++i) {
        assert(a[i] > 0);

        Double y = log2l(a[i]);
        Double _y = last - y;
        if (_y > 0) {
            ll r = (ll)ceill(_y/2);
            ans += r*2;
            last = y + r*2;
        } else {
            last = y;
        }
    }
    return ans;
}


ll solve(int N, vi& a) {
    vi zeros;
    rep(i,N) if (a[i] == 0) zeros.pb(i);

    int Z = zeros.size();
    if (Z >= 2) {
        rep(i,Z-1) if (zeros[i+1] - zeros[i] >= 2) return -1;
    }

    if (Z > 0) {
        return solve_neg(a, 0, zeros[0]) + solve_pos(a,zeros.back()+1, N);
    }
    int lo = 0, hi = N;
    while (lo+3 < hi) {
        int d = (hi - lo)/3;
        int x1 = lo+d, x2 = hi-d;
        ll p1 = solve_neg(a,0,x1) + solve_pos(a,x1,N);
        ll p2 = solve_neg(a,0,x2) + solve_pos(a,x2,N);
        if (p1 < p2) {
            hi = x2;
        } else {
            lo = x1;
        }
    }
    ll best = min(solve_neg(a,0,N), solve_pos(a,0,N));
    for (int x=lo; x<=hi; ++x) {
        ll p = solve_neg(a,0,x) + solve_pos(a,x,N);
        if (p < best) best = p;
    }
    return best;
}


