            cnt-=now; p.second-=now;
            if (0<p.second) margin.push(p);
        }
        left[i+1]+=cnt*i;
        if (m) margin.emplace(i,m);
    }
    margin=decltype(margin)();
    for (int i=N-2;i>=0;--i){
