	for(int i = 0; i < n; i++){
		cin >> a[i];
		if(a[i] < 0){
			am[i] = a[i];
			ap[i] = -2*a[i];
			b[i] = 0;
			c[i] = 1;
		}
		else{
			am[i] = -2*a[i];
			ap[i] = a[i];
			b[i] = 1;
			c[i] = 0;
		}
	}
	for(int i = 0; i < n-1; i++){
		while(am[i] > am[i+1]){
			am[i] = am[i]*4;
			b[i] = b[i]+2;
		}
		if(i > 0){b[i] = (i+1)*b[i]+b[i-1];}
	}
	for(int i = n-1; i > 0; i--){
		while(ap[i] < ap[i-1]){
			ap[i] = ap[i]*4;
			c[i] = c[i]+2;
		}
		if(i < n-1){c[i] = (n-i)*c[i]+c[i+1];}
