int64_t dp[200010][16];

int64_t computeDP(const std::vector<int64_t>& a, int i, int x) {
    if (i == a.size() - 1) {
        return 2 * x;
    }
    if (x > 15) {
        return computeDP(a, i, 15) + 2 * (a.size() - i) * (15 - x);
    }
    if (dp[i][x] >= 0) {
        return dp[i][x];
    }

    int64_t cur = a[i],
            nxt = a[i + 1];
    for (int i = 0; i < x; i++) {
        cur *= 4;
    }

    int y = 0;
    while (nxt < cur) {
        nxt *= 4;
        y++;
    }
    dp[i][x] = computeDP(a, i + 1, y) + 2 * x;
    return dp[i][x];
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    vector<int64_t> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    vector<int64_t> score1(n);
    memset(dp, -1, sizeof(dp));
    for (int i = 0; i < n; i++) {
        score1[i] = computeDP(a, i, 0);
    }

    reverse(a.begin(), a.end());

    vector<int64_t> score2(n);
    memset(dp, -1, sizeof(dp));
    for (int i = 0; i < n; i++) {
        score2[i] = computeDP(a, i, 0);
    }
    reverse(score2.begin(), score2.end());

    int64_t ans = (1LL << 50);

    for (int i = 0; i < n; i++) {
        ans = min(ans, i + score1[i] + (i > 0 ? score2[i - 1] : 0));
    }
    cout << ans << endl;

    return 0;
}

