inline bool isinteger(double x) { return std::abs(x - std::round(x)) < EPS; }

void solve() {
	ll N;
	cin>>N;
	vector<ll> a(N);
	rep(i,N)cin>>a[i];

	auto makedp = [&](vector<ll> &a){
		ll size=101;
		//dp[i][j] a[i]に4をj回かけたときa[i]-a[N-1]が単調増加するための4をかける回数
		vector<vector<ll>> dp(N,vector<ll>(size,0));
		for(ll j=0;j<size;j+=2){
			dp[N-1][j]=j;
		}
		rrep(i,N-1){
			for(ll j=0;j<size;j+=2){
				double t=log2(a[i])+j - log2(a[i+1]);
				if(isinteger(t))t=round(t);
				ll x=0,dif=0;
				if(t>EPS){
					if(size<=ceil(t)){
						x=size-1;
						dif=(ceil(t)-(size-1))*(N-i-1);
						if(dif%2)dif++;
					}else{
						x=ceil(t);
						if(x%2)x++;
					}
				}
				dp[i][j]=dp[i+1][x]+j+dif;
			}
		}
		return dp;
	};
	vector<vector<ll>> dp=makedp(a);
	rep(i,N)a[i]*=2;
	reverse(all(a));
	vector<vector<ll>> revdp=makedp(a);

	debug(dp);
	debug(revdp);

	ll ans=INF;
	rep(i,N){
		ll t=dp[i][0];
		ll s=revdp[N-1-i][0] + i;
		debug(t,s);
		chmin(ans,s+t);
	}
	p(ans);
}

