ll solve_mini(int n, vector<ll>& a) {
    vector<ll> L(n, 0);
    vector<ll> v;
    for (int i = 0; i < n; i++) {
        if (i > 0) L[i] += L[i - 1];
        L[i]++;
        v.push_back(a[i]);
        int sz = v.size();
        for (int j = sz - 1; j > 0; j--) {
            while (v[j - 1] < v[j]) {
                v[j - 1] *= 4;
                L[i] += 2;
            }
        }       
    }

    vector<ll> R(n, 0);
    v.clear();
    for (int i = n - 1; i >= 0; i--) {
        if (i < n - 1) R[i] += R[i + 1];
        v.push_back(a[i]);
        int sz = v.size();
        for (int j = sz - 1; j > 0; j--) {
            while (v[j - 1] < v[j]) {
                v[j - 1] *= 4;
                R[i] += 2;
            }
        } 
    }

    ll ans = min(L[n - 1], R[0]);
    for (int i = 1; i < n; i++) {
        ans = min(ans, L[i - 1] + R[i]);
    }
    return ans;
}

