LL delt(LL a,LL b){
  LL ret = 0;
  if(a <= b){
    while(a*4 <= b){
      a*=4;
      ret++;
    }
    return ret;
  }
  ret--;
  while(b*4 < a){
      b*=4;
      ret--;
  }
  return ret;
}

