		if(cost(m) < cost(m + 1))
			r = m;
		else
			l = m + 1;
	}
	cout << cost(l) << endl;
	// cout << l << endl;
	int ans = INT_MAX;
	for(int i = 0; i < N; i++)
		ans = min(ans, cost(i));
