const ll INFLL = (1ll << 60); 

vector<ll> solve(const vector<ll> &X){
	ll N = X.size();
	vector<ll> A(N);
	REP(i, N) A[i] = X[i];
 	stack<pll> st;
 	st.push({N-1, INFLL});
	vector<ll> res(N+1, 0);

	for(int i=N-2;i>=0;i--){
		ll cnt = res[i+1];
		if(A[i] <= A[i+1]){
			ll tmp = A[i];
			ll yoyu = 0;
			while(1){
				if(tmp*4 > A[i+1]) break;
				tmp *= 4;
				yoyu++;
			}
			st.push({i, yoyu});
		}else{
			ll tmp = A[i+1];
			ll tarinai = 0;
			while(1){
				if(tmp >= A[i]) break;
				tmp *= 4;
				tarinai++;
			}
			while(tarinai > 0){
				cnt += (st.top().first - i);
				st.top().second--;
				if(st.top().second == 0) st.pop();
				tarinai--;
			}
		}
		res[i] = cnt;
	}
	return res;
}

