int lg(ll A, int x, ll B) {
  for (int i = 0; i < x; i++) A *= 4;
  double dB = B;
  // A*4^x <= B*4^y
  for (int y = 0;; y++) {
    if (dB > A + 100 || A <= B) {
      return y;
    }
    dB *= 4;
    B *= 4;
  }
}

