			ind = jump[ind] - 1;
		}
		if (c == 0 && jump[ind] != 1) {
			ind = jump[ind] - 1;
			up[i] = up[ind];
		} else up[i] = -c;
		jump[i] = jump[ind];
		TL[i] = TL[i - 1] + r * 2 + 1;
	}
	//cout << i << " " << TL[i] << endl;
}
minn = min(TR[1], TL[n]);
for (i = 2;i<=n;i++) minn = min(minn, TR[i] + TL[i - 1]);
cout << minn << endl;
return 0;
}

