struct BIT {
	int node[200006]; int N = 200002;
	void init() {
		fill(node, node + N + 1, 0);
	}
	void add(int i, int x) {
		while (i <= N) {
			node[i] += x; i += i & -i;
		}
	}
	int sum(int x) {
		int s = 0;
		while (x > 0) {
			s += node[x]; x -= x & -x;
		}
		return s;
	}
};

