                A[i] *= 4;
                if (A[i] > 0) return INF;
                res += 2;
            }
        }
    }

    FOR(i, d, A.size() - 1) {
        if (i == 0 || A[i] > A[i - 1]) continue;
        while (A[i] < A[i - 1]) {
            A[i] *= 4;
            if (A[i] < 0) return INF;
            res += 2;
        }
    }
    return res;
}

