struct val_t {
	int l, r;
	ll al, ar;
};

vll solve(vll a) {
	int n = a.size();
	vll ret(n);
	deque<val_t> vals = { { n - 1, n - 1, a[n - 1], LLONG_MAX } };
	Loopr(i, n - 1) {
		ret[i] = ret[i + 1];
		if (a[i] * 4 <= vals[0].al) {
			vals.push_front({ i, i, a[i], a[i] });
		}
		else if (a[i] <= vals[0].al) {
			vals[0].l = i;
			vals[0].al = a[i];
		}
		else {
			while (a[i] > vals[0].al) {
				ret[i] += 2 * (vals[0].r - vals[0].l + 1);
				vals[0].al *= 4;
				if (vals.size() >= 4) {
					vals[0].ar *= 4;
					if (vals[0].ar * 4 > vals[1].al) {
						vals[1].l = vals[0].l;
						vals[1].al = vals[0].al;
						vals.pop_front();
					}
				}
			}
			vals[0].l = i;
			vals[0].al = a[i];
		}
	}
	return ret;
}

int main() {
	int n; cin >> n;
	vll a(n); Loop(i, n) cin >> a[i];
	vll pos = solve(a);
	reverse(a.begin(), a.end());
	vll neg = solve(a);
	reverse(neg.begin(), neg.end());
	Loop(i, n) neg[i] += 1;
	ll ans = LLONG_MAX;
	Loop(i, n + 1) {
		if (i == 0) ans = min(ans, pos[i]);
		else if (i == n) ans = min(ans, neg[i - 1]);
		else ans = min(ans, neg[i - 1] + pos[i]);
	}
	cout << ans << endl;
}

