					acu[i] += 2ll * st.top().se;
					st.top().fi--;

					if (!st.top().fi) {
						ii aux = st.top();
						st.pop();
						st.top().se += aux.se;
					}
				}

				st.top().se++;
			}
		}
	}

	while (st.size())
		st.pop();

	// Negativos
	ll s = 0;

	for (int i = 0; i < n; i++) {
		if (!i) {
			st.emplace(1e9, 1);
		} else {
			if (a[i] <= a[i-1]) {
				ll x = a[i], r = 0;

				while (x * 4 <= a[i-1])
					x *= 4, r++;

				if (!r) st.top().se++;
				else st.emplace(r, 1);
			} else {
				ll x = a[i-1];

				while (a[i] > x) {
					x *= 4;
					s += 2ll * st.top().se;
					st.top().fi--;

					if (!st.top().fi) {
						ii aux = st.top();
						st.pop();
						st.top().se += aux.se;
					}
				}

				st.top().se++;
			}
		}

		acu[i+1] += s + i + 1;
	}

	for (int i = 0; i <= n; i++){
		mn = min(mn, acu[i]);
	}

	cout << mn << endl;

	return 0;
}

