		LL t1 = a[i - 1], t2 = a[i];
		if (t1 < t2) swap(t1, t2);
		while (t1 >= t2) {
			t2 *= 4;
			need[i]++;
		}
	}
	vector<PII> v;
	//for (int i = 1; i <= n; i++) cout << need[i] << endl;
