typedef long long int llint;

std::vector<int> make_count(double a_logtwo[], int mid, int n){
  //std::cout << "make_count " << mid << std::endl;
  std::vector<int> count(n);
  for(int i=mid; i<n-1; i++){
    count[i+1] = std::ceil((a_logtwo[i] - a_logtwo[i+1] + count[i])/2)*2;
    if(count[i+1] < 0) count[i+1] = 0;
  }
  for(int i=mid-1; i>0; i--){
    count[i-1] = std::ceil((a_logtwo[i] - a_logtwo[i-1] + count[i])/2)*2;
    if(count[i-1] < 0) count[i-1] = 0;
  }

  return count;
}

int count_all(double a_logtwo[], int mid, int n){
  std::vector<int> count = make_count(a_logtwo, mid, n);
  int count_all = mid;
  for(int i=0; i<n; i++){
    count_all+=count[i];
  }
  return count_all;
}

