long long solve() {
  long long ans = -1;
  memo[0][0] = 1;
  for(int i = 1; i < n; ++i) {
    long long cnt = 0, now = a[i - 1];
    memo[i][0] = memo[i - 1][0] + 1;
    while(a[i] > now) {
      cnt += 2;
      now *= 4;
    }
    memo[i][0] += cnt * i;
  }
  for(int i = n - 2; i >= 0; --i) {
    long long cnt = 0, now = a[i + 1];
    memo[i][1] = memo[i + 1][1];
    while(a[i] > now) {
      cnt += 2;
      now *= 4;
    }
    memo[i][1] += cnt * (n - 1 - i);
  }
  ans = min(memo[n - 1][0], memo[0][1]);
  for(int i = 0; i < n - 1; ++i) {
    long long now = 0;
    now += memo[i][0] + memo[i + 1][1];
    ans = min(ans, now);
  }

  return ans;
}

