const ll MOD=1e9+7;

bool ge(ll a,ll b){
	if(b==0) return false;
	if(a==0) return true;
	int t=__builtin_ctzll(a);
	a>>=t;
	t=__builtin_ctzll(b);
	b>>=t;
	return a<b;
}

void solve(vector<ll> a,vector<int> &re){
	int n=a.size();
	rep(i,n)if(a[i]>0){
		++re[i+1];
		a[i]*=-2;
	}
	for(auto &x:a) x*=-1;
	out(a,re,1);
	// dec!
	ll prv=MOD*16;
	rep(i,n){
		int tmp=64-__builtin_clzll(a[i])+re[i+1] - (64-__builtin_clzll(prv)+re[i]);
		out(tmp,1);
		if(tmp>0) re[i]+=(tmp+1)/2*2;
		if(tmp==0 && ge(prv,a[i])) re[i]+=2;
		prv=a[i];
	}
	rep(i,n) re[i]+=re[i+1];
	out(re,1);
}

int main(){
  ios_base::sync_with_stdio(false);
  cout<<fixed<<setprecision(0);
	int n;
	cin>>n;
	vector<ll> a(n);
	rep(i,n) cin>>a[i];
	vector<int> ge(n),le(n);
	rep(i,n-1){
		ll l=a[i];
		ll r=a[i+1];
		while(l>r){
			r*=2;
			++ge[i+1];
		}
		while(l*2<=r){
			l*=2;
			--ge[i+1];
		}
		l=a[i];
		r=a[i+1];
		while(l<r){
			l*=2;
			++le[i];
		}
		while(l>=r*2){
			r*=2;
			--le[i];
		}
	}
	out(ge,le,1);
	vector<ll> l(n);
	vector<pii> st{{MOD,-1}};
	rep(i,n-1){
		l[i+1]+=l[i];
		if(le[i]<0){
			st.eb((-le[i])/2,i);
		}else{
			rep(_,(le[i]+1)/2){
				l[i+1]+=2*(i-st.back().Y);
				--st.back().X;
				if(st.back().X==0) st.pop_back();
			}
		}
	}
	out(l,1);
	vector<ll> r(n);
	{
		vector<pii> st{{MOD,n-1}};
		rrep(i,n-1){
			r[i]+=r[i+1];
			if(ge[i+1]<0){
				st.eb((-ge[i])/2,i);
			}else{
				rep(_,(ge[i+1]+1)/2){
					r[i]+=2*(st.back().Y-i);
					out(i,st,1);
					--st.back().X;
					if(st.back().X==0) st.pop_back();
				}
			}
		}
	}
	out(r,1);
	ll re=min(l[n-1]+n,r[0]);
	rep(i,n-1) MN(re,l[i]+r[i+1]+i+1);
	cout<<re<<endl;
  return 0;
}

