ll f(ll x, ll y) {
	ll ans = 0;
	if (y > x) {
		while (y > x) {
			ans++;
			x *= 4;
		}
		return ans * 2;
	}
	else if(y==x){
		return 0;
	}
	else {
		swap(x, y);
		while (y >= x*4) {
			ans++;
			x *= 4;
		}
		return -ans * 2;

	}
}



int main() {
	ll n;
	cin >> n;
	REP(i, 1, n) {
		cin >> a[i];
	}
	b[n] = b[n + 1] = 0; b[0] = 0;
	ll cnt_b = 0;
	stack<stc> st1;
	PER(i, n - 1, 1) {
		ll x = f(a[i+1], a[i]);
		if (x < 0) {
			//cout << i <<" " << x << endl;
			st1.push({ i,-x });
			b[i] = b[i + 1];
		}
		else if (x == 0) {
			b[i] = b[i + 1];
		}
		else {
			b[i] = b[i + 1];
			bool flag = 1;
			while (!st1.empty()) {
				stc cur = st1.top();
				st1.pop();
				if (x <= cur.dif) {
					//cout << i << "! ";

					b[i] += x * (cur.name - i);
					//cout << b[i] << endl;
					cur.dif -= x;
					if (cur.dif > 0) {
						st1.push(cur);
					}
					flag = 0;
					break;
				}
				else {
					b[i] += cur.dif*(cur.name - i);
					x -= cur.dif;
				}
			}
			if (flag) {
				b[i] += (n - i)*x;

			}
		}

	}
	stack<stc> st2;
	c[0] = c[1] = 0; c[n + 1] = 0;
	REP(i, 2, n) {
		ll x = f(a[i-1], a[i]);
		if (x < 0) {
			st2.push({ i, -x });
			c[i] = c[i - 1];
		}
		else if(x==0){
			c[i] = c[i - 1];
		}
		else {
			c[i] = c[i - 1];
			bool flag = 1;
			while (!st2.empty()) {
				stc cur = st2.top();
				st2.pop();
				if (x <= cur.dif) {
					c[i] += x * (-cur.name + i);
					cur.dif -= x;
					if (cur.dif > 0) {
						st2.push(cur);
					}
					flag = 0;
					break;
				}
				else {
					c[i] += cur.dif*(-cur.name + i);
					x -= cur.dif;
				}
			}
			if (flag) {
				c[i] += (i - 1)*x;
			}
		}
	}
	ll ans = 1e10;
	REP(i, 1, n+1) {
		ans = min(ans, (i - 1) + c[i - 1] + b[i]);
	}
	/*
