    vector<long long> res(n + 1, inf);
    vector<vector<long long>> dp(n + 1, vector<long long>(16, inf));
    res[n] = res[n - 1] = 0;
    for (int i = 0; i < 16; ++i) dp[n - 1][i] = i;
    for (int i = n - 2; i >= 0; --i) {
      long long now = v[i];
      for (int j = 0; j < 16; ++j) {
        long long nxt = v[i + 1];
        for (int k = 0; k < 16; ++k) {
          if (now <= nxt) {
            dp[i][j] = dp[i + 1][k] + j;
            break;
          }
          nxt <<= 2;
        }
        if (dp[i][j] == inf) dp[i][j] = dp[i + 1][15] + n - 1 - i + j;
        now <<= 2;
      }
      res[i] = dp[i][0] << 1;
    }
    return res;
  };
  suf = calc(a);
  reverse(a.begin(), a.end());
  for (auto& p : a) p *= 2;
  pre = calc(a);
  reverse(pre.begin(), pre.end());
  for (int i = 0; i <= n; ++i) pre[i] += i;
  long long res = inf;
