void pre(ll B[MAX_N]) {
	stack<pi> st;
	st.push(pi(inf, N - 1));
	B[N - 1] = 0;
	ll cost = 0;
	rer(i, N - 1, 0) {
		// debug(i);
		while(A[i] > A[i + 1]) {
			A[i + 1] *= 4;
			pi p = st.top(); st.pop();
			p.fst--;
			cost += (2 * (p.sec - i));
			if(p.fst) st.push(p);
		}
		B[i] = cost;
		ll n = A[i];
		int cnt = 0;
		while(n * 4 <= A[i + 1]) {
			n *= 4; cnt++;
		}
		debug(i, vi(A, A + N), n, cnt);
		if(cnt) st.push(pi(cnt, i));
	}
}

void solve() {
