void sub(long* P) {
  stack<int> gap;
  for (int i = 0; i < n; ++i) {
    gap.push(0);
  }

  long sum = 0;
  for (int i = 1; i < n; ++i) {
    long s = a[i - 1];
    long t = a[i];
    while (s < t) {
      sum += i - gap.top(); gap.pop();
      s *= 4;
    }

    while (s >= t * 4) {
      gap.push(i);
      t *= 4;
    }
    P[i + 1] = 2 * sum;
  }
}

