				auto f=las.front();
				las.pop_front();
				while(f.first.first<v[i]){
					f.first.first*=4LL;
					f.first.second*=4LL;
					cs+=f.second*2LL;
				}
				while(las.size()&&las.front().first.first<f.first.second){
					auto g=las.front();
					las.pop_front();
					while(g.first.first<f.first.second){
						g.first.first*=4LL;
						g.first.second*=4LL;
						cs+=g.second*2LL;
					}
					f.second+=g.second;
					f.first.second=g.first.second;
				}
				f.first.first=v[i];
				f.second++;
				las.push_front(f);
			}
			if(flag==false)bc[i]=cs;
			else {
				cs++;
				fr[v.size()-i-1]=cs;
			}
		}
