	vector<int> v(n + 2);
	for (int i = 1; i <= n; ++i)
		scanf("%d", &v[i]);
	vector<ll> pre(n + 2), suf(n + 2);
	for (int it = 0; it < 2; ++it) {
		vector<ll> s;
		for (int i = 2; i <= n; ++i) {
			ll a = v[i - 1];
			ll b = v[i];
			if (a >= b) {
				pre[i] = pre[i - 1];
				ll times = 0;
				while (a >= b * 4) {
					++times;
					b *= 4;
				}
				s.push_back(times);
			}
			else {
				ll need = 0;
				while (a < b) {
					a *= 4;
					++need;
				}
				ll now = need*(i - 1 - s.size());
				ll cur = need;
				while (!s.empty()) {
					s.back() -= cur;
					if (s.back() == 0) {
						s.pop_back();
						break;
					}
					else if (s.back() < 0) {
						cur = -s.back();
						s.pop_back();
						now += cur;
					}
				}
				pre[i] = pre[i - 1] + now;
			}
		}
		pre.swap(suf);
		reverse(v.begin(), v.end());
	}
	reverse(suf.begin(), suf.end());
	for (int i = 1; i <= n; ++i) {
		pre[i] <<= 1;
		suf[i] <<= 1;
		pre[i] += i;
	}
	ll res = suf[1];
	for (int i = 1; i + 1 <= n; ++i)
		res = min(res, pre[i] + suf[i + 1]);
	printf("%lld\n", res);
	return 0;
}

