    }
    else {
      ll temp = a[i - 1];
      num[i] = num[i - 1];
      while (4*temp <= a[i]) {
        num[i]--;
        temp *= 4;
      }
      ans += num[i] * 2;
    }
    sum += num[i];
  }
  ll pre = -INF;
  ll left = 0, right = 0;
  vl dp(n);
  rep (i, n) {
    int cnt = 0;
