namespace Sparse {
	int INF = 1e+15;
	int table[18][500000];
	int log_2[200000];

	void init(int a[], int n) {
		int i, j;

		for(i = 0; i < 18; i++)
			for (j = 0; j < n + (1 << 17); j++)
				table[i][j] = INF;

		rep(i, n) table[0][i] = a[i];
		for (i = 1; i < 18; i++) {
			rep(j, n) {
				table[i][j] = min(table[i - 1][j], table[i - 1][j + (1 << (i - 1))]);
			}
		}

		log_2[1] = 0;
		for (i = 2; i <= n; i++) {
			log_2[i] = log_2[i / 2] + 1;
		}
	}

	//[l, r)
	int getMin(int l, int r) {
		if (l >= r) return INF;
		int i = log_2[r - l];
		return min(table[i][l], table[i][r - (1 << i)]);
	}
};

int INF = 1e+15;
