void calc(int *a, int *f) {
	static int ra[200000];
	static int r[200001];
	static int dp[200001];	//minA[i][j] = min(ra[i],…,ra[j])としたとき、dp[i] = sum(minA[i][j], j in i≦j<n), 0≦i≦n-1
	int i;

	//cout << "A = ";
	//for (i = 0; i < n; i++) cout << a[i] << " ";
	//cout << endl;

	ra[0] = a[0];
	for (i = 1; i < n; i++) ra[i] = ra[i - 1] + a[i];

	r[0] = 0;
	for (i = 1; i <= n; i++) r[i] = r[i - 1] + ra[i - 1];

	Sparse::init(ra, n);
	dp[n] = 0;
	for (i = n - 1; i >= 0; i--) {
		int st = i + 1, ed = n + 1, mid;	//xxxooo, (st, ed]
		while (ed - st >= 2) {
			mid = (st + ed) / 2;
			int res = Sparse::getMin(i + 1, mid);
			if (res <= ra[i]) ed = mid;
			else st = mid;
		}
		int j = ed - 1;

		dp[i] = ra[i] * (j - i) + dp[j];
	}

	for (i = 0; i < n; i++) {
		int sumX = r[n] - r[i] - (n - i) * ra[i];
		int sumMinX = dp[i] - (n - i) * ra[i];
		f[i] = sumX - sumMinX;
	}
}

void reverse(int *a, int n) {
