vector<ll> calc_lef(const vector<ll>& A) {
	int N = A.size();
	vector<ll> ne(N);
	for (int i = 1; i < N; i++) {
		ll val = A[i], cnt = 0;
		while (A[i - 1] >= val) val <<= 2LL, cnt += 2;
		if (A[i - 1] >= A[i]) ne[i] = cnt - 2;
	}
	vector<ll> lef(N + 1);
	lef[1] = 1;
	set<int> pos;
	pos.insert(0);
	for (int i = 1; i < N; i++) {
		if (A[i - 1] >= A[i]) {
			if (ne[i] > 0) pos.insert(i);
			lef[i + 1] = lef[i] + 1;
			continue;
		}
		ll val = A[i - 1], cnt = 0, sum = 0;
		while (val < A[i]) {
			val <<= 2LL, cnt += 2;
			int pre = *pos.rbegin();
			sum += (i - pre) * 2;
			ne[pre] -= 2;
			if (ne[pre] == 0) pos.erase(pre);
		}
		lef[i + 1] = lef[i] + sum + 1;
	}
	return lef;
}

vector<ll> calc_rig(const vector<ll>& A) {
	int N = A.size();
	vector<ll> ne(N);
	for (int i = N - 2; i >= 0; i--) {
		ll val = A[i], cnt = 0;
		while (val <= A[i + 1]) val <<= 2LL, cnt += 2;
		if (A[i] <= A[i + 1]) ne[i] = cnt - 2;
	}
	vector<ll> rig(N + 1);
	set<int> pos;
	pos.insert(N - 1);
	for (int i = N - 2; i >= 0; i--) {
		if (A[i] <= A[i + 1]) {
			if (ne[i] > 0) pos.insert(i);
			rig[i] = rig[i + 1];
			continue;
		}
		ll val = A[i + 1], cnt = 0, sum = 0;
		while (val < A[i]) {
			val <<= 2LL, cnt += 2;
			int nex = *pos.begin();
			sum += (nex - i) * 2;
			ne[nex] -= 2;
			if (ne[nex] == 0) pos.erase(nex);
		}
		rig[i] = rig[i + 1] + sum;
	}
	return rig;
}

int main()
{
	int N;
	cin >> N;
	vector<ll> A(N);
	for (int i = 0; i < N; i++) {
		cin >> A[i];
