            auto it=rbegin(memo);
            vi x;
            while(sum>0){
                auto p=*it;
                if(p.second<=sum){
                    sum-=p.second;
                    x.pb(p.first);
                    dp[i+1]+=(i-p.first)*p.second;
                }
                else{
                    dp[i+1]+=(i-p.first)*sum;
                    memo[p.first]-=sum;
                    sum=0;
                }
                it--;
            }
            rep(j,0,x.size()){
                ll X=x[j];
                memo.erase(X);
            }
        }
    }
    ll ans=INF;
    REP(i,0,N) ans=std::min(ans,dp[i]+cp[N-i]);
    cout<<ans<<endl;
}

