int lg(ll A, ll B) {
  if (A == B) return 0;
  if (A < B) {
    int res = 0;
    while (A * 2 <= B) {
      ++res;
      A *= 2;
    }
    return -res;
  }
  int res = 0;
  while (A > B) {
    ++res;
    B *= 2;
  }
  return res;
}

int even(int n) {
  while (abs(n) % 2 != 0) ++n;
  return n;
}

int f(ll A, ll B) { return even(lg(A, B)); }

