#define PIL pair<int, LL>
#define pos first
#define pw second

int N;
LL a[MAXN], cnt1[MAXN], cnt2[MAXN];

void solve(LL *cnt) {
	vector<PIL> stk;
	stk.push_back({N, INF});

	cnt[N - 1] = 0;
	for (int i = N - 2; i >= 0; i--) {
		LL add = 0;

		if (a[i] > a[i + 1]) {
			LL tmp = a[i + 1];
			while (a[i] > tmp) {
				tmp *= 4;
				add += (stk.back().pos - (i + 1)) * 2;
				stk.back().pw--;
				if (stk.back().pw <= 0) stk.pop_back();
			}
		}
		else {
			LL pw = 0, tmp = a[i + 1];
			while (a[i] <= tmp) {
				tmp *= 4;
				pw += 1;
			}
			if (pw > 1) stk.push_back({i + 1, pw - 1});
		}

		cnt[i] = cnt[i + 1] + add;
	}
}

