using namespace std;
typedef long long li;


vector<li> asc_costs(vector<li> xs) {
    // action: 4x
    vector<li> costs(xs.size() + 1);

    for (int i = xs.size() - 1; i >= 0; --i) {
        li local_cost = 0;
        li cur = xs[i];
        li prev = (i + 1 < xs.size()) ? xs[i + 1] : (1LL << 55);
        while (cur > prev) {
            prev *= 4;
            local_cost += 1;
        }
        costs[i] = costs[i + 1] + local_cost * (xs.size() - 1 - i);
    }
    return costs;
}

int main() {
    li n;
