    vector<li> xs(n);
    for (int i = 0; i < n; ++i) {
        cin >> xs[i];
    }

    vector<li> positive_costs = asc_costs(xs);
    reverse(xs.begin(), xs.end());
    vector<li> negative_costs = asc_costs(xs);
    reverse(negative_costs.begin(), negative_costs.end());

    li ans = 1LL << 60;
    for (int i = 0; i <= n; ++i) {
        ans = min(ans, i + (positive_costs[i] + negative_costs[i]) * 2);
    }

    cout << ans << endl;
    return 0;
}

