    int j2 = 0;
    for (int j = 0; j < 16; j++) {
      while (next < cur) {
        next *= 4;
        j2++;
      }
      if (j2 < 16) {
        dp[i][j] = dp[i + 1][j2] + j;
      }
      else {
        dp[i][j] = dp[i + 1][15] + (j2 - 15) * (n - 1 - i) + j;
      }
      cur *= 4;
    }
  }
