int64_t dp[200010][16];

int64_t computeDP(const std::vector<int64_t>& a, int i, int x) {
    if (i == a.size() - 1) {
        return 2 * x;
    }
    if (x > 15) {
        return computeDP(a, i, 15) + 2 * (a.size() - i) * (15 - x);
    }
    if (dp[i][x] >= 0) {
        return dp[i][x];
    }

    int64_t cur = a[i],
            nxt = a[i + 1];
    for (int i = 0; i < x; i++) {
        cur *= 4;
    }

    int y = 0;
    while (nxt < cur) {
        nxt *= 4;
        y++;
    }
    dp[i][x] = computeDP(a, i + 1, y) + 2 * x;
    return dp[i][x];
}

