vector<long long> get(vector<long long> A){
	vector<long long> C(A.size(),0LL);
	for(int i=1;i<A.size();i++){
		long long t=  A[i];
		int c = 0;
		while(A[i]>0&&t<A[i-1]){
			c++;
			t*=-2;
		}
		while(A[i]<0&&t>A[i-1]){
			c++;
			t*=-2;
		}

		C[i] = c;
	}

	vector<long long> ret(A.size(),0LL);

	for(int i=A.size()-1;i>=0;i--){
		if(i+1==A.size())continue;
		ret[i] = ret[i+1];
		ret[i] += C[i+1] * (A.size()-1 - i);
	}
	return ret;
}


