void solve() {
	int n;
	while (cin >> n) {
		vector<ll> a(n);
		for (int i = 0; i < n; i++) {
			cin >> a[i];
		}

		vector<ll> pw(61);
		pw[0] = 1;
		for (int i = 1; i <= 60; i++) {
			pw[i] = pw[i - 1] * (-2);
		}

		vector<ii> neg(n);
		neg[0] = { 0, 0 };
		for (int i = 1; i < n; i++) {
			const ll x = a[i - 1] * (-2);
			const ll y = a[i] * (-2);
			int cntX = 0;
			int cntY = 0;
			if (abs(x) < abs(y)) {
				ll xx = x;
				while (true) {
					if (abs(xx) < abs(y)) {
						xx *= 4;
						cntX += 2;
					}
					else break;
				}
			}
			if (abs(x) > abs(y)) {
				ll yy = y;
				while (true) {
					if (abs(x) >= abs(yy)) {
						yy *= 4;
						cntY += 2;
					}
					else break;
				}
				cntY -= 2;
			}
			neg[i] = { cntX, cntY };
		}

		vector<pair<ll, ll>> pos(n);
		pos[n - 1] = { 0, 0 };
		for (int i = n - 2; i >= 0; i--) {
			const ll x = a[i];
			const ll y = a[i + 1];
			int cntX = 0;
			int cntY = 0;
			if (abs(x) > abs(y)) {
				ll yy = y;
				while (true) {
					if (abs(x) > abs(yy)) {
						yy *= 4;
						cntY += 2;
					}
					else break;
				}
			}
			if (abs(x) < abs(y)) {
				ll xx = x;
				while (true) {
					if (abs(xx) <= abs(y)) {
						xx *= 4;
						cntX += 2;
					}
					else break;
				}
				cntX -= 2;
			}

			pos[i] = { cntX, cntY };
		}

		//for (auto& p : neg) cerr << "(" << p.first << " " << p.second << ")"; cerr << endl;
		//for (auto& p : pos) cerr << "(" << p.first << " " << p.second << ")"; cerr << endl;
		//cerr << endl;

		vector<ll> aggNeg(n);
		aggNeg[0] = 0;
		for (int i = 1; i < n; i++) {
			const ll x = a[i - 1] * (-2);
			const ll y = a[i] * (-2);
			if (abs(x) > abs(y)) {
				aggNeg[i] = aggNeg[i - 1] + i * neg[i].first;
			}
			else {
				aggNeg[i] = aggNeg[i - 1] + i * neg[i].first - pos[i - 1].second;
			}
		}

		vector<ll> aggPos(n);
		aggPos[n - 1] = 0;
		for (int i = n - 2; i >= 0; i--) {
			const ll x = a[i];
			const ll y = a[i + 1];
			if (abs(x) < abs(y)) {
				aggPos[i] = aggPos[i + 1] + (n - i - 1) * pos[i].second;
			}
			else {
				aggPos[i] = aggPos[i + 1] + (n - i - 1) * pos[i].second - pos[i + 1].first;
			}

		}

		//for (ll x : aggNeg) cerr << x << " "; cerr << endl;
		//for (ll x : aggPos) cerr << x << " "; cerr << endl;

		ll ans = 1LL << 62;
		for (int cntNeg = 0; cntNeg <= n; cntNeg++) {
			if (cntNeg == 0) {
				ans = min(ans, aggPos[0]);
				continue;
			}
			if (cntNeg == n) {
				ans = min(ans, n + aggNeg[n - 1]);
				continue;
			}
			ans = min(ans, cntNeg + aggNeg[cntNeg - 1] + aggPos[cntNeg]);
		}

		cout << ans << endl;
	}
}

