const int N = 2e5 + 6;
const int LOG = 32;

int n;
int arr[N];
int pref[N], suff[N];
int cnt[LOG];

void solve(int* res)
{
  memset(cnt, 0, sizeof cnt);
  res[n] = 0;
  for(int i = n - 1 ; i >= 0 ; i--){
    int x = arr[i];
    res[i] = res[i + 1];
    for(int y = 0 ; y < x ; y++){
      if(!cnt[y])
        continue;
      int p = (x - y + 1) >> 1;
      res[i] += cnt[y] * p;
      cnt[y] = 0;
    }
    cnt[x]++;
  }
}

int main()
{
  scanf("%d", &n);
  for(int i = 0 ; i < n ; i++){
    scanf("%d", &arr[i]);
    arr[i] = log2(arr[i]);
  }
  solve(suff);
  reverse(arr, arr + n);
  solve(pref);
  reverse(pref, pref + n);
  int ans = 1e9;
  for(int i = 0 ; i <= n ; i++){
    int cur = suff[i] * 2 + i + pref[n - i] * 2;
    ans = min(ans, cur);
  }
  cout << ans << endl;
  return 0;
}

