const ll INF = ll(4e18);
const int MAXP = 16;

vector<ll> get(const vector<ll>& a) {
	const int n = sz(a);
	vector<vector<ll>> dp(n, vector<ll>(MAXP, INF));
	for (int p = 0; p < MAXP; p++) {
		dp[n - 1][p] = p * 2;
	}
	for (int i = n - 2; i >= 0; i--) {
		ll cur = a[i];
		for (int p = 0; p < MAXP; p++) {
			ll nxt = a[i + 1];
			for (int np = 0; np < MAXP; np++) {
				if (cur <= nxt) {
					dp[i][p] = min(dp[i][p], dp[i + 1][np] + p * 2);
				}
				nxt *= 4;
			}
			cur *= 4;
		}
	}
	vector<ll> ans(n, INF);
	for (int i = 0; i < n; i++) {
		for (int p = 0; p < MAXP; p++) {
			ans[i] = min(ans[i], dp[i][p]);
		}
	}
	return ans;
}

void solve() {
	int n;
	while (cin >> n) {
		vector<ll> a(n);
		for (int i = 0; i < n; i++) {
			cin >> a[i];
		}
		vector<ll> suff = get(a);

		vector<ll> b(n);
		for (int i = 0; i < n; i++) {
			b[i] = a[n - i - 1] * 2;
		}
		vector<ll> pref = get(b);
		reverse(all(pref));

#ifdef LOCAL_COMP
		for (ll x : pref) cerr << x << " "; cerr << endl;
		for (ll x : suff) cerr << x << " "; cerr << endl;
#endif

		ll ans = INF;
		for (int cntNeg = 0; cntNeg <= n; cntNeg++) {
			ll t;
			if (cntNeg == 0) {
				t = suff[0];
			} else if (cntNeg == n) {
				t = n + pref[n - 1];
			} else {
				t = cntNeg + pref[cntNeg - 1] + suff[cntNeg];
			}

#ifdef LOCAL_COMP
			cerr << cntNeg << " -> " << t << endl;
#endif

			ans = min(ans, t);
		}

		cout << ans << endl;
	}
}

