// template

vector<int> solve(vector<int> A) {
	stack<int> st;
	int N = A.size();
	st.push(A.size()-1);
	vector<int> res(N);
	RFOR(i, 0, N - 1) {
		int& left = A[i];
		int& right = A[i + 1];

		int cnt = 0;
		while (left > right) {
			right *= 4;
			int index = st.top(); st.pop();
			cnt += (index - i);
			if (index != i+1) {
				A[index] *= 4;
			}
			if (index + 1 == N or A[index] * 4 <= A[index + 1]) st.push(index);
		}
		res[i] = cnt;
	}
	RFOR(i, 0, N - 2) {
		res[i] += res[i + 1];
	}
	return res;
}

