int count(int a, int b) {
  if (a <= b && b < 4 * a) return 0;
  else if (a < b) {
    return -1 + count(4 * a, b);
  } else {
    return 1 + count(a, 4 * b);
  }
}
signed main() {
  int N; cin >> N;
  VI A(N);
  REP (i, N) cin >> A[i];
  VVI dp0(N, VI(16)), dp1(N, VI(16));
  REP (x, 16) {
    dp0[N - 1][x] = x;
    dp1[0][x] = x;
  }
  for (int i = N - 2; i >= 0; i--) {
    int dif = count(A[i], A[i + 1]);
    REP (x, 16) {
      int tmp = max(0LL, x + dif);
      if (tmp >= 16) {
        dp0[i][x] = dp0[i + 1][15] + x + (tmp - 15) * (N - i - 2);
      } else {
        dp0[i][x] = dp0[i + 1][tmp] + x;
      }
    }
  }
  REP (i, N - 1) {
    int dif = count(A[i + 1], A[i]);
    REP (x, 16) {
      int tmp = max(0LL, x + dif);
      if (tmp >= 16) {
        dp1[i + 1][x] = dp1[i][15] + x + (tmp - 15) * i;
      } else {
        dp1[i + 1][x] = dp1[i][tmp] + x;
      }
    }
  }
  int ans = 1e18;
  REP (i, N) {
    int tmp = i + dp0[i][0] * 2 + (i == 0 ? 0 : dp1[i - 1][0] * 2);
    ans = min(ans, tmp);
  }
