const int inf = 1 << 30;
const ll linf = 1LL << 60;
const double PI = 3.14159265358979323846;
///////////////////////////////////////////////////////////////////////////////////////////////////


int N;
ll D[MAX_N], RD[MAX_N];
ll A[MAX_N];

void pre(ll A[MAX_N], ll D[MAX_N]) {
	vector<pi> stack;
	stack.pb(pi(N - 1, inf));
	D[N - 1] = 0;

	rer(i, N - 1, 0) {
		D[i] = D[i + 1];
		if(A[i] <= A[i + 1]) {
			int cnt = 0;
			while(A[i + 1] >= A[i] * (1ll << (2 * cnt + 2))) cnt++;
			if(cnt) stack.pb(pi(i, cnt));
		}
		else {
			int cnt = 0;
			while(A[i + 1] * (1ll << (2 * cnt)) < A[i]) cnt++;
			while(true) {
				pi p = stack.back(); stack.pop_back();
				if(p.sec < cnt) {
					D[i] += 1ll * (p.fst - i) * (cnt - p.sec) * 2;
					cnt -= p.sec;
				}
				else {
					D[i] += 1ll * (p.fst - i) * cnt * 2;
					stack.pb(pi(p.fst, p.sec - cnt));
					break;
				}
			}
		}
	}
}

void solve() {
	cin >> N;
	rep(i, 0, N) cin >> A[i];
	pre(A, D);
	reverse(A, A + N);
	pre(A, RD);
	reverse(RD, RD + N);
	// debug(vl(D, D + N));
	// debug(vl(RD, RD + N));
	ll res = linf;
	rep(i, 0, N) {
		if(i == 0) MIN(res, D[0]);
		else if(i == N - 1) MIN(res, RD[N - 1] + 1);
		else {
			MIN(res, RD[i] + D[i + 1] + 1);
		}
	}
	cout << res << "\n";
}

