const ll INF = 1000000000000000;

int main()
{
    int n;
    cin >> n;
    ll a[200003];
    for(int i = 0; i < n; i++) cin >> a[i];
    ll l[200003], r[200003];
    l[0] = l[1] = 0;
    set<P> st;
    for(int i = 2; i <= n; i++){
        l[i] = l[i - 1];
        if(a[i - 2] < a[i - 1]){
            ll b = 0;
            ll s = a[i - 2];
            while(s < a[i - 1]){
                s *= 4;
                b += 2;
            }
            int t = i - 1;
            while(st.size()){
                auto itr = --st.end();
                P p = *itr;
                st.erase(itr);
                if(p.second > b){
                    l[i] += (t - p.first) * b;
                    st.insert(P(p.first, p.second - b));
                    t = p.first;
                    break;
                }
                l[i] += (t - p.first) * b;
                t = p.first;
                b -= p.second;
            }
            if(b) l[i] += b * t;
        }
        else{
            ll b = 0;
            ll s = a[i - 1];
            while(s <= a[i - 2]){
                s *= 4;
                b += 2;
            }
            b -= 2;
            if(b) st.insert(P(i - 1, b));
        }
    }
    for(int i = 0; i <= n; i++) l[i] += i;
    st.clear();
    r[n] = r[n - 1] = 0;
    for(int i = n - 2; i >= 0; i--){
        r[i] = r[i + 1];
        if(a[i + 1] < a[i]){
            ll b = 0;
            ll s = a[i + 1];
            while(s < a[i]){
                s *= 4;
                b += 2;
            }
            int t = n - i - 1;
            while(st.size()){
                auto itr = st.begin();
                P p = *itr;
                st.erase(itr);
                if(p.second > b){
                    r[i] += (t - p.first) * b;
                    st.insert(P(p.first, p.second - b));
                    t = p.first;
                    break;
                }
                r[i] += (t - p.first) * b;
                t = p.first;
                b -= p.second;
            }
            if(b) r[i] += b * t;
        }
        else{
            ll b = 0;
            ll s = a[i];
            while(s <= a[i + 1]){
                s *= 4;
                b += 2;
            }
            b -= 2;
            if(b) st.insert(P(n - i - 1, b));
        }
    }
    ll ans = INF;
    for(int i = 0; i <= n; i++) ans = min(ans, l[i] + r[i]);
    cout << ans << endl;
}

