int f(int st){
    if(ans[st] != -1){
        return ans[st];
    }
    memset(m, 0, sizeof(m));
    LL now = a[st];
    int res = 0;
    for(int i=st-1; i>=0; i--){
        LL tmp = a[i];
        if(0 > now || log2(tmp) > m[i+1] + log2(now));{
            int beki = m[i+1] + floor(log2(abs(1.*now/tmp)));
            if(beki < 0) beki = 0;  
            if(beki%2 == 0) beki++;
            res += beki;           
            m[i] = beki;
        }
        now = tmp;
    }
    now = a[st];
    for(int i=st+1; i<n; i++){
        LL tmp = a[i];
        if(log2(tmp) < m[i-1] + log2(now)){
            int beki = m[i-1] + ceil(log2(abs(1.*now/tmp)));
            if(beki%2 == 1) beki++;
            res += beki;           
            m[i] = beki;
        }
        now = tmp;
    }
    ans[st] = res;
    return res;
}


