    for (size_t i=k; i-->1;) {
      intmax_t left = A[i-1];
      intmax_t right = A[i];
      if (left <= right) continue;
      left = -left;
      right = -right;
      intmax_t d = (left+right-1) / left;
      intmax_t n = 1;
      while (n < d) {
        n <<= 2;
        acc += 2;
      }
      res += acc;
    }
  }
  {
    // positive
    intmax_t acc = 0;
    for (size_t i=k; i+1<A.size(); ++i) {
      intmax_t left = A[i];
      intmax_t right = A[i+1];
      if (left <= right) continue;
      intmax_t d = (left+right-1) / right;
      intmax_t n = 1;
      while (n < d) {
        n <<= 2;
        acc += 2;
      }
      res += acc;
    }
  }
  return res;
}

int main() {
  size_t N;
  scanf("%zu", &N);

  std::vector<intmax_t> A(N);
  for (size_t i=0; i<N; ++i)
    scanf("%jd", &A[i]);

  if (std::is_sorted(A.begin(), A.end()))
    return puts("0"), 0;

  size_t lb = 0;
  size_t ub = N;
  intmax_t res = intmax_t(1)<<62;
  while (ub-lb > 1) {
    size_t mid = (lb+ub)>>1;
    intmax_t left = doit(A, mid);
    intmax_t right = doit(A, mid+1);
    res = std::min({res, left, right});
    ((left < right)? ub:lb) = mid;
  }
  printf("%jd\n", res);
}

