vector<llint>ryu(vector<llint>a){
	llint n=a.size(),i,ans=0;
	vector<llint>ret(n+1);
	stack<pair<int,int>>sta;
	sta.push(mp(n-1,mod));
	for(i=n-2;i>=0;i--){
