class Segtree {
private:
    int N;
    vector<long long int> v;

public:
    Segtree(int n) {
        N = 1;
        while(N < n) N *= 2;
        v = vector<long long int>(2 * N, 0);
    }

    // update k th element
    void update(int k, int a) {
        k += N-1; // leaf
        v[k] = a;
        while(k > 0) {
            k = (k - 1) / 2;
            v[k] = v[2 * k + 1] + v[2 * k + 2];
        }
    }
    // sum [a, b)
    int query(int a, int b) { return query(a, b, 0, 0, N); }

    int query(int a, int b, int k, int l, int r) {
        if(r <= a or b <= l) return 0;
        if(a <= l and r <= b) return v[k];
        int m = (l + r) / 2;
        return (query(a, b, k*2+1, l, m) + query(a, b, k*2+2, m, r));
    }

    void print()
    {
    	for(int i = 0; i < 2 * N; i++){
    		cout << v[i] << " ";
    	}
    	cout << endl;
    }
};

int main()
{
	int n;
	cin >> n;
	long long int a[200001];
	bool sorted = true;
	for(int i = 0; i < n; i++){
		cin >> a[i];
		if(i > 0 && a[i - 1] > a[i]) sorted = false;
	}
	if(sorted) {
		cout << 0 << endl;
		return 0;
	}
	// a[i]がa[i - 1]よりも大きくなるために必要な最小奇数回数、最小偶数回数
	int odd[200001] = {};
	int even[200001] = {};
	for(int i = 1; i < n; i++){
		long long int tmp1 = a[i - 1];
		long long int tmp2 = a[i];
		int cnt = 0;
		while(tmp1 > tmp2){
			cnt++;
			tmp2 *= 2;
		}
		if(cnt % 2 == 0){
			odd[i] = cnt + 1;
			even[i] = cnt;
		} else {
			odd[i] = cnt;
			even[i] = cnt + 1;
		}
	}
	// odd、evenでそれぞれ和をとる
	// oddは右から左、evenは左から右
	long long int oddsum[200001] = {};
	long long int evensum[200001] = {};
	Segtree oddtree(n);
	Segtree eventree(n);
	for(int i = 1; i < n; i++){
		evensum[i] += evensum[i - 1] + even[i];
		eventree.update(i, evensum[i]);

	}
	for(int i = n - 2; i >= 0; i--){
		oddsum[i] = oddsum[i + 1] + odd[i];
		oddtree.update(i, oddsum[i]);
	}
	long long int ans = mod;
	for(int i = 0; i < n; i++){
		ans = min(ans, oddtree.query(0, i) - i * oddsum[i] + 1 + eventree.query(i + 1, n) - (n - i - 1) * evensum[i]);
	}
	cout << ans << endl;
}

