#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

ll N, A[200000];

const double EPS = 1e-10;
double l2;

vector<ll> solve(vector<double> &a) {
  vector<double> x(a);

  vector<ll> ret(N);
  ll cnt = 0;

  stack<ll> stk;
  for (int i = N - 1; i >= 0; i--) {
    ret[i] = cnt;
    if (i == 0) break;

    stk.push(i + 1);
    while (x[i - 1] > x[i] + EPS) {
      ll k;
      while (1) {
        k = stk.top();
        if (k == N) break;
        stk.pop();
        if (x[k - 1] + l2 * 2 < x[k] + EPS) break;
      }

      x[i] += l2 * 2;
      x[k - 1] += l2 * 2;
      stk.push(k);

      cnt += (k - i) * 2;
    }
  }

  return ret;
}

int main(void) {
  cin >> N;
  REP(i, 0, N) cin >> A[i];

  l2 = log(2);

  vector<double> a(N);
  REP(i, 0, N) a[i] = log(A[i]);

  vector<ll> r = solve(a);

  reverse(a.begin(), a.end());
  REP(i, 0, N) a[i] += l2;
  vector<ll> l = solve(a);
  reverse(l.begin(), l.end());
  REP(i, 0, N) l[i] += i + 1;

  // REP(i, 0, N) cerr << l[i] << " " << r[i] << endl;

  ll ans = min(r[0], l[N - 1]);
  REP(i, 0, N - 1) {
    ans = min(ans, l[i] + r[i + 1]);
  }
  cout << ans << endl;
}

