int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    cin >> N;
    cnt1[1] = 1;
    for(int i = 1; i <= N; ++i){
        cin >> A[i];
    }

    stack<pll> st;
    st.push({linf, 1});

    for(int i = 2; i <= N; ++i){
        cnt1[i] = cnt1[i - 1] + 1;
        ll cp = A[i - 1];
        ll cnt = 0;

        if(cp < A[i]){
            while(cp < A[i]) cp *= 4, cnt += 2;

            ll pre = i;
            while(cnt != 0){
                pll p = st.top();
                st.pop();

                if(cnt <= p.first){
                    p.first -= cnt;
                    cnt1[i] += cnt * (pre - p.second);
                    cnt = 0;
                    if(p.first != 0) st.push(p);
                }else{
                    cnt1[i] += p.first * (pre - p.second);
                    cnt -= p.first;
                    pre = p.second;
                }
            }
        }else{
            cp = A[i];
            while(cp * 4 <= A[i - 1]) cp *= 4, cnt += 2;
            if(cnt != 0) st.push({cnt, i});
        }
    }

    while(!st.empty()) st.pop();
    st.push({linf, N});
    for(int i = N - 1; i >= 1; --i){
        cnt2[i] = cnt2[i + 1];
        ll cp = A[i + 1];
