int main() {
    int N;
    cin >> N;

    if (N == 1) {
        cout << 0 << endl;
        return 0;
    }

    ll A[N];
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
    }

    ll fore[N - 1], back[N - 1];
    for (int i = 0; i < N - 1; ++i) {
        fore[i] = 0;
        while (A[i] * mypow(4LL, fore[i]) < A[i + 1]) {
            ++fore[i];
        }

        if (fore[i] == 0) {
            fore[i] = -15;
            while (A[i] < A[i + 1] * mypow(4LL, -fore[i])) {
                ++fore[i];
            }
        }

        back[i] = 0;
        while (A[i] > A[i + 1] * mypow(4LL, back[i])) {
            ++back[i];
        }

        if (back[i] == 0) {
            back[i] = -15;
            while (A[i] * mypow(4LL, -back[i]) > A[i + 1]) {
                ++back[i];
            }
        }
    }

    ll fsum[N + 1], bsum[N + 1];

    fsum[0] = fsum[1] = 0;
    queue<pair<ll, ll>> que;
    que.push(mp(-1, -INF));

    for (int s = 0; s <= N - 2; ++s) {
        fsum[s + 2] = fsum[s + 1];
        ll k = fore[s];

        if (k < 0) {
            que.push(mp(s, k));
        } else {
            ll cur = s;
            while (true) {
                auto p = que.front();
                que.pop();

                fsum[s + 2] += (cur - p.first) * k * 2;
                k += p.second;
                cur = p.first;

                if (k <= 0) {
                    if (k < 0) {
                        p.second = k;
                        que.push(p);
                    }
                    break;
                }
            }
        }
    }

    queue<pair<ll, ll>> empty;
    swap(empty, que);

    bsum[N] = bsum[N - 1] = 0;
    que.push(mp(N - 1, -INF));
    for (int s = N - 2; s >= 0; --s) {
        bsum[s] = bsum[s + 1];
        ll k = back[s];

        if (k < 0) {
            que.push(mp(s, k));
        } else {
            ll cur = s;
            while (true) {
                auto p = que.front();
                que.pop();

                bsum[s] += (p.first - cur) * k * 2;
                k += p.second;
                cur = p.first;

                if (k <= 0) {
                    if (k < 0) {
                        p.second = k;
                        que.push(p);
                    }
                    break;
                }
            }
        }
    }

    ll ans = INF;

    for (int s = 0; s <= N; ++s) {
        ans = min(ans, fsum[s] + bsum[s] + s);
        // cout << s << ":" << fsum[s] << " " << bsum[s] << endl;
    }

    cout << ans << endl;
    return 0;
}

