struct RMaxQ {
    static const int N2 = 524288;
    int dat[N2];

    void init() {
        rep(i, N2) {
            dat[i] = 0;
        }
    }

    void updatem(int k) {
        k += N2 - 1;
        dat[k] -= 1;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = max(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    void update(int k, int a) {
        k += N2 - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = max(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    int query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)return -INF;
        if (a <= l && r <= b)return dat[k];
        else {
            int m = (l + r) / 2;
            int vl = query(a, b, k * 2 + 1, l, m);
            int vr = query(a, b, k * 2 + 2, m, r);
            return max(vl, vr);
        }
    }

};

RMaxQ rMaxQ1;
RMaxQ rMaxQ2;

void preCalc() {
    rMaxQ1.init();
    rMaxQ2.init();
    int prev = INF;
    for (int i = 1; i <= N; ++i) {
        int cnt = 1;
        int a = A[i - 1];
        while (a > prev) {
            prev *= 4;
            int R = i;//固定
            int can = 1;//動かす
            int cant = i + 1;
            while (cant - can > 1) {
                int m = (can + cant) / 2;
                if (rMaxQ1.query(m, R, 0, 0, rMaxQ1.N2) >= 1) {
                    can = m;
                } else {
                    cant = m;
                }
            }
            cnt += 2 * (i - can);
            rMaxQ1.updatem(can);
        }
        int aaa = 0;
        while (prev >= 4 * a) {
            aaa++;
            prev /= 4;
        }
        rMaxQ1.update(i, aaa);
        if (i == 1) {
            rMaxQ1.update(i, 1000000);
        }
        prev = a;
        X[i] = cnt + X[i - 1];
    }

    prev = INF;
    for (int i = N - 1; i >= 0; --i) {
        int cnt = 0;
        int a = A[i];
        while (a > prev) {
            prev *= 4;
            int L = i;//固定
            int can = N;//動かす
            int cant = i;
            while (can - cant > 1) {
                int m = (can + cant) / 2;
                if (rMaxQ2.query(L, m, 0, 0, rMaxQ2.N2) >= 1) {
                    if (i == 2)cerr << "a" << endl;
                    can = m;
                } else {
                    if (i == 2)cerr << "b" << endl;
                    cant = m;
                }
            }
            cnt += 2 * (can - i - 1);
            cerr << i << " " << can - i - 1 << endl;
            rMaxQ2.updatem(can - 1);
        }
        int aaa = 0;
        while (prev >= 4 * a) {
            aaa++;
            prev /= 4;
        }
        rMaxQ2.update(i, aaa);
        if (i == N) {
            rMaxQ2.update(i, 1000000);
        }
        prev = a;
        Y[i] = cnt + Y[i + 1];
    }
}

