vector<int> calc(){
	vector<int> res(n+1, 0);
	for (int i = 0; i < 16; i++)
		dp[n][i] = i;

	for (int i = n - 1; i > 0; i--){
		int p = 1, t = 1, c = 0;
		res[i] = 1e18;
		for(int j = 0; j < 16; j++){
			while((1.0*a[i+1]/p) < (1.0*a[i]/t)){
				t*=4;
				c++;
			}
			dp[i][j] = j + dp[i+1][min(15ll, c)] + (n - i) * max(0ll, c - 15);
			p *= 4;
			res[i] = min(res[i], dp[i][j]);
		}
	}
	return res;
}

