LL posi[200001];

int main() {
	cin >> N;
	REP(i, 0, N) {
		cin >> A[i];
	}

	vector<int> gaps;
	REP(i, 2, N + 1) {
		LL a = A[N - i];
		LL b = A[N - i + 1];
		while (a * 4 <= b) {
			gaps.push_back(N - i);
			a *= 4;
		}

		LL sum = 0;
		while (a > b) {
			b *= 4;
			int k = gaps.empty() ? N - 1 : gaps.back();
			if (!gaps.empty()) gaps.pop_back();
			sum += k - (N - i);
		}
		posi[i] += posi[i - 1] + 2 * sum;
	}

	reverse(A, A + N);
	gaps.clear();
	REP(i, 2, N + 1) {
		LL a = A[N - i];
		LL b = A[N - i + 1];
		while (a * 4 <= b) {
			gaps.push_back(N - i);
			a *= 4;
		}

		LL sum = 0;
		while (a > b) {
			b *= 4;
			int k = gaps.empty() ? N - 1 : gaps.back();
			if (!gaps.empty()) gaps.pop_back();
			sum += k - (N - i);
		}
		nega[i] += nega[i - 1] + 2 * sum;
	}

	LL mn = INFLL;
	REP(i, 0, N + 1) {
		mn = min(mn, nega[i] + posi[N - i] + i);
	}
