bool g(ll a,ll b,ll c,ll d){
	if(b == d)return a > c;
	if(b < d){
		while(b < d && a > c){
			c *= 4;
			d --;
		}
		return a > c;
	}
	else {
		while(b > d && a < c){
			a *= 4;
			b --;
		}
		return a > c;
	}
}

