void calc(vector<ll>& v, vector<ll>& r)
{
	ll mi = v[0];
	reps(i, 1, N) {
		if (mi < v[i]) {
			ll x = v[i] / mi;
			ll t = 0;
			if (x % 4) {
				x /= 4;
				t = 2;
			} 
			x -= x % 4;
			while (x > 1) {
				t+=2;
				x /= 4;
			}
			r[i+1] =  i * t + r[i];
		} else {
			r[i+1] = r[i];
		}
		mi = v[i];
	}
}

