#include <bits/stdc++.h>
using namespace std;
using lint = long long;
using pi = pair<int, int>;
const int MAXN = 500005;
const int mod = 998244353;

int n, a[MAXN];

vector<lint> solve(){
	vector<lint> dap;
	dap.push_back(0);
	dap.push_back(0);
	vector<pi> stk;
	for(int i=1; i<n; i++){
		int flr = 0;
		if(a[i-1] < a[i]){
			for(lint x = a[i-1]; x < a[i]; x *= 4) flr += 2;
		}
		else{
			for(lint x = a[i]; x * 4 <= a[i-1]; x *= 4) flr -= 2;
		}
		if(flr < 0){
			stk.emplace_back(flr, i);
			dap.push_back(dap.back());	
		}
		else{
			lint ret= dap.back();
			int prv = i;
			while(!stk.empty() && flr > 0 && stk.back().first < 0){
				int min_diff = min(-stk.back().first, flr);
				ret += (prv - stk.back().second) * min_diff;
				prv = stk.back().second;
				flr -= min_diff;
				stk.back().first += min_diff;
				if(stk.back().first == 0) stk.pop_back();
			}
			ret += prv * flr;
			if(flr > 0) stk.emplace_back(flr, i);
			dap.push_back(ret);
		}
	}
	assert(dap.size() == n + 1);
	return dap;
}


