	reverse(sol_sfx.begin(), sol_sfx.end());
	lint ret = 1e18;
	for(int i=0; i<=n; i++){
		ret = min(ret, sol_pfx[i] + i + sol_sfx[i]);
	}
	cout << ret << endl;
}

