Info positive_from[MAX_N], negative_from[MAX_N];

int main(int argc, char **argv) {
    std::cin >> N;

    for (int i = 1; i <= N; i++) {
        std::cin >> A[i];
    }

    if (N == 1) {
        std::cout << 0 << std::endl;
        return 0;
    }

    for (int i = N; 1 <= i; i--) {
        if (0 < A[i]) {
            positive_from[i].num = 0;
            positive_from[i].value = A[i];
        } else {
            positive_from[i].num = 1;
            positive_from[i].value = - A[i] * 2;
        }
        if (i < N) {
            positive_from[i].num += positive_from[i+1].num;
            long long tmp = positive_from[i+1].value;
            long long num = 0;
            while (tmp < positive_from[i].value) {
                tmp = - tmp * 2;
                num++;
            }
            positive_from[i].num += num * (N - i);
        }
    }

    for (int i = 1; i <= N; i++) {
        if (A[i] < 0) {
            negative_from[i].num = 0;
            negative_from[i].value = A[i];
        } else {
            negative_from[i].num = 1;
            negative_from[i].value = - A[i] * 2;
        }
        if (1 < i) {
            negative_from[i].num += negative_from[i-1].num;
            long long tmp = negative_from[i-1].value;
            long long num = 0;
            while (tmp > negative_from[i].value) {
                tmp = - tmp * 2;
                num++;
            }
            negative_from[i].num += num * (i - 1);
        }
    }

    long long ret = std::min(positive_from[1].num, negative_from[N].num);

    for (int i = 2; i <= N; i++) {
        ret = std::min(ret, positive_from[i].num + negative_from[i-1].num);
    }
    std::cout << ret << std::endl;


    return 0;
}

