                }
            }
            if(cnt>0){
                dp[i] += (n - 1 - i) * cnt;
            }
        }else{
            int cnt = 0;
            ll ai = a[i];
            while(ai*4 <= a[i+1]){
                cnt++;
                ai *= 4;
            }
            if(cnt>0){
                s.push(P(i,cnt));
            }
        }
    }
