void dbl(deque<int>&deq,int &num,int n){
	deq.back()*=4;
	int p=deq.size()-1;
	while(p&&deq[p-1]<deq[p]){
		p--;
		deq[p-1]*=4;
	}
	if(p==0){
		num+=n*2;
	}
	else{
		num+=(deq.size()-p)*2;
	}
}


