using namespace std;

typedef pair<int, int> pii;

const int MN = 200010;

int N;
int A[MN], D[MN], dp1[MN], dp2[MN];
vector<pii> seg;

void solve(int *dp) {
    seg.clear();

    dp[N - 1] = 0;
    seg.push_back(pii(N - 1, N - 1));
    for(int i = N - 2; i >= 0; i--) {
        dp[i] = dp[i + 1];

        if(A[i + 1] < A[i]) {
            int p = 1;
            int cnt = 0;
            while(1LL * p * A[i + 1] < A[i]) {
                cnt++;
                p *= 4;
            }

            pii tmp = pii(i, i);
            while(seg.size()) {
                if(cnt < D[ seg.back().first ]) {
                    D[ seg.back().first ] -= cnt;
                    break;
                }
                dp[i] += (cnt - D[ seg.back().first ]) * (seg.back().second - seg.back().first + 1);
                cnt -= D[ seg.back().first ];
                D[ seg.back().first ] = 0;
                tmp.second = seg.back().second;
                seg.pop_back();
            }
            seg.push_back(tmp);
        }
        else seg.push_back(pii(i, i));
    }
}

int main() {
    scanf("%d", &N);

    for(int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
    }
    for(int i = 1; i < N; i++) {
        int p = 4;
        while(1LL * p * A[i - 1] <= A[i]) {
            D[i]++;
            p *= 4;
        }
    }

    solve(dp1);

    reverse(A, A + N);
    for(int i = 1; i < N; i++) {
        int p = 4;
        while(1LL * p * A[i - 1] <= A[i]) {
            D[i]++;
            p *= 4;
        }
    }

    solve(dp2);

    int ans = 1e9;
    for(int i = 0; i <= N; i++) {
        ans = min(ans, 2 * dp1[i] + 2 * dp2[N - i] + i);
    }
    printf("%d", ans);
}

