std::pair<std::vector<intmax_t>, std::vector<intmax_t>> doit(const std::vector<intmax_t>& A) {
  size_t N = A.size();
  std::vector<intmax_t> neg(N+1);
  {
    // negative
    for (size_t i=N; i-->1;) {
      intmax_t left = A[i-1];
      intmax_t right = A[i];
      left = -left;
      right = -right;
      if (left <= right) {
        continue;
      }
      intmax_t d = (left+right-1) / left;
      intmax_t n = 1;
      while (n < d) {
        n <<= 2;
        neg[i+1] += 2;
      }
    }
  }
  std::vector<intmax_t> pos(N+1);
  {
    // positive
    for (size_t i=0; i+1<N; ++i) {
      intmax_t left = A[i];
      intmax_t right = A[i+1];
      if (left <= right) {
        continue;
      }
      intmax_t d = (left+right-1) / right;
      intmax_t n = 1;
      while (n < d) {
        n <<= 2;
        pos[i] += 2;
      }
    }
  }

  for (size_t i=0; i<=N; ++i)
    fprintf(stderr, "%jd%c", neg[i], i<N? ' ':'\n');
  for (size_t i=0; i<=N; ++i)
    fprintf(stderr, "%jd%c", pos[i], i<N? ' ':'\n');

  for (size_t i=1; i<=N; ++i) {
    neg[i] *= N-i;
    neg[i] += neg[i-1];
  }
  for (size_t i=N+1; i-->1;) {
    pos[i-1] *= i;
    pos[i-1] += pos[i];
  }

  for (size_t i=0; i<=N; ++i)
    fprintf(stderr, "%jd%c", neg[i], i<N? ' ':'\n');
  for (size_t i=0; i<=N; ++i)
    fprintf(stderr, "%jd%c", pos[i], i<N? ' ':'\n');

  return {neg, pos};
}

int main() {
  size_t N;
  scanf("%zu", &N);

  std::vector<intmax_t> A(N);
  for (size_t i=0; i<N; ++i)
    scanf("%jd", &A[i]);

  if (std::is_sorted(A.begin(), A.end()))
    return puts("0"), 0;

  auto np = doit(A);
  intmax_t res = intmax_t(1)<<60;
  for (size_t i=0; i<=N; ++i) {
    intmax_t cur = i;
    cur += np.first[i];
    cur += np.second[i];
    res = std::min(res, cur);
  }
  printf("%jd\n", res);
}

