vector<ll> getDP(const vector<ll> a) {
	const int n = (int) a.size();
	vector<ll> dp(n + 1, 0);

	vector<Range> ranges;

	ranges[0].last;

	for (int i = n - 1; i >= 0; --i) {
		dp[i] = dp[i+1];
		ranges.push_back( { a[i], a[i], 1LL });

		// cerr << "i = " << i << endl;

		while (ranges.size() > 1) {
			const int k = (int) ranges.size();

			if (ranges[k - 1].last <= ranges[k - 2].first)
				break;
			while (ranges[k - 1].last > ranges[k - 2].first) {
				ranges[k - 2].first <<= 2;
				// cerr << ranges[k-2].first << endl;
				ranges[k - 2].last <<= 2;
				dp[i] += ranges[k - 2].sz;
			}
			ranges[k - 2].first = ranges[k - 1].first;
			ranges[k - 2].sz += ranges[k - 1].sz;
			ranges.pop_back();
		}
		// cerr << "sz = " << ranges.size() << endl;
		// cerr << "sum = " << sum << endl;
	}

	return dp;
}

