const int N = 2e5 + 9;
ll mem[N][64];
vector<ll> v;
bool valid(ll x, ll y) {
	return (LLONG_MIN / y <= x && x <= LLONG_MAX / y);
}
ll power(int cnt) {
	ll val = (1LL << cnt);
	return ((cnt & 1) ? -val : val);
}
ll solve(int idx, int cntLast) {
	if (idx == sz(v))
		return 0;
	ll &rt = mem[idx][cntLast];
	if (~rt)
		return rt;
	rt = INF;
	ll last = LLONG_MIN;
	if (idx)
		last = v[idx - 1] * power(cntLast);
	for (int cnt = 0; cnt <= 60; cnt++) {
		ll cur = power(cnt);
		if (valid(cur, v[idx])) {
			cur *= v[idx];
			if (cur >= last)
				rt = min(rt, cnt + solve(idx + 1, cnt));
		}
	}
	return rt;
}

int main() {
	run();
	memset(mem, -1, sizeof(mem));
	int n;
	cin >> n;
	v = vector<ll>(n);
	for (auto &it : v)
		cin >> it;
	ll res = solve(0, 0);
	if (res == INF)
		res = -1;
