const int MAXN = 220000;

int n;
ll a[MAXN];
ll dpr[MAXN];
ll dpl[MAXN];
ll go[MAXN];

void solve(ll *a, int n, ll *dp) {
	for (int i = 0; i + 1 < n; ++i) {
		if (a[i] <= a[i + 1]) {
			int cnt = 0;
			ll cur = a[i];
			while (cur * 4 <= a[i + 1])
				++cnt, cur *= 4;
			go[i] = cnt * 2;
		}
		else {
			int cnt = 0;
			ll cur = a[i + 1];
			while (cur < a[i])
				cur *= 4, --cnt;
			go[i] = cnt * 2;
		}
		go[i] = -go[i];
	}
	dp[n - 1] = 0;
	vector<tuple<int, ll, ll>> vv;
	for (int i = n - 2; i >= 0; --i) {
		ll d = go[i];
		if (d <= 0) {
			vv.emplace_back(i + 1, d, d * (n - 1 - i));
			dp[i] = dp[i + 1];
		}
		else {
			ll sum = d * (n - 1 - i);
			ll cur = d;
			int fl = 0;
			while (!vv.empty()) {
				int r; ll s, dd;
				tie(r, dd, s) = vv.back();
				vv.pop_back();
				if (cur + dd <= 0) {
					fl = 1;
					vv.emplace_back(r, cur + dd, sum + s);
					dp[i] = dp[r] + (sum + s) + (cur + dd) * (n - r);
					break;
				}
				else {
					sum += s;
					cur += dd;
				}
			}
			if (!fl) {
				vv.emplace_back(n - 1, cur, sum);
				dp[i] = sum;
			}
		}
	}
}

