ll solve_mini(int n, vector<ll>& a) {
    vector<ll> L(n, 0);
    vector<ll> v;
    for (int i = 0; i < n; i++) {
        if (i > 0) L[i] += L[i - 1];
        L[i]++;
        v.push_back(a[i]);
        int sz = v.size();
        for (int j = sz - 1; j > 0; j--) {
            while (v[j - 1] < v[j]) {
                v[j - 1] *= 4;
                L[i] += 2;
            }
        }       
    }

    vector<ll> R(n, 0);
    v.clear();
    for (int i = n - 1; i >= 0; i--) {
        if (i < n - 1) R[i] += R[i + 1];
        v.push_back(a[i]);
        int sz = v.size();
        for (int j = sz - 1; j > 0; j--) {
            while (v[j - 1] < v[j]) {
                v[j - 1] *= 4;
                R[i] += 2;
            }
        } 
    }

    ll ans = min(L[n - 1], R[0]);
    for (int i = 1; i < n; i++) {
        ans = min(ans, L[i - 1] + R[i]);
    }
    return ans;
}

template <typename T>
struct LazySegmentTree {
    int n;
    vector<T> data;
    vector<T> lazy;
    T INITIAL_DATA_VALUE;
    T INITIAL_LAZY_VALUE;

    //使うときは、この3つを適宜変更する
    static T merge(T x, T y);
    void updateNode(int k, T x);
    void apply(int k, int seg_len);

    void init(int size, T initial_data_value, T initial_lazy_value) {
        n = 1;
        INITIAL_DATA_VALUE = initial_data_value;
        INITIAL_LAZY_VALUE = initial_lazy_value;
        while (n < size) n *= 2;
        data.resize(2 * n - 1, INITIAL_DATA_VALUE);
        lazy.resize(2 * n - 1, INITIAL_LAZY_VALUE);
    }

    LazySegmentTree(int size, T initial_data_value, T initial_lazy_value) {
        init(size, initial_data_value, initial_lazy_value);
    }

    LazySegmentTree(int size, T initial_value) {
        init(size, initial_value, initial_value);
    }

    T getLeaf(int k) {
        return data[k + n - 1];
    }

    void eval(int k, int l, int r) {
        if (lazy[k] == INITIAL_LAZY_VALUE) return;
        apply(k, r - l);
        if (r - l > 1) {
            updateNode(2 * k + 1, lazy[k]);
            updateNode(2 * k + 2, lazy[k]);
        }
        lazy[k] = INITIAL_LAZY_VALUE;
    }

    //区間[a, b)に対する更新
    //k:節点番号, [l, r):節点に対応する区間
    void update(int a, int b, T x, int k, int l, int r) {
        eval(k, l, r);
        //[a, b)と[l, r)が交差しない場合
        if (r <= a || b <= l) return;
        //[a, b)が[l, r)を含む場合、節点の値
        if (a <= l && r <= b) {
            updateNode(k, x);
            eval(k, l, r);
        } else {
            update(a, b, x, k * 2 + 1, l, (l + r) / 2);
            update(a, b, x, k * 2 + 2, (l + r) / 2, r);
            data[k] = merge(data[2 * k + 1], data[2 * k + 2]);
        }
    }

    void update(int a, int b, T x) {
        update(a, b, x, 0, 0, n);
    }

    //区間[a, b)に対するクエリに答える
    //k:節点番号, [l, r):節点に対応する区間
    T query(int a, int b, int k, int l, int r) {
        eval(k, l, r);
        //[a, b)と[l, r)が交差しない場合
        if (r <= a || b <= l) return INITIAL_DATA_VALUE;
        //[a, b)が[l, r)を含む場合、節点の値
        if (a <= l && r <= b) return data[k];
        else {
            //二つの子をマージ
            T vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return merge(vl, vr);
        }
    }

    //外から呼ぶ用
    T query(int a, int b) {
        return query(a, b, 0, 0, n);
    }
};

//使うときは以下3つを変更
template <typename T>
T LazySegmentTree<T>::merge(T x, T y) {
    return x + y;
}

template <typename T>
void LazySegmentTree<T>::updateNode(int k, T x) {
    lazy[k] = x;
}

template <typename T>
void LazySegmentTree<T>::apply(int k, int seg_len) {
    data[k] = lazy[k] * seg_len;
}

ll solve(int n, vector<ll>& a) {
    LazySegmentTree<ll> lst1(n, 0, 0);
    vector<ll> L(n, 0);
    for (int i = 0; i < n; i++) {
        if (i > 0) L[i] += L[i - 1];
        L[i]++;
        if (i > 0) {
            ll cnt = lst1.query(i - 1, i);
            if (a[i - 1] >= a[i]) {
                ll tmp = a[i];
                while (tmp < a[i - 1]) {
                    tmp *= 4;
                    cnt -= 2;
                }
                lst1.update(i, i + 1, cnt);
                continue;
            } else {
                ll tmp = a[i - 1];
                while (tmp < a[i]) {
                    tmp *= 4;
                    cnt += 2;
                }
            }

            int ng = -1, ok = i;
            while (ok - ng > 1) {
                int mid = (ok + ng) / 2;
                ll foo = lst1.query(mid, mid + 1);
                if (foo == cnt) {
                    if (a[mid] < a[i]) ok = mid;
                    else ng = mid;
                } else {
                    if (foo < cnt) ok = mid;
                    else ng = mid;                    
                }
            }

            int ok2 = i, ng2 = -1;
            while (ok2 - ng2 > 1) {
                int mid = (ok2 + ng2) / 2;
                ll foo = lst1.query(mid, mid + 1);
                if (foo < cnt) ok2 = mid;
                else ng2 = mid;
            }

            if (ok2 < i) {
                ll hoge = lst1.query(ok2, i);
                L[i] += (ok2 - ok) * 2 + cnt * (i - ok2) - hoge;
                lst1.update(ok2, i, cnt);
                lst1.update(ok, ok2, cnt + 2);
            }
        }
    }

    LazySegmentTree<ll> lst2(n, 0, 0);
    vector<ll> R(n, 0);
    for (int i = n - 1; i >= 0; i--) {
        if (i < n - 1) {
            R[i] += R[i + 1];
            ll cnt = lst2.query(i + 1, i + 2);
            if (a[i + 1] >= a[i]) {
                ll tmp = a[i];
                while (tmp < a[i + 1]) {
                    tmp *= 4;
                    cnt -= 2;
                }
                lst2.update(i, i + 1, cnt);
                continue;
            } else {
                ll tmp = a[i + 1];
                while (tmp < a[i]) {
                    tmp *= 4;
                    cnt += 2;
                }
            }

            int ok = i, ng = n;
            while (ng - ok > 1) {
                int mid = (ok + ng) / 2;
                ll foo = lst2.query(mid, mid + 1);
                if (foo == cnt) {
                    if (a[mid] < a[i]) ok = mid;
                    else ng = mid;
                } else {
                    if (foo < cnt) ok = mid;
                    else ng = mid;                    
                }
            }

            int ok2 = i, ng2 = n;
            while (ng2 - ok2 > 1) {
                int mid = (ok2 + ng2) / 2;
                ll foo = lst2.query(mid, mid + 1);
                if (foo < cnt) ok2 = mid;
                else ng2 = mid;
            }

            if (i < ok2) {
                ll hoge = lst2.query(i + 1, ok2 + 1);
                R[i] += (ok - ok2) * 2 + cnt * (ok2 - i) - hoge;
                lst2.update(i + 1, ok2 + 1, cnt);
                lst2.update(ok2 + 1, ok + 1, cnt + 2);
            }
        }
    }

    ll ans = min(L[n - 1], R[0]);
    for (int i = 1; i < n; i++) {
        ans = min(ans, L[i - 1] + R[i]);
    }
    return ans;
}

