int costL[200001];
int costR[200001];

void calc(int *a, int *f) {
	int i, j;

	for (i = 0; i < n; i++) {
		int x = 0;
		int sumX = 0;
		for (j = i + 1; j < n; j++) {
			x = max(x + a[j], 0LL);
			sumX += x;
		}
		f[i] = sumX;
	}
}

void reverse(int *a, int n) {
	int l = 0, r = n - 1;
	while (l < r) {
		swap(a[l], a[r]);
		l++; r--;
	}
}

signed main() {
	int i, j;

	cin >> n;
	rep(i, n) cin >> a[i];

	for (i = 1; i < n; i++) {
		int t = a[i];
		while (t < a[i - 1]) {
			t *= 4;
			b[i]++;
		}
		while (t >= a[i - 1] * 4) {
			t /= 4;
			b[i]--;
		}
	}

	for (i = n - 2; i >= 0; i--) {
		int t = a[i];
		while (t < a[i + 1]) {
			t *= 4;
			c[i]++;
		}
		while (t >= a[i + 1] * 4) {
			t /= 4;
			c[i]--;
		}
	}
	reverse(c, n);

	calc(c, costL);
	calc(b, costR);

