			ans += at_least;
			long long new_dg_2 = at_least;

			long long rem_2 = last_dg_2 - at_least;   // <= 32
			long double x = last_ms;
			while (rem_2 > 0) { x *= 2; rem_2--; }

			long double y = ms[i];
			while (y < x) {
				ans += 2;
				new_dg_2 += 2;
				y *= 4LL;
			}

			last_dg_2 = new_dg_2;
			last_ms = save_msi;

			if (fast_calc)
				if (ans >= mn)
					return ans;
		}

	return ans;
}

map<int, long long> solve_rev, solve_forw;

long long calc(int x, int fast_calc = 0) {
	if (x < 0) x = 0;
	if (x > n) x = n;

	// >= for indexes [0...x-1]   + rotate
	int ms_len = 0;
	for (int i = x - 1; i >= 0; i--)
		ms[ms_len++] = s[i];
	long long ans = 0;
	if (solve_rev.find(x) != solve_rev.end())
		ans = solve_rev[x];
	else {
		ans = solve(ms, ms_len, fast_calc);
		solve_rev[x] = ans;
	}
	ans += x; // rotate

	if (fast_calc)
		if (ans >= mn)
			return ans;

	// <= for indexes [x...n)
	ms_len = 0;
	for (int i = x; i < n; i++)
		ms[ms_len++] = s[i];
	if (solve_forw.find(x) != solve_forw.end())
		ans += solve_forw[x];
	else {
		solve_forw[x] = solve(ms, ms_len, fast_calc);
		ans += solve_forw[x];
	}

	return ans;
}

long long my_min(long long lst, long long new_val, int pp) {
	if (lst > new_val)
		min_pos = pp;
	return min(lst, new_val);
}

int main() {
	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

	clock_t t_BG = clock();

	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%d", &s[i]);

	mn = LL_INF;

	if (n < 7000) {
		for (int i = 0; i <= n; i++)
			mn = min(mn, calc(i));
		cout << mn;
		return 0;
	}

	int down = 0, up = n+1;
	while (up > down + 3) {
		int t1 = down + (up - down) / 3;
		int t2 = up - (up - down) / 3;
		long long ans1 = calc(t1);
		long long ans2 = calc(t2);
		mn = my_min(mn, ans1, t1);
		mn = my_min(mn, ans2, t2);

		if (ans1 < ans2)
			up = t2;
		else
			down = t1;
	}
	for (int i = down - 20; i <= down + 20; i++)
		if (i >= 0 && i <= n) {
			mn = my_min(mn, calc(i, 1), i);
			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}

	for (int i = 0; i < 20; i++) {
		mn = my_min(mn, calc(i, 1), i);
		mn = my_min(mn, calc(n-i, 1), n-i);

		mn = my_min(mn, calc(n / 2 - i, 1), n/2 - i);
		mn = my_min(mn, calc(n / 2 + i, 1), n / 2+ i);

		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;
	}

	int move = 1234;
	while (move > 1) {
		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;

		for (int i = min_pos + move; i <= n; i += move) {
			long long val = calc(i, 1);
			if (val < mn) {
				mn = val;
				min_pos = i;
				break;
			}
			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}
		for (int i = min_pos - move; i >= 0; i -= move) {
			long long val = calc(i, 1);
			if (val < mn) {
				mn = val;
				min_pos = i;
				break;
			}
			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}
		move /= 2;
	}

	for (int i = min_pos - 20; i <= min_pos + 20; i++)
		if (i >= 0 && i <= n) {
			mn = my_min(mn, calc(i, 1), i);
			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}

	while (1)
		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) < TL) {
			mn = min(mn, calc(rand() % n, 1));
		}
		else
			break;
	cout << mn;
	return 0;
}

