vector<long long> solve(vector<long long>T) {
	vector<long long> ans; long long sum = 0; ans.push_back(0); ans.push_back(0);

	for (int i = T.size() - 2; i >= 0; i--) {
		long long E = 0, B = T[i + 1]; while (T[i] > B) { E++; B *= 4; }

		for (int j = 0; j < E; j++) {
			for (int k = i + 1; k < T.size(); k++) {
				if (T[k - 1] <= T[k]) break;
				if (T[k] * 4 >= (1LL << 32)) { sum += (long long)(T.size() - k); break; }
				T[k] *= 4; sum++;
			}
		}
		ans.push_back(sum);
	}
	return ans;
}

