typedef pair<int,int> P;

int N, A[200005];

vector<int> build(int flag){

  vector<P> v;

  int sum = 0;

  vector<int> res;

  int a0 = 0;

  if( !flag && A[N-1] < 0 ) a0++;
  if( flag && A[N-1] > 0 ) a0++;

  res.push_back( a0 );

  for(int i=N-1;i>0;i--){

    int a = A[i-1], b = A[i];

    if( flag ){

      a *= 2;

      b *= 2;

      sum++;

    }

    if( a > b ){

      int cnt = 0;

      while( a > b ){

	b *= 4;
	cnt++;

	if( (int)v.size() ){

	  if( v[v.size()-1].first == 1 ){

	    v.pop_back();

	    if( v.size() && v[v.size()-1].first == 0 ){
	      v[v.size()-1].second++;
	    }
	    else v.push_back( P( 0, 1 ) );

	  }
	  else if( v[v.size()-1].first != 0 ){
	    v[v.size()-1].first--;
	  }
	  else{

	    int S = v[v.size()-1].second;

	    sum += S * 2;

	    v.pop_back();

	    if( v.size() ){
	      v.pop_back();
	      S++;
	    }

	    if( v.size() && v[v.size()-1].first == 0 ){
	      v[v.size()-1].second += S;
	    }else v.push_back( P( 0, S ) );

	  }

	}

      }

      sum += cnt * 2;

      if( (int)v.size() && v[v.size()-1].first == 0 ){
	v[v.size()-1].second++;
      }
      else v.push_back( P( 0, 1 ) );

    }
    else{

      int cnt = 0;

      while( a <= b ){

	a *= 4;

	cnt++;

      }

      if( (int)v.size() && v[v.size()-1].first == cnt-1 && cnt - 1 == 0 ){
	v[v.size()-1].second++;
      }else v.push_back( P( cnt-1, 1 ) );

    }

    /*    if(flag){

      cout<<i<<endl;

      for(P p : v) cout<<p.first<<' '<<p.second<<endl;

      cout<<endl;

      }*/

    res.push_back( sum );

  }

  return res;  
}

