bool over(ll a, ll b){
	return abs(a) > (5e18 / abs(b));
}

ll f(int id, int ant){
	if(id == n){
		return 0;
	}
	if(dp[id][ant] != -1) return dp[id][ant];

	ll &ans = dp[id][ant];
	ans = 1e18;
	for(int i = 0; i < 64; i++){
		if(!over(v[id], p2[i]) && ((v[id] * p2[i]) >= (v[id-1] * p2[ant]))){
			ans = min(ans, f(id+1, i) + i);
		}
		else if(over(v[id], p2[i])) break;
	}
	return ans;
}

