int n;

vector<ll> solve(vector<ll> v) {
    vector<vector<ll>> dp(n, vector<ll>(30, 0));
    vector<ll> ret(n, inf * inf);
    for(int i = n - 1; i >= 0; i--) {
        __int128 num1 = v[i];
        for(int j = 0; j < 30; j++) {
            if(i == n - 1) {
                dp[i][j] = 2 * j;
                continue;
            }
            __int128 num2 = v[i + 1];
            int cnt = 0;
            while(num1 > num2) {
                cnt++;
                num2 *= 4;
            }
            if(cnt < 30) dp[i][j] = 2 * j + dp[i + 1][cnt];
            else dp[i][j] = 2 * j + dp[i + 1][29] + 2 * (ll)(cnt - 29) * (n - i - 1);
            num1 *= 4;
            ret[i] = min(ret[i], dp[i][j]);
        }
    }
    return ret;
}

