// ll xs[200000+10]; // xs[i]: vs[i]に何回-2を掛けたらvs[i-1]以上になるか
// ll ys[200000+10]; // ys[i]: nvs[i]に何回-2を掛けたらnvs[i+1]以下になるか

ll memo1[200000+10][20];
ll memo2[200000+10][20];

ll go1(int pos, int x) {
  assert(pos > 0);
  if(x > 16) {
    ll res = go1(pos, 16);
    res += (x-16LL) * (n-pos);
    return res;
  }
  if(pos >= n) {
    return 0;
  }
  ll &res = memo1[pos][x];
  if(res < 0) {
    ll prev = vs[pos-1] << x;
    ll cur = vs[pos];
    ll cnt = 0;
    while(prev > cur) {
      cur *= 4;
      cnt += 2;
    }
    res = cnt + go1(pos+1, cnt);
    // cerr << "go1 " << pos << " " << x << " " << res << " " << cnt << endl;
  }
  return res;
}

ll go2(int pos, int x) {
  assert(pos <= n-2);
  if(x > 16) {
    ll res = go2(pos, 16);
    res += (x-16LL) * (pos+1);
    return res;
  }
  if(pos < 0) {
    return 0;
  }
  ll &res = memo2[pos][x];
  if(res < 0) {
    ll next = nvs[pos+1] * (1LL << x);
    ll cur = nvs[pos];
    ll cnt = 0;
    while(cur > next) {
      cur *= 4;
      cnt += 2;
    }
    res = cnt + go2(pos-1, cnt);
    // cerr << "go2 " << pos << " " << x << " " << res << endl;
  }
  return res;
}


int main(void) {
  scanf("%d", &n);
  REP(i, n) {
    scanf("%lld", &vs[i]);
    nvs[i] = vs[i] * -2;
  }
  memset(memo1, -1, sizeof memo1);
  memset(memo2, -1, sizeof memo2);

  ll res = 1000000000000000000LL;
  for(int i = 0; i <= n; ++i) {
    // i番目からを正にする
    ll cur = i; // i番目より前には軒並み-2を掛ける
    cur += go1(i+1, 0); // 正側
    cur += go2(i-2, 0); // 負側
    // cerr << i << ":" << cur << endl;
    res = min(cur, res);
  }
  cout << res << endl;
  return 0;
}

