void func( int n , i64 *a , i64 *dp )
{
    dp[n] = 0 ;
    stack<int> st ;
    for(int i=n-1 ; i>=1 ; i--)
    {
        dp[i] = dp[i+1] ;
        if( a[i] <= a[i+1] )
        {
            st.push(i) ;
            continue ;
        }
        int c = howMuch(a[i],a[i+1]) ;
        for(int j=i+1; j<=n ; j++)
        {
            dp[i] += c ;
            a[j] *= p[c] ;
            if( st.empty() )
            {
                dp[i] += (n-j)*c ;
                break ;
            }
            if( st.top() == j )
            {
                c = howMuch(a[j],a[j+1]) ;
                if( c==0 )
                {
                    break ;
                }
                else st.pop() ;
            }
        }
    }
    return ;
}

