void solve(){
    i64 N;
    cin >> N;

    vector<i64> a(N);
    rep(i,0,N) cin >> a[i];

    vector<i64> pow4(31);
    pow4[0]=1;
    rep(i,1,pow4.size()) pow4[i]=pow4[i-1]*4;

    i64 size=40;
    vector<vector<i64>> memo1(N,vector<i64>(size));
    vector<vector<bool>> done1(N,vector<bool>(size));
    function<i64(i64,i64)> rec1=[&](i64 i,i64 x){
        assert(x<size);
        if(done1[i][x]) return memo1[i][x];
        done1[i][x]=true;
        if(i==N-1) return memo1[i][x]=0;
        if(x>15) return memo1[i][x]=rec1(i,15)+(N-i)*(x-15);
        i64 y=0;
        while(a[i]*pow4[x]>a[i+1]*pow4[y]) ++y;
        return memo1[i][x]=rec1(i+1,y)+y;
    };

    vector<vector<i64>> memo2(N,vector<i64>(size));
    vector<vector<bool>> done2(N,vector<bool>(size));
    function<i64(i64,i64)> rec2=[&](i64 i,i64 x){
        assert(x<size);
        if(done2[i][x]) return memo2[i][x];
        done2[i][x]=true;
        if(i==0) return memo2[i][x]=0;
        if(x>15) return memo2[i][x]=rec2(i,15)+(i+1)*(x-15);
        i64 y=0;
        while(a[i]*pow4[x]>a[i-1]*pow4[y]) ++y;
        return memo2[i][x]=rec2(i-1,y)+y;
    };

