    for (int i=1;i<N;i++) {
        float frac = (float) A[N-1-i]/ (float) A[N-i];
        //cout << frac << endl;
        if (frac<=1) B[i] = B[i-1];
        else {
            int k = 1;
            long long temp;
            while (pow(4,k)<frac) {
                k += 1;
                temp = pow(4,k);
                if (temp >= 1900000000) break;
            }
            B[i] = B[i-1] + 2*k*i;
        }
    }
    /*cout << "B : ";
