vector<ll> calc(ll n, vector<ll> &a){
    ll log = 16;
    vector dp(n, vector(log, 0LL));
    rep(j,0,log)dp[n-1][j] = j * 2;
    rrep(i,n-1, 0){
        if(a[i] < a[i+1]){
            ll t = 1;
            ll num = a[i+1] / a[i];
            ll p = 0;
            while(t <= num){
                p++;t *= 4;
            }
            p--;
            debug("1", a[i], a[i+1], p);

            rep(j,0,log){
                dp[i][j] = dp[i+1][max(0LL, j - p)] + j * 2;
            }
        }
        else{
            ll t = 1;
            ll num = (a[i] + a[i+1] - 1) / a[i+1];
            ll p = 0;
            while(t < num){
                p++;t *= 4;
            }
            debug("2", a[i], a[i+1], p);

            rep(j,0,log){
                if(j + p < log){
                    dp[i][j] = dp[i+1][j + p] + j * 2;
                }
                else{
                    dp[i][j] = dp[i+1][log-1] + (n - i - 1) * (j + p - log+1) * 2 + j * 2;
                }
            }
        }
    }

