    positive_work_count[i] = positive_work_count[i + 1];
    ll num0 = A[i];
    ll num1 = A[i + 1];
    while (num0 > num1) {
      num1 *= 4;
      positive_work_count[i] += (N - i - 1) * 2;
    }
  }

  ll res = 1e18;
  REP(i, N + 1) {
    ll neg = i > 0 ? negative_work_count[i - 1] : 0;
    ll pos = i < N ? positive_work_count[i] : 0;
    res = min(res, neg + pos);
  }
  cout << res << endl;
  return 0;
}

