   else{
      ll k = 0;
      ll tmp1 = A[l] * (1ll << (2*x));
      ll tmp2 = A[l + 1];
      while (tmp2 < tmp1){
         tmp2 *= 4;
         k ++;
      }
      dp_pos[l][x] = positive(l + 1, k) + x;
      return dp_pos[l][x];     
   }
}

ll negative(ll l, ll x){
   /*
   A0, A1, ..., A_lに対し, A_lに*4をx回したときに合計*4を何回すれば単調減少列を作れるか？
   */
  if (dp_neg[l][x] >= 0) return dp_neg[l][x];
  else if (l < 0) return 0;
  else if (x > MAX_X) return (negative(l, MAX_X) + (x - MAX_X) * (l + 1));
  else if (l == 0){
     dp_neg[l][x] = x;
     return x;
  }
  else{
     ll k = 0;
     ll tmp1 = A[l] * (1ll << (2 * x));
     ll tmp2 = A[l - 1];
     while (tmp2 < tmp1){
        tmp2 *= 4;
        k++;
     }
     dp_neg[l][x] = negative(l - 1, k) + x;
     return dp_neg[l][x];
   }
}

int main(){
   //input
   cin >> N;
   REP(i, N){
      cin >> A[i];
   }
   //init DPtable with -INF
   REP(l, MAX_N){
      REP(x, MAX_X + 1){
         dp_pos[l][x] = -INF;
         dp_neg[l][x] = -INF;
      }
   }
   /*
   REP(l, N){
      REP(x, 4){
         printf("positive(%lld, %lld) = %lld\n", l, x, positive(l,x));
         printf("negative(%lld, %lld) = %lld\n", l, x, negative(l,x));
      }
   }
   */
   ll ans = INF;
   REP(i, N + 1){
      ll tmp = positive(i, 0) * 2 + negative(i - 1, 0) * 2 + i;
      chmin(ans, tmp);
   }
   cout << ans << endl;
}

