signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	auto calc = [&](std::vector<int> must, std::vector<int> yoyu) {
		std::vector<int> b(n, 0);
		int sum = 0;
		std::stack<PAIR> st;
		st.push(PAIR(0, n - 1));
		RREP(i, n - 1) {
			if (must[i] == 0) {
				st.push(PAIR(yoyu[i], i));
			}
			else {
				int pos = i;
				int rest = must[i];
				while (true) {
					PAIR p = st.top();
					sum += (p.second - pos) * rest;
					pos = p.second;
					if (p.first == 0) break;
					st.pop();
					if (p.first < rest) {
						rest -= p.first;
					}
					else {
						p.first -= rest;
						if (p.first != 0) st.push(p);
						break;
					}
				}
			}
			b[i] = sum;
		}
		return b;
	};

	std::vector<int> b;
	{
		std::vector<int> must(n - 1, 0), yoyu(n - 1, 0);
		REP(i, n - 1) {
			int x(a[i]), y(a[i + 1]);
			if (x <= y) {
				while (true) {
					x <<= 2;
					if (x > y) break;
					yoyu[i] += 2;
				}
			}
			else {
				while (true) {
					y <<= 2;
					must[i] += 2;
					if (x <= y) break;
				}
			}
		}

		b = calc(must, yoyu);
	}

	std::vector<int> c;
	{
		std::reverse(ALL(a));

		std::vector<int> must(n - 1, 0), yoyu(n - 1, 0);
		REP(i, n - 1) {
			int x(a[i]), y(a[i + 1]);
			if (x <= y) {
				while (true) {
					x <<= 2;
					if (x > y) break;
					yoyu[i] += 2;
				}
			}
			else {
				while (true) {
					y <<= 2;
					must[i] += 2;
					if (x <= y) break;
				}
			}
		}

		c = calc(must, yoyu);
		std::reverse(ALL(c));
	}

	int ans = INFLL;
	REP(i, n + 1) {
