//union-find 并查集
struct UF{
    vi par;
    explicit UF(int n) {
        par.assign(n + 1, 0);
        rng (i, 1, n + 1) par[i] = i;
    }
    int find(int x) {
        return x == par[x] ? x : par[x] = find(par[x]);
    }
    void unite(int x, int y) {
        par[find(x)] = find(y);
    }
};


vi get_popcnt(int n) {
    vi res(n + 1);
    rng (i, 0, n) {
        if (i * 2 <= n) res[i * 2] = res[i];
        if ((i & 1) == 0) res[i + 1] = res[i] + 1;
    }
    return res;
}




