int main() {
    FAST_READ
#ifdef LOCAL
    ifstream in("main.in");
    cin.rdbuf(in.rdbuf());
#endif
    int n;
    cin >>n;
    vi a(n); FOR(x, a) cin >> x;
//    dprintln(n);
    vector<unordered_map<int,int>> pos(n);

    function<int(int,int)> solve;
    solve = [&](int i, int j) {
//        dprintln(i, j);
        if(i == n-1) return 2*j;
//        assert(i < n);
        auto iter = pos[i].find(j);
        if(iter != pos[i].end()) return iter->second;

//        if(i >= 3800) return 0;

        // min x s.t. a[i] * 4**j <= a[i+1] * 4**x
        if(a[i] >= a[i+1]) {
            // min x s.t. 4**(x-j) >= a[i]/a[i+1]
            int q = ceil(a[i], a[i+1]);
            int d = 0; ll t = 1;
            while(t < q) {
                t *= 4;
                ++d;
            }
            int x = j + d;
            int tmp = solve(i + 1, x);
            return pos[i][j] = 2 * j + tmp;
        }
        else {
            // min x s.t. 4**(j-x) <= a[i+1]/a[i]
            // max d s.t. 4**d <= a[i+1]/a[i]
            int q = a[i+1] / a[i];
            int d = 0; ll t = 1;
            while (t <= q) {
                t *= 4;
                d++;
            }
            --d;
            int x = max(0, j - d);
            int tmp = solve(i + 1, x);
            return pos[i][j] = 2 * j + tmp;
        }
    };

    vector<unordered_map<int,int>> neg(n);

    function<int(int,int)> solve2;
    solve2 = [&](int i, int j) {
        if(i == 0) {
            return 2*j + 1;
        }

        auto iter = neg[i].find(j);
        if (iter != neg[i].end()) return iter->second;

        //min x s.t. a[i] * 2 * 4 ** j <= a[i-1] * 2 * 4 ** x  ==>
        //min x s.t. a[i] * 4 ** j <= a[i-1] * 4 ** x
        // 4 ** (x - j) >= a[i] / a[i-1]
        if (a[i] >= a[i-1]) {
            int q = ceil(a[i], a[i-1]);
            int d = 0; ll t = 1;
            while (t < q) {
                t *= 4;
                ++d;
            }
            int x = j + d;
            int tmp = solve2(i - 1, x);
            return neg[i][j] = 2 * j + 1 + tmp;
        }
        else {
            // 4 ** (j-x) <= a[i-1]/a[i]
            int d = 0; ll t = 1;
            int q = a[i-1] / a[i];
            while (t <= q) {
                d++;
                t *= 4;
            }
            d--;
            int x = max(0, j - d);
            return neg[i][j] = 2 * j + 1 + solve2(i-1, x);
        }
    };
//
//    int t1 = solve(0, 0);
//    println(t1);
//    int t2 = solve2(n - 1, 0);
//    println(t1, t2);
    int ans = min(solve(0, 0), solve2(n-1, 0));
    rng (i, 0, n - 1) {
//        int x = solve2(i, 0), y = solve(i + 1, 0);
//        println(x, y);
        ans = min(ans, solve2(i, 0) + solve(i + 1, 0));
    }

    println(ans);



#ifdef LOCAL
    cout << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << " s.\n";
#endif
    return 0;
}

