        nega[i] = A[i] * 2LL;
    }

    vector<ll> msb_posi(N), msb_nega(N), pre(N+2), suf(N+2);
    for(int i=0; i<N; i++) {
        for(int k=40; k>=0; k--) {
            if(posi[i] >> k & 1) {
                msb_posi[i] = k;
                break;
            }
        }
        for(int k=40; k>=0; k--) {
            if(nega[i] >> k & 1) {
                msb_nega[i] = k;
                break;
            }
        }
    }

    // suffix (増加, a_{i+1} >= a_i)
    fill(dp1[0], dp1[N], LONGINF);
    for(int k=0; k<20; k++) dp1[N][k] = 2*k;
    for(int i=N-2; i>=0; i--) {
        for(int k=0; k<20; k++) {
            ll sub = msb_posi[i] + 2*k - msb_posi[i+1];
            int j = (sub <= 0 ? 0 : (sub + 1) / 2);
            if(sub - 2*j == 0) {
                ll P = posi[i], Q = posi[i+1];
                ll diff = abs(msb_posi[i] - msb_posi[i+1]);
                if(msb_posi[i] < msb_posi[i+1]) P <<= diff;
                else Q <<= diff;
                if(P > Q) j++;
            }

            int l = min(19, j);
            ll add = (N-i-1) * max(0, j-19);
            chmin(dp1[i+1][k], dp1[i+2][l] + add + 2*k);
        }
    }

    // prefix (減少, a_{i-1} >= a_i)
    fill(dp2[2], dp2[N+2], LONGINF);
    for(int k=0; k<20; k++) dp2[1][k] = 2*k;
    for(int i=1; i<N; i++) {
        for(int k=0; k<20; k++) {
            ll sub = msb_nega[i] + 2*k - msb_nega[i-1];
            int j = (sub <= 0 ? 0 : (sub + 1) / 2);
            if(sub - 2*j == 0) {
                ll P = nega[i], Q = nega[i-1];
                ll diff = abs(msb_nega[i] - msb_nega[i-1]);
                if(msb_nega[i] < msb_nega[i-1]) P <<= diff;
                else Q <<= diff;
                if(P > Q) j++;
            }

            int l = min(19, j);
            ll add = i * max(0, j-19);
            chmin(dp2[i+1][k], dp2[i][l] + add + 2*k);
        }    
    }

    ll ans = LONGINF;
    for(int i=0; i<=N; i++) {
        for(int j=0; j<20; j++) {
            for(int k=0; k<20; k++) {
                chmin(ans, dp2[i][j] + dp1[i+1][k] + i);
            }
        }
    }
    cout << ans << endl;
    return 0;
}

