  for(int i = 0; i < N; i++) {
    cin >> A[i];
    A[i] = log(A[i]);
  }

  const double log4 = log(4);

  vector< int64 > suffix(N);
  {
    vector< double > add(N);
    UnionFindRange uf(N + 1);

    auto add2 = [&](int idx) {
      return add[uf.find(idx)];
    };

    for(int i = N - 2; i >= 0; i--) {
      int64 times = 0;
      for(int j = i + 1; j < N; j = uf.find(uf.range(j).second + 1)) {
        if(A[j - 1] + add2(j - 1) <= A[j] + add2(j)) break;
        while(A[j - 1] + add2(j - 1) > A[j] + add2(j)) {
          add[uf.find(j)] += log4;
          times += 2 * uf.size(j);
        }
        if(A[j - 1] + add2(j - 1) + log4 >= A[j] + add2(j)) { // えーなにかが起こる
          uf.unite(j - 1, j);
        }
      }
      suffix[i] = suffix[i + 1] + times;
    }
  }


  vector< int64 > prefix(N);
  {
    vector< double > add(N);
    prefix[0] = 1;

    UnionFindRange uf(N + 1);

    auto add2 = [&](int idx) {
      return add[uf.find(idx)];
    };

    for(int i = 1; i < N; i++) {
      int64 times = 1;
      for(int j = i - 1; j > 0; j = uf.range(j).first - 1) {
        if(A[j] + add2(j) >= A[j + 1] + add2(j + 1)) break;
        while(A[j] + add2(j) < A[j + 1] + add2(j + 1)) {
          add[uf.find(j)] += log4;
          times += 2 * uf.size(j);
        }
        if(A[j] + add2(j) + log4 >= A[j + 1] + add2(j + 1)) { // えーなにかが起こる
          uf.unite(j, j + 1);
        }
      }
      prefix[i] = prefix[i - 1] + times;
    }
  }

  int64 ret = min(prefix[N - 1], suffix[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, prefix[i - 1] + suffix[i]);
  }
  cout << ret << endl;

}

