            dp2[i][j] = 1e18;
        }
    }
    for (int i = 0; i <= 15; ++i) {
        dp1[i][n + 1] = 0;
        dp2[i][0] = 0;
    }
    for (int i = n; i >= 1; --i) {
        for (int j = 0; j <= 15; ++j) {
            long long v = 1e18;
            long long x = a[i] * 1ll * pw[j];
            for (int k = 0; k <= 15; ++k) {
                long long y = a[i + 1] * 1ll * pw[k];
                if (x <= y)
                    v = min(v, dp1[k][i + 1]);
            }
            int z = 0;
            long long p = 1;
            while (a[i + 1] * p < x) {
                z++;
                p *= 4;
            }
            if (z > 15) 
                v = min(v, dp1[15][i + 1] + (n - i) * 1ll * (z - 15));
            dp1[j][i] = v + 2 * j;
        } 
    } 
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= 15; ++j) {
            long long v = 1e18;
            long long x = a[i] * 1ll * pw[j];
            for (int k = 0; k <= 15; ++k) {
                long long y = a[i - 1] * 1ll * pw[k];
                if (x <= y)
                    v = min(v, dp2[k][i - 1]);
            }
            int z = 0;
            long long p = 1;
            while (a[i - 1] * p < x) {
                z++;
                p *= 4;
            }
            if (z > 15) 
                v = min(v, dp2[15][i - 1] + (i - 1) * 1ll * (z - 15));
            dp2[j][i] = v + 2 * j;
        } 
    } 
    long long ans = 1e18;
    for (int i = 1; i <= n + 1; ++i) 
