int N;
ll cnt(int b, ll *A){
    int cnt=0;
    ll prev;
    for(int i=b;i>0;i--){
        ll a;
        if(A[i]>0){
            cnt++;
            a=A[i]*(-2);
        }else a=A[i];
        if(i==b) prev=a;
        else{
            if(a<prev) prev=a;
            else{
                int e = ceil(log((double)prev/(double)a)/log(4));
                cnt += 2*e;
                prev = (1LL<<(2*e))*a;
            }
        }
    }
    for(int i=b+1;i<=N;i++){
        ll a;
        if(A[i]<0){
            cnt++;
            a=A[i]*(-2);
        }else a=A[i];
        if(i==b+1) prev=a;
        else{
            if(a>prev) prev=a;
            else{
                int e = ceil(log((double)prev/(double)a)/log(4));
                cnt += 2*e;
                prev = (1LL<<(2*e))*a;
            }
        }
    }
    return cnt;
}


