//Union Find Tree
class UnionFindTreeSize {
public:
	vector<int> parent;
    vector<int> maxidx;
    vector<int> minidx;

    UnionFindTreeSize(int N = 1) : parent(N,-1),maxidx(N),minidx(N){
        iota(maxidx.begin(),maxidx.end(),0);
        iota(minidx.begin(),minidx.end(),0);
	}

	int root(int n) {
        return (parent[n]<0?n:parent[n] = root(parent[n]));
	}

    bool same(int n, int m) {
		return root(n) == root(m);
	}

    int mini(int n) {
        return minidx[root(n)];
    }

    int maxi(int n) {
        return maxidx[root(n)];
    }

	void unite(int n, int m) {
		n = root(n);
		m = root(m);
		if (n == m) return;
		if(parent[n]>parent[m]) swap(n, m);
        parent[n] += parent[m];
        parent[m] = n;
        maxidx[n] = max(maxidx[n],maxidx[m]);
        minidx[n] = min(minidx[n],minidx[m]);
	}

    int size(int n){
        return (-parent[root(n)]);
    }

    void print() {
        for(int i = 0; i < parent.size(); ++i) cout << root(i) << " ";
        cout << endl;
    }
};


vector<ll> f(const int N,const vector<ll>& A) {
    vector<ll> dp(N+2,0);
    vector<ll> X(N+2,LOWINF);
    UnionFindTreeSize uf(N+2);
    for(int i = N-1; 1 <= i; --i) {
        dp[i] += dp[i+1];
        if(A[i] <= A[i+1]) {
            ll cnt = 0;
            ll tmp = A[i];
            while(tmp*4LL <= A[i+1]) cnt+=1,tmp*=4LL;
            X[i] += cnt;
        }
        else{
            ll cnt = 0;
            ll tmp = A[i+1];
            while(A[i] > tmp) cnt+=1,tmp*=4LL;
            int r = uf.maxi(i+1);
            while(cnt) {
                dp[i] += (ll)uf.size(r)*cnt;
                ll m = min(cnt,X[r]);
                cnt -= m;
                X[r] -= m;
                uf.unite(uf.mini(r)-1,r);
                r = uf.maxi(r+1);
            }
        }
    }
    return dp;
}

