ll f(ll x, ll y) {
	ll ans = 0;
	if (y > x) {
		while (y > x) {
			ans++;
			x *= 4;
		}
		return ans * 2;
	}
	else if(y==x){
		return 0;
	}
	else {
		swap(x, y);
		while (y >= x*4) {
			ans++;
			x *= 4;
		}
		return -ans * 2;

	}
}



