	PER(i, n - 1, 1) {
		ll x = f(a[i+1], a[i]);
		if (x < 0) {
			//cout << i <<" " << x << endl;
			st1.push({ i,-x });
			b[i] = b[i + 1];
		}
		else if (x == 0) {
			b[i] = b[i + 1];
		}
		else {
			b[i] = b[i + 1];
			bool flag = 1;
			while (!st1.empty()) {
				stc cur = st1.top();
				st1.pop();
				if (x <= cur.dif) {
					//cout << i << "! ";

					b[i] += x * (cur.name - i);
					//cout << b[i] << endl;
					cur.dif -= x;
					if (cur.dif > 0) {
						st1.push(cur);
					}
					flag = 0;
					break;
				}
				else {
					b[i] += cur.dif*(cur.name - i);
					x -= cur.dif;
				}
			}
			if (flag) {
				b[i] += (n - i)*x;

			}
		}

