				}
				else {
					c[i] += cur.dif*(-cur.name + i);
					x -= cur.dif;
				}
			}
			if (flag) {
				c[i] += (i - 1)*x;
			}
		}
	}
	ll ans = 1e18;
	REP(i, 1, n+1) {
		ans = min(ans, (i - 1) + c[i - 1] + b[i]);
	}
