    for (long l = N-2;l >= 0;l--) {
        REP(x,16) {
            if (pow4[x] * A[l] <= A[l+1]) dp1[l][x] = dp1[l+1][0] + x;
            else {
                LL k = ceil((log(pow4[x])+log(A[l])-log(A[l+1]))/log(4));
                if (k >= 15) dp1[l][x] = dp1[l+1][15] + x + (N-l+1) * (k-15);
                else dp1[l][x] = dp1[l+1][k] + x;
            }
        }
    }
    for (long l = 1;l < N;l++) {
        REP(x,16) {
            if (pow4[x] * A[l] >= A[l-1]) {
                dp2[l][x] = dp2[l-1][0] + x;
            }
            else {
                LL k = ceil((log(pow4[x])+log(A[l])-log(A[l-1]))/log(4));
                if (k >= 15) dp2[l][x] = dp2[l-1][15] + x + (l+1) * (k-15);
                else dp2[l][x] = dp2[l-1][k] + x;
            }
        }
    }

    LL ans = min(2*dp1[0][0],2*dp2[N-1][0] + N);
    FOR(i,1,N) {
        ans = min(ans,i+2*(dp1[i][0]+dp2[i-1][0]));
    }

    cout << ans << endl;
}

