          j = itr->first;
          itr->second -= k;
          k = 0;
          break;
        } else {
          r[i] += k * (itr->first - j);
          j = itr->first;
          k -= itr->second;
          mp.erase(itr++);
          if (k == 0) break;
        }
      }
      r[i] += k * (n - j);
    }
