const int N = 200005;
const LD INF = 1e18;

int A[N];
long double vals[N];
LL SUF[N], PRE[N], UPD[N];
vi st;
int n;

LD getVal(int idx) {
  if(idx == n + 1 || idx == 0) {
    return INF;
  }
  return vals[idx] + UPD[idx];
}

int main() {
  S(n);
  rep(i,1,n+1) {
    S(A[i]);
    vals[i] = log2(A[i]);
  }

  SUF[n + 1] = 0;
  st.pb(n + 1);
  for(int i = n; i >= 1; i--) {
    SUF[i] = SUF[i + 1];
    if(vals[i] <= getVal(i + 1)) {
      st.pb(i);
      continue;
    }
    long double cur = vals[i];
    while(st.size()) {
      int idx = st.back();
      long double nxt = getVal(idx);
      if(cur <= nxt) break;
      int upds = 0;
      while(cur > nxt) {
        nxt += 2.0;
        UPD[idx] += 2;
        upds += 2;
      }
      st.pop_back();
      assert(st.size() >= 1);
      int idx2 = st.back();
      SUF[i] += (idx2 - idx) * 1LL * upds;
      if(idx2 - 1 != idx) {
        UPD[idx2 - 1] += upds;
      }
      cur = getVal(idx2 - 1);
    }
    st.pb(i);
  }

  st.clear();
  PRE[0] = 0;
  st.pb(0);
  memset(UPD, 0, sizeof(UPD));
  rep(i,1,n+1) {
    vals[i] += 1.0; // Multiply atleast once first
    PRE[i] = PRE[i - 1] + 1;
    if(vals[i] <= getVal(i - 1)) {
      st.pb(i);
      continue;
    }
    long double cur = vals[i];
    while(st.size()) {
      int idx = st.back();
      long double nxt = getVal(idx);
      if(cur <= nxt) break;
      int upds = 0;
      while(cur > nxt) {
        nxt += 2.0;
        UPD[idx] += 2;
        upds += 2;
      }
      st.pop_back();
      assert(st.size() >= 1);
      int idx2 = st.back();
      PRE[i] += (idx - idx2) * 1LL * upds;
      if(idx2 + 1 != idx) {
        UPD[idx2 + 1] += upds;
      }
      cur = getVal(idx2 + 1);
    }
    st.pb(i);
  }

  LL ans = SUF[1];
  rep(i,1,n+1) {
    ans = min(ans, PRE[i] + SUF[i + 1]);
  }
  cout << ans << "\n";
  return 0;
}

