void solve(int *a, int b, ll *F)
{
	F[n] = 0;
	for (int i = n-1; i >= 1; -- i)
	{
		F[i] = F[i+1];
		ll t = a[i+1];
		while (a[i] > t)
		{
			t *= b;
			F[i] += n-i;
		}
	}
}

