      if (x < 0) return x;
      return -2 * x;
    });
    l.at(1) = a.at(0) > 0;
    std::stack<size_t> stk;
    for (size_t i = 1; i < n; i++) {
      l.at(i + 1) = l.at(i) + (a.at(i) > 0);
      long long x = b.at(i - 1), y = b.at(i);
      if (x <= y) {
        while (x <= 4LL * y) {
          stk.push(i);
          y *= 4LL;
        }
      } else {
        while (x > y) {
          x *= 4LL;
          long long j = 0;
          if (!stk.empty()) j = stk.top(), stk.pop();
          l.at(i + 1) += (i - j) * 2u;
        }
      }
    }
    return l;
  };
  auto b = [&]{
    auto b = a;
    std::reverse(b.begin(), b.end());
    std::for_each(b.begin(), b.end(), [](auto& x){x = -x;});
    return b;
  }();
  auto l = make_l(a), r = make_l(b);
  std::reverse(r.begin(), r.end());
  long long ret = 1LL << 60;
  for (size_t i = 0; i <= n; i++) {
    ret = std::min(ret, l.at(i) + r.at(i));
  }
