void solve(int* res)
{
  memset(cnt, 0, sizeof cnt);
  res[n] = 0;
  for(int i = n - 1 ; i >= 0 ; i--){
    int x = arr[i];
    res[i] = res[i + 1];
    for(int y = 0 ; y < x ; y++){
      if(!cnt[y])
        continue;
      int p = (x - y + 1) >> 1;
      res[i] += cnt[y] * p;
      cnt[x] += cnt[y];
      cnt[y] = 0;
    }
    cnt[x]++;
  }
}

