  solve(pref);
  reverse(pref, pref + n);
  int ans = 1e9;
  for(int i = 0 ; i <= n ; i++){
    int cur = suff[i] * 2 + i + pref[n - i] * 2;
    ans = min(ans, cur);
  }
  cout << ans << endl;
  return 0;
}

