    int ans = NOTHING;

    int tmp = dfs(1, 0);
    if (tmp != NOTHING) {
      ans = min(ans, tmp);
    }

    for (int i = 1; i < 63; i += 2) {
      ll curVal = a[0] * mul[i];
      if (!limitOk(curVal)) {
        break;
      }
      int tmp = dfs(1, i);
      if (tmp != NOTHING) {
        ans = min(ans, tmp + i);
      }
    }

    if (ans == NOTHING) {
      cout << -1 << endl;
    } else {
      cout << ans << endl;
    }
  }
}

