    for (int i=1; i<=n; i++)
        scanf("%d", &V[i]);
    for (int i=1; i<=n; i++)
        for (int j=0; j<=15; j++)
            dp[i][j]=INF, dp2[i][j]=INF;

    for (int j=0; j<=15; j++)
    {
        dp[n][j] = 2*j;
    }

    for (int i=n-1; i>=1; i--)
    {
        for (int j=0; j<=15; j++)
        {
            ll x = V[i] * P[j];
            ll put = log(x/V[i+1])/log(4)-3;
            while (P[put]*V[i+1]<x && put<=15)
                put++;
            if (put<=15)
                dp[i][j] = dp[i + 1][put] + j * 2;
            else
            {
                dp[i][j] = dp[i+1][15] + (put-15)*(n-i)*2 + j*2;
            }
        }
    }


    for (int j=0; j<=15; j++)
    {
        dp2[1][j] = 2*j+1;
    }

    for (int i=1; i<=n; i++)
        V[i]*=2;

    for (int i=2; i<=n; i++)
    {
        for (int j=0; j<=15; j++)
        {
            ll x = V[i] * P[j];
            ll put = log(x/V[i-1])/log(4)-3;
            while (P[put]*V[i-1]<x && put<=15)
                put++;
            if (put<=15)
                dp2[i][j] = dp2[i - 1][put] + j * 2 + 1;
            else
            {
                dp2[i][j] = dp2[i-1][15] + (put-15)*(i-1)*2 + j*2 + 1;
            }
        }
    }

