		x = max(0LL, x + a[i]);
		ret += x;
	}
	return ret;
}

void reverse(int *a, int n) {
	int l = 0, r = n - 1;
	while (l < r) {
		swap(a[l], a[r]);
		l++; r--;
	}
}

