  for (int i = 0; i < n; i++) std::cin >> a[i];
  auto sub_solve = [&] (std::vector<int> a) {
    std::vector<long long> left(n + 1, 0);
    left [1] = a.front() > 0;
    std::stack<int> stk;
    for (int i = 2; i <= n; i++) {
      left[i] = left[i - 1];
      long long x = a[i - 2], y = a[i - 1];
      if (x > 0) x *= -2;
      if (y > 0) y *= -2, left[i]++;
      while (x <= 4 * y) {
        stk.push(i - 1);
        y *= 4;
      }
      while (x > y) {
        int len = i - 1;
        if (!stk.empty()) {
          len -= stk.top(); stk.pop();
        }
        left[i] += len * 2;
        x *= 4;
      }
    }
    return left;
  };
  auto left = sub_solve(a);
  auto b = [&]{
    auto b = a;
    std::reverse(b.begin(), b.end());
    std::for_each(b.begin(), b.end(), [](int& x){x = -x;});
    return b;
  }();
  auto right = [&] () {
    auto right = sub_solve(b);
    std::reverse(right.begin(), right.end());
    return right;
  }();
  constexpr int inf = 1 << 30;
  long long ret = inf;
  for (int i = 0; i <= n; i++) {
    cmn(ret, left[i] + right[i]);
  }
