			int k = calc(j,A[i],A[i+1],0);
			if (k >= 15)dpr[i][j] = dpr[i + 1][15] + ((ll)(k-15))*((ll)(N-i+1)) + 2*j;
			else dpr[i][j] = dpr[i + 1][k] + 2*j;
		}
	}


	A[0] *= -2;
	for (int j = 0; j <= 15; j++)dpl[0][j] = j + 1;
	for (int i = 1; i < N; i++) {
		A[i] *= -2LL;
		for (int j = 0; j <= 15;j++) {
			dpl[i][j]++;
			int k = calc(j,A[i],A[i-1],1);
			if(k >= 15)dpl[i][j] = dpl[i-1][15] + ((ll)(k - 15))*((ll)(i)) + j;
			else dpl[i][j] = dpl[i-1][k] + j;
		}
	}

	ll ans = dpr[0][0];
	for (int i = 0; i < N; i++) {
		ans = min(ans, dpl[i][0] + dpr[i+1][0]);
	}
	puts(ans);

	return 0;
}

