			invAns = rp[n - i];
		}

		ll lAns = 0;
		if (i < n) {
			lAns = dp[i];
		}

		ll cans = (invAns + lAns) * 2 + i;

		// debugPrintf("%d\n", cans);

		ans = min(ans, cans);
	}

	writerLn(ans);

}

