    std::vector<long long> left(n + 1, 0);
    left [1] = a.front() > 0;
    std::stack<int> stk;
    for (int i = 2; i <= n; i++) {
      left[i] = left[i - 1];
      long long x = a[i - 2], y = a[i - 1];
      if (x > 0) x *= -2;
      if (y > 0) y *= -2, left[i]++;
      while (x <= 4 * y) {
