    for (int i = 1; i < n; i++) {
        int cnt = 0;
        i64 a = as[i - 1], b = as[i];
        while (a > b) {
            b *= 4;
            cnt += 2;
        }
        pos[i] = cnt;
    }
    for (int i = 1; i < n; i++) {
        pos[i] += pos[i - 1];
    }

    for (int i = 0; i < n - 1; i++) {
        int cnt = 0;
        i64 a = as[i], b = as[i + 1];
        while (a < b) {
            a *= 4;
            cnt += 2;
        }
        neg[i] = cnt;
    }
    for (int i = n - 2; i >= 0; i--) {
        neg[i] += neg[i + 1];
    }

    BIT pbit(n), nbit(n);
    for (int i = 0; i < n; i++) {
        pbit.add(i, pos[i]);
        nbit.add(i, neg[i]);
    }

    i64 ans = 4e18;
