int calc(int i, int x) {
	//pe(i); print(x);
	if (x > 20) {
		return calc(i, 20) + (N - i)*(x - 20);
	}
	if (done[i][x])return dp[i][x];
	done[i][x] = true;
	if (i >= N - 1) {
		return dp[i][x]=x;
	}
	else {
		return dp[i][x]=x + calc(i + 1, max(0LL, x + d[i + 1]));
	}
}

ll B[200020];
