int dpB[200020][25];
int calcB(int i, int x) {
	if (x > 20) {
		return calcB(i, 20) + (N - i)*(x - 20);
	}
	if (doneB[i][x])return dpB[i][x];
	doneB[i][x] = true;
	if (i >= N - 1) {
		return dpB[i][x]=x;
	}
	else {
		return dpB[i][x]=x + calcB(i + 1, max(0LL, x + dB[i + 1]));
	}
}

