					rne[i + 1] = rne[rne[i + 1] + 1];
			}
			rne[i] = rne[i + 1];
		}
	}
	reverse(Aa.begin(), Aa.end());
	A = Aa;
	A.push_back(INF);
	vector<ll> lans(N + 1);
