ll power(ll e, ll x)
{
	if (x == 0) return 1LL;
	if (x % 2 != 0) return (power(e, x - 1) * e);
	ll temp = power(e, x / 2);
	return (temp * temp);
}

void solve()
{
	int N;
	cin >> N;
	vecll as(N), bs;
	rep(N, i) cin >> as[i];
	bs = as;
	reverse(all(bs));

	vec pcnt(N), acnt(N), bcnt(N);

	rep(N-1, i)
	{
		if (as[i+1]>=as[i]) continue;
		ll pre = as[i] * power(4, pcnt[i] / 2);
		//assert(as[i + 1] >= 0 && pre > 0);
		int ok = 40, ng = -1;
		while (abs(ok-ng)>1)
		{
			int mid = (ok + ng) / 2;
			((as[i + 1] * power(4, mid) < pre) ? ok : ng) = mid;
		}
		pcnt[i + 1] = ok*2;
	}
	//cout << pcnt << endl;
	rep(N - 1, i) acnt[i + 1] = pcnt[i + 1] + acnt[i];
	pcnt.clear();
	pcnt.resize(N, 0);
	rep(N-1, i)
	{
		if (bs[i+1] >= bs[i]) continue;
		ll pre = bs[i] * power(4, pcnt[i] / 2);
		//assert(bs[i + 1] >= 0 && pre > 0);
		int ok = 30, ng = -1;
		while (abs(ok - ng) > 1)
		{
			int mid = (ok + ng) / 2;
			((bs[i + 1] * power(4, mid) < pre) ? ok : ng) = mid;
		}
		pcnt[i + 1] = ok * 2;
	}
	rep(N - 1, i) bcnt[i + 1] = pcnt[i + 1] + bcnt[i];

	ll ans = min(acnt[N-1], bcnt[N-1]+N);

	//cout << acnt << endl << bcnt << endl;

	Rep(1, N - 1, i)
	{
		ll tmp = acnt[N - 1] - acnt[i] + i + bcnt[N-1] - bcnt[i];
		//cout << acnt[N - 1] - acnt[i] << ' ' << bcnt[N - 1] - bcnt[N - i + 1] << endl;
		ans = min(ans, tmp);
	}

	cout << ans << endl;
}

