//ここから編集する
class Solve {
public:
    void input() {

    }

    ll count(ll from, ll to) {
        int ret = 0;
        while (from < to) {
            from <<= 2;
            ret += 2;
        }
        return ret;
    }

    ll kanwa(ll from, ll to) {
        int ret = 0;
        while (from < to) {
            from <<= 2;
            if (from <= to)
                ret += 2;
        }
        return ret;
    }


    void solve() {
        input();
        int N;
        cin >> N;
        vector<ll> A(N);
        rep(i, 0, N) cin >> A[i];


        struct Tapi {
            int pt;
            ll rest; //残り何回防げるか
        };

        vector<ll> inc(N), dec(N);
        stack<Tapi> stapi;
        for (int i = N - 1; i > 0; --i) {
            if (A[i - 1] <= A[i]) {
                //普通
                inc[i - 1] = inc[i];
                ll tmp = kanwa(A[i - 1], A[i]);
                if (tmp > 0) {
                    stapi.push(Tapi{i - 1, tmp});
                }
            } else {
                ll tmp = count(A[i], A[i - 1]);
                inc[i - 1] = inc[i];
                while (tmp > 0) {
                    if (stapi.empty()) {
                        ll add = tmp * (N - i);
                        inc[i - 1] += add;
                        tmp = 0;
                    } else {
                        Tapi top = stapi.top();
                        stapi.pop();
                        ll waste = min(tmp, top.rest);
                        ll add = waste * (top.pt - i + 1);
                        inc[i - 1] += add;
                        tmp -= waste;
                        top.rest -= waste;
                        if (top.rest > 0) {
                            stapi.push(top);
                        }
                    }
                }
            }
        }


        stapi = stack<Tapi>();
        dec[0] = 1;
        for (int i = 0; i < N - 1; ++i) {
            if (A[i] >= A[i + 1]) {
                dec[i + 1] = dec[i] + 1;
                ll tmp = kanwa(A[i + 1], A[i]);
                if (tmp > 0) {
                    stapi.push(Tapi{i + 1, tmp});
                }
            } else {
                ll tmp = count(A[i], A[i + 1]);
                dec[i + 1] = dec[i] + 1;
//                ll add = tmp * (i + 1);
//                dec[i + 1] = dec[i] + 1 + add;
                while (tmp > 0) {
                    if (stapi.empty()) {
                        ll add = tmp * (i + 1);
                        dec[i + 1] += add;
                        tmp = 0;
                    } else {
                        Tapi top = stapi.top();
                        stapi.pop();
                        ll waste = min(tmp, top.rest);
                        ll add = waste * (i - top.pt + 1);
                        inc[i - 1] += add;
                        tmp -= waste;
                        top.rest -= waste;
                        if (top.rest > 0) {
                            stapi.push(top);
                        }
                    }
                }
            }
        }

        ll ans = min(inc[0], dec.back());
        for (int i = 0; i < N - 1; ++i) {
            ll tmp = dec[i] + inc[i + 1];
            chmin(ans, tmp);
        }

        cout << ans << endl;
    }


};


