const int MAX = 200002;
const int TREE_SIZE = 524288;

int n;
long long a[MAX];
long long more[MAX], rem[MAX], used[MAX];
long long tree[TREE_SIZE];
vector <int> v[MAX + 32];

int getLeaf(int idx) {
    return idx + TREE_SIZE / 2;
}

long long query(int idx) {
    idx = getLeaf(idx);
    long long sum = 0;
    while (idx) {
        sum += tree[idx];
        idx /= 2;
    }
    return sum;
}

void update(int left, int right, long long delta) {
    int idxL = getLeaf(left), idxR = getLeaf(right);

    if (idxL == idxR) {
        tree[idxL] += delta;
        return;
    }

    tree[idxL] += delta, tree[idxR] += delta;
    while (idxL + 1 != idxR) {
        if (idxL % 2 == 0) tree[idxL + 1] += delta;
        if (idxR % 2 == 1) tree[idxR - 1] += delta;
        idxL /= 2, idxR /= 2;
    }
}

long long remove(int idx) {
    // fprintf(stderr, "At remove().\n");
    long long ret = 0;
    while (idx < n) {
        long long curVal = used[idx] - query(idx);
        // fprintf(stderr, "  >> index %d, value %lld (original was %lld)\n", idx, curVal, used[idx]);
        if (curVal <= 0) break;

        int next = n;
        for (int use = used[idx] - 1; use >= 0; use--) {
            int left = 0, right = (int)v[use].size() - 1;
            while (left <= right) {
                int mid = (left + right) / 2;
                v[use][mid] <= idx ? left = mid + 1 : right = mid - 1;
            }
            if (right + 1 < (int)v[use].size()) {
                next = min(next, v[use][right + 1]);
            }
        }
        // fprintf(stderr, "    -- next is %d\n", next);
        update(idx, next - 1, curVal);
        ret += (next - idx) * curVal;
        idx = next;
    }
    // fprintf(stderr, "  >> returning: %lld\n", ret);
    return ret;
}

