#define N 200005

int A[N];
long long cc[N];
int jump[N];

bool comp(long long &add,int ind) {
  long long mini = min(cc[ind-1],cc[ind]);
  long long a = cc[ind-1]- mini,
  b = cc[ind] - mini;
  if(a==0) {
    long long tmp = 0;
    if(b>=32) {
      return true;
    }
    long long x= A[ind-1],y = A[ind];
    assert(b%2==0);
    while(b>0) {
      y*= 4;
      b-=2;
    }
    if(x<=y) {
      return true;
    }
    while(x>y) {
      tmp +=2;
      y *= 4;
    }
    add += tmp;
    return false;
  } else {
    long long tmp = 0;
    if(a>=32) {
      a = 32;
      add += a-32;
    }
    long long x = A[ind-1],y = A[ind];
    assert(a%2==0);
    while(a>0) {
      x *=4;
      a -=2;
    }
    if(x<=y) {
      return true;
    }
    while(x>y) {
      tmp += 2;
      y *=4;
    }
    add += tmp;
    return false;
  }
}
void calculate(long long *save,int n) {
  memset(cc,0,sizeof(cc));
  long long ret = 0;
  for(int i=n;i>=1;--i) {
    jump[i] = i+1;
    int go = jump[i];
    while(go<=n) {
      long long tmp = 0;
      if(!comp(tmp,go)) {
        int nextGo = jump[go];
        cc[nextGo-1] += tmp;
        int numJump = nextGo-go;
        ret += (long long)numJump*tmp;
        go = nextGo;
      } else {
        break;
      }
    }
    jump[i] = go;
    save[i] = ret;
  }
}
long long tmp[N],tmp2[N];
void solve() {
  int n;scanf("%d ", &n);
  for(int i=1;i<=n;++i) {
    scanf("%d ", &A[i]);
  }
  calculate(tmp,n);
  reverse(A+1,A+n+1);
  calculate(tmp2,n);
  reverse(tmp2+1,tmp2+n+1);
  long long mini = 1e18;
  for(int i=1;i<=n+1;++i) {
    long long R = i-1;
    R += tmp2[i-1] + tmp[i];
    mini = min(mini,R);
  }
  printf("%lld\n", mini);
}

int main() {
  //freopen("input.txt","r",stdin);
  solve();
  return 0;
}

