ll n, a[200000];
ll counter[200000], backcounter[200000];
ll sum[200000], backsum[200000];

ll getCounter(ll x, ll y) { // x 4^m <= y
  ll ans = 0;
  while (x > y) y *= 4, ans++;
  return ans * 2;
}

int main() {
  scanf("%lld", &n);
  for (ll i = 0; i < n; i++) scanf("%lld", &a[i]);
  for (ll i = n-1; i >= 1; i--) {
    counter[i] = getCounter(a[i-1], a[i]) * (n-i);
  }
  sum[n-1] = counter[n-1];
  for (ll i = n-2; i >= 1; i--) sum[i] = sum[i+1] + counter[i];
  backcounter[0] = 1;
  for (ll i = 1; i < n; i++) {
    backcounter[i] = getCounter(a[i], a[i-1]) * i + 1;
  }
  backsum[0] = backcounter[0];
  for (ll i = 1; i < n-1; i++) backsum[i] = backsum[i-1] + backcounter[i];
  ll ans = min(sum[1],backsum[n-2]);
  for (ll i = 0; i < n - 2; i++) ans = min(ans, sum[i+2] + backsum[i]);
  printf("%lld\n", ans);
}

