const LL Inf=1e18;
LL solve() {
  p4[0]=1; FOR(i,1,20) p4[i]=p4[i-1]*4;
  REP(i,N)REP(j,20)dpl[i][j]=dpr[i][j]=Inf;
  REP(j,20) dpr[N-1][j]=dpl[0][j]=j;

  for(int i=N-2; i>=0; --i) {
    int k=0;
    REP(j,16) {
//      dump(i,j,k);
      while(p4[j]*A[i]>p4[k]*A[i+1]) ++k;
      if(k<=15) dpr[i][j]=dpr[i+1][k]+j;
      else dpr[i][j]=dpr[i+1][j-1]+(LL)(N-1-i)*(k-15)+j;
    }
  }
  FOR(i,1,N) {
    int k=0;
    REP(j,16) {
      while(p4[k]*A[i-1]<p4[j]*A[i]) ++k;
      if(k<=15) dpl[i][j]=dpl[i-1][k]+j;
      else dpl[i][j]=dpl[i-1][j-1]+(LL)i*(k-15)+j;
    }
  }
  LL res=dpr[0][0]*2;
  FOR(i,1,N) SMIN(res,i+dpl[i-1][0]*2+dpr[i][0]*2);
  return res;
}


