int main() {
  int n;
  while (std::cin >> n) {
    std::vector<int64_t> a(n+2);
    std::vector<int64_t> prefix(n+2, -1), suffix(n+2, -1);
    for (int i = 1; i <= n; ++ i) std::cin >> a[i];
    prefix[0] = 0;
    if (a[1] <= 0) prefix[1] = 0;
    else prefix[1] = 1;
    for (int i = 2; i <= n; ++ i) {
      int64_t pre = a[i-1] <= 0 ? a[i-1] : a[i-1] * -2;
      int64_t cur = a[i] <= 0 ? a[i] : a[i] * -2;
      if (pre == 0 && cur < 0
          || prefix[i-1] == -1) {
        prefix[i] = -1;
        continue;
      }
      int64_t cnt = a[i] <= 0 ? 0 : 1;
      int64_t ops = 0;
      while (pre >= cur) {
        ops += 2;
        pre *= 4;
      }
      prefix[i] = cnt + ops * (i-1) + prefix[i-1];
    }
    suffix[n+1] = 0;
    if (a[n] >= 0) suffix[n] = 0;
    else suffix[n] = 1;
    for (int i = n-1; i > 0; -- i) {
      int64_t suf = a[i+1] >= 0 ? a[i+1] : a[i+1] * -2;
      int64_t cur = a[i] >= 0 ? a[i] : a[i] * -2;
      if (suf == 0 && cur > 0 || suffix[i+1] == -1) {
        suffix[i] = -1;
        continue;
      }
      int64_t cnt = a[i] >= 0 ? 0 : 1;
      int64_t ops = 0;
      while (suf < cur) {
        ops += 2;
        suf *= 4;
      }
      suffix[i] = cnt + ops * (n-i) + suffix[i+1];
    }
    int64_t res = -1;
    for (int i = 0; i <= n; ++ i) {
//      std::cout << prefix[i] <<  "  " << suffix[i+1] << std::endl;
      int64_t temp = -1;
      if (prefix[i] != -1 && suffix[i+1] != -1) {
        temp = prefix[i] + suffix[i+1];
      }
      if (temp == -1) continue;
      if (res == -1) res = temp;
      else {
        res = std::min(res, temp);
      }
    }
    std::cout << res << std::endl;
  }
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
const long long INF = 1LL<<60;
const int MAX = 16;
int N;
vector<long long> A;

vector<vector<long long>> calc(vector<long long> &a, int limit = 0) {
    vector<vector<long long>> dp(N+1, vector<long long>(MAX, INF));
    for (int j = 0; j < MAX; ++j) dp[0][j] = 0, dp[1][j] = j*2 + limit;
    for (int i = 1; i < N; ++i) {
        long long s = a[N-i-1];
        for (int j = 0; j < MAX; ++j) {
            long long t = a[N-i];
            int need = 0;
            while (s > t) ++need, t *= 4;
            long long add = 0;

            if (need >= MAX) {
                add = (need - MAX + 1) * i * 2;
                need = MAX-1;
            }
            dp[i+1][j] = min(dp[i][need] + j * 2 + add + limit , dp[i+1][j]);
            s *= 4;
        }
    }
    return dp;
}

long long solve() {
    vector<vector<long long>> suff = calc(A);
    reverse(A.begin(), A.end());
    vector<vector<long long>> pre = calc(A, 1);
    long long res = INF;
    for (int i = 0; i <= N; ++i) {
     res = min(res ,pre[i][0] + suff[N-i][0] );
    }
    return res;
}

int main() {
    cin >> N;
    A.resize(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    cout << solve() << endl;
}

