typedef long long ll;
typedef pair<int, int> pii;
typedef vector<vector<int>> matrix;

ll l[1000000];
int n;

int solve(int numNeg) {
  int ret = 0;
  ll last = 0;
  for(int i = numNeg; i < n; i++) {
    ll curr = l[i];
    while(curr < last) {
      curr *= 4;
      ret += 2;
    }
    last = curr;
  }
  last = 0;
  for(int i = numNeg-1; i >= 0; i--) {
    ret++;
    ll curr = l[i] * -2;
    while(curr > last) {
      curr *= 4;
      ret += 2;
    }
    last = curr;
  }
  return ret;
}

void solve() {
  cin >> n;
  for(int i = 0; i < n; i++) {
    cin >> l[i];
  }
  int lhs = 0;
  int rhs = n;
  int ret = 1e9;
  while(lhs != rhs) {
    int a = (lhs+rhs)/2;
    int b = a+1;
    int as = solve(a);
    int bs = solve(b);
    if(as < bs) {
      rhs=b-1;
    }
    else {
      lhs=a+1;
    }
    ret = min(ret, min(as, bs));
  }
  cout << ret << endl;
}

