ll _solve(vector<Double>& log4, int lo) {
    if (lo >= N) return 0;
    Double last = log4[lo];
    ll ans = 0;
    for (int i=lo+1; i<N; ++i) {
        Double y = log4[i];
        ll r = 0;
        if (last > y) {
            r = (ll)ceill(last - y);
        }
        last = y + r;
        ans += r*2;
    }
    return ans;
}


