void solve(){
    i64 N;
    cin >> N;

    vector<i64> a(N);
    rep(i,0,N) cin >> a[i];

    vector<i64> pow4(20);
    pow4[0]=1;
    rep(i,1,pow4.size()) pow4[i]=pow4[i-1]*4;

    vector<vector<i64>> memo1(N,vector<i64>(pow4.size()));
    vector<vector<bool>> done1(N,vector<bool>(pow4.size()));
    function<i64(i64,i64)> rec1=[&](i64 i,i64 x){
        assert(x<pow4.size());
        if(done1[i][x]) return memo1[i][x];
        done1[i][x]=true;
        if(i==N-1) return memo1[i][x]=0;
        i64 lb=-1,ub=pow4.size()-1;
        while(ub-lb>1){
            i64 mid=(lb+ub)/2;
            if(mid-x>=0?a[i]<=a[i+1]*pow4[mid-x]:a[i]*pow4[x-mid]<=a[i+1]) ub=mid;
            else lb=mid;
        }
        return memo1[i][x]=rec1(i+1,ub)+ub;
    };

    vector<vector<i64>> memo2(N,vector<i64>(pow4.size()));
    vector<vector<bool>> done2(N,vector<bool>(pow4.size()));
    function<i64(i64,i64)> rec2=[&](i64 i,i64 x){
        assert(x<pow4.size());
        if(done2[i][x]) return memo2[i][x];
        done2[i][x]=true;
        if(i==0) return memo2[i][x]=0;
        i64 lb=-1,ub=pow4.size()-1;
        while(ub-lb>1){
            i64 mid=(lb+ub)/2;
            if(mid-x>=0?a[i]<=a[i-1]*pow4[mid-x]:a[i]*pow4[x-mid]<=a[i-1]) ub=mid;
            else lb=mid;
        }
        return memo2[i][x]=rec2(i-1,ub)+ub;
    };

    i64 ans=min(rec1(0,0)*2,rec2(N-1,0)*2+N);
    rep(i,1,N) {
        ans = min(ans, rec1(i, 0) * 2 + rec2(i - 1, 0) * 2 + i);
    }

    cout << ans << endl;
}

