using namespace std;

const int MAX = 200001;
const int INF = 1073741823; // 10^30-1、使わない辺とかに用いる

int operate(int64_t l, int64_t r) { // 必要操作回数
	int ret = 0;
	while(l > r) {
		++ ret;
		r *= 4;
	}
	return ret;
}

struct graph {
	int64_t A;
	int connect;
	int num;
	int remove; // 正の方向と決め打った時の操作回数
	int add; // 負の方向と決め打った時の操作回数
	void addChange(int right, int n) {
		remove += operate(A, right) * n;
		num += n;
	}
	void addChange2(int left, int n) {
		add += operate(A, left) * n;
		num += n;
	}
};

int main() {
	int N;
	static graph A[MAX];
	cin >> N;
	A[0].A = INF;
	for (int i = 1;i <= N;++ i) cin >> A[i].A;

	stack<int> stk;
	stk.push(0);
	for (int i = 1;i <= N;++ i) {
		A[i].num = 1;
		A[i].remove = 0;
		while (A[stk.top()].A <= A[i].A) stk.pop();
		A[i].connect = stk.top();
		stk.push(i);
	}
	for (int i = N;i >= 1;-- i) A[A[i].connect].addChange(A[i].A, A[i].num);
	for (int i = N - 1;i >= 1;-- i) A[i].remove += A[i + 1].remove;

	while(!stk.empty()) stk.pop();
	stk.push(0);
	for (int i = N;i >= 1;-- i) {
		A[i].num = 1;
		A[i].add = 0;
		while (A[stk.top()].A <= A[i].A) stk.pop();
		A[i].connect = stk.top();
		stk.push(i);
	}
	for (int i = 1;i <= N;++ i) A[A[i].connect].addChange2(A[i].A, A[i].num);
	for (int i = 2;i <= N;++ i) A[i].add += A[i - 1].add;

	int ans = INF;
	for (int i = 1;i <= N;++ i) {
		ans = min(ans, i - 1 + (A[i].add + A[i].remove) * 2);
	}
	cout << ans;
	return 0;
}
/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり
また、コンテスト後に https://31536000.hatenablog.com/ で解説していると思うので、良かったら読んでねー

まず、ある値を境に負か正か変わる
ので、その境目をO(N)で決め打ってみる

面倒なので正の方向で考えると、境目を境にかならず単調増加な形になる
これはO(N)で求められるので、O(N^2)解は定まった
さて、次にこれの計算量を減らす必要がある
でも、これは単調増加なのを利用するとO(1)で求められるので実はO(N)
*/

#include<iostream>
#include<algorithm>
#include<vector>
#include<queue>
using namespace std;
typedef long long ll;
typedef pair<ll,ll> P;
const ll inf=1744174417441744;
P convert_32(ll a){
  ll b=0;
  for(ll i=0;i<25;i++){
    if((a>>(i*2))>0) b=i;
  }
  return P(b,(a<<(50-b*2)));
}
vector<ll> solve(ll n,vector<ll> kvec){
  vector<ll> ans;
  vector<P> vec;
  for(int i=0;i<n;i++) vec.push_back(convert_32(kvec[i]));
  ans.push_back(0);
  ans.push_back(0);
  queue<P> que;
  que.push(P(inf,0));
  for(int i=1;i<n;i++){
    if(vec[i-1]>=vec[i]){
      if(vec[i-1].second<vec[i].second){
        que.push(P(vec[i].first-vec[i-1].first-1,i));
      }
      else que.push(P(vec[i].first-vec[i-1].first,i));
      ans.push_back(ans[i]);
    }
    else{
      ll zan=(vec[i].first-vec[i-1].first);
      if(vec[i].second>vec[i-1].second) zan++;
      ll kans=0;
      while(zan>0){
        P tp=que.front();
        que.pop();
        ll val=tp.first,idx=tp.second;

        if(val<=zan){
          kans+=(i-idx)*val;
          zan-=val;
        }
        else{
          if(val!=inf) val-=zan;
          que.push(P(val,idx));
          kans+=(i-idx)*zan;
          zan=0;
          break;
        }
      }
      ans.push_back(ans[i]+kans*2);
    }
  }
  return ans;
}
int main(){
  vector<ll> v,v2;
  int n;
  cin>>n;
  for(int i=0;i<n;i++){
    ll a;
    cin>>a;
    v.push_back(a);
    v2.push_back(a*2);
  }
  reverse(v.begin(),v.end());
  vector<ll> ans1=solve(n,v2);
  for(int i=0;i<=n;i++) ans1[i]+=i;
  vector<ll> ans2=solve(n,v);
  reverse(ans2.begin(),ans2.end());

  ll ans=inf;
  for(int i=0;i<=n;i++){
    ans=min(ans,ans1[i]+ans2[i]);
  }
  cout<<ans<<endl;
}

