using P = pair<int,int>;
using node = pair<string,ll>;
const ll inf = numeric_limits<ll>::max()/3;
const ll mod = 1e9+7;

ll a[200200];
ll to_right[200200][16];
ll to_left[200200][16];

ll get_x(ll head, ll next){
  if(head <= next)
    return 0;
  ll div = (head / next) + (head % next > 0);
  return (ll)ceil(log(div) / log(4));
}


int main(void) {
  ll n;
  cin >> n;
  for(int i = 1;i <= n;++i){
    cin >> a[i];
  }

  for(int j = 1;j < 16;++j){
    to_left[0][j] = 0;
    to_left[1][j] = 0;
  }
  for(int i = 2;i <= n;++i){
    for(int j = 0;j < 16;++j){
      ll head = a[i] * (ll)pow(4,j);
      ll x = get_x(head, a[i-1]);
      if(x < 16) {
        to_left[i][j] = x + to_left[i-1][x];
      } else {
        to_left[i][j] = x + to_left[i-1][15] + (x - 15) * (i-1);
      }
    }
  }

  for(int j = 0;j < 16;++j){
    to_right[n+1][j] = 0;
    to_right[n][j] = 0;
  }
  for(int i = n-1;i >= 1;--i){
    for(int j = 0;j < 16;++j){
      ll head = a[i] * (ll)pow(4,j);
      ll x = get_x(head, a[i+1]);
      if(x < 16) {
        to_right[i][j] = x + to_right[i+1][x];
      } else {
        to_right[i][j] = x + to_right[i+1][15] + (x - 15) * (n-i);
      }
    }
  }

  ll res = inf;
  for(int i = 1;i <= n+1;++i){
    //printf("[%d : ", i);
    //cout << (i-1) + to_left[i-1][0]*2 + to_right[i][0]*2 << endl;
    res = min(res, (i-1) + to_left[i-1][0]*2 + to_right[i][0]*2);
  }
  cout << res << endl;
  return 0;
}

