template <class T, class U> inline bool chmax(T& lhs, const U& rhs) { if (lhs < rhs) { lhs = rhs; return 1; } return 0; }
template <class T, class U> inline bool chmin(T& lhs, const U& rhs) { if (lhs > rhs) { lhs = rhs; return 1; } return 0; }

typedef long long lint;
#define int long long

int calculate(lint x, lint y) {
    int res = 0;
    while (x > y) {
        y *= 4;
        ++res;
    }
    return res;
}

int calculate2(lint x, lint y) {
    int res = 0;
    while (x * 4 <= y) {
        ++res;
        x *= 4;
    }
    return res;
}

std::vector<int> solve(const std::vector<lint>& vec) {
    int N = vec.size();
    std::vector<int> res(N);
    std::stack<int> next;
    next.push(N);
    for (int i = N - 2; i >= 0; --i) {
        res[i] += res[i + 1];
        int need = calculate(vec[i], vec[i + 1]);
        if (need == 0) {
            int push = calculate2(vec[i], vec[i + 1]);
            while (push--) next.push(i + 1);
            continue;
        }
        int add = 0, prev = i + 1;
        for (int coeff = need; coeff > 0; --coeff) {
            int border = next.top();
            add += (border - prev) * coeff;
            prev = border;
            if (border == N) {
                break;
            }
            next.pop();
        }
        res[i] += add;
    }
    return res;
}

signed main() {

    int N;
    std::cin >> N;
    std::vector<lint> A(N);
    rep (i, N) std::cin >> A[i];

    std::vector<lint> B = A;
    std::reverse(all(B));
    rep (i, N) B[i] *= 2;

    std::vector<int> fr = solve(A), ba = solve(B);
    std::reverse(all(ba));
    rep (i, N) {
        fr[i] *= 2;
        ba[i] = ba[i] * 2 + i + 1;
    }

    int answer = std::min(fr.front(), ba.back());
    rep (i, N - 1) chmin(answer, ba[i] + fr[i + 1]);
    std::cout << answer << '\n';
    return 0;

}

