        int cnt = 0;
        while (y < x) {
            y *= 4;
            cnt++;
        }
        while (cnt > 0) {
            if (stk.empty()) {
                s += (ll)(n - i - 1) * cnt * 2;
                cnt = 0;
            } else {
                auto [j, c] = stk.top();
                int c1 = min(cnt, c);
                s += (ll)(j - i - 1) * c1 * 2;
                cnt -= c1;
                if (c == c1) {
                    stk.pop();
                }
            }
        }
        b[i] = s;
        int cnt1 = 0;
        while (y >= 4 * x) {
            x *= 4;
            cnt1++;
        }
        if (cnt1 > 0) {
            stk.emplace(i + 1, cnt1);
        }
    }
    return b;
}

