    auto score2 = computeScore(a);
    reverse(score2.begin(), score2.end());

    int64_t ans = (1LL << 50);

    for (int i = 0; i < n; i++) {
        ans = min(ans, i + score1[i] + (i > 0 ? score2[i - 1] : 0));
    }
    cout << ans << endl;

    return 0;
}

