template<class T> using V = vector<T>;
template<class T> using VV = V<V<T>>;
constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n-1); }

using P = pair<ll, ll>;

V<ll> solve(V<ll> v) {
    int n = int(v.size());
    V<ll> ans(n + 1); ans[n-1] = ans[n] = 0;
    V<P> st;
    st.push_back(P(1, TEN(9)));
    ll all_c = 0;
    auto inc = [&](ll x) {
        while (x) {
            P pa = st.back(); st.pop_back();
            ll u = min(x, pa.second);
            all_c += 2 * pa.first * u;
            x -= u;
            pa.second -= u;
            if (pa.second == 0) {
                assert(st.size());
                st.back().first += pa.first;
            } else {
                st.push_back(pa);
            }
        }
    };
    ll bk = v[n - 1];
    for (int i = n-2; i >= 0; i--) {
        //add v[i]
        ll nw = v[i];
        ll c = 0;
        while (bk < nw) {
            c++;
            bk *= 4;
        }
        inc(c);
        c = 0;
        while (4 * nw <= bk) {
            c++;
            nw *= 4;
        }
        st.push_back(P(1, c));
        bk = v[i];
        ans[i] = all_c;
    }
    return ans;
}

