//const ll mod = 1000000007;
struct UnionFind {
    vector<int> par;
    vector<int> rank;
    vector<ll> Size;
    vector<ll> l, r;
    UnionFind(int n = 1) {
        init(n);
    }

    void init(int n = 1) {
        par.resize(n + 1); rank.resize(n + 1); Size.resize(n + 1);
        l.resize(n + 1), r.resize(n+1);
        for (int i = 0; i <= n; ++i) l[i] = i, r[i] = i, par[i] = i, rank[i] = 0, Size[i] = 1;
    }

    int root(int x) {
        if (par[x] == x) {
            return x;
        }
        else {
            int r = root(par[x]);
            return par[x] = r;
        }
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        Size[x] += Size[y];
        chmin(l[x], l[y]);
        chmax(r[x], r[y]);
        return true;
    }

    ll size(int x){
        return Size[root(x)];
    }
};

ll N;
vector<ll> A;
ll g(ll a, ll b) {
    if(a == b) return 0;
    if(a < b) {
        ll ret = 0;
        while(a < b) {
            a *= 4;
            ret += 2;
        }
        return ret;
    } else {
        return -g(b, a) + 2;
    }
}
vector<ll> f(vector<ll> A) {
    vector<ll> L(N + 1);
    vector<ll> add(N);
    UnionFind uni(N);
    for(int i = N - 1; i >= 0; i--) {
        ll delta = 0;
        ll idx = i + 1;
        while(idx <= N - 1) {
            ll tmp = g(A[idx], A[idx-1]) + add[idx-1] - add[idx];
            //cerr << idx << " " << tmp << endl;
            if(tmp <= 0) break;
            delta += tmp * uni.size(idx);
            ll l = uni.l[uni.root(idx)];
            ll r = uni.r[uni.root(idx)];
            //cerr << i << " " << idx << " " << l << " " << r << " " << tmp << endl;
            add[l] += tmp;
            if(l != r) add[r] += tmp;
            idx = r + 1;
            uni.merge(l, l - 1);
        }
        L[i] = L[i+1] + delta;
    }
    return L;
}

