						cnt = 0;
						q.push(tmpp); 
						break;
					}
					x = q.front().second;
					q.pop();
				}
				g[i] += 1ll * (x - 1) * cnt; 	
			}
			else
			{
				ll tmp = b[i];
				int cnt = 0;
				while (tmp * 4 >= b[i - 1]) 
				{
					tmp *= 4;
					cnt += 2;
