signed main(){
  ll n;
  cin>>n;
  for(ll i=1;i<=n;i++) cin>>ar[i];
  for(ll i=0;i<200005;i++){
    for(ll j=0;j<=15;j++){
      dp1[i][j]=inf;
      dp2[i][j]=inf;
    }
  }
  for(ll i=0;i<=15;i++){
    dp1[n+1][i]=0;
    dp1[n][i]=i;
  }
  for(ll i=n-1;i>=1;i--){
    for(ll j=0;j<=15;j++){
      ll dis=(ar[i]*((ll)1<<(2*j))/ar[i+1]);
      ll x=0;
      while(dis>0){
        dis/=4;
        x++;
      }
      if(x>=15) dp1[i][j]=min(dp1[i][j],(n-i)*(x-15)+dp1[i+1][15]+j);
      else dp1[i][j]=min(dp1[i][j],dp1[i+1][x]+j);
    }
  }
  for(ll i=0;i<=15;i++) {
    dp2[0][i]=0;
    dp2[1][i]=i;
  }
  for(ll i=2;i<=n;i++){
    for(ll j=0;j<=15;j++){
      ll dis=(ar[i]*((ll)1<<(2*j))/ar[i-1]);
      ll x=0;
      while(dis>0){
        dis/=4;
        x++;
      }
      if(x>=15) dp2[i][j]=min(dp2[i][j],(i-1)*(x-15)+dp2[i-1][15]+j);
