int solve(vector<int> X, vector<int> &R) {
	int N = X.size();
	R.resize(N);
	R.back() = 0;
	int last = N - 1;
	for (int i = N - 2; i >= 0; i--) {
		R[i] = R[i + 1];
		for (int j = i + 1; j <= last; j++) {
			if (X[j - 1] <= X[j])break;
			if (j == last) {

				while (X[j - 1] > X[j]) {
					X[j] *= 4;
					R[i] += 2 * (N - j);
				}
				last = i;
				break;
			}
			while (X[j - 1] > X[j]) {
				X[j] *= 4;
				R[i] += 2;
			}
		}
	}

}

