		//iまでを正の降順にするために必要な回数
		ans = 0;
		if(x[i-1] >= x[i]){
			nega[i] = nega[i-1];
			num = 0;
			a = x[i-1];
			b = x[i];
			while(a > b * 4){
				b *= 4;
				num++;
			}
			if(num == 0){
				len[snum]++;
			}else{
				snum++;
				len[snum] = 1;
				dep[snum] = dep[snum-1] - num;
			}
		}else{
			a = x[i-1];
			b = x[i];
			num = 0;
			while(a < b){
				a *= 4;
				num++;
			}
			num += dep[snum];
			for(j=snum;j>=0;j--){
				if(num > dep[j]){
					/*if(i == 2){
						p("-----");
						pe(num - dep[j]);
						p(len[j]);
						p("-----");
					}*/
					ans += (num - dep[j]) * len[j];
					dep[j] = num;
				}else{
					break;
				}
			}
			c = 0;
			a = snum;
			while(dep[snum] == num && snum >= 0){
				c += len[snum];
				len[snum] = 0;
				dep[snum] = 0;
				snum--;
			}
			if(snum == -1){
				snum = 0;
				len[snum] = c + 1;
				dep[snum] = num;
			}else{
				snum ++;
				len[snum] = c + 1;
				dep[snum] = num;
			}
		}
		nega[i] = nega[i-1] + ans * 2;
		ans = 0;
	}
	ans = posi[0];
	for(i=0;i<n-1;i++){
		ans = min(ans,nega[i] + posi[i+1] + i + 1);
	}
	ans = min(ans,nega[n-1]);
