template<typename T,const int MAXSSTN=50010>
class StarrySkyTree{
public:
  int size=0;
  int depth=0; // the depth of the tree
  int best=0;  // the index of maximum element
  int start=0; // the initial index of inputs
  T dat_add[4 * MAXSSTN];
  T dat[4 * MAXSSTN];
  StarrySkyTree(int n){
    init(n);
    for(int i=start;i<(1<<(depth+1));i++){
      if(i<start+n)
	dat[i]=0;
    }
    for(int i=start;i<start+n;i++){
      int tmp=i;
      while(par(tmp)!=-1){
	dat[par(tmp)]=parent(tmp);
	tmp=par(tmp);
      }
    }
    int i=0;
    while(i<start)i=(dat[i]==dat[2*i+1])?2*i+1:2*i+2;
    best=i-start;
  }
  StarrySkyTree(int n,T* v){
    init(n);
    for(int i=start;i<(1<<(depth+1));i++){
      if(i<start+n)
	dat[i]=v[i-start];
    }
    for(int i=start;i<start+n;i++){
      int tmp=i;
      while(par(tmp)!=-1){
	dat[par(tmp)]=parent(tmp);
	tmp=par(tmp);
      }
    }
    int i=0;
    while(i<start)i=(dat[i]==dat[2*i+1])?2*i+1:2*i+2;
    best=i-start;
  }
  T max_element(int a, int b){ return max_element(a, b, 0, 0, (1<<depth)); }
  void add(int s, int t, T x){ add(s, t, 0, 0, (1<<depth), x); }
  void add(int i, T x){ add(i, i + 1, 0, 0, (1<<depth), x); }

  int par(int i){
    if(i==0)
      return -1;
    return (i-1)/2;
  }

  void clear(int n) {
    init(n);
    for(int i=start;i<(1<<(depth+1));i++){
      if(i<start+n)
	dat[i]=0;
    }
    for(int i=start;i<start+n;i++){
      int tmp=i;
      while(par(tmp)!=-1){
	dat[par(tmp)]=parent(tmp);
	tmp=par(tmp);
      }
    }
    int i=0;
    while(i<start)i=(dat[i]==dat[2*i+1])?2*i+1:2*i+2;
    best=i-start;
  }

  void update(int d,T x){
    int i=d+start;
    dat[i]=x;
    while(par(i)!=-1){
      dat[par(i)]=parent(i);
      i=par(i);
    }
    i=0;
    while(i<start){
      i=(dat[i]==dat[2*i+1])?2*i+1:2*i+2;
    }
    best=i-start;
  }
  void dump(){
    for(int i=0;i<(depth+1);i++){
      for(int j=0;j<(1<<i);j++)
	print_(dat[j+(1<<i)-1]);
      cerr<<endl;
    }
    cerr<<endl;
  }
private:
  void print_(T a){
    cerr<<a<<" ";
  }
  T unit_max(){
    return -1e18;
  }
  T unit_add(){
    return 0;
  }
  T max_(T a,T b){
    return max(a,b);
  }
  T add_(T a,T b){
    return a+b;
  }
  T parent(int tmp){
    return (tmp<((tmp+1)/2*4-1-tmp))?max_(dat[tmp],dat[(tmp+1)/2*4-1-tmp]):max_(dat[(tmp+1)/2*4-1-tmp],dat[tmp]);
  }
  void init(int n){
    size=n;
    while((1<<depth)<n)depth++;
    start=(1<<depth)-1;
    for(int i=0;i<4*MAXSSTN;i++){
      dat_add[i]=unit_add();
      dat[i]=unit_max();
    }
    for(int i=start;i<(1<<(depth+1));i++){
      dat[i]=unit_max();
    }
  }
  T max_element(int a, int b, int k, int l, int r){
    if(b <= l || r <= a) return unit_max();
    if(a <= l && r <= b) return add_(dat[k],dat_add[k]);

    T vl = max_element(a, b, k * 2+1, l, (l + r) / 2);
    T vr = max_element(a, b, k * 2+2, (l + r) / 2, r);
    return add_(max_(vl, vr),dat_add[k]);
  }
  void add(int a, int b, int k, int l, int r, T x){
    if(b <= l || r <= a) return;
    if(a <= l && r <= b){
      dat_add[k] =add_(dat_add[k],x);
    }else{
      add(a, b, k * 2+1, l, (l + r) / 2, x);
      add(a, b, k * 2+2, (l + r) / 2, r, x);
      dat[k] = max_(add_(dat[k * 2+1],dat_add[k * 2+1]), add_(dat[k * 2 + 2],dat_add[k * 2 + 2]));
    }
  }
};

int n;
LL a[200000],ll[200001],ll_rev[200001],adel[200000],adp[200000];

LL delt(LL a,LL b){
  LL ret = 0;
  if(a <= b){
    while(a*4 <= b){
      a*=4;
      ret++;
    }
    return ret;
  }
  ret--;
  while(b*4 < a){
      b*=4;
      ret--;
  }
  return ret;
}

int main(){
  cin>>n;
  REP(i,n)cin>>a[i];
  REP(i,n)adp[i]=a[i];

  StarrySkyTree<LL> sst(n);
  ll[n] = 0;
  ll[n-1] = 0;
  REP(i,n-1){
    int irev = n-2-i;
    LL target = a[irev];
    LL nbh    = a[irev+1];
    LL delta = delt(target,nbh);
    LL asgn = 0;
    if(delta >= 0){
      ll[irev] = ll[irev+1];
      sst.update(irev,delta);
    }else{
      while(-delta){
        int lb = irev+1;
        int ub = n-1;
        if(sst.max_element(irev+1,n) == 0){
          asgn += n-1-irev;
          delta++;
          continue;
        }
        while(lb < ub){
          int mid = (lb+ub)/2;
          if(sst.max_element(irev+1,mid+1) > 0){
            ub = mid-1;
          }else{
            lb = mid;
          }
        }
        sst.add(lb,1LL);
        asgn += lb-irev;
        delta++;
      }

      ll[irev] = ll[irev+1]+asgn;
      sst.update(irev,0);
    }
  }

  sst.clear(n);

  ll_rev[0] = 0;
  ll_rev[1] = 0;

  REP(i,n-1){
    int irev = n-2-i;
    int irev_idx = i+2;
    LL target = a[irev_idx-1];
    LL nbh    = a[irev_idx-2];
    LL delta = delt(target,nbh);
    LL asgn = 0;
    if(delta >= 0){
      ll_rev[irev_idx] = ll_rev[irev_idx-1];
      sst.update(irev,delta);
    }else{
      while(-delta){
        int lb = irev+1;
        int ub = n-1;
        if(sst.max_element(irev+1,n) == 0){
          asgn += n-1-irev;
          delta++;
          continue;
        }
        while(lb < ub){
          int mid = (lb+ub)/2;
          if(sst.max_element(irev+1,mid+1) > 0){
            ub = mid-1;
          }else{
            lb = mid;
          }
        }
        sst.add(lb,1LL);
        asgn += lb-irev;
        delta++;
      }
      ll_rev[irev_idx] = ll_rev[irev_idx-1]+asgn;
      sst.update(irev,0);
    }
  }

  /*REP(i,n+1)cerr<<ll[i]<<" ";
  cerr<<endl;
  REP(i,n+1)cerr<<ll_rev[i]<<" ";
  cerr<<endl;*/

  REP(i,n+1)ll[i]*=2;
  REP(i,n+1)ll_rev[i] = i+ll_rev[i]*2;
  LL ret = 1e15;
  REP(i,n+1)ret = min(ret,ll[i]+ll_rev[i]);
  cout<<ret<<endl;
  return 0;
}

