void calc(vector<double>& lg, vector<int>& so, int n) {
	vector<pii> po;

	int cou = 0;
	double cur = lg[n - 1];

	for (int i = n - 1; 0 <= i; i--) {
		int nex = i ? lg[i] : 0;

		if (nex > cur) {
			int sa = ceil((nex - cur) / 2) * 2;

			int cpos = i;
			for (auto itr = po.rbegin(); itr != po.rend(); ++itr) {
				if (itr->second >= sa) {
					itr->second -= sa;
					sa = 0;
					cou += (itr->first - cpos)*sa;
					break;
				}
				else {
					cou += (itr->first - cpos)*itr->second;
					sa -= itr->second;
					itr->second = 0;
				}
			}

			cou += sa * (n- cpos);
		}
		else if (cur - nex >= 2) po.push_back({ i, ((int)((cur - nex) / 2)) * 2 });

		cur = nex;

		so[i] = cou;
	}
}

