int main() {
  int n;
  cin >> n;
  vector<int64_t> a(n);
  cin >> a;
  vector<int64_t> dp1(n + 1), dp2(n + 1);
  auto b = a;
  for (int i = 0; i < n; ++i) {
    b[i] *= -2;
    dp1[i + 1] = dp1[i] + 1;
    for (int j = i - 1; j >= 0; --j) {
      if (b[j] < -1e12) {
        dp1[i + 1] += 2 * (j + 1);
        break;
      } else {
        while (b[j] > b[j + 1]) {
          dp1[i + 1] += 2;
          b[j] *= 4;
        }
      }
    }
  }
  reverse(a);
  b = a;
  for (int i = 0; i < n; ++i) {
    dp2[i + 1] = dp2[i];
    for (int j = i - 1; j >= 0; --j) {
      if (b[j] > 1e12) {
        dp2[i + 1] += 2 * (j + 1);
        break;
      } else {
        while (b[j] < b[j + 1]) {
          dp2[i + 1] += 2;
          b[j] *= 4;
        }
      }
    }
  }
  int64_t res = numeric_limits<int64_t>::max();
  for (int i = 0; i <= n; ++i) chmin(res, dp1[i] + dp2[n - i]);
  cout << res << endl;
}

