};

ostream& operator<<(ostream& os, State &s) {
	cerr << endl;
	os << "{mini = " << s.mini << " maxi = " << s.maxi << " q = " << s.q << "}\n";
	return os;
};

void buildsuf() {
	vector<State> st;	
	ll cur = 0;
	fdi(n, 1) {
		State val = State(mp(a[i], deg[i]), mp(a[i], deg[i]), 1LL);		
		while (sz(st)) {
			State nxt = st.back();			
			if (!cmp(nxt.mini, val.maxi)) break;
			st.pop_back();
			while (cmp(nxt.mini, val.maxi)) {
				cur += nxt.q * 2;
				nxt.mini.second += 2;
				nxt.maxi.second += 2;
			}			
			val.q += nxt.q;
			val.maxi = nxt.maxi;
		}
		st.pb(val);
//		dbg(i);
//		dbg(st);		
		suf[i] = cur;
	}
	dbg1(suf, n);
}

void buildpref() {	
	vector<State> st;	
	ll cur = 0;
	fi(1, n) {
		State val = State(mp(a[i], deg[i] + 1), mp(a[i], deg[i] + 1), 1LL);		
		while (sz(st)) {
			State nxt = st.back();			
			if (!cmp(nxt.mini, val.maxi)) break;
			st.pop_back();
			while (cmp(nxt.mini, val.maxi)) {
				cur += nxt.q * 2;
				nxt.mini.second += 2;
				nxt.maxi.second += 2;
			}			
			val.q += nxt.q;
			val.maxi = nxt.maxi;
		}
		st.pb(val);
//		dbg(i);
//		dbg(st);		
		pref[i] = cur + i;
	}
	dbg1(pref, n);
}

void solve() {
	buildsuf();
	buildpref();
	ans = INF;
	fi(0, n) {
		ans = min(ans, pref[i] + suf[i + 1]);
	}	
	printf("%lld\n", ans);
}

