        while(st.size()){
            auto p = st.top();
            st.pop();
            if(p.second >= k){
                p.second-=k;
                st.push(p);
                k = 0;
                break;
            }else{
                k-=p.second;
                res[i-1] += (p.first-i-1)*k;
            }
        }
        res[i-1] += (n-i-1)*k;
        if(hoge(a[i-1],a[i]))st.emplace((ll)i,hoge(a[i-1],a[i]));
