	//positive[i]は、A[N-i]からA[N-1]までをすべて正で昇順に並べるのにかかる手数
	//negative[i]は、A[0]からA[i-1]までをすべて負で昇順に並べるのにかかる手数
	scanf("%d", &N);
	for (int i = 0; i < N; i++) {
		scanf("%d", &A[i]);
	}

