                if (e >= B) { break; }
                lneed[i] += 2, lst[h + 1].insert(e), er.push_back(e), next = std::max(next, e);
            }
            if (next == 0) { break; }
            B = next;
            for (const ld e : er) { lst[h].erase(e); }
        }
    }
    for (int i = 1; i < N; i++) { lneed[i] += lneed[i - 1]; }
    //    show(rneed), show(lneed);
    ll ans = std::min(rneed[0], lneed[N - 1] + N);
    for (int i = 0; i < N - 1; i++) { ans = std::min(ans, lneed[i] + i + 1 + rneed[i + 1]); }
    std::cout << ans << std::endl;
    return 0;
}

