	for(int i=n-1;i>=1;i--){
		b[i-1] = b[i];
		ll cur = a[i];
		ll nex = a[i-1];
		ll cnt = 0;
		if(nex <= cur){
			while(nex * 4 <= cur){
				nex *= 4;
				cnt++;
			}
			if(cnt>0){
				place.pb(i);
				decr.pb(cnt);
			}
		}
		else{
			while(nex > cur){
				cur *= 4;
				cnt++;
			}
			b[i-1] += cnt * (n-i);
			for(int j = place.size()-1 ; j>=0 ; j--){
				ll ab = min(cnt, decr[j]);
				b[i-1] -= ab * (n-place[j]);
				cnt -= ab;
				if(cnt == 0)j=-1;
			}
		}
	}
	place.clear();
	decr.clear();
	reverse(a.begin(),a.end());
	for(int i=n-1;i>=1;i--){
