#define ll long long 
#define N 200010
int n;
ll a[N], b[N], f[N], g[N], lazy;  

int main()
{
	while (scanf("%d", &n) != EOF)
	{
		for (int i = 1; i <= n; ++i) scanf("%lld", a + i);
		lazy = 0; f[n] = 0; 
		priority_queue <ll, vector <ll>, greater <ll> > pq;  
		for (int i = n - 1; i >= 1; --i) 
		{
			f[i] = f[i + 1];
			if (a[i] > a[i + 1]) 
			{
				ll tmp = a[i + 1];
				int cnt = 0; 
				while (tmp < a[i]) 
				{
					tmp *= 4;
					cnt += 2;
				}
				f[i] += 1ll * (n - i - pq.size()) * cnt; 
				lazy += cnt; 
				while (!pq.empty() && pq.top() - lazy <= 0)  
				{
					f[i] += lazy - pq.top();  
					pq.pop();
				}
			}
			else
			{
				ll tmp = a[i]; 
				int cnt = 0;
				while (tmp * 4 < a[i + 1])
				{
					tmp *= 4;
					cnt += 2;
				}
				if (cnt) pq.push(cnt);  
			}
		}
		while (!pq.empty()) pq.pop();
		lazy = 0; 
		g[1] = 1;
		b[1] = -a[1];
		for (int i = 2; i <= n; ++i)
		{
			g[i] = g[i - 1] + 1;
			b[i] = -a[i];
			if (b[i] < b[i - 1])
			{
				ll tmp = b[i - 1];
				int cnt = 0;
				while (tmp > b[i])
				{
					tmp *= 4;
					cnt += 2;
				}
				g[i] += 1ll * (i - 1 - pq.size()) * cnt; 
				lazy += cnt;
				while (!pq.empty() && pq.top() - lazy <= 0)
				{
					g[i] += lazy - pq.top();
					pq.pop();
				}
			}
			else
			{
				ll tmp = b[i - 1];
				int cnt = 0;
				while (tmp * 4 > b[i])
				{
					tmp *= 4;
					cnt += 2;
				}
				if (cnt) pq.push(cnt);
			}
		}
		ll res = min(f[1], g[n]);
		for (int i = 1; i < n; ++i) res = min(res, g[i] + f[i + 1]);
		printf("%lld\n", res);
	}
	return 0;
}

