		scanf("%d", &v[i]);
	vector<ll> pre(n + 2), suf(n + 2);
	for (int it = 0; it < 2; ++it) {
		vector<pair<ll, int> > s;
		for (int i = 2; i <= n; ++i) {
			ll a = v[i - 1];
			ll b = v[i];
			if (a >= b) {
				pre[i] = pre[i - 1];
				ll times = 0;
				while (a >= b * 4) {
					++times;
					b *= 4;
				}
				s.push_back({ times,i });
			}
			else {
				ll need = 0;
				while (a < b) {
					a *= 4;
					++need;
				}
				ll now = need*(i - 1 - s.size());
				ll cur = need;
				while (!s.empty()) {
					s.back().first -= cur;
					if (s.back().first == 0) {
						s.pop_back();
						break;
					}
					else if (s.back().first < 0) {
						cur = -s.back().first;
						ll idx = s.back().second;
						s.pop_back();
						ll curIdx = 0;
						if (!s.empty())
							curIdx = s.back().second;
						now += cur;
						if (curIdx != idx - 1)
							break;
					}
					else
						break;
				}
				pre[i] = pre[i - 1] + now;
			}
		}
		pre.swap(suf);
		reverse(v.begin(), v.end());
	}
	reverse(suf.begin(), suf.end());
	for (int i = 1; i <= n; ++i) {
		pre[i] <<= 1;
		suf[i] <<= 1;
		pre[i] += i;
	}
	ll res = suf[1];
	for (int i = 1; i + 1 <= n; ++i)
		res = min(res, pre[i] + suf[i + 1]);
	printf("%lld\n", res);
	return 0;
}

