struct BIT {
	vector<int> bit;
	int n;

	BIT(int N) :n(N + 2), bit(N * 2) {}

	int sum(int i) {
		++i;
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, int x) {
		++i;
		while (i <= n) {
			bit[i] += x;
			i += i & (-i);
		}
	}
};

void solve()
{
	int N; cin >> N;
	vector<double> A(N);
	REP(i, N) {
		int a; cin >> a;
		A[i] = log2(a);
	}

	vector<vector<int> > dpRight(N, vector<int>(20));
	RFOR(i, 0, dpRight.size() - 1) {
		REP(j, dpRight[i].size()) {
			auto num = A[i + 1];
			int cnt = 0;
			while (A[i] + j * 2.0 > num) {
				num += 2.0;
				++cnt;
			}
			int index = min(cnt, dpRight[i].size() - 1LL);
			dpRight[i][j] = dpRight[i + 1][index] + cnt;
		}
	}

	vector<vector<int> > dpLeft(N, vector<int>(20));
	FOR(i, 1, dpLeft.size()) {
		REP(j, dpLeft[i].size()) {
			auto left = A[i-1];
			auto right = A[i];
			int cnt = 0;
			while (left < right + j * 2.0) {
				left += 2.0;
				++cnt;
			}
			int index = min(cnt, dpLeft[i].size() - 1LL);
			dpLeft[i][j] = dpLeft[i - 1][index] + cnt;
		}
	}

	int ans = min(dpLeft.back()[0],dpRight.front()[0])*2;
	REP(i, N-1) {
		auto left = i;
		auto right = i + 1;
		ans = min((dpLeft[left][0] + dpRight[right][0])*2 + (i + 1), ans);
	}
	cout << ans << endl;
}

