int64_t log4(int64_t val) {
    int64_t res = 0;
    while (val > (int64_t(1) << (2 * res)))
        res += 1;

    return res;
}

int64_t log4xl(__int128_t val) {
    int64_t res = 0;
    while (val > (__int128_t(1) << __int128_t(2 * res)))
        res += 1;

    return res;
}


vector<vector<int64_t>> calc(vector<int> a) {
    const int n = SZ(a);
    vector<vector<int64_t>> f(n + 1, vector<int64_t>(32)); // [0; 31].

    for (int from = n - 2; from >= 0; --from) {
        int pos = from + 1;

        __int128_t num = a[pos - 1];
        for (int z = 0; z <= 31; ++z, num *= 4) {
            int64_t dv = log4xl((num + a[pos] - 1) / a[pos]);
            if (dv <= 30)
                f[from][z] = dv + f[from + 1][dv];
            else
                f[from][z] = dv + f[from + 1][30] + (dv - 30) * (n - pos - 1);
        }
    }

    // for (int from = n - 1; from >= 0; --from) {
    //     pre_a[from] = pre_a[from + 1];

    //     int pos = from + 1;
    //     if (pos < n) {
