#include <bits/stdc++.h>
#define MAXN 200100
#define MAXL 80
#define INF 1800004407370900666
using namespace std;
typedef long long int lli;

lli seq[MAXN];
lli pd[MAXN][MAXL];
lli n;

lli expo(lli n, lli e){
	if(e==0) return 1;
	if(e==1) return n;
	lli ax;
	if(e%2==0){
		ax = expo(n,e/2);
		if(abs(ax) >= INF) return 0;
		return ax*ax;
	}
	ax = n*expo(n,e-1);
	if(abs(ax) >= INF) return 0;
	return n*expo(n,e-1);
}

lli eleva(lli n, lli e){
	lli res = n;

	lli two = expo(-2,e);
	if(two == 0) return 0;
	res *= two;
	if(res >= INF) return 0;
	return res;
}
int ok;
lli solve(lli ind, lli e){

	if(ind == n+1){
		ok = 1;
		return 0;

	}
	lli i;
	lli res = INF;
	lli ax = eleva(seq[ind-1],e);
	if(ind != 1 && ax == 0) return INF;
	if(pd[ind][e] != -1) return pd[ind][e];


	for(i = 0; i <= 70; i++){ //

		if(ind != 1){
			lli ax2 = eleva(seq[ind],i);
			if(ax2 == 0) break;
			if(ax > ax2) continue;
			else res = min(solve(ind+1,i)+i, res);
		}else{
			res = min(solve(ind+1,i)+i, res);
		}
	}
	return pd[ind][e] = res;
}


int main (){

	cin >> n;

	lli i,j;

	for(i = 1; i <= n; i++){
		cin >> seq[i];
		for(j = 0; j <= 70; j++){
			pd[i][j] = -1;
		}
	}
	lli res = solve(1,0);
	if(ok) cout << res << endl;
	else cout << -1 << endl;
}

