using namespace std;

long long N, X[100009], E[100009], G;

vector<long long> solve() {
	G = X[0];
	for (int i = 1; i < N; i++) {
		if (G <= X[i]) { G = X[i]; E[i] = 0; }
		else {
			if (X[i - 1] >= X[i]) {
				for (int j = 0; j < 32; j++) {
					if (X[i - 1] <= (1LL << j)*X[i]) { E[i] = E[i - 1] + j; break; }
				}
			}
			else {
				for (int j = 0; j < 32; j++) {
					if ((1LL << j) * X[i - 1] > X[i]) { E[i] = E[i - 1] - (j - 1); break; }
				}
			}
		}
	}

	long long sum = 0, ret = 0, pos = 0; for (int i = 0; i < N; i++) sum += E[i];
	vector<long long>res; res.push_back(sum);

	for (int i = 0; i < N - 1; i++) {
		for (int j = i + 1; j <= N; j++) {
			long long JURAI = E[j]; if (j > pos) JURAI -= ret;

			if (j == i + 1) {
				E[i + 1] = 0;
			}
			else {
				if (G <= X[j]) { G = X[j]; E[j] = 0; }
				else {
					if (X[j - 1] >= X[j]) {
						for (int k = 0; k < 32; k++) {
							if (X[j - 1] <= (1LL << k)*X[j]) { E[j] = E[j - 1] + k; break; }
						}
					}
					else {
						for (int k = 0; k < 32; k++) {
							if ((1LL << k) * X[j - 1] > X[j]) { E[j] = E[j - 1] - (k - 1); break; }
						}
					}
				}
			}
			sum -= (JURAI - E[j]);
			if (E[j] >= 30 || j == N - 1 || JURAI - E[j] == 0) {
				ret = JURAI - E[j]; pos = j;
				res.push_back(sum - ret * (N - pos - 1));
			}
		}
	}
	res.push_back(0);
	return res;
}

int main() {
	cin >> N;
	for (int i = 0; i < N; i++) cin >> X[i];

	vector<long long> v1 = solve(); reverse(X, X + N);
	vector<long long> v2 = solve();
	reverse(v2.begin(), v2.end());
	long long minx = (1LL << 60);
	for (int i = 0; i <= N; i++) minx = min(minx, v1[i] + v2[i] + i);
	cout << minx << endl;
	return 0;
}

