vector <ll> dp(vector <ll> A){
    vector <ll> DP;
    A.pb(inf);
    DP.resize(maxn);
    DP[n - 1] = 0;
    ll q;
    vector <pll> LAST;
    LAST.pb(mp(n - 1, A[n - 1]));
    for (q = n - 2; q >= 0; q--){
        ll c = 0;
        ll a = A[q], b = A[q + 1];
        while (a > b){
            c++;
            b *= 4;
        }
//        cout << "q c " << q << " " << c << endl;
        if (c == 0){
            DP[q] = DP[q + 1];
            LAST.pb(mp(q, A[q]));
//            cout << "DP " <<  q << " " << DP[q] << endl;
            continue;
        }
        ll ans = DP[q + 1];
        ll nc = c;
        ll j = q;
        while (LAST.size() != 0){
            ll last = LAST[LAST.size() - 1].second;
            ll i = LAST[LAST.size() - 1].first;
            ans = ans + nc * (i - j);
            if (last * st2[2 * nc] <= A[i + 1]){
                LAST[LAST.size() - 1].second *= st2[2 * nc];
                break;
            }
            else{
                ll a, b, dc = 0;
                a = last * st2[2 * nc], b = A[i + 1];
                while (a > b){
                    dc++;
                    b *= 4;
                }
                nc = dc;
                LAST.pop_back();
                if (LAST.size() == 0){
                    break;
                }
                LAST[LAST.size() - 1].second *= (last / A[i]);
            }
        }
//        ll last = LAST[LAST.size() - 1].first;
        DP[q] = ans;
//        cout << "DP " <<  q << " " << DP[q] << endl;
    }
    return DP;
}

