ll arr[200005], pre[200005], suf[200005], rem[200005];
void solve(int n, ll *ans)
{
	std::set<int> se = {n - 1};
	for (int i = 0; i < n; i++)
		rem[i] = 0;
	for (int i = n - 2; i >= 0; i--)
	{
		ans[i] = ans[i + 1];
		if (arr[i + 1] >= arr[i])
		{
			int x = 0;
			while (arr[i] << (x << 1) <= arr[i + 1])
				x++;
			rem[i] = x - 1;
			if (rem[i])
				se.insert(i);
			continue;
		}
		ll cur = arr[i + 1];
		while (cur < arr[i])
		{
			int x = *se.begin();
			if (!--rem[x])
				se.erase(x);
			ans[i] += x - i << 1;
			cur <<= 2;
		}
	}
}
