			pre[u]=pre[u-1];
		}
		else
		{
			int t=calc(a[u-1],a[u]);
			while (top>0&&sta[top]<=t)	{t=t-sta[top];top--;}
			pre[u]=pre[u-1]+calc(a[u-1],a[u])*(u-sta1[top]-1);
		}
	}
	LL ans=suf[1];
	for (LL u=2;u<=n+1;u++) ans=min(ans,pre[u-1]+u-1+suf[u]);
	printf("%lld\n",ans);
	return 0;
}

