    ll a[n+1] = {};
	srep(i, 1, n+1)cin >> a[i];

    // DPポジティブ
    ll dpp[n+1][15];
    int mcount[n+1][15]; // multiple count

    // dpp[n]初期化
    dpp[n][0] = 0;
    mcount[n][0] = 0;
    int shoki = 0;
    ll ashoki = a[n];
    while(ashoki*4 <= 1000000000){
        shoki++;
        ashoki = ashoki*4;
        dpp[n][shoki] = shoki*2;
        mcount[n][shoki] = shoki;
    }
    srep(i, shoki, 15){
        dpp[n][i] = shoki*2;
        mcount[n][i] = shoki;
    }

    // dpp回す
    for(int i=n-1; i>=1; --i){
        ll ai = a[i];
        ll ai1 = a[i+1];
        ll ai1_max = ruijou(ai1,mcount[i+1][14]);
        if(ai>ai1_max){  // そもそもデカい(最大<4*ai1[14])
            rep(j, 15){
                dpp[i][j] = dpp[i+1][14] + (n-i)*2;
                mcount[i][j] = 0;
            }
        }else{ // 普通に計算
            //[i][14]埋める
            int jjj = 0;
            while(ai*4<=ai1_max){
                jjj++;
                ai = ai*4;
            }
            dpp[i][14] = dpp[i+1][14] + jjj*2;
            mcount[i][14] = jjj;
            //0から13計算
            for(int j=13;j>=0;--j){
                int flag = 0;
                for(int k=j;k>=0;--k){
                    if(ruijou(a[i], k) <= ruijou(a[i+1], mcount[i+1][j])){
                        dpp[i][j] = dpp[i+1][j] + k*2;
                        mcount[i][j] = k;
                        flag = 1;
                        break;
                    }
                }
                if(flag == 0){
                    dpp[i][j] = dpp[i][j+1];
                    mcount[i][j] = mcount[i][j+1];
                }           
            }
        }
    }

    dpp[0][0] = 0;
    mcount[0][0] = 0;


    // DPネガティブ
    ll dpn[n+1][15];
    int mcountn[n+1][15]; // multiple count negative

    // dpn[0]初期化
    rep(i,15){
        dpn[0][i] = 0;
        mcountn[0][i] = 0;
    }

    // dpn[1]初期化 1文字マイナス
    dpn[1][0] = 1;
    mcountn[1][0] = 0;
    int shokin = 0;
    ll ashokin = a[1] * (-2);
    while(ashokin*4 <= -2000000000){
        shokin++;
        ashokin = ashokin*4;
        dpn[1][shokin] = shokin*2 + 1;
        mcount[1][shokin] = shokin;
    }
    srep(i, shokin, 15){
        dpn[1][i] = shokin*2 + 1;
        mcount[1][i] = shokin;
    }

    // dpn回す
    for(int i=2; i<=n; ++i){
        ll ai = a[i] * (-2);
        ll ai1 = a[i-1] * (-2);
        ll ai1_max = ruijou(ai1,mcount[i-1][14]);
        if(ai<ai1_max){  // そもそもデカい(最大<4*ai1[14])
            rep(j, 15){
                dpn[i][j] = dpn[i-1][14] + (i-1)*2 + 1;
                mcount[i][j] = 0;
            }
        }else{ // 普通に計算
            //[i][14]埋める
            int jjj = 0;
            while(ai*4>=ai1_max){
                jjj++;
                ai = ai*4;
            }
            dpn[i][14] = dpn[i-1][14] + jjj*2 + 1;
            mcount[i][14] = jjj;
            //0から13計算
            for(int j=13;j>=0;--j){
                int flag = 0;
                for(int k=j;k>=0;--k){
                    if(ruijou(a[i], k) <= ruijou(a[i-1], mcount[i-1][j])){
                        dpn[i][j] = dpn[i-1][j] + k*2 + 1;
                        mcount[i][j] = k;
                        flag = 1;
                        break;
                    }
                }
                if(flag == 0){
                    dpn[i][j] = dpn[i][j+1];
                    mcount[i][j] = mcount[i][j+1];
                }           
            }
        }
    }


    ll ans = 999999999;

    /*
    rep(i, n+1){
        cout << i << "dpp=" << dpp[i][0] << "dpn=" << dpn[i][n] << endl;
    }
    */

    //ポジネガともに1文字以上
    srep(i, 1, n){
        if(ans > dpp[i+1][0] + dpn[i][0]){
            ans = dpp[i+1][0] + dpn[i][0];
            //cout << "i = " << i << endl;
        }
    }
    //ポジn文字
    if(ans > dpp[1][0]){
        ans = dpp[1][0];
    }
    //ネガn文字
    if(ans > dpn[n][0]){
        ans = dpn[n][0];
    }

    cout << ans << endl;



    return 0;
}

