int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int n; cin >> n;
  vector<LLI> a(n);
  REP(i,n) cin >> a[i];

  REPE(x,15) dp[n-1][x] = x;
  REV(i,n-2,0){
    REPE(x,15){
      int y = ceil(log10(1.0 * a[i] / a[i+1])) + x;
      if(y > 15)
	dp[i][x] = (dp[i+1][15] + (x-15)*(n-i-1)) + x;
      else
	dp[i][x] = dp[i+1][y] + x;
    }
  }

  REPE(x,15) dp2[0][x] = x;
  FOR(i,1,n){
    REPE(x,15){
      int y = ceil(log10(1.0 * a[i] / a[i-1])) + x;
      if(y > 15)
	dp2[i][x] = (dp2[i-1][15] + (x-15)*i) + x;
      else
	dp2[i][x] = dp2[i-1][y] + x;
    }
  }

  LLI ans = 1e9;

  REPE(i,n){
    LLI t = i + dp[i][0]*2 + (i==0 ? 0 : dp2[i-1][0]*2);
    ans = min(ans, t);
  }

  cout << ans << endl;

  return 0;
}

