class prime {
private:
public:
	std::vector<int> primes;
	std::vector<bool> isPrime;
	prime(int num = 0) {
		if (num == 0) return;
		isPrime.resize(num + 1);
		fill(isPrime.begin(), isPrime.end(), true);
		int ma = sqrt(num) + 1;
		isPrime[0] = isPrime[1] = false;
		int cnt = 0;
		for (int i = 2; i <= ma; ++i) if (isPrime[i]) {
			for (int j = 2; i*j <= num; ++j) {
				isPrime[i*j] = false;
				cnt++;
			}
		}
		primes.reserve(cnt);
		for (int i = 0; i < isPrime.size(); ++i) if (isPrime[i]) {
			primes.push_back(i);
		}
	}

	bool IsPrime(int num) {
		if (num < isPrime.size()) return isPrime[num];
		for (auto p : primes) {
			if (num%p == 0) return false;
		}
		int ma = sqrt(num) + 1;
		for (int i = primes.back(); i <= ma; i += 2) {
			if (num%i == 0) return false;
		}
		return true;
	}

	std::map<int, int> GetFactor(int num) {
		std::map<int, int> res;
		int a = 2;
		auto it = primes.begin();
		while (num >= a * a) {
			if (num%a == 0) {
				res[a]++;
				num /= a;
			}
			else {
				++it;
				if (it == primes.end()) {
					break;
				}
				a = *it;
			}
		}
		res[num]++;
		return res;
	}
};

int gcd(int a, int b) {
	return b != 0 ? gcd(b, a % b) : a;
}

int lcm(int a, int b) {
	return a * b / gcd(a, b);
}

// a x + b y = gcd(a, b)
int extgcd(int a, int b, int &x, int &y) {
	int g = a; x = 1; y = 0;
	if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
	return g;
}

inline long long mod(long long a, long long m) {
	return (a % m + m) % m;
}

// condition: gcd(a,m) == 1
long long modinv(long long a, long long m) {
	long long x, y;
	extgcd(a, m, x, y);
	return mod(x, m);
}

struct BIT {
	vector<int> bit;
	int n;

	BIT(int N) :n(N + 2), bit(N * 2) {}

	int sum(int i) {
		++i;
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, int x) {
		++i;
		while (i <= n) {
			bit[i] += x;
			i += i & (-i);
		}
	}
};

void solve()
{
	int N; cin >> N;
	vector<double> A(N);
	REP(i, N) {
		int a; cin >> a;
		A[i] = log2(a);
	}

	vector<vector<int> > dpRight(N, vector<int>(20));
	RFOR(i, 0, dpRight.size() - 1) {
		REP(j, dpRight[i].size()) {
			auto num = A[i + 1];
			int cnt = 0;
			while (A[i] + j * 2.0 > num) {
				num += 2.0;
				++cnt;
			}
			int index = min(cnt, static_cast<int>(dpRight[i].size() - 1));
			dpRight[i][j] = dpRight[i + 1][index] + cnt;
		}
	}

	vector<vector<int> > dpLeft(N, vector<int>(20));
	FOR(i, 1, dpLeft.size()) {
		REP(j, dpLeft[i].size()) {
			auto left = A[i-1];
			auto right = A[i];
			int cnt = 0;
			while (left < right + j * 2.0) {
				left += 2.0;
				++cnt;
			}
			int index = min(cnt, static_cast<int>(dpRight[i].size() - 1));
			dpLeft[i][j] = dpLeft[i - 1][index] + cnt;
		}
	}

	int ans = min(dpLeft.back()[0],dpRight.front()[0])*2;
	REP(i, N-1) {
		auto left = i;
		auto right = i + 1;
		ans = min((dpLeft[left][0] + dpRight[right][0])*2 + (i + 1), ans);
	}
	cout << ans << endl;
}

