  solve(true,lsum);
  solve(false,rsum);

  ll ans=INF;
  for(int i=0;i<=N;i++){
      ll res=lsum[i]+rsum[i];
      res*=2;
      res+=i;
      chmin(ans,res);
  }

  cout<<ans<<endl;

  return 0;
}

