int f1(long long x, int y, long long z) {
	for (int i = max(0, y/2*2 - 32); ; i += 2) {
		int s = i - min(i, y);
		int t = y - min(i, y);
		if ((z<<s) >= (x<<t)) return i;
	}
}

int f2(long long x, int y, long long z) {
	for (int i = max(1, y/2*2 - 33); ; i += 2) {
		int s = i - min(i, y);
		int t = y - min(i, y);
		if ((z<<s) >= (x<<t)) return i;
	}
}

long long f(int p) {
	long long r = 0;
	{
		int x = 0, y = 0;
		for (int i = p; i < N; ++ i) {
			auto v = f1(x, y, A[i]);
			x = A[i];
			y = v;
			r += v;
		}
	}
	{
		int x = 0, y = 0;
		for (int i = p-1; i >= 0; -- i) {
			auto v = f2(x, y, A[i]);
			x = A[i];
			y = v;
			r += v;
		}
	}
	return r;
}

