LL getNeedShift(LL v1, LL v2){
    LL cnt = 0;
    if(v1 <= v2){
        while(v1 * 4 <= v2){
            v1 <<= 2;
            cnt -= 2;
        }
    }else{
        while(v2 < v1){
            v2 <<= 2;
            cnt += 2;
        }
    }
    return cnt;
}

vector<vector<LL>> calcOpCnt(vector<LL>& a){
    LL n = a.size();
    vector<vector<LL>> res(n, vector<LL>(16));
    for(LL j = 0; j < 16; ++j){
        res[n-1][j] = j;
    }

    for(LL i = n-2; i >= 0; --i){
        LL s = getNeedShift(a[i], a[i+1]);
        for(LL j = 0; j < 16; ++j){
            if(j + s >= 16){
                res[i][j] = res[i+1][15] + 15 + (j + s - 15) * (n - i);
            }else{
                res[i][j] = res[i+1][max<LL>(0, j + s)] + j;
            }
        }
    }
    return res;
}

