ll num(ll p, ll N, ll *A){
    ll n=0;
    ll temp=0;
    for(ll i=p+2; i<N; i++){
        if(A[i]==A[i-1]){
            n+=temp;
        }else if(A[i]<A[i-1]){
            ll b=A[i];
            ll c=A[i-1];
            ll cnt=0;
            while(b<c){
                b*=4;
                cnt++;
            }

            temp+=cnt;
            n+=temp;
        }else{
            ll b=A[i-1];
            ll c=A[i];
            ll cnt=0;
            while(b<c){
                b*=4;
                cnt++;
            }

            if(b>c){
                cnt--;
            }

            temp-=cnt;
            n+=temp;
        }
    }

    n+=p-1;
    temp=0;
    for(ll i=p; i>=0; i--){
        if(A[i]==A[i+1]){
            n+=temp;
        }else if(A[i]<A[i+1]){
            ll b=A[i];
            ll c=A[i+1];
            ll cnt=0;
            while(b<c){
                b*=4;
                cnt++;
            }

            temp+=cnt;
            n+=temp;
        }else{
            ll b=A[i+1];
            ll c=A[i];
            ll cnt=0;
            while(b<c){
                b*=4;
                cnt++;
            }

            if(b>c){
                cnt--;
            }

            temp-=cnt;
            n+=temp;
        }
    }
    return n;
}

