#include <bits/stdc++.h>
#define REP(i, a, n) for (ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

vector<ll> solve(ll N, vector<ll> A) {
  stack<ll> stk;
  vector<ll> ret(N);
  ll cnt = 0;

  for (ll i = N - 1; i >= 0; i--) {
    ret[i] = cnt;
    if (i == 0) break;

    ll x = A[i - 1], y = A[i];

    while (x > y) {
      ll k = N;
      if (!stk.empty()) {
        k = stk.top();
        stk.pop();
      }
      cnt += (k - i) * 2;
      y *= 4;
    }

    while (x * 4 <= y) {
      stk.push(i);
      x *= 4;
    }
  }

  return ret;
}

int main(void) {
  ll N;
  cin >> N;
  vector<ll> A(N);
  REP(i, 0, N) cin >> A[i];

  vector<ll> r = solve(N, A);

  reverse(A.begin(), A.end());
  REP(i, 0, N) A[i] *= 2;
  vector<ll> l = solve(N, A);
  reverse(l.begin(), l.end());
  REP(i, 0, N) l[i] += i + 1;

  REP(i, 0, N) cerr << l[i] << " " << r[i] << endl;

  ll ans = min(l[N - 1], r[0]);
  REP(i, 0, N - 1) ans = min(ans, l[i] + r[i + 1]);
  cout << ans << endl;
}

