using namespace std;

using int64 = long long;


int main() {
  int N;
  cin >> N;
  vector< double > A(N);
  for(int i = 0; i < N; i++) {
    cin >> A[i];
    A[i] = log(A[i]);
  }

  const double log4 = log(4);

  vector< int64 > suffix(N);
  {
    vector< double > add(N);
    for(int i = N - 2; i >= 0; i--) {
      int times = 0;
      for(int j = i + 1; j < N; j++) {
        if(A[j - 1] + add[j - 1] <= A[j] + add[j])break;
        while(A[j - 1] + add[j - 1] > A[j] + add[j]) {
          add[j] += log4;
          times += 2;
        }
      }
      suffix[i] = suffix[i + 1] + times;
    }
  }

  vector< int64 > prefix(N);
  {
    vector< double > add(N);
    prefix[0] = 1;
    for(int i = 1; i < N; i++) {
      int times = 1;
      for(int j = i; j > 0; j--) {
        // A[j-1]+add[j-1]のほうが大きくしたい
        if(A[j - 1] + add[j - 1] >= A[j] + add[j])break;
        while(A[j - 1] + add[j - 1] < A[j] + add[j]) {
          add[j - 1] += log4;
          times += 2;
        }
      }
      prefix[i] = prefix[i - 1] + times;
    }
  }

  int64 ret = min(prefix[N - 1], suffix[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, prefix[i - 1] + suffix[i]);
  }
  cout << ret << endl;

}

