vector<long long> func(long long N, vector<long long> A) {
	vector<long long> res(N);
	res[N - 1] = 0;

	stack<pair<int, int>> S;
	S.push(make_pair(N - 1, N));

	for(int i = N - 2; i >= 0; --i) {
		res[i] = res[i + 1];
		if(A[S.top().first] >= A[i]) {
			S.push(make_pair(i, i + 1));
		} else {
			do {
				while(A[S.top().first - 1] > A[S.top().first]) {
					res[i] += S.top().second - S.top().first;
					A[S.top().first] *= 4;

					if(S.top().second - S.top().first > 1 && S.top().second != N) {
						A[S.top().second - 1] *= 4;
					}
				}
				S.pop();
			} while(!S.empty() && A[S.top().first - 1] > A[S.top().first]);

			if(S.empty()) {
				S.push(make_pair(i, N));
			} else {
				S.push(make_pair(i, S.top().first));
			}
		}
	}

	for(int i = 0; i < N; ++i) {
		res[i] *= 2;
	}

	return res;
}

void solve(long long N, vector<long long> A){
	vector<long long> B = func(N, A);

	reverse(A.begin(), A.end());
	vector<long long> C = func(N, A);
	reverse(C.begin(), C.end());

	/*
	for(int i = 0; i < N; ++i) {
		cerr << B[i] << "," << C[i] << endl;
	}
	*/

	long long res = min(B[0], C[N-1] + N);
	for(int i = 1; i < N; ++ i) {
		res = min(res, i + B[i] + C[i - 1]);
	}
	cout << res << endl;
}

