int main(){
	int n; cin >> n;
	vl a(n); rep(i,n) cin >> a[i];
	int M = 62;
	vvl minus(n,vl(M,linf)), plus(n+1,vl(M,linf));
	for(int i=0; i<M; i+=2) plus[n][i] = 0; 
	rep(i,n){
		if(i==0){
			for(int j=1; j<M; j+=2) minus[i][j] = j;
			continue;
		}
		int cnt = 0;
		if(a[i-1] >= a[i]){
			ll tmp = a[i];
			while(a[i-1] >= tmp * 2) tmp *= 2, cnt++;
			if(cnt & 1) cnt--;
		}else{
			ll tmp = a[i-1];
			while(tmp < a[i]) tmp *= 2, cnt--;
			if(cnt & 1) cnt--; 
		}
		for(int j=1; j<M; j+=2){
			if(j+cnt >= M) break;
			if(j+cnt < 1) continue;
			chmin(minus[i][j+cnt], minus[i-1][j] + j+cnt);
		}
		if(cnt > 0) for(int j=1; j<cnt; j+=2) chmin(minus[i][j], minus[i][0] + j);
	}
	for(int i=n-1; i>=0; i--){
		if(i==n-1){
			for(int j=0; j<M; j+=2) plus[i][j] = j;
			continue;
		}
		int cnt = 0;
		if(a[i+1] >= a[i]){
			ll tmp = a[i];
			while(a[i+1] >= tmp * 2) tmp *= 2, cnt++;
			if(cnt & 1) cnt--;
		}else{
			ll tmp = a[i+1];
			while(a[i] > tmp) tmp *= 2, cnt--;
			if(cnt & 1) cnt--;
		}
		for(int j=0; j<M; j+=2){
			if(j+cnt >= M) break;
			if(j+cnt < 0) continue;
			chmin(plus[i][j+cnt], plus[i+1][j] + j+cnt);
		}
		if(cnt > 0) for(int j=0; j<cnt; j+=2) chmin(plus[i][j], plus[i+1][0] + j);
	}
	ll ans = plus[0][0];
	rep(i,n){
		chmin(ans, minus[i][1] + plus[i+1][0]);
	}
	cout << ans << "\n";
}

