#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    cin >> n;

    vector<long long int> a(n);
    for(int i=0; i<n; i++){
        cin >> a[i];
    }

    vector<long long int> dp1(n,1);// ---
    vector<long long int> dp2(n,0);// +++

    vector<long long int> b2 = a;
    stack<long long int> st2;// critical points (order not inverted even after the multiplication by 4)
    st2.push(n-1);

    for(int i=n-2; i>=0;i--){
        dp2[i] += dp2[i+1];

        while(b2[i] > b2[i+1]){
            b2[i+1] *= 4;

            // then, need to multiply 4 to a[i+1] ~ a[j] to keep the order unchanged
            int j = st2.top(); st2.pop();
            if(j != i+1) b2[j] *= 4;

            dp2[i] += (j-(i+1)+1) * 2;

            if(j == n-1 || b2[j] * 4 <= b2[j+1]) st2.push(j);
        }

        if(b2[i] * 4 <= b2[i+1]) st2.push(i);
    }

    vector<long long int> b1 = a;
    stack<long long int> st1;
    b1[0] *= -2;
    st1.push(0);

    for(int i=1; i<n;i++){
        b1[i] *= -2;
        dp1[i] += dp1[i-1];

        while(b1[i-1] > b1[i]){
            b1[i-1] *= 4;

            // then, need to multiply 4 to a[j] ~ a[i-1] to keep the order unchanged
            int j = st1.top(); st1.pop();
            if(j != i-1) b1[j] *= 4;

            dp1[i] += ((i-1)-j+1) * 2;

            if(j == 0 || b1[j-1] <= b1[j] * 4) st1.push(j);
        }
        if(b1[i-1] <= b1[i] * 4) st1.push(i);
    }

    long long int ans = dp2[0];// ++...+
    for(int i=0; i+1<n; i++){
        ans = min(ans, dp1[i] + dp2[i+1]);// -+...+ ~ -...-+
    }
    ans = min(ans, dp1[n-1]);// --...-
    cout << ans << endl;
    return 0;
}

