ll s1[300000],s2[300000];

void calc(ll*s){
	stack<int>st;
	double p=a[0];
	int cnt=0;
	for(int i=1;i<n;i++){
		while(p+EPS<a[i]){
			if(st.empty()){
				cnt+=i;
			}
			else{
				cnt+=i-st.top();
				st.pop();
			}
			p+=2;
		}
		double b=a[i];
		while(p>=b+2+EPS){
			b+=2;
			st.push(i);
		}
		s[i]=cnt;
		p=a[i];
	}
}
