const ll inf=174417441744174417;
P convert_32(ll a){
  ll b=0;
  for(ll i=0;i<25;i++){
    if((a>>(i*2))>0) b=i;
  }
  return P(b,(a<<(50-b*2)));
}
vector<ll> solve(ll n,vector<ll> kvec){
  vector<ll> ans;
  vector<P> vec;
  for(int i=0;i<n;i++) vec.push_back(convert_32(kvec[i]));
  ans.push_back(0);
  ans.push_back(0);
  queue<P> que;
  que.push(P(inf,0));
  for(int i=1;i<n;i++){
    if(vec[i-1]>=vec[i]){
      if(vec[i-1].second<vec[i].second){
        if(vec[i].first>vec[i-1].first+1) que.push(P(vec[i].first-vec[i-1].first-1,i));
      }
      else {
        if(vec[i].first>vec[i-1].first) que.push(P(vec[i].first-vec[i-1].first,i));
      }
      ans.push_back(ans[i]);
    }
    else{
      ll zan=(vec[i].first-vec[i-1].first);
      if(vec[i].second>vec[i-1].second) zan++;
      ll kans=0;
      while(zan>0){
        P tp=que.front();
        que.pop();
        ll val=tp.first,idx=tp.second;

        if(val<=zan){
          kans+=(i-idx)*val;
          zan-=val;
        }
        else{
          if(val!=inf) val-=zan;
          que.push(P(val,idx));
          kans+=(i-idx)*zan;
          zan=0;
          break;
        }
      }
      ans.push_back(ans[i]+kans*2);
    }
  }
  return ans;
}
