            for (const ld e : rst[h]) {
                if (e >= B) { break; }
                rneed[i] += 2, rst[h + 1].insert(e), er.push_back(e), next = std::max(next, e);
            }
            if (next == 0) { break; }
            B = next;
            for (const ld e : er) { rst[h].erase(e); }
        }
    }
    for (int i = N - 2; i >= 0; i--) { rneed[i] += rneed[i + 1]; }
