TR[n] = 0;
jump[n] = n;
for (i = n - 1;i>=1;i--) {
	if (tab[i] <= tab[i + 1]) {
		TR[i] = TR[i + 1];
		d = tab[i];
		c = 0;
		while (d * 4 <= tab[i + 1]) {
			d *= 4;
			c++;
		}
		if (c == 0) jump[i] = jump[i + 1]; else {
			jump[i] = i;
			up[i] = c;
		}
	} else {
		d = tab[i + 1];
