			d *= 4LL;
			c++;
		}
		r = 0;
		ind = i + 1;
		l = jump[ind];
		while (c > 0) {
			r += (jump[ind] - ind + 1) * 1LL * c;
			if (jump[ind] == n) break;
			c -= up[ind];
			ind = jump[ind] + 1;
		}
		if (c == 0 && jump[ind] != n) {
			ind = jump[ind] + 1;
			up[i] = up[ind];
		} else up[i] = -c;
		jump[i] = jump[ind];
		TR[i] = TR[i + 1] + r * 2;
	}
