ll lft[200005] , rgt[200005] , n , a[200005];
ll dp[200005][18];
const ll inf = 1e15;
ll solve(ll id ,ll x)
{
        if(x >= 17) return inf;
        if(id == n + 1) {
                return 0;
        }
        if(dp[id][x] != -1) return dp[id][x];
        ll mup = 1LL;
        for(ll i=0;i<x;i++) mup = mup*4;
        mup = mup * a[id-1];
        ll cnt = 0;
        ll cur = a[id];
        while(mup > cur) {
                cur = cur * 4; cnt++;
                if(cnt >= 15) return dp[id][x] = solve(id+1, 15) + 15;
        }
        return dp[id][x] = solve(id+1, cnt) + cnt;
}
ll ans[200005];
ll ans2[200005];
int main()
{
        cin >> n;
        for(ll i=1;i<=n;i++) cin >> a[i];
        for(ll i=2;i<=n;i++) {
                lft[i] = 0;
                ll cnt = 0;
                ll x = a[i];
                ll y = a[i-1];
                while(x < y) {
                        x = x*4;
                        cnt++;
                }
                lft[i] = cnt + cnt;
                //cout << i << " " << lft[i] << endl;
        }
        for(ll i = n-1; i>=1;i--) {

                rgt[i] =0;
                ll x = a[i] * 2;
                ll y = a[i+1];
                ll cnt = 0;
                while(x < y) {
                        x = x * 4;
                        cnt++;
                }
                rgt[i] = cnt + cnt + 1;
                //cout << i << " " << rgt[i] << endl;
        }
        memset(dp,-1,sizeof dp);
        for(ll i=2;i<=n;i++) {
                for(ll j=0;j<=15;j++) {
                        ll  y= solve(i, j);
                        if(j==0) ans[i] = y + y;
                }
        }
        //for(ll i=2;i<=n;i++) cout << i << " --- " << ans[i] << "\n";
        for(ll i=1;i<=n;i++) a[i] = a[i] * 2;
        memset(dp,-1,sizeof dp);
        reverse(a+1, a+n+1);
        //for(ll i=1;i<=n;i++) cout << a[i] << " "; cout << endl;
        for(ll i=2;i<=n;i++) {
                for(ll j=0;j<=15;j++) {
                        ll y = solve(i,j);
                        if(j==0){
                                //cout << y + y << " ";
                                ans2[i] += y + y + (n-i+1);
                        }
                }
        }
        ll ret = 1e14;
        //for(ll i=2;i<=n;i++) cout << i << " ------- " << ans2[i] << endl;
        for(ll i=1;i<=n;i++) {
                ret = min(ret , ans[i + 1] + ans2[n+1-i + 1]);
        }
        cout << ret << endl;
        //for(ll i=1;i<=n;i++) cout << ans[i] << " ";
        return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cout.precision(12);

    int n;
    static int64_t a[200000];
    cin >> n;
    for(int i=0;i<n;++i){
        cin >> a[i];
    }

    static int64_t dp[2][200000][16];
    static int64_t pow4[16] = {1};
    for(int i=1;i<=15;++i) pow4[i] = 4 * pow4[i-1];

    for(int j=0;j<=15;++j) dp[0][n-1][j] = j;
    for(int i=n-2;i>=0;--i){
        for(int j=0;j<=15;++j){
            int jj = 0;
            while( (j<=jj && a[i] > a[i+1]*pow4[jj-j]) || (j>jj && a[i]*pow4[j-jj] > a[i+1]) ) ++jj;
            if(jj <= 15) dp[0][i][j] = j + dp[0][i+1][jj];
            else dp[0][i][j] = j + dp[0][i+1][15] + (n-i-1) * (jj-15);
        }
    }
    for(int j=0;j<=15;++j) dp[1][0][j] = j;
    for(int i=1;i<n;++i){
        for(int j=0;j<=15;++j){
            int jj = 0;
            while( (j<=jj && a[i] > a[i-1]*pow4[jj-j]) || (j>jj && a[i]*pow4[j-jj] > a[i-1])) ++jj;
            if(jj <= 15) dp[1][i][j] = j + dp[1][i-1][jj];
            else dp[1][i][j] = j + dp[1][i-1][15] + i * (jj-15);
        }
    }
    int64_t ans = INT64_MAX;
    for(int x=0;x<=n;++x){
        int64_t cand = x;
        if(x > 0) cand += dp[1][x-1][0] * 2;
        if(x < n) cand += dp[0][x][0] * 2;
        ans = min(ans, cand);
    }
    cout << ans << endl;

    return 0;
}

