void calc(long long res[max_n]) {
    res[n + 1] = 0;
    res[n] = 0;
    vector<int> v, nv;
    for (int i = n - 1; i > 0; --i) {
        long long x = a[i + 1];
        int cnt = 0;
        while (a[i] > x) {
            x *= 4;
            ++cnt;
        }
        if (cnt == 0) {
            long long y = a[i];
            if (y * 4 <= x) {
                --cnt;
            }
        }
        res[i] = res[i + 1];
        if (cnt >= 0) {
            res[i] += 1LL * cnt * (n - i - v.size());
            nv.clear();
            for (int j = 0; j < v.size(); ++j) {
                int x = v[j] + cnt;
                if (x < 0) {
                    nv.push_back(x);
                } else {
                    res[i] += x;
                }
            }
            v.swap(nv);
        } else {
            v.push_back(cnt);
        }
    }

    for (int i = 1; i < n; ++i) {
        res[i] *= 2;
    }
}

