const int MOD = 1000000007;


int n;
vector<ll> solve(vi d) {
    vector<ll> dp;
    dp.push_back(0);
    ll cur = 0;
    ll last = MOD;
    vector<pii> t; // *4 , count
    t.emplace_back(MOD, 0);
    RREP(i, n) {
        ll x = d[i];
        while(x > last) {
            int c4, cnt; tie(c4, cnt) = t.back(); t.pop_back();
            cur += 2 * cnt;
            c4 --;
            if (c4 > 0) {
                t.emplace_back(c4, cnt);
            } else {
                t.back().second += cnt;
            }
            last *= 4;
        }
        if (x * 4 > last) {
            t.back().second ++;
        } else {
            ll j = 0, y = x;
            while(y * 4 <= last) {
                j ++;
                y *= 4;
            }
            t.emplace_back(j, 1);
        }
        last = x;
        dp.push_back(cur);
    }
    return dp;
}

