int log2(ll p, ll q){
  int counter = 0;
  int cc = !!(p % q) * 2;
  ll v = p / q;
  while(v){
    if(v % 2) cc++;
    v /= 2;
    counter++;
  }
  return counter + (cc > 1);
}

int log2(ll v){
  int counter = 0;
  int cc = 0;
  while(v){
    if(v % 2) cc++;
    v /= 2;
    counter++;
  }
  return counter + (cc > 1);
}

ll pow2(int x) {
  ll res = 1;
  for(int i=0;i<x;i++) res *= 2;
  return res;
}

