            i64 mid=(lb+ub)/2;
            if(a[i]*pow4[x]<=a[i-1]*pow4[mid]) ub=mid;
            else lb=mid;
        }
        return rec2(i-1,ub)+ub;
    };

    i64 ans=inf64;
    rep(i,0,N){
        ans=min(ans,rec1(i,0)*2+(i==0?0:(rec2(i-1,0)*2+i)));
    }

    cout << ans << endl;
}

