int log4(ll p, ll q, bool f = true){
  int counter = 0;
  int cc = !!(p % q) * 2;
  ll v = p / q;
  while(v >= 4){
    if(v % 4) cc++;
    v /= 4;
    counter++;
  }
  if(v > 1) cc++; 
  debug(p); debug(q); debug(cc);
  return counter + (cc >= 1) * f;
}

ll pow2(int x) {
  ll res = 1;
  for(int i=0;i<x;i++) res *= 2;
  return res;
}

int main(){
