int nex[1 << 18];
ll gen[1 << 18]; bool used[1 << 18];
ll dfs(int id) {
	if (used[id])return gen[id];
	if (id == n)return gen[id] = 0;
	used[id] = true;
	int to = nex[id];
	ll res = (to - id)*sum[id] + dfs(to);
	return gen[id] = res;
}
void initt() {
	priority_queue<LP> q;
	rep1(i, n - 1) {
			while (!q.empty()) {
				LP ne = q.top();
				if (ne.first > sum[i]) {
					nex[ne.second] = i; q.pop();
				}
				else {
					break;
				}
			}
			q.push({ sum[i],i });
	}
	while (!q.empty()) {
		P ne = q.top();q.pop();
		nex[ne.second] = n;
	}
	rep1(i, n - 1) {
		dfs(i);
	}
}
ll invaum[1 << 18];
ll invcnt[1 << 18];
ll invsum[1 << 18];

int invnex[1 << 18];
ll invgen[1 << 18]; bool invused[1 << 18];
ll invdfs(int id) {
	if (id < 0)return 0;
	if (invused[id])return invgen[id];
	invused[id] = true;
	int to = invnex[id];
	ll res = (id - to)*invsum[id] + dfs(to);
	return invgen[id] = res;
}
void invinitt() {
	priority_queue<LP> q;
	per(i, n - 1) {
		while (!q.empty()) {
			LP ne = q.top();
			if (ne.first > invsum[i]) {
				invnex[ne.second] = i; q.pop();
			}
			else {
				break;
			}
		}
		q.push({ invsum[i],i });
	}
	while (!q.empty()) {
		P ne = q.top(); q.pop();
		invnex[ne.second] = -1;
	}
	per(i, n - 1) {
		invdfs(i);
	}
}

