// i0 must be within range.
long long helper(const vector<long long>& a, int i0, int d){
  long long ans = 0;
  long long current = a[i0];
  //cerr << i0 << ',' << d << endl;
  for(int i = i0 + d; i < a.size() && i >=0; i+=d){
    long long current_factor = 1;
    //cerr << "I=" << i << endl;
    while(current_factor * a[i] < current){
      ans += 2;
      current_factor *= 4;
      //cerr << "tmpC=" << current_factor << endl;
    }
    current = current_factor * a[i];
    //cerr << "C=" << current_factor << endl;

  }
  return ans;
}


long long solve(long long n, vector<long long> a){
  long long ans = LLONG_MAX;
  for(int i=0; i<=n; i++){
    long long tmp = i;
    if(i>0) tmp+=helper(a, i-1, -1);
    if(i<n) tmp+=helper(a, i, 1);
    ans = min(ans, tmp);
  }
  return ans;
}

