struct BIT{
    int n;
    vector<double> bit;

    BIT(){}
    BIT(int x){
        n = x;
        bit.assign(n+1, 0.0);
    }

    void init(int x){
        n = x;
        bit.assign(n+1, 0.0);
    }

    void add(int i, double x){
        i++;
        while (i <= n){
            bit[i] += x;
            i += i & -i;
        }
    }

    // [0, i]
    double sum(int i){
        i++;
        double ret = 0;
        while (i > 0){
            ret += bit[i];
            i -= i & -i;
        }
        return ret;
    }

    // [l, r)
    double sum(int l, int r){
        if (l >= r) return 0;
        return sum(r-1) - sum(l-1);
    }
};

const double EPS = 1e-14;

VL calc(VL a){
    int n = a.size();
    VL ret(n);
    vector<double> d(n);
    REP(i,n) d[i] = log2(a[i]) / 2;
    BIT bit(n);
    bit.add(0, d[0]);
    FOR(i,1,n-1) bit.add(i, d[i] - d[i-1]);
    set<int> st;
    st.insert(n);
    ll s = 0;
    FORR(i,n-2,0){
        if (a[i] <= a[i+1]){
            if (d[i] <= d[i+1] - 1 + EPS) st.insert(i + 1);
            ret[i] = s;
            continue;
        }
        ll c = 0;
        while (a[i] > a[i+1]){
            a[i+1] *= 4;
            c++;
        }
        set<int> rm;
        ll y = i + 1;
        for (int x : st){
            s += c * (x - y);
            bit.add(y, c);
            bit.add(x, -c);
            if (x < n && bit.sum(x) + EPS < bit.sum(x - 1)){
                c = 1.0 + bit.sum(x - 1) - bit.sum(x) - EPS;
                rm.insert(x);
            }else{
                break;
            }
            y = x;
        }
        for (int x : rm) st.erase(x);
        ret[i] = s;

        // REP(i,n) cout << pow(4, bit.sum(i)) << " ";
        // cout << endl;
    }
    REP(i,n) ret[i] *= 2;
    return ret;
}

