int a[MAXN];
int p[MAXN], q[MAXN];
ll pre_p[MAXN], suf_q[MAXN];

int main(void)
{
	int n;
	scanf("%d",&n);
	for(int i=1; i<=n; ++i) scanf("%d",&a[i]);

	stack<pii> sta;
	sta.push(make_pair(1,inf));
	for(int i=1; i<n; ++i)
	{
		p[i] = calc(a[i], a[i+1]);
		pre_p[i] = pre_p[i-1];

		if(p[i] < 0){ sta.push(make_pair(i, -p[i])); continue;}

		while(p[i])
		{
			int cur = min(p[i], sta.top().second);
			pre_p[i] += cur * (i - sta.top().first + 1);

			p[i] -= cur;
			sta.top().second -= cur;
			if(!sta.top().second) sta.pop();
		}
	}

	while(!sta.empty()) sta.pop();
	sta.push(make_pair(n,inf));
	for(int i=n; i>=2; --i)
	{
		q[i] = calc(a[i], a[i-1]);
		suf_q[i] = suf_q[i+1];

		if(q[i] < 0){ sta.push(make_pair(i, -q[i])); continue;}

		while(q[i])
		{
			int cur = min(q[i], sta.top().second);
			suf_q[i] += cur * (sta.top().first - i + 1);

			q[i] -= cur;
			sta.top().second -= cur;
			if(!sta.top().second) sta.pop();
		}
	}

	ll ans = linf;
	for(int i=0; i<=n; ++i)
	{
		ll res = 0;
		if(i>=1) res += pre_p[i-1] + i;
		if(i+1<=n) res += suf_q[i+2];

		ans = min(ans, res);
	}
	printf("%lld",ans);
	return 0;
}

