	if (solve_rev.find(x) != solve_rev.end())
		ans = solve_rev[x];
	else {
		ans = solve(ms, ms_len, fast_calc);
		solve_rev[x] = ans;
	}
	ans += x; // rotate

	if (fast_calc)
		if (ans >= mn)
			return ans;

	// <= for indexes [x...n)
	ms_len = 0;
	for (int i = x; i < n; i++)
		ms[ms_len++] = s[i];
	if (solve_forw.find(x) != solve_forw.end())
		ans += solve_forw[x];
	else {
		solve_forw[x] = solve(ms, ms_len, fast_calc);
		ans += solve_forw[x];
	}

	return ans;
}

