bool cmpNegative(int64_t v1, int64_t v2, int cnt2) {
	while (cnt2) {
		v2 *= 4;
		--cnt2;
		if (v1>=v2)
			return false;
	}
	return v1<v2;
}

bool cmpPositive(int64_t v1, int cnt1, int64_t v2) {
	while (cnt1) {
		v1 *= 4;
		--cnt1;
		if (v1>v2)
			return false;
	}
	return v1<v2;
}

void calcLeft() {
	int _prev = -INF;
	for (int i=1; i<=n; ++i) {
		leftCost[i] = leftCost[i-1];
		int cur = a[i];
		if (cur>0) {
			++leftCost[i];
			cur *= -2;
		}
		int tmp = 0;
		while (cmpNegative(cur, _prev, tmp)) {
			leftCost[i] += 2*(i-1);
			++tmp;
		}
		_prev = cur;
	}
}

void calcRight() {
	int _prev = INF;
	for (int i=n; i>=1; --i) {
		rightCost[i] = rightCost[i+1];
		int cur = a[i];
		if (cur<0) {
			++rightCost[i];
			cur *= -2;
		}
		int tmp = 0;
		while (cmpPositive(_prev, tmp, cur)) {
			rightCost[i] += 2*(n-i);
			++tmp;
		}
		_prev = cur;
	}
}

void solve() {
	int64_t res = INF;
	for (int i=0; i<=n; ++i)
		res = min(res, leftCost[i] + rightCost[i+1]);
	cout << res;
}

