  {
    for(segn2=1; segn2<n; segn2*=2);
    data.assign(segn2*2, make_pair(initVal, 0));
  }

  SimpleSegTree(int n, double initVal): //RangeMinimunQuery
    SimpleSegTree(n, initVal, [](Type a, Type b){ return max(a, b); }) {}

  //get value [a,b)
  Type query(int a, int b, int l = 0, int r = -1, int k = 0){
    if(r == -1) r = segn2;
    if(a <= l && r <= b) return data[k];
    if(r <= a || b <= l) return {initVal, -1};
    return merge(query(a,b,l,(l+r)/2,k*2+1),query(a,b,(l+r)/2,r,k*2+2));
  }

  //set kth number x
  void set(int k, double x){
    k += segn2-1;
    data[k] = {x, k - (segn2-1)};
    while(k > 0){
      k = (k-1)/2;
      data[k] = merge(data[k*2+1], data[k*2+2]);
    }
  }
};




