using namespace std;
const int maxn = 234567;
long long f[maxn][16];
vector<long long> solve(vector<int> a){
	int l = a.size();
	for(int i = 0; i < 16; i++) f[l - 1][i] = i;
	for(int i = l-2; i >= 0; i--){
		for(int j = 0; j < 16; j++) f[i][j] = 1ll<<60;
		if(a[i] <= a[i + 1]){
			int mvs = 0;
			long long now = a[i];
			while(now <= a[i + 1]) now *= 4, mvs++;
			for(int j = 0; j < 16; j++){
				int take = max(j - mvs + 1, 0);
				f[i][j] = min(f[i][j], j + f[i + 1][take]);
			}
		} else {
			int mvs = 0;
			long long now = a[i + 1];
			while(now < a[i]) now *= 4, mvs++;
			for(int j = 0; j < 16; j++){
				int take = j + mvs;
				if(take >= 15) f[i][j] = min(f[i][j], j + f[i + 1][15] + (l - i - 1) * (take - 15));
				else f[i][j] = min(f[i][j], j + f[i + 1][take]);
			}
		}
	}
	vector<long long> ans;
	for(int i = 0; i < l; i++){
		long long h = 1ll<<60;
		for(int j = 0; j < 16; j++) h = min(h, f[i][j]);
		ans.push_back(h);
	}
	return ans;
}
int main(){
	int n; cin >> n;
	vector<int> a(n); for(int & i : a) cin >> i;
	vector<long long> res1 = solve(a);
	reverse(a.begin(), a.end()); for(int &i : a) i *= -2;
	vector<long long> res2 = solve(a);
	reverse(res2.begin(), res2.end());
	long long ans = 2*res1[0];
	for(int i = 1; i < n; i++){
		ans = min(ans, 2*res2[i - 1] + 2*res1[i] + i);
	}
	ans = min(ans, 2*res2.back() + n);
	cout << ans << endl;
	return 0;
}

