int rf(int i) {
	if (rd[i].count(rl[i])) return rd[i][rl[i]];
	int &res = rd[i][rl[i]];
	res = rm[i];
	if (i == n - 1) {
		return res;
	}
	while (rl[i] > rl[i+1]) {
		rm[i+1] += 2;
		rl[i+1] *= 4;
	}
	res += rf(i + 1);
	return res;
}
int lf(int i) {
	if (ld[i].count(ll[i])) return ld[i][ll[i]];
	int &res = ld[i][ll[i]];
	res = lm[i];
	if (i == 0) {
		return res;
	}
	while (ll[i] > ll[i-1]) {
		lm[i-1] += 2;
		ll[i-1] *= 4;
	}
	res += lf(i - 1);
	return res;
}
