constexpr int MAXN = 200000, MAXA = 1000000000, MINA = 1;

int A[MAXN + 2], N;

int cost(int center) {
	int ans = 0;
	for(int i = center - 1, pn = 0; i >= 0; i--) {
		if(pn == 0 && A[i] > A[i + 1]) {
			pn++;
			ans++;
		} else if(pn != 0) {
			int n = pn;
			ll a = A[i], b = A[i + 1];
			while(a > b) {
				b *= 4;
				n -= 2;
			}
			while(a < b) {
				a *= 4;
				n += 2;
			}
			ans += n;
			pn = n;
		}
	}
	for(int i = center + 1, pn = 0; i < N; i++) {
		if(pn != 0 || A[i - 1] > A[i]) {
			int n = pn;
			ll a = A[i], b = A[i - 1];
			while(a > b) {
				b *= 4;
				n -= 2;
			}
			while(a < b) {
				a *= 4;
				n += 2;
			}
			ans += n;
			pn = n;
		}
	}
	return ans;
}

int main() {
