ll power(ll e, ll x)
{
	if (x == 0) return 1LL;
	if (x % 2 != 0) return (power(e, x - 1) * e);
	ll temp = power(e, x / 2);
	return (temp * temp);
}

void solve()
{
	int N;
	cin >> N;
	vecll as(N);
	rep(N, i) cin >> as[i];

	vec pcnt(N), acnt(N);

	rep(N-1, i)
	{
		ll cnt = 0, k = 1, pre = as[i] * power(4, pcnt[i] / 2);
		while (as[i + 1] * k < pre)
		{
			cnt += 2;
			k *= 4;
		}
		pcnt[i+1] = cnt;
	}
	//cout << pcnt << endl;

	rep(N - 1, i) acnt[i + 1] = pcnt[i + 1] + acnt[i];
	ll ans = acnt[N-1];

	//cout << acnt << endl;

	Rep(1, N-1, i)
	{
		ll tmp = acnt[N-1] - acnt[i] + i;
		ans = min(ans, tmp);
	}

	cout << ans << endl;

}

