int n;

ll ans(vector<ll> a, int mid) {
  ll res = 0;
  ll pre = 0;
  for (int i = mid; i < n; ++i) {
    if (a[i] < 0) {
      a[i] *= -2;
      res++;
    }
    if (pre > a[i]) {
      while (pre > a[i]) {
        a[i] <<= 2LL;
        res += 2;
      }
    }
    pre = a[i];
    // cout << pre << endl;
  }
  pre = 0;
  for (int i = mid - 1; i >= 0; --i) {
    if (a[i] > 0) {
      a[i] *= -2;
      res++;
    }
    if (pre < a[i]) {
      while (pre < a[i]) {
        a[i] <<= 2LL;
        res += 2;
      }
    }
    pre = a[i];
  }
  return res;
}

int main() {
  cin >> n;
