  for (int i = 0; i < n; ++i) {
    cin >> a[i];
  }

  int left = -1;
  int right = n;
  ll ret = 1e18;
  while (right - left > 1) {
    int mid = left + (right - left) / 2;
    ll buf = ans(a, mid);
    // cout << mid << " " << buf << endl;
    if (buf < ret) {
      right = mid;
      ret = buf;
    } else
      left = mid;
  }
  cout << ret << endl;
}

