using namespace std;
long long positive[300001], negative[300001];
long long N, A[300000];

int main(void) {
	long long L, X, Y;
	//i = 0,...,N (N+1個の値を取る)
	//positive[i]は、A[N-i]からA[N-1]までをすべて正で昇順に並べるのにかかる手数
	//negative[i]は、A[0]からA[i-1]までをすべて負で昇順に並べるのにかかる手数
	scanf("%lld", &N);
	for (int i = 0; i < N; i++) {
		scanf("%lld", &A[i]);
	}

	//positiveの計算
	positive[0] = 0;
	positive[1] = 0;

	for (int i = 2; i < N + 1; i++) {
		//A[N-i]とA[N-i+1]を比較。A[N-i+1]を何回4倍すればA[N-i]以上になるか？
		L = 0;
		X = A[N - i];
		Y = A[N - i + 1];
		while (X > Y) {
			Y = 4 * Y;
			L = L + 2;
		}
		positive[i] = positive[i - 1] + L * (i - 1);
	}
	//negativeの計算
	negative[0] = 0;
	negative[1] = 1;

	for (int i = 2; i < N + 1; i++) {
		//A[i-2]とA[i-1]を比較。
		L = 0;
		X = A[N - i];
		Y = A[N - i + 1];
		while (X < Y) {
			X = 4 * X;
			L = L + 2;
		}
		negative[i] = negative[i - 1] + L * (i - 1) + 1;
	}

	long long ans = positive[0] + negative[N];

	for (int i = 0; i < N + 1; i++) {
//		printf("pos %lld neg %lld\n", positive[i], negative[i]);
		if (ans > positive[i] + negative[N - i]) {
			ans = positive[i] + negative[N - i];
		}
	}
	printf("%lld\n", ans);
}

