using namespace std;
const int MAXN = 2e5 + 7;
int n, pre[MAXN], nxt[MAXN];
ll a[MAXN], b[MAXN], low[MAXN], up[MAXN], num[MAXN], cnt1[MAXN], cnt2[MAXN];
void deal(ll* a, ll* cnt)
{
    for (int i = 1; i <= n; i++)
    {
        low[i] = up[i] = a[i]; num[i] = 1;
        pre[i] = i - 1;
        nxt[i - 1] = i;
        cnt[i] = cnt[i - 1];
        while (pre[i] && up[i] > low[pre[i]])
        {
            while (up[i] > low[pre[i]]) low[pre[i]] *= 4, up[pre[i]] *= 4, cnt[i] += num[pre[i]] * 2;
            num[i] += num[pre[i]]; up[i] = up[pre[i]];
            pre[i] = pre[pre[i]];
            nxt[pre[i]] = i;
        }
    }
    // for (int i = 0; i <= n; i++) printf("%lld%c", cnt[i], " \n"[i == n]);
}
int main()
{
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) scanf("%lld", &a[i]), b[i] = a[i] * 2;
    deal(b, cnt1);
    for (int i = 1; i <= n / 2; i++) swap(a[i], a[n + 1 - i]);
    deal(a, cnt2);
    ll ans = 1e18;
    for (int i = 0; i <= n; i++)
        ans = min(ans, i + cnt1[i] + cnt2[n - i]);
    printf("%lld\n", ans);
    return 0;
}

