            for (int j = 0; j < 32; j++) {
                x *= 2;
                cnt++;
                if (cnt & 1) continue;
                if (x >= A[i]) break;
            }
            R[i] = R[i + 1] + cnt * (n - i);
        } else R[i] = R[i + 1];
    }
    L[1] = 0, L[2] = 1;
    FI(i, 3, n) {
        if (A[i - 1] > A[i - 2]) {
            LL x = A[i - 2];
            int cnt = 0;
            for (int j = 0; j < 32; j++) {
                x *= 2;
                cnt++;
                if (cnt & 1) continue;
                if (x >= A[i - 1]) break;
            }
            assert(x >= A[i - 1]);
            L[i] = L[i - 1] + cnt * (i - 2);
        } else L[i] = L[i - 1];
    }
    int ans = INT_MAX;
    FI(i, 1, n) ans = min(ans, L[i] + R[i]);
    printf("%d\n", ans);
}

