int count(vector<int> A, int d) {
    int res = 0;
    REV(i, d - 1, 0) {
        A[i] *= -2;
        res += 1;
        if (i < A.size() - 1 && A[i] > A[i + 1]) {
            while (A[i] > A[i + 1]) {
                A[i] *= 4;
                res += 2;
            }
        }
    }

    FOR(i, d, A.size() - 1) {
        if (i == 0 || A[i] > A[i - 1]) continue;
        while (A[i] < A[i - 1]) {
            A[i] *= 4;
            res += 2;
        }
    }
    return res;
}

