ll lft[200005] , rgt[200005] , n , a[200005];
ll dp[200005][18];
const ll inf = 1e15;
ll solve(ll id ,ll x)
{
        if(x >= 17) return inf;
        if(id == n + 1) {
                return 0;
        }
        if(dp[id][x] != -1) return dp[id][x];
        ll mup = 1LL;
        for(ll i=0;i<x;i++) mup = mup*4;
        mup = mup * a[id-1];
        ll cnt = 0;
        ll cur = a[id];
        while(mup > cur) {
                cur = cur * 4; cnt++;
        }
        return solve(id+1, cnt) + cnt;
}
ll ans[200005];
ll ans2[200005];
int main()
{
        cin >> n;
        for(ll i=1;i<=n;i++) cin >> a[i];
