                ll x = a[i];
                ll y = a[i-1];
                while(x < y) {
                        x = x*4;
                        cnt++;
                }
                lft[i] = cnt + cnt;
                //cout << i << " " << lft[i] << endl;
        }
        for(ll i = n-1; i>=1;i--) {

                rgt[i] =0;
                ll x = a[i] * 2;
                ll y = a[i+1];
