    minvR[0] = 0;
    minvR[1] = 0;
    for (long long i = 2; i <= N; i++) {
        long long cnt = 0;
        long long left = a[N - i + 1];
        long long right = a[N - i + 2];
        while (left > right) {
            right  *= 4;
            cnt++;
        }
        minvR[i] = minvR[i - 1] + 2 * cnt * (i - 1);
