using namespace std;
typedef long long ll;

vector<ll> solve(ll n, vector<ll> a) {
  stack<pair<ll, ll>> stk;
  vector<ll> ret(n);
  ll cnt = 0;

  for (ll i = n - 1; i >= 0; i--) {
    ret[i] = cnt;
    if (i == 0) break;

    ll x = a[i - 1], y = a[i];
    if (x > y) {
      while (x > y) {
        ll k = n;
        while (!stk.empty()) {
          if (stk.top().second == 0) {
            stk.pop();
            continue;
          }
          k = stk.top().first;
          stk.top().second--;
          break;
        }
        cnt += (k - i) * 2;
        y *= 4;
      }
    } else {
      ll r = 0;
      while (x * 4 <= y) {
        r++;
        x *= 4;
      }
      stk.push(make_pair(i, r));
    }
  }

  return ret;
}

int main(void) {
  ll n;
  cin >> n;
  vector<ll> a(n);
  REP(i, 0, n) cin >> a[i];

  vector<ll> r = solve(n, a);

  reverse(a.begin(), a.end());
  REP(i, 0, n) a[i] *= 2;
  vector<ll> l = solve(n, a);
  reverse(l.begin(), l.end());
  REP(i, 0, n) l[i] += i + 1;

  ll ans = min(l[n - 1], r[0]);
  REP(i, 0, n - 1) ans = min(ans, l[i] + r[i + 1]);
  cout << ans << endl;
}

