using namespace std;

using int64 = long long;

const int64 inf = (1LL << 50);

int64 dp[200010][15];

vector<int64> computeScore(const std::vector<int64>& a) {
    int n = a.size();
    for (int x = 0; x < 15; x++) {
        dp[n - 1][x] = 2 * x;
    }

    for (int i = n - 2; i >= 0; i--) {
        int64 cur = a[i];

        for (int x = 0; x < 15; x++) {
            dp[i][x] = inf;

            int64 nxt = a[i + 1];

            for (int y = 0; y < 15; y++) {
                // 4^x * a_i <= 4^y * a_{i+1}
                if (cur <= nxt) {
                    dp[i][x] = min(dp[i][x], dp[i + 1][y] + 2 * x);
                } else {
                    dp[i][x] = min(dp[i][x], dp[i + 1][y] + 2 * (x + 15 * (n - i - 1)));
                }
                nxt *= 4;
            }
            cur *= 4;
        }
    }

    vector<int64> score(n);
    for (int i = 0; i < n; i++) {
        score[i] = dp[i][0];
    }
    return score;
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
