ll n, a[200000];
ll counter[200000], backcounter[200000];
ll sum[200000], backsum[200000];

ll getCounter(ll x, ll y) { // x 4^m <= y
  ll ans = 0;
  while (x > y) y *= 4, ans++;
  return ans * 2;
}

int main() {
  scanf("%lld", &n);
  for (ll i = 0; i < n; i++) scanf("%lld", &a[i]);
  counter[n-1] = 0;
  for (ll i = n-2; i >= 0; i--) {
    counter[i] = getCounter(a[i], a[i+1]) * (n-1-i);
  }
  sum[n-1] = counter[n-1];
  for (ll i = n-2; i >= 0; i--) sum[i] = sum[i+1] + counter[i];
  backcounter[0] = 1;
  for (ll i = 1; i < n; i++) {
    backcounter[i] = getCounter(a[i], a[i-1]) * i + 1;
  }
  backsum[0] = backcounter[0];
  for (ll i = 1; i < n; i++) backsum[i] = backsum[i-1] + backcounter[i];
  ll ans = min(sum[0],backsum[n-1]);
  for (ll i = 0; i < n - 1; i++) ans = min(ans, sum[i+1] + backsum[i]);
  printf("%lld\n", ans);
}

#include <bits/stdc++.h>
using namespace std;

int main()
{
    int n;
    cin >> n;
    vector<long long> v(n);
    for (int i = 0; i < n; ++i)
        cin >> v[i];
    vector<long long> tmp(n);
    vector<int> count_minus(n, 0), count_plus(n, 0);
    vector<int> mini_plus(n, 0), mini_minus(n, 0);
    for (int i = 0; i < n; ++i) {
        tmp[i] = v[i];
        if (tmp[i] > 0) {
            tmp[i] *= -2;
            count_minus[i]++;
        }
        if (i != 0) {
            int k = log((float)tmp[i] / tmp[i-1]) / log(4) + 0.9999;
            if (k < 0) k = 0;
            if (tmp[i] > tmp[i-1]) {
                int u = log((float) tmp[i-1] / tmp[i]) / log(4);
                mini_minus[i] = u * 2;
                count_minus[i] += u * 2;
                tmp[i] *= pow(4, u);
            }
            count_minus[i] += k * 2 * i + count_minus[i-1];
        }
        //cout << i << " " << tmp[i] << " " << count_minus[i] << " " << mini_minus[i] << endl;
    }
    for (int i = n-1; i >= 0; --i) {
        tmp[i] = v[i];
        if (i != n-1) {
            int k = log((float)tmp[i] / tmp[i+1]) / log(4) + 0.9999;
            if (k < 0) k = 0;
            if (tmp[i] < tmp[i+1]) {
                int u = log((float) tmp[i+1] / tmp[i]) / log(4);
                mini_plus[i] = u * 2;
                count_plus[i] += u * 2;
                tmp[i] *= pow(4, u);
            }
            count_plus[i] += k * 2 * (n-i-1) + count_plus[i+1];
        }
        //cout << i << " " << tmp[i] << " " << count_plus[i] << " " << mini_plus[i] << endl;
    }
    int ans = min(count_plus[0]-mini_plus[0], count_minus[n-1]-mini_minus[n-1]);
    //cout << ans << endl;
    for (int i = 0; i < n-1; ++i) {
        int t = count_plus[i+1] - mini_plus[i+1] + count_minus[i] - mini_minus[i]; 
        ans = min(ans, t);
    }
    cout << ans << endl;
    return 0;
}

