    stack<pair<int, int> > st;
    st.push({0, 1<<30});
    for (int i = 1; i < n; i++) {
        if (a[i-1] >= a[i]) {
            dp1[i+1] = dp1[i] + 1;
            long long t = a[i];
            int k = 0;
            while (4 * t <= a[i-1]) { t *= 4; k += 2; }
            if (k > 0) {
                st.push({i, k});
