void solve() {
    int N;
    cin >> N;
    vector<ll> A(N);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    // i: マイナスとプラスの区切れ目
    ll ans = 1LL << 60;
    for(int i = 0; i <= N; i++) {
        vector<ll> B = A;
        ll cnt = 0;
        ll now = 0;
        for(int j = i - 1; j >= 0; j--) {
            while(now < B[j]) {
                B[j] *= -2;
                cnt++;
            }
            now = B[j];
        }
        for(int j = i; j < N; j++) {
            while(now > B[j]) {
                B[j] *= -2;
                cnt++;
            }
            now = B[j];
        }
        ans = min(ans, cnt);
    }
    cout << ans << endl;
}

