ll comp(ll a,ll b){
	ll ret = 0;
	if(a > b){
		ll mul = (a + b - 1) / b;
		ll tmp = 1;
		while(tmp < mul){
			tmp *= 4;
			ret++;
		}
	}
	else{
		ll mul = (b + a - 1) / a;
		ll tmp = 1;
		while(tmp < mul){
			tmp *= 4;
			ret--;
		}
	}
	return ret;
}

ll dfs(int a, int b){
	if(dp[a][b] != -1)return dp[a][b];
	if(a == n-1)return dp[a][b] = 0;
	ll tmp = max(0LL, comp(v[a],v[a+1]) + b);
	if(tmp > 15){
		return dp[a][b] = tmp + (tmp - 15) * (n - a - 1) + dfs(a+1, 15);
	}
	else{
		return dp[a][b] = tmp + dfs(a+1,tmp);
	}
}

