ll div_up(ll a, ll b)
{
    return (a + b - 1) / b;
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    ll n, a[212345], sumP[212345], sumM[212345];

    cin >> n;
    for (ll i = 0; i < n; i++)
    {
        cin >> a[i];
    }

    sumP[n - 1] = 0;

    for (ll i = n - 2; i >= 0; i--)
    {
        sumP[i] = sumP[i + 1];

        if (a[i] <= a[i + 1])
        {
            continue;
        }

        //ll tmp = div_up(div_up(a[i], a[i + 1]), 4) * 2 * (n - 1 - i);
        ll tmp = (ll)ceil((ll)log(div_up(a[i], a[i + 1])) / (ll)log(4)) * 2 * (n - 1 - i);

        sumP[i] += tmp;
    }

    sumM[0] = 0;

    for (ll i = 1; i < n; i++)
    {
        sumM[i] = sumM[i - 1];

        if (a[i - 1] >= a[i])
        {
            continue;
        }

        ll tmp = (ll)ceil((ll)log(div_up(a[i], a[i - 1])) / (ll)log(4)) * 2 * i;

        sumM[i] += tmp;
    }

    for (ll i = 0; i < n; i++)
    {
        sumM[i] += i + 1;
    }

    ll res = sumP[0];

    for (int i = 1; i < n; i++)
    {
        ll tmp = sumP[i] + sumM[i - 1];

        res = min(res, tmp);
