#include <bits/stdc++.h>
using namespace std;
struct Seg {
  Seg *ch[2];
  long long minValue, sumValue;
  long long addTag;
  int l, r, m;
  static constexpr long long INF = 1ll<<60;
  void pull() {
    minValue = min(ch[0]->minValue, ch[1]->minValue);
    sumValue = ch[0]->sumValue + ch[1]->sumValue;
  }
  int len() {
    return r - l;
  }
  void push() {
    if (addTag) {
      for (int i = 0; i < 2; ++i) {
        ch[i]->addTag += addTag;
        ch[i]->sumValue += addTag * ch[i]->len();
        ch[i]->minValue += addTag;
      }
      addTag = 0;
    }
  }
  Seg(int l, int r) : l(l), r(r), m(l + r >> 1) {
    minValue = sumValue = 0;
    addTag = 0;
    if (r - l > 1) {
      ch[0] = new Seg(l, m);
      ch[1] = new Seg(m, r);
    }
  }
  void addValue(int ql, int qr, long long qv) {
    if (ql <= l and r <= qr) addTag += qv, minValue += qv, sumValue += qv;
    else {
      push();
      if (ql < m) ch[0]->addValue(ql, qr, qv);
      if (m < qr) ch[1]->addValue(ql, qr, qv);
      pull();
    }
  }
  long long getMinValue(int ql, int qr) {
    if (ql <= l and r <= qr) return minValue;
    else {
      push();
      long long ans = INF;
      if (ql < m) ans = min(ans, ch[0]->getMinValue(ql, qr));
      if (m < qr) ans = min(ans, ch[1]->getMinValue(ql, qr));
      pull();
      return ans;
    }
  }
  long long getSumValue(int ql, int qr) {
    if (ql <= l and r <= qr) return sumValue;
    else {
      push();
      long long ans = 0;
      if (ql < m) ans = min(ans, ch[0]->getSumValue(ql, qr));
      if (m < qr) ans = min(ans, ch[1]->getSumValue(ql, qr));
      pull();
      return ans;
    }
  }
};
class Solution {
  int n;
  vector<long long> A;
  int climb(long long a, long long b) {
    if (b == a) return 0;
    assert(b <= a);
    int ans = 0;
    while (b < a) b *= 4, ++ans;
    return ans;
  }
  int reach(long long a, long long b) {
    if (b == a) return 0;
    assert(b <= a);
    int ans = 0;
    while (b * 4 <= a) b *= 4, ++ans;
    return ans;
  }
  long long test(int idx) {
    long long ans = idx != 0;
    for (int i = idx + 1, col = 0; i < n; ++i) {
      if (A[i - 1] >= A[i]) {
        col += 2 * climb(A[i - 1], A[i]);
      }
      else {
        col = max(0, col - 2 * reach(A[i], A[i - 1]));
      }
      ans += col;
    }
    for (int i = idx - 2, col = 0; i >= 0; --i) {
      ++ans;
      if (A[i] <= A[i + 1]) {
        col = max(0, col - 2 * climb(A[i + 1], A[i]));
      }
      else {
        col += 2 * reach(A[i], A[i + 1]);
      }
      ans += col;
    }
    return ans;
  }
public:
  void run(istream &in, ostream &out) {
    in >> n;
    A.resize(n);
    for (int i = 0; i < n; ++i) in >> A[i];
    long long ans = 1ll<<60;
    for (int i = max(0, n / 2 - 100); i < min(n, n / 2 + 100); ++i) {
      ans = min(ans, test(i));
    }
    out << ans << '\n';
  }


};
int main() {
  ios_base::sync_with_stdio(false);
  Solution().run(cin, cout);
  return 0;
}

