		if(k>1) km=max(0LL,(ruiruilog4m[0]-ruiruilog4m[k-1]-ruilog4m[k-1]*max(0,k-1))*2);
		kans+=kp+km;
		//printf("k:%d kp:%lld km:%lld kans:%lld\n",k,kp,km,kans);
		ans=min(ans,kans);
	}
	prin(ans);
	return 0;
}

