int rec(int idx,int mp,int si){
    if(mp>M-1)return oo;
    int &ret=dp[idx][mp][si];
    if(ret!=-1)return ret;
    if(idx==n)return ret=0;
    if(si==0){
        ll ad=aa[idx],oth=aa[idx-1]*(1LL<<mp);
        int p=0;
        while(p<M&&ad<oth&&OO/4>=ad)ad*=4,p+=2;
