int check(int firstPlus) {
    int cnt = 0;
    if (firstPlus > 0) {
        cnt++;
        double now = B[firstPlus - 1] + 1;
        for (int i = firstPlus - 2; i >= 0; i--) {
            int diff = max(0LL, (int) ceil(now - B[i] + EPS));
            if (diff % 2 == 0) diff++;
            now = B[i] + diff;
            cnt += diff;
        }
    }
    double now = B[firstPlus];
    for (int i = firstPlus + 1; i < N; i++) {
        int diff = max(0LL, (int) ceil(now - B[i] + EPS));
        if (diff % 2) diff++;
        now = B[i] + diff;
        cnt += diff;
    }
    return cnt;
}

