int N;
ll A[MAX_N];
ll PA[MAX_N];
ll B1[MAX_N], B2[MAX_N];

void pre(ll B[MAX_N]) {
	stack<pi> st;
	st.push(pi(inf, N - 1));
	B[N - 1] = 0;
	ll cost = 0;
	rer(i, N - 1, 0) {
		// debug(i);
		while(A[i] > A[i + 1]) {
			A[i + 1] *= 4;
			pi p = st.top(); st.pop();
			p.fst--;
			cost += (2 * (p.sec - i));
			if(p.fst) st.push(p);
		}
		B[i] = cost;
		ll n = A[i];
		int cnt = 0;
		while(n * 4 <= A[i + 1]) {
			n *= 4; cnt++;
		}
		// debug(i, vi(A, A + N), n, cnt);
		if(cnt) st.push(pi(cnt, i));
	}
}

void solve() {
	cin >> N;
	rep(i, 0, N) cin >> PA[i];

	rep(i, 0, N) A[i] = PA[i];
	pre(B1);
	rep(i, 0, N) A[i] = PA[i];
	reverse(A, A + N);
	pre(B2);
	reverse(B2, B2 + N);
	// debug(vi(B1, B1 + N));
	// debug(vi(B2, B2 + N));
	ll res = B1[0];
	MIN(res, B2[N - 1] + N);
	rep(i, 0, N - 1) {
		MIN(res, B2[i] + B1[i + 1] + i + 1);
	}
	cout << res << "\n";
}

