int main() {
	usize n;
	::std::cin >> n;
	::std::vector<u64> a(n);
	for (auto &e : a) {
		::std::cin >> e;
	}
	::std::vector<u64> pos(n + 1), neg(n + 1);

	struct ar {
		u64 cnt;
		u64 dif;
	};
	::std::stack<ar> st;
	neg[0] = 0;
	neg[1] = 1;
	st.push({ 1, ::std::numeric_limits<u64>::max()/2 });
	for (const auto i : rep<>(1, n)) {
		neg[i + 1] = neg[i] + 1;
		u64 prev = a[i - 1], cur = a[i];
		if (prev < cur * 4) {
			while (prev < cur) {
				prev *= 4;
				neg[i + 1] += st.top().cnt * 2;
				--st.top().dif;
				if (st.top().dif == 0) {
					const u64 temp = st.top().cnt;
					st.pop();
					st.top().cnt += temp;
				}
			}
			++st.top().cnt;
		}
		else {
			st.push({ 1, 0 });
			while (prev >= cur * 4) {
				cur *= 4;
				++st.top().dif;
			}
		}
	}
	st = ::std::stack<ar>();
	pos[n] = 0;
	pos[n - 1] = 0;
	st.push({ 1, ::std::numeric_limits<u64>::max() / 2 });
	for (const auto i : revrep<>(0, n - 1)) {
		pos[i] = pos[i + 1];
		u64 prev = a[i + 1], cur = a[i];
		if (prev < cur * 4) {
			while (prev < cur) {
				prev *= 4;
				pos[i] += st.top().cnt * 2;
				--st.top().dif;
				if (st.top().dif == 0) {
					const u64 temp = st.top().cnt;
					st.pop();
					st.top().cnt += temp;
				}
			}
			++st.top().cnt;
		}
		else {
			st.push({ 1, 0 });
			while (prev >= cur * 4) {
				cur *= 4;
				++st.top().dif;
			}
		}
	}


	u64 ans = ::std::numeric_limits<u64>::max();

	for (const auto i : rep<>(0, n + 1)) {
		samin(ans, neg[i] + pos[i]);
	}

	::std::cout << ans << ::std::endl;
	return 0;
}

