void solve(){
  ll pos[N][16];
  rep(i, N)rep(j, 16)pos[i][j] = INFL;
  rep(i, 16){
    pos[N-1][i] = i * 2;
  }
  for(ll i = N-2; i >= 0; i--){
    for(ll j = 0; j <= 15; j++){
      ll a = A[i];
      rep(_, j) a *= 4;
      ll b = A[i+1];
      ll cnt = 0;
      while(a > b){
        b *= 4;
        cnt++;
      }
      if(cnt <= 15){
        pos[i][j] = pos[i+1][cnt] + 2 * j;
      }else{
        pos[i][j] = pos[i+1][15] + 2 * (cnt-15) * (N-i-1) + 2 * j;
      }
    }
  }
  vector<ll> right(N+1);
  right[N] = 0;
  rep(i, N){
    ll m = INFL;
    rep(j, 15){
      m = min(m, pos[i][j]);
    }
    right[i] = m;
  }

  vector<ll> eff(N, 0);
