    A[i] *= -2;
  }
  ll neg[N][16];
  rep(i, N)rep(j, 16)neg[i][j] = INFL;
  rep(i, 16){
    neg[0][i] = i * 2 + 1;
  }
  for(ll i = 1; i < N; i++){
    for(ll j = 0; j <= 15; j++){
      ll b = A[i];
      rep(_, j) b *= 4;
      ll a = A[i-1];
      ll cnt = 0;
      while(a > b){
        a *= 4;
        cnt++;
      }
      if(cnt <= 15){
        neg[i][j] = neg[i-1][cnt] + 2 * j + 1;
      }else{
        neg[i][j] = neg[i-1][15] + 2 * (cnt-15) * i + 2 * j + 1;
      }
    }
  }
  vector<ll> left(N+1, 0);
  rep(i, N){
    ll m = INFL;
    rep(j, 15) m = min(m, neg[i][j]);
    left[i+1] = m;
  }
  ll ans = INFL;
  rep(i, N){
    ans = min(ans, left[i] + right[i]);
  }
  cout << ans << endl;
}
