long long N , A[MaxN] ;
long long Dp1[MaxN] , Dp2[MaxN] ;
int main() {
	long double Log4 = log( 4 ) ;
	N = Readin() ;
	for(register long long i = 0 ; ++i <= N ; A[i] = Readin() ) ;
	Dp1[N] = Dp1[N+1] = 0 ;
	for(register long long i = N ; --i ; )
		if( A[i] <= A[i+1] ) Dp1[i] = Dp1[i+1] ;
		else Dp1[i] = Dp1[i+1] + (long long)( log( A[i] / A[i+1] ) / Log4 + ( 1 - Eps ) ) * ( N - i << 1 ) ;
	Dp2[0] = 0 ; Dp2[1] = 1 ;
	for(register long long i = 1 ; ++i <= N ; ) {
		if( A[i] <= A[i-1] ) Dp2[i] = Dp2[i-1] + 1 ;
		else Dp2[i] = Dp2[i-1] + 1 + (long long)( log( A[i-1] / A[i] ) / Log4 + ( 1 - Eps ) ) * ( i - 1 << 1 ) ;
	}
