template<class Cond> struct chain {
  Cond cond; chain(Cond cond) : cond(cond) {}
  template<class T> bool operator()(T& a, const T& b) const { if(cond(a, b)) { a = b; return true; } return false; }
};
template<class Cond> chain<Cond> make_chain(Cond cond) { return chain<Cond>(cond); }

int main() {
  i64 N;
  cin >> N;
  vector<i64> A(N);
  rep(i,0,N) {
    cin >> A[i];
  }
  auto chmin = make_chain(std::greater<i64>());
  auto func = [&chmin](i64 N, const vector<i64>& A, i64 mns) {
    const int H = 16;
    auto dp = ndvec(N + 1, H, i64(1e18));
    rep(i,0,H) {
      dp[N][i] = 0;
      dp[N - 1][i] = 2 * i + mns;
    }
    for(int i = N - 1; i --> 0;) {
      i64 alpha = A[i];
      for(int j = 0; j < H; j++) {
        i64 beta = A[i + 1];
        i64 cnt = 0;
        while(alpha > beta) {
          beta *= 4;
          cnt++;
        }
        i64 bck = 0;
        if(cnt >= H) {
          bck = (cnt - H + 1) * 2 * i;
          cnt = H - 1;
        }
        chmin(dp[i][j], dp[i + 1][cnt] + 2 * j + bck + mns);
        alpha *= 4;
      }
    }
    return dp;
  };
  auto rdp = func(N, A, 0);
  reverse(all(A));
  auto ldp = func(N, A, 1);
  i64 ans = i64(1e18);
  for(int i = 0;i <= N;i++) {
    rep(j,0,16) rep(k,0,16) {
      chmin(ans, rdp[i][j] + ldp[N - i][k]);
    }
  }
  cout << ans << endl;
}

