int NOTHING = INT_MAX / 4;
ll LIMIT = LONG_LONG_MAX / 4;
ll mul[70];
int n;
ll a[200000];
int dp[200002][100];

bool limitOk(ll x) {
  if (x >= LIMIT || x <= -LIMIT) {
    return false;
  }
  return true;
}

int dfs(int idx, int preMul) {
  if (idx == n) {
    return 0;
  }
  if (dp[idx][preMul] != -1) {
    return dp[idx][preMul];
  }

  ll preVal = a[idx - 1] * mul[preMul];
  int res = NOTHING;

  if (preVal >= a[idx]) {
    ll curVal = a[idx];
    int cnt = 0;

    for (int i = 0; i < 63; i++) {
      ll curVal = a[idx] * mul[i];
      if (!limitOk(curVal)) {
        break;
      }
      if (curVal >= preVal) {
        res = min(res, dfs(idx + 1, i) + i);
        break;
      }
    }
  } else {
    res = min(res, dfs(idx + 1, 0));

    for (int i = 1; i < 63; i++) {
      ll curVal = a[idx] * mul[i];
      if (!limitOk(curVal)) {
        break;
      }
      if (curVal < preVal) {
        continue;
      }

      res = min(res, dfs(idx + 1, i) + i);
    }
  }

  return dp[idx][preMul] = res;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(0);

  mul[0] = 1;
  for (int i = 1; i < 63; i++) {
    mul[i] = mul[i - 1] * (-2);
  }

  while (cin >> n) {
    for (int i = 0; i < n; i++) {
      cin >> a[i];
    }

    memset(dp, -1, sizeof(dp));

    int ans = NOTHING;

    ans = min(ans, dfs(1, 0));

    for (int i = 1; i < 63; i++) {
      ll curVal = a[0] * mul[i];
      if (!limitOk(curVal)) {
        break;
      }
      ans = min(ans, dfs(1, i) + i);
    }

    if (ans == NOTHING) {
      cout << -1 << endl;
    } else {
      cout << ans << endl;
    }
  }
}

