  {
  using P = pair<ll, ll>;
  stack<P> st;
  const ll inf = 1e18;
  st.emplace(0, inf);

  dp0[0] = 0;
  dp0[1] = 0;
  for(int i = 1; i < n; i++) {
    ll t = a[i-1], h = 0;
    while(t < a[i]) t *= 4, h++;
    dp0[i + 1] = dp0[i];
    while(h > 0) {
      auto p = st.top();
      st.pop();
      ll use = min(h, p.second);
      h -= use;
      p.second -= use;
      dp0[i+1] += use * (i - p.first);
      if(p.second > 0) st.push(p);
    }
    ll u = a[i];
    h = 0;
    while(u < t) u *= 4, h++;
    st.emplace(i, max(0ll, h - 1));
  }
  }

  {
  reverse(a, a + n);
  using P = pair<ll, ll>;
  stack<P> st;
  const ll inf = 1e18;
  st.emplace(0, inf);

