#include<bits/stdc++.h>
using namespace std;
const int N = 2e5 + 1;
const int mod = 998244353;
int power(int a, int b){
    int res = 1;
    while(b > 0){
        if(b & 1){
            res = 1LL * res * a % mod;
        }
        a = 1LL * a * a % mod;
        b >>= 1;
    }
    return res;
}
long long a[N], b[N];
long long n, dpa[N][30], dpb[N][30];
long long funa(int idx, int j){
    if(idx == n + 1) return 0;
    long long &ret = dpa[idx][j], tot = j;
    if(ret != -1) return ret;
    long long val = a[idx], prev = a[idx - 1];
    if(j < 16){
        while(tot--){
            prev *= 4;
            if(prev > 3e18 / 4) return 1e8;
        }
        int cnt = 0;
        while(val < prev){
            cnt++;
            if(cnt >= 30 || val > 3e18 / 4) return 1e8;
            val *= 4;
        }
        return ret = 2 * cnt + funa(idx + 1, cnt);
    }else{
        return ret = 2 * (j - 15) * (n - idx) + funa(idx + 1, 15);
    }
}
long long funb(int idx, int j){
    if(idx == 0) return 0;
    long long &ret = dpb[idx][j], tot = j;
    if(ret != -1) return ret;
    long long val = b[idx], prev = b[idx + 1];
    if(j < 16){
        while(tot--){
            prev *= 4;
            if(prev > 3e18 / 4) return 1e8;
        }
        int cnt = 0;
        while(val < prev){
            cnt++;
            if(cnt >= 30 || val > 3e18 / 4) return 1e8;
            val *= 4;
        }
