            }
            else{
                // 現在のところの値に対して 4 ^ ope_cnt したものと、次の要素の値を比較し、次の値が何回計算する必要があるか調べる
                ll c_val = A[pos] * (1LL << (ope_cnt * 2));
                if(c_val <= A[pos + 1]){
                    // 操作の必要なし
                    res = dp_pos[pos + 1][0];
                }
                else{
                    // 何回操作したら超えるか調べる
                    // 15を超えた分は、残りの数字をすべて4でかける操作で代用できるので、その分を加算しておくことで代用する
                    // c_val <= A[pos + 1] * (4 ^ n_cnt)となる最小のn_cntを計算する
                    ll n_cnt = 0;
                    ll cmp = (A[pos + 1] + c_val - 1) / A[pos + 1];
                    for(; ; n_cnt++){
                        if(cmp <= 1LL << (n_cnt * 2)){
                            break;
                        }
                    }
                    if(n_cnt > 15){
                        ll diff = n_cnt - 15;
                        res = (N - 1 - pos) * 2 * diff + 15 * 2 + dp_pos[pos + 1][15];
                    }
                    else{
                        res = n_cnt * 2 + dp_pos[pos + 1][n_cnt];
                    }
                }

            }
            dp_pos[pos][ope_cnt] = res;
        }
    }
}

int main(){
    cin >> N;
    for(ll i = 0; i < N; i++){
        cin >> A1[i];
        A2[N - 1 - i] = A1[i];
    }

    solve(A1, dp_pos);
    solve(A2, dp_neg);

    ll ans = min(dp_pos[0][0], dp_neg[0][0] + N);
    for(ll i = 1; i < N; i++){
        // iから正になる場合
        ans = min(ans, dp_neg[N-i-1][0] + dp_pos[i][0] + i);
    }
    cout<< ans << endl;

    return 0;
}

