using namespace std;

typedef pair<int,int> P;

int N, A[200005];

vector<int> build(int flag){

  vector<P> v;

  int sum = 0;

  vector<int> res;

  int a0 = 0;

  if( !flag && A[N-1] < 0 ) a0++;
  if( flag && A[N-1] > 0 ) a0++;

  res.push_back( a0 );

  for(int i=N-1;i>0;i--){

    int a = A[i-1], b = A[i];

    if( flag == 0 ){

      if( a < 0 ) a *= -2, sum++;

      if( b < 0 ) b *= -2, sum++;

    }else{

      if( a > 0 ) a *= -2, sum++;

      if( b > 0 ) b *= -2, sum++;

      a = abs( a );

      b = abs( b );

    }

    if( a > b ){

      int cnt = 0;

      while( a > b ){

	b *= 4;
	cnt++;

	if( (int)v.size() ){

	  if( v[v.size()-1].first != 0 ){

	    v.pop_back();

	    if( v.size() && v[v.size()-1].first == 0 ){
	      v[v.size()-1].second++;
	    }else v.push_back( P( 0, 1 ) );

	  }
	  else{

	    int S = v[v.size()-1].second;

	    sum += S * 2;

	    v.pop_back();

	    if( v.size() ){
	      v.pop_back();
	      S++;
	    }

	    if( v.size() && v[v.size()-1].first == 0 ){
	      v[v.size()-1].second += S;
	    }else v.push_back( P( 0, S ) );

	  }

	}

      }

      sum += cnt * 2;

      if( (int)v.size() && v[v.size()-1].first == 0 ){
	v[v.size()-1].second++;
      }else v.push_back( P( 0, 1 ) );

    }
    else{

      int cnt = 0;

      while( a <= b ){

	a *= 4;

	cnt++;

      }

      if( (int)v.size() && v[v.size()-1].first == cnt-1 && cnt - 1 == 0 ){
	v[v.size()-1].second++;
      }else v.push_back( P( cnt-1, 1 ) );

    }

    /*    if(flag){

      cout<<i<<endl;

      for(P p : v) cout<<p.first<<' '<<p.second<<endl;

      cout<<endl;

      }*/

    res.push_back( sum );

  }

  return res;  
}

signed main(){

  cin>>N;

  for(int i=0;i<N;i++) cin>>A[i];

  if( N == 1 ){
    cout<<0<<endl;
    return 0;
  }

  vector<int> R = build(0);

  reverse( A, A + N );

  vector<int> L = build(1);

  reverse( R.begin(), R.end() );
  /*
  for(int p : L ) cout<<p<<' ';
  cout<<endl;

  for(int p : R ) cout<<p<<' ';
  cout<<endl;
  */
  int ans = min( L[N-1], R[0] );

  for(int i=0;i<N-1;i++){

    ans = min( ans, L[i] + R[i+1] );

  }

  cout<<ans<<endl;

  return 0;
}

