ll N ;
vector<ll> A;

ll cal(ll from, ll to){
    vector<ll> temp = A;
    ll ans = 0;
    while(from > 0){
        from --;
        if(temp[from] > temp[from+1]){
            temp[from] *= (-2);
            ans ++;
            from ++;
        }
    }
    while(to < N-1){
        to++;
        if(temp[to-1] > temp[to]){
            temp[to] *= (-2);
            ans ++;
            to --;
        }

    }

    return ans;
}
ll cal_re(ll from, ll to){
    ll ans = to - from  + 1;
    vector<ll> temp = A;

    while(from > 0){
        from --;
        if(temp[from] < temp[from+1]){
            temp[from] *= (-2);
            ans ++;
            from ++;
        }
    }
    while(to < N-1){
        to++;
        if(temp[to-1] < temp[to]){
            temp[to] *= (-2);
            ans ++;
            to --;
        }
    }
    return ans;
}

