int main() {
  int n;
  cin >> n;
  if (n == 1) {
    cout << 0 << endl;
    return 0;
  }
  vl a(n);
  rep (i, n) {
    cin >> a[i];
  }
  vll dp1(n, vl(16, INF));
  rep (i, 16) {
    dp1[n - 1][i] = 2*i;
  }
  for (int i = n - 2; i >= 0; i--) {
    ll me = a[i], you = a[i + 1];
    int j = 0, k = 0;
    rep (j, 16) {
      while (me > you) {
        you *= 4;
        k++;
      }
      if (k < 16) {
        dp1[i][j] = min(dp1[i][j], dp1[i + 1][k] + 2*j);
      }
      else {
        dp1[i][j] = min(dp1[i][j], dp1[i + 1][15] + 2*j + 2*(k - 15)* (n - 1 - i));
      }
      me *= 4;
    }
  }
  vll dp2(n, vl(16, INF));
  rep (i, 16) {
    dp2[0][i] = 1 + 2*i;
  }
  for (int i = 1; i < n; i++) {
    ll me = a[i]*-2, you = a[i - 1]*-2;
    int j = 0, k = 0;
    rep (j, 16) {
      while (me < you) {
        you *= 4;
        k++;
      }
      if (k < 16) {
        dp2[i][j] = min(dp2[i][j], dp2[i - 1][k] + 2*j + 1);
      }
      else {
        dp2[i][j] = min(dp2[i][j], dp2[i - 1][15] + 2*j + 2*(k - 15)*i + 1);
      }
      me *= 4;
    }
  }
  ll ans = min(dp2[n - 1][0], dp1[0][0]);
  for (int i = 0; i < n - 1; i++) {
    ans = min(ans, dp2[i][0] + dp1[i + 1][0]);
  }
  cout << ans << endl;
}

