vector<long long> get(vector<long long> A){


	vector<long long> ret(A.size(),0LL);
	vector<int> ok;
	for(int i=A.size()-1;i>=0;i--){
		if(i+1==A.size())continue;
		ret[i] = ret[i+1];
		int now = i;
		long long c = 0;
		while(true){
			for(int j=0;j<c/2;j++){
				A[now] *= 4;
			}
			if(A[now]<=A[now+1]){
				ok.push_back(now);
				break;
			}
			c=0;
			while(A[now]>A[now+1]){
				c+=2;
				A[now+1]*=4;
			}
			if(ok.size()!=0){
				ret[i] += c*(ok.back()-now);
				if(ok.back()-now==1)c=0;
				now=ok.back();
				ok.pop_back();
			}
			else{
				ret[i] += c*(A.size()-1-now);
				break;
			}
		}

	}
	return ret;
}


