            if (pow4[x] * A[l] <= A[l-1]) {
                dp2[l][x] = dp2[l-1][0] + x;
            }
            else {
                LL k = ceil((log((double)pow4[x])+log((double)A[l])-log((double)A[l-1]))/log(4.0));
                if (k >= 15) dp2[l][x] = dp2[l-1][15] + x + l * (k-15);
                else dp2[l][x] = dp2[l-1][k] + x;
            }
        }
    }

    LL ans = min(dp1[0][0] * 2, dp2[N - 1][0] * 2 + N);

    for (int i = 1; i < N; i++) {
        ans = min(ans, dp1[i][0] * 2 + dp2[i - 1][0] * 2 + i);
    }

    cout << ans << endl;
}

