vector<ll> solve(vector<ll>& A){
    int n = A.size();
    vector<ll> dp(n, -1);
    vector<ll> mpow(20, 1);
    rep(i, 1, 20) mpow[i] = mpow[i-1] * 4;
    stack<pll> st;
    dp[0] = 0;
    st.emplace(0, INF);
    ll ans = 0;
    rep(i, 1, n){
        ll cnt = 0;
        if(A[i-1] < A[i]){
            rep(j, 1, 20) if(A[i-1] * mpow[j] >= A[i]){
                cnt = -j;
                break;
            }
        }else{
            rep(j, 1, 20) if(A[i-1] < A[i] * mpow[j]){
                cnt = j - 1;
                break;
            }
        }
        if(cnt > 0){
            st.emplace(i, cnt);
        }else if(cnt < 0){
            while(cnt < 0){
                auto tmp = st.top();st.pop();
                if(tmp.second + cnt < 0){
                    ans += ((ll)i - tmp.first) * 2 * tmp.second;
                    cnt += tmp.second;
                }else{
                    ans += ((ll)i - tmp.first) * 2 * (-cnt);
                    tmp.second += cnt;
                    if(tmp.second > 0) st.push(tmp);
                    break;
                }
            }
        }
        dp[i] = ans;
    }
    return dp;
}

