const ll inf = 1e15;
ll solve(ll id ,ll x)
{
        if(x >= 17) return inf;
        if(id == n + 1) {
                return 0;
        }
        if(dp[id][x] != -1) return dp[id][x];
        ll mup = 1LL;
        for(ll i=0;i<x;i++) mup = mup*4;
        mup = mup * a[id-1];
        ll cnt = 0;
        ll cur = a[id];
        while(mup > cur) {
                cur = cur * 4; cnt++;
        }
        if(cnt <= 15){
        return dp[id][x] = solve(id+1, cnt) + cnt;

        }else {
                return dp[id][x] = solve(id+1, 15) + cnt + (cnt-15)*(n-id);
        }
}
