        if (a[i] <= a[i + 1])
        {
            continue;
        }
        else if (a[i - 1] <= -2 * a[i])
        {
            ans++;
            a[i] *= -2;
        }
        else
        {
            ll cost = ceil(logl((lld)a[i] / (lld)a[i + 1]) / logl(4));
            a[i + 1] *= pow(4, cost);

            ans += 2 * cost;
        }
    }

    cout << ans << endl;
    return 0;
}

