i64 pos(const vector<i64> &b, int l, int r)
{
  i64 cnt = 0;
  i64 res = 0;
  for (int i = l + 1; i < r; i++)
  {
    i64 x = b[i - 1];
    i64 y = b[i];
    if (y < 0)
    {
      y *= -2;
      res++;
    }
    i64 rem;
    if (x <= y)
    {
      rem = -ceil(log2(1.0 * y / x));
    }
    else
    {
      rem = ceil(log2(1.0 * x / y));
    }
    rem += cnt;
    if (rem < 0)
      rem = 0;
    rem += rem & 1;
    res += rem;
    cnt = rem;
  }
  return res;
}

i64 neg(const vector<i64> &b, int l, int r)
{
  i64 cnt = 0;
  i64 res = 0;

  for (int i = r - 2; i >= l; i--)
  {
    i64 x = b[i];
    i64 y = b[i + 1];
    if (x > 0)
    {
      x *= -2;
      res++;
    }
    i64 rem;
    if (x <= y)
    {
      rem = -ceil(log2(1.0 * x / y));
    }
    else
    {
      rem = ceil(log2(1.0 * y / x));
    }
    rem += cnt;
    if (rem < 0)
      rem = 0;
    rem += rem & 1;
    res += rem;
    cnt = rem;
  }

  return res;
}

const i64 MAX = LONG_MAX / 2;

i64 solve(vector<i64> a)
{
  i64 N = a.size();
  if (N == 1)
  {
    cout << 0 << endl;
    return 0;
  }

  vector<i64> b = a;

  i64 res = MAX;

  for (int i = 0; i + 1 < N; i++)
  {
    int j = i + 1;
    i64 c = -1;
    bool OK =  true;
    for (i64 x = a[i]; abs(x) <= MAX && OK; x *= -2)
    {
      c++;
      i64 d = -1;
      for (i64 y = a[j]; abs(y) <= MAX && OK; y *= -2)
      {
        d++;
        if (x <= y)
        {
          b[i] = x;
          b[j] = y;
          i64 ne = neg(b, 0, j);
          i64 po = pos(b, j, N);
          i64 temp = ne + po + c + d;
          res = min(temp, res);
          b[i] = a[i];
          b[j] = a[j];
          OK = false;
        }
      }
    }
  }
  return res;
}

int main()
{
  i64 N;
  cin >> N;
  vector<i64> a(N);
  rep(i, 0, N - 1) cin >> a[i];

  if(count(all(a), 0) == N) {
    cout << 0 << endl;
    return 0;
  }

  {
    int zero_cnt = 0;
    bool now = false;
    rep(i, 0, N - 1)
    {
      if (a[i] == 0)
      {
        if (!now)
        {
          zero_cnt++;
        }
        now = true;
      }
      else
      {
        now = false;
      }
    }

    if (zero_cnt > 1)
    {
      cout << -1 << endl;
      return 0;
    }

    if (zero_cnt == 1)
    {
      vector<i64> before;
      vector<i64> after;
      bool now = false;
      rep(i, 0, N - 1)
      {
        if (now && a[i] == 0)
          continue;
        if (!now && a[i] == 0)
        {
          now = true;
        }
        else if (!now)
          before.push_back(a[i]);
        else
          after.push_back(a[i]);
      }
      i64 ne = MAX;
      i64 po = MAX;
      {
        i64 c = -1;
        for (i64 x = before.back(); abs(x) <= MAX; x *= -2)
        {
          c++;
          if (x < 0)
          {
            swap(before.back(), x);
            ne = min(ne, neg(before, 0, before.size()) + c);
            swap(before.back(), x);
          }
        }
      }
      {
        i64 c = -1;
        for (i64 x = after.front(); abs(x) <= MAX; x *= -2)
        {
          c++;
          if (x > 0)
          {
            swap(after.front(), x);
            po = min(po, pos(after, 0, after.size()) + c);
            swap(after.front(), x);
          }
        }
      }

      cout << ne + po << endl;
      return 0;
    }
  }

  cout << solve(a) << endl;

  return 0;
}

