int MAX = 16;

vector<vector<ll>> solve(vector<ll> a, int offset = 0) {
    int n = a.size();
    vector<vector<ll>> dp(n + 1, vector<ll>(MAX, INF));
    for (int j = 0; j < MAX; ++j) dp[0][j] = 0, dp[1][j] = j * 2 + offset;
    for (int i = 1; i < n; ++i) {
        ll s = a[n - i - 1];
        for (int j = 0; j < MAX; ++j) {
            ll t = a[n - i];
            int need = 0;
            while (s > t) ++need, t *= 4;
            ll add = 0;
            if (need >= MAX) {
                add = (need - MAX + 1) * i * 2;
                need = MAX - 1;
            }
            cmin(dp[i + 1][j], dp[i][need] + j * 2 + add + offset);
            s *= 4;
        }
    }
    return dp;
}

