struct range{
    lint len, L, R;
    range(lint len, lint L, lint R): len(len), L(L), R(R){}
};

lint push_L(stack<range> &st, range a){
    if(st.empty()){
        st.push({1, 0, a.R});
        return 0;
    }
    else if(st.top().R < a.L * 4){
        st.push(a);
        return 0;
    }
    else{
        auto t = st.top(); st.pop();
        lint ret = 0;
        while(t.R > a.L){
            t.R *= 4; t.L *= 4;
            ret += t.len * 2;
        }
        t.R = a.R;
        t.len += a.len;
        return ret + push_L(st, t);
    }
}

lint push_R(stack<range> &st, range a){
    if(st.empty()){
        st.push({a.len, a.L, 0});
        return 0;
    }
    else if(st.top().L > a.R * 4){
        st.push(a);
        return 0;
    }
    else{
        auto t = st.top(); st.pop();
        lint ret = 0;
        while(t.L < a.R){
            t.L *= 4; t.R *= 4;
            ret += t.len * 2;
        }
        t.L = a.L;
        t.len += a.len;
        return ret + push_R(st, t);
    }
}

