#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<ll, ll> ii;

#define X first
#define Y second

const int N = 2e5 + 10;
const int inf = 1e9 + 10;

long long a[N];
ii s[N];
int n;
long long f[2][N];

long long cost(ii p1, ii p2) {
    if (p2.Y >= p1.Y + 31) return 0;
    long long ans = max(0LL, p1.Y - p2.Y - 31);
    p2.Y += ans;

    ll d1 = max(0LL, p1.Y - p2.Y);
    p1.X <<= d1;
    ll d2 = max(0LL, p2.Y - p1.Y);
    p2.X <<= d2;

    while (p2.X < p1.X) p2.X <<= 2, ans += 2;
    return ans;
}
long long solve() {
    if (n == 1) return 0;
    if (n == 2) {
        return a[2] < a[1];
    }
    int top = 0;
    s[0] = ii(n + 1, inf);
    for(int i = n; i >= 2; i--) {
        ll use = cost(ii(a[i - 1], 0), ii(a[i], 0));
        //cout << i << " " << use << '\n';
        f[0][i] = f[0][i + 1] + use;
        while (1) {
            ll need = cost(ii(a[i], use), ii(a[s[top].X], s[top].Y));
            if (!need) break;
            f[0][i] += (s[top - 1].X - s[top].X) * need;
            top--;
        }
        s[++top] = ii(i, use);
    }
    //for(int i = 1; i <= n; i++) cout << f[0][i] << " ";cout << '\n';

    top = 0;
    s[0] = ii(0, inf);
    for(int i = 1; i < n; i++) {
        ll use = cost(ii(a[i + 1] * 2, 0), ii(a[i] * 2, 0)) + 1;
        //cout << i << " " << use << '\n';
        f[1][i] = f[1][i - 1] + use;
        while (1) {
            ll need = cost(ii(a[i], use), ii(a[s[top].X], s[top].Y));
            if (!need) break;
            f[1][i] += (s[top].X - s[top - 1].X) * need;
            top--;
        }
        s[++top] = ii(i, use);
    }
    //for(int i = 1; i <= n; i++) cout << f[1][i] << " ";cout << '\n';
    long long ans = min(f[0][2], f[1][n - 1] + 1);
    for(int i = 1; i < n; i++) {
        ans = min(ans, f[1][i - 1] + 1 + f[0][i + 2]);
    }
    return ans;
}
int main() {
    cin >> n;
    for(int i = 1; i <= n; i++) cin >> a[i];
    cout << solve();
}

