const ll limit = 200010;
ll minus_values[limit],plus_values[limit];


int main(void){
	ll n;
	cin >> n;
	vector<ll> a(n);
	rep(i,n) cin >> a[i];

	minus_values[0] = 1;
	rep(i,1,n){
		ll prv = -2LL * a[i-1];
		minus_values[i] = minus_values[i-1];
		ll cur = -2LL * a[i];
		minus_values[i]++;
		while(abs(prv) < abs(cur)){
			minus_values[i] += 2LL * i;
			prv *= 4LL;
		}
	}

	plus_values[n-1] = 0;
	rrep(i,n-1,0){
		ll prv = a[i+1];
		plus_values[i] = plus_values[i+1];
		ll cur = a[i];
		while(abs(prv) < abs(cur)){
			plus_values[i] += 2LL * (n - 1 - i);
			prv *= 4LL;
		}
	}

	ll ans = min(minus_values[n-1],plus_values[0]);
	rep(i,n-1) chmin(ans, minus_values[i] + plus_values[i+1]);
	cout << ans << endl;

	return 0;
}

