using namespace std;

typedef long long ll;

struct triple
{
    ll val;
    int lef, rig;
    triple(ll a = 0, int b = 0, int c = 0) {val = a, lef = b, rig = c;}
};

struct My_stack
{
    triple mas[200005];
    int tail = 0;
    ll sum = 0;
    void clear()
    {
        sum = 0, tail = 0;
        return;
    }
    void add(ll val, int lef, int rig)
    {
        while (tail > 0 && val <= mas[tail].val)
        {
            sum -= (ll) (mas[tail].rig - mas[tail].lef + 1) * mas[tail].val;
            lef = min(lef, mas[tail].lef), rig = max(rig, mas[tail].rig);
            tail--;
        }
        tail++;
        mas[tail] = triple(val, lef, rig);
        sum += (ll) (mas[tail].rig - mas[tail].lef + 1) * mas[tail].val;
        return;
    }
    ll get_sum()
    {
        return sum;
    }
};

ll a[200005], step[200005], suf[200005], st[200005], pref[200005];
My_stack S;

int main()
{
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    ios_base::sync_with_stdio(0); cin.tie(0);
    int n;
    ll sum = 0;
    cin >> n;
    for (int i = 1; i <= n; i++) cin >> a[i];
    step[1] = 0;
    for (int i = 2; i <= n; i++)
    {
        if (a[i - 1] <= a[i])
        {
            int h = 0;
            while (a[i - 1] * (1ll << h) < a[i]) h += 2;
            if (a[i - 1] * (1ll << h) == a[i])
                step[i] = max(step[i - 1] - (ll) h, 0ll);
            else
                step[i] = max(step[i - 1] - (ll) h + 2, 0ll);
        }
        if (a[i - 1] > a[i])
        {
            int h = 0;
            while (a[i] * (1ll << h) < a[i - 1]) h += 2;
            step[i] = step[i - 1] + (ll) h;
        }
    }
    S.clear();
    for (int i = n; i > 0; i--)
    {
        S.add(step[i], i, i);
        sum += step[i];
        suf[i] = sum - S.get_sum();
    }
    suf[n + 1] = 0;

    for (int i = 1; i <= n; i++) a[i] *= (-2), st[i] = 1;
    for (int i = n - 1; i > 0; i--)
    {
        if (a[i] <= a[i + 1])
        {
            int h = 0;
            while (a[i + 1] * (1ll << h) > a[i]) h += 2;
            if (a[i + 1] * (1ll << h) == a[i])
                st[i] = max(st[i + 1] - (ll) h, 1ll);
            else
                st[i] = max(st[i + 1] - (ll) h + 2, 1ll);
        }
        if (a[i] > a[i + 1])
        {
            int h = 0;
            while (a[i] * (1ll << h) > a[i + 1]) h += 2;
            st[i] = st[i + 1] + (ll) h;
        }
    }
    S.clear();
    sum = 0;
    for (int i = 1; i <= n; i++)
    {
        S.add(st[i] - 1, i, i);
        sum += st[i];
        pref[i] = sum - S.get_sum();
    }
    pref[0] = 0;
    ll answer = (ll) 1e18;
    for (int i = 0; i <= n; i++) answer = min(answer, pref[i] + suf[i + 1]);
    cout << answer;
    return 0;
}

