                continue;
            }
            for(int p = 0; p <= 60; p++) {
                if(llabs(1LL * arr[i - 1] * pw[p]) > 1e18) {
                    break;
                }
                if(1LL * arr[i] * pw[j] >= 1LL * arr[i - 1] * pw[p]) {
                    dp[i][j] = min(dp[i][j], dp[i - 1][p] + j);
                }
            }
        }
    }
    int ans = INF;
    for(i = 0; i <= 60; i++) {
        ans = min(ans, dp[n][i]);
    }
