struct snode_t {
    llf valley, peak, lazy;
    int lef, rig;
    snode_t* chd[2];
} pool[1100000], *root, *last;

void update(snode_t *node) {
    node->valley = MIN(node->chd[0]->valley + node->chd[0]->lazy, node->chd[1]->valley + node->chd[1]->lazy);
    node->peak = MAX(node->chd[0]->peak + node->chd[0]->lazy, node->chd[1]->peak + node->chd[1]->lazy);
}

snode_t* build(const int lef, const int rig, const vector<int>& a, const llf d) {
    snode_t *node = last++;
    node->lef = lef;
    node->rig = rig;
    if (lef != rig) {
        const int mid = (lef + rig) >> 1;
        node->chd[0] = build(lef, mid, a, d);
        node->chd[1] = build(mid + 1, rig, a, d);
        node->lazy = 0.L;
        update(node);
    } else {
        node->valley = log2(a[lef] * 1.L) + d;
        node->peak = node->valley;
        node->chd[0] = nullptr;
        node->chd[1] = nullptr;
        node->lazy = 0.L;
    }
    return node;
}

pair<lld, llf> nond(snode_t *node, const int lef, llf bar) {
    if (node->lazy > eps) {
        node->valley += node->lazy;
        node->peak += node->lazy;
        if (node->chd[0] != nullptr) {
            node->chd[0]->lazy += node->lazy;
            node->chd[1]->lazy += node->lazy;
        }
        node->lazy = 0.L;
    }
    if (lef <= node->lef && node->peak < bar - eps) {
        lld d = MAX((lld)ceil(bar - node->valley), 0LL);
        if (d & 1) d += 1LL;
        while (node->valley + d * 1.L < bar - eps) d += 2LL;
        while (d - 2LL >= 0LL && node->valley + (d - 2LL) * 1.L > bar - eps) d -= 2LL;
        node->lazy += d * 1.L;
        return MP(d * (node->rig - node->lef + 1), node->peak + node->lazy);
    } else {
        lld cnt = 0LL;
        if (node->chd[0]->rig >= lef
            && node->chd[0]->valley + node->chd[0]->lazy < bar - eps) {
            auto foo = nond(node->chd[0], lef, bar);
            cnt += foo.first;
            UPDMAX(bar, foo.second);
        }
        if (node->chd[1]->valley + node->chd[1]->lazy < bar - eps) {
            auto foo = nond(node->chd[1], lef, bar);
            cnt += foo.first;
            UPDMAX(bar, foo.second);
        }
        update(node);
        return MP(cnt, bar);
    }
}

pair<lld, llf> noni(snode_t *node, const int rig, llf bar) {
    if (node->lazy > eps) {
        node->valley += node->lazy;
        node->peak += node->lazy;
        if (node->chd[0] != nullptr) {
            node->chd[0]->lazy += node->lazy;
            node->chd[1]->lazy += node->lazy;
        }
        node->lazy = 0.L;
    }
    if (rig >= node->rig && node->peak < bar - eps) {
        lld d = MAX((lld)ceil(bar - node->valley), 0LL);
        if (d & 1) d += 1LL;
        while (node->valley + d * 1.L < bar - eps) d += 2LL;
        while (d - 2LL >= 0LL && node->valley + (d - 2LL) * 1.L > bar - eps) d -= 2LL;
        node->lazy += d * 1.L;
        return MP(d * (node->rig - node->lef + 1), node->peak + node->lazy);
    } else {
        lld cnt = 0LL;
        if (node->chd[1]->lef <= rig
            && node->chd[1]->valley + node->chd[1]->lazy < bar - eps) {
            auto foo = noni(node->chd[1], rig, bar);
            cnt += foo.first;
            UPDMAX(bar, foo.second);
        }
        if (node->chd[0]->valley + node->chd[0]->lazy < bar - eps) {
            auto foo = noni(node->chd[0], rig, bar);
            cnt += foo.first;
            UPDMAX(bar, foo.second);
        }
        update(node);
        return MP(cnt, bar);
    }
}

int main() {
    //ios_base::sync_with_stdio(0);
    int n;
    while (cin >> n) {
        vector<int> a(n, 0);
        for (int i = 0; i < n; ++i) {
            cin >> a[i];
        }
        vector<lld> f(n + 1, 0);
        f[n] = 0LL;
        last = pool;
        root = build(0, n - 1, a, 0.L);
        for (int i = n - 1; i >= 0; --i) {
            const llf bar = log2(a[i]);
            f[i] = f[i + 1] + nond(root, i, bar).first;
            //fprintf(stderr, "f[%d] = %lld\n", i, f[i]);
        }
        vector<lld> g(n + 1, 0);
        g[0] = 0LL;
        last = pool;
        root = build(0, n - 1, a, 1.L);
        for (int i = 0; i < n; ++i) {
            const llf bar = log2(a[i]);
            g[i + 1] = g[i] + noni(root, i, bar).first + 1LL;
            //fprintf(stderr, "g[%d] = %lld\n", i + 1, g[i + 1]);
        }
        lld foo = 0x3f3f3f3f3f3f3f3fLL;
        for (int i = 0; i <= n; ++i) {
            UPDMIN(foo, f[i] + g[i]);
        }
        cout << foo << endl;
    }
    return 0;
}

