using namespace std;

void solve(long long N, vector<long long> A){
  long long ans = -1;
  vector<long long> B(N);
  for (int i = 0; i < N+1; i++) {
    long long a = 0;
    copy(A.begin(), A.end(), B.begin());
    for (int j = i; j < N; j++) {
      if (B[j] < 0) {
        B[j] *= -2;
        a++;
      }
      if (j == i) {
        continue;
      }
      while (B[j] < B[j-1]) {
        B[j] *= 4;
        a += 2;
        if (a > ans && ans != -1) {
          break;
        }
      }
      if (a > ans && ans != -1) {
        break;
      }
    }
    for (int j = i-1; j >= 0; j--) {
      if (B[j] > 0) {
        B[j] *= -2;
        a++;
      }
      if (j == N-1) {
        continue;
      }
      while (B[j] > B[j+1]) {
        B[j] *= 4;
        a += 2;
        if (a > ans && ans != -1) {
          break;
        }
      }
      if (a > ans && ans != -1) {
        break;
      }
    }
    if (a < ans || ans == -1) {
      ans = a;
    }
  }
  std::cout << ans << std::endl;
}

int main(){
  long long N;
  scanf("%lld",&N);
  vector<long long> A(N);
  for(int i = 0 ; i < N ; i++){
    scanf("%lld",&A[i]);
  }
  solve(N, A);
  return 0;
}

