vi solve(vi v){
    ll n=v.size();
    vi cnt(n);
    cnt[n-1]=inf;
    rep(i,n-1){
        ll k=v[i];
        while(k*4<=v[i+1]){
            cnt[i]++;
            k*=4;
        }
    }
    deque<ll> c;
    c.push_front(n-1);
    vi res(n);
    for(int i=n-2;i>=0;i--){
        res[i]=res[i+1];
        if(v[i]>v[i+1]){
            ll k=v[i+1];
            while(k<v[i]){
                cnt[i+1]--;k*=4;res[i]++;
            }
            if(cnt[i+1]>0)c.push_front(i+1);
            else{
                int b=i+1;
                ll r=-cnt[i+1];
                chmax(cnt[i+1],0ll);
                while(true){
                    int j=c.front();
                    res[i]+=r*(j-b);
                    if(cnt[j]>=r){
                        cnt[j]-=r;break;
                    }
                    r-=cnt[j];
                    cnt[j]=0;
                    c.pop_front();
                    b=j;
                }
            }
            if(cnt[i]>0)c.push_front(i);
        }
    }
    return res;
}
