const int MAX_N = 200050;
const int MAX_BEGIN_NUM = 32;
int N;
long long A[MAX_N];
long long positive_from[MAX_N][MAX_BEGIN_NUM], negative_from[MAX_N][MAX_BEGIN_NUM];
// positive_from[i][j] : A[i]に-2をj回かけて、i以降を正の増加数列にするときに、i+1以降に-2をかける最小値。A[i]に-2をj回かけて負なら-1

int main(int argc, char **argv) {
    std::cin >> N;

    for (int i = 1; i <= N; i++) {
        std::cin >> A[i];
    }

    if (N == 1) {
        std::cout << 0 << std::endl;
        return 0;
    }

    for (int i = 1; i <= N; i++) {
        for (int j = 0; j < MAX_BEGIN_NUM; j++) {
            positive_from[i][j] = -1;
            negative_from[i][j] = -1;
        }
    }

    for (int i = N; 1 <= i; i--) {
        long long begin_val = A[i];
        for (int j = 0; j < MAX_BEGIN_NUM; j++) {
            if (0 < begin_val) {
                if (i == N) {
                    positive_from[i][j] = 0;
                } else {
                    long long next_val = A[i+1];
                    for (int k = 0; k < MAX_BEGIN_NUM; k++) {
                        if (begin_val <= next_val) {
                            positive_from[i][j] = k + positive_from[i+1][k];
                            break;
                        }
                        next_val = - next_val * 2;
                    }
                }
            }
            begin_val = - begin_val * 2;
        }
    }

    for (int i = 1; i <= N; i++) {
        long long begin_val = A[i];
        for (int j = 0; j < MAX_BEGIN_NUM; j++) {
            if (begin_val < 0) {
                if (i == 1) {
                    negative_from[i][j] = 0;
                } else {
                    long long next_val = A[i-1];
                    for (int k = 0; k < MAX_BEGIN_NUM; k++) {
                        if (next_val <= begin_val) {
                            negative_from[i][j] = k + negative_from[i-1][k];
                            break;
                        }
                        next_val = - next_val * 2;
                    }
                }
            }
            begin_val = - begin_val * 2;
        }
    }

    long long ret = std::min(
        A[1] > 0 ? positive_from[1][0] : positive_from[1][1] + 1,
        A[N] < 0 ? negative_from[N][0] : negative_from[N][1] + 1
    );

    //std::cout << "check1:" << positive_from[1][0] << " " << negative_from[N][1] + 1 << " " << ret << std::endl;

    for (int i = 2; i <= N; i++) {
        long long tmp_pos = A[i] > 0 ? positive_from[i][0] : positive_from[i][1] + 1;
        long long tmp_neg = A[i-1] < 0 ? negative_from[i-1][0] : negative_from[i-1][1] + 1;

        ret = std::min(ret, tmp_pos + tmp_neg);

        //std::cout << "check2:" << tmp_pos << " " << tmp_neg << " " << ret << std::endl;
    }
    std::cout << ret << std::endl;
    return 0;
}

