ll n, A[200010], L[200010], R[200010];

signed main() {
    scanf("%lld", &n);
    for(int i = 1; i <= n; i++) scanf("%lld", &A[i]);
    vector <PI> V(0);
    V.push_back(PI(1, 1000000000ll));
    ll ans = 0;
    for(int i = 2; i <= n; i++) {
        ll a = A[i - 1], b = A[i];
        if(a > b) {
            ll cnt = 0;
            while(b * 4 <= a) b *= 4, cnt++;
            V.push_back(PI(i, cnt));
        } else {
            while(a < b) {
                ans += (i - V.back().f);
                if(!--V.back().s) V.pop_back();
                a *= 4;
            }
        }
        L[i] = ans;
    }
    V.clear();
    V.push_back(PI(n, 1000000000ll));
    ans = 0;
    for(int i = n - 1; i >= 1; i--) {
        ll a = A[i + 1], b = A[i];
        if(a > b) {
            ll cnt = 0;
            while(b * 4 <= a) b *= 4, cnt++;
            V.push_back(PI(i, cnt));
        } else {
            while(a < b) {
                ans += (V.back().f - i);
                if(!--V.back().s) V.pop_back();
                a *= 4;
            }
        }
        R[i] = ans;
    }
    ll nwans = 1e18;
    for(int i = 1; i <= n + 1; i++) nwans = min(nwans, (L[i - 1] + R[i]) * 2 + (i - 1));
    printf("%lld\n", nwans);
    return 0;
}

