			while (S.back() && c[S.back()] < c[S.back() + 1]) {
				if (S[S.size()-2] + 1 != S.back()) c[S[S.size()-2] + 1] *= 4;
				c[S.back()] *= 4;
				pr[i] += S.back() - S[S.size()-2];
