pll mk(ll a, ll b){
  while(a>0 && a%4==0){
    b++;a/=4;
  }
  return pll(a,b);
}
bool lss(pll a, pll b){
  ll x = a.first, s = a.second;
  ll y = b.first, t = b.second;
  if(t-s>=16)return true;
  if(s-t>=16)return false;
  if(t-s>=0)return x <= (y<<(2*(t-s)));
  return (x<<(2*(s-t))) <= y;
}

int main(){
  scanf("%d",&n);
  REP(i,n)scanf("%d",a+i);
  // right
  {
    stack<int> cussion;
    rcnt[n-1] = 0;
    cussion.push(1);
    pll head = mk(a[n-1], 1);
    FORR(i,0,n-1){
      pll cur = mk(a[i], 1);
      ll need = 0;
      while(!lss(cur,head)){
        need++;
        head.second++;
      }
      ll space = 0;
      while(true){
        head.second--;
        if(!lss(cur,head))break;
        space++;
      }
      head = cur;
      rcnt[i] = rcnt[i+1];
      if(need>0){
        ll tmp = 0;
        while(true){
          tmp += cussion.top(); cussion.pop();
          if(cussion.size()==0){
            cussion.push(0);
            break;
          }
          ll sp = -cussion.top(); cussion.pop();
          ll sub = min(need, sp);
          sp -= sub; need -= sub;
          rcnt[i] += sub*tmp;
          if(sp>0){
            cussion.push(-sp);
            cussion.push(0);
            break;
          }
        }
        rcnt[i] += need*tmp;
        cussion.top() += tmp;
      }
      if(space > 0){
        cussion.push(-space);
        cussion.push(1);
      }else{
        cussion.top() += 1;
      }
    }
  }
  // left
  REP(i,n)a[i]*=2;
  reverse(a,a+n);
  {
