    lcnt[n-1] = 0;
    cussion.push(1);
    pll head = mk(a[n-1], 1);
    FORR(i,0,n-1){
      pll cur = mk(a[i], 1);
      ll need = 0;
      while(!lss(cur,head)){
        need++;
        head.second++;
      }
      ll space = 0;
      while(true){
        head.second--;
        if(!lss(cur,head))break;
        space++;
      }
      // DEBUG(cur.first);DEBUG(cur.second);
      // DEBUG(need);DEBUG(space);
      head = cur;
      lcnt[i] = lcnt[i+1];
      if(need>0){
        ll tmp = 0;
        while(true){
          tmp += cussion.top(); cussion.pop();
          if(cussion.size()==0){
            cussion.push(0);
            break;
          }
          ll sp = -cussion.top(); cussion.pop();
          ll sub = min(need, sp);
          sp -= sub; need -= sub;
          lcnt[i] += sub*tmp;
          if(sp>0){
            cussion.push(-sp);
            cussion.push(0);
            break;
          }
        }
        lcnt[i] += need*tmp;
        cussion.top() += tmp;
      }
      if(space > 0){
        cussion.push(-space);
        cussion.push(1);
      }else{
        cussion.top() += 1;
      }
