long long solve(unsigned long long * ms, int ms_len, int fast_calc = 0) {
	long long ans = 0;
	if (ms_len <= 0)
		return ans;

	unsigned long long last_dg_2 = 0;
	unsigned long long last_ms = ms[0];

	for (int i = 1; i < ms_len; i++)
		if (last_dg_2 <= 0) {
			if (ms[i] >= last_ms) {
				last_ms = ms[i];
				continue;
			}

			long long ad = 0;
			long long val_save = ms[i];

			while (ms[i] < last_ms) {
				ans += 2;
				ad += 2;
				ms[i] *= 4LL;
			}

			if (ms[i] > 1000000000LL) {
				last_dg_2 = ad;
				last_ms = val_save;
			}
			else {
				last_dg_2 = 0;
				last_ms = ms[i];
			}

			if (fast_calc)
				if (ans >= mn)
					return ans;
		}
		else {
			unsigned long long save_msi = ms[i];

			if (ms[i] >= last_ms) {
				unsigned long long x = last_ms;
				long long rem_2 = last_dg_2;
				while (ms[i] >= x && rem_2 > 0) {
					x *= 2;
					rem_2--;
				}
				if (ms[i] >= x) {
					last_dg_2 = 0;
					last_ms = ms[i];
					continue;
				}
			}

			// ms[i] < last_ms * 2^last_dg_2
			long long at_least = last_dg_2 - 36;
			at_least = max(at_least, 0LL);

			ans += at_least;
			long long new_dg_2 = at_least;

			long long rem_2 = last_dg_2 - at_least;   // <= 36

			unsigned long long x = last_ms;
			unsigned long long y = ms[i];

			if (y >= x) {
				long long ee = 0;
				while (y >= x) {
					ee++;
					x *= 2;
				}
				new_dg_2 += max(0LL, rem_2 - ee + 1);
				ans += max(0LL, rem_2 - ee + 1);
			}
			else {
				long long ee = 0;
				while (y < x) {
					ee++;
					y *= 2;
				}
				new_dg_2 += ee + rem_2;
				ans += ee + rem_2;
			}

			if (new_dg_2 & 1) {
				new_dg_2++;
				ans++;
			}

			last_dg_2 = new_dg_2;
			last_ms = save_msi;


			/*long double x = last_ms;
			while (rem_2 > 0) { x *= 2; rem_2--; }

			long double y = ms[i];
			while (y < x) {
				ans += 2;
				new_dg_2 += 2;
				y *= 4LL;
			}

			last_dg_2 = new_dg_2;
			last_ms = save_msi;*/

			if (fast_calc)
				if (ans >= mn)
					return ans;
		}

	return ans;
}

map<int, long long> solve_rev, solve_forw;

long long calc(int x, int fast_calc = 0) {
	if (x < 0) x = 0;
	if (x > n) x = n;

	// >= for indexes [0...x-1]   + rotate
	int ms_len = 0;
	for (int i = x - 1; i >= 0; i--)
		ms[ms_len++] = s[i];
	long long ans = 0;
	if (solve_rev.find(x) != solve_rev.end())
		ans = solve_rev[x];
	else {
		ans = solve(ms, ms_len, fast_calc);
		solve_rev[x] = ans;
	}
	ans += x; // rotate

	if (fast_calc)
		if (ans >= mn)
			return ans;

	// <= for indexes [x...n)
	ms_len = 0;
	for (int i = x; i < n; i++)
		ms[ms_len++] = s[i];
	if (solve_forw.find(x) != solve_forw.end())
		ans += solve_forw[x];
	else {
		solve_forw[x] = solve(ms, ms_len, fast_calc);
		ans += solve_forw[x];
	}

	return ans;
}

long long my_min(long long lst, long long new_val, int pp) {
	if (lst > new_val)
		min_pos = pp;
	return min(lst, new_val);
}

