        }
    }
    suf[0] = 1;
    for(int i = 1 ; i <= N ; ++i) pre[i] = i - 1,suf[i] = i + 1;
    pre[N + 1] = N;
    memset(val,0,sizeof(val));
    for(int i = 1 ; i < N ; ++i) {
        if(a[i] < a[i + 1]) {
            int64 t = a[i];
            while(t < a[i + 1]) {t *= 4;val[i] += 2;}
        }
        else {
            int64 t = a[i];
            while(t / 4 >= a[i + 1]) {t /= 4;val[i] -= 2;}
        }
    }
    for(int i = 2 ; i <= N ; ++i) {
        dp[1][i] = dp[1][i - 1];
        if(a[i] > a[i - 1]) {
            int t = val[i - 1],p = i - 1;
            while(1) {
                dp[1][i] += 1LL * t * (p - pre[p]);
                if(pre[p] + 1 != p) val[pre[p] + 1] += t;
                if(val[pre[p] + 1] + val[pre[p]] <= 0) break;
                if(pre[p] == 0) break;
                t = val[pre[p] + 1] + val[pre[p]];
                p = pre[p];val[p] = t;
                pre[suf[p]] = pre[p];suf[pre[p]] = suf[p];
            }
            pre[suf[i - 1]] = pre[i - 1];
            suf[pre[i - 1]] = suf[i - 1];
        }
    }
    int64 ans = dp[0][1];
    for(int i = 1 ; i <= N ; ++i) {
        ans = min(dp[1][i] + i + dp[0][i + 1],ans);
    }
    out(ans);enter;
}
