long long cost_front[300000] = {};
long long cost_back[300000] = {};
int main() {
	int n;
	cin >> n;
	vector<long double> a;
	REP(i, n) {
		long double tmp;
		cin >> tmp;
		a.push_back(log2(tmp));
	}
	vector<long double> b;
	REP(i, n) {
		b.push_back(a[i]+(long double)2.0);
	}
	long long now_itr = 0;
	cost_front[0] = 1;
	for (int i = 1; i < n; ++i) {
		cost_front[i] = cost_front[i - 1] + 1;
		while (b[i] > b[i - 1]) {
			for (int q = i - 1; q >= 0; --q) {
				cost_front[i] += 2;
				b[q] += (long double)2.000000000;
				if (q == 0 || b[q] <= b[q - 1]) {
					break;
				}
				if (b[q] > b[q - 1]) {
					if (now_itr == q) {
						cost_front[i] += 2 * now_itr;
						break;
					}
					else {
						if (now_itr == q - 1) {
							now_itr++;
							cost_front[i] += 2 * now_itr;
							break;
						}
					}
				}
			}
		}
	}
	now_itr = n - 1;
	for (int i = n - 2; i >= 0; --i) {
		cost_back[i] = cost_back[i + 1];
		while (a[i] > a[i + 1]) {
			for (int q = i + 1; q < n;++q) {
				cost_back[i] += 2;
				a[q] += (long double)2.000000000;
				if (q == n-1 || a[q] <= a[q + 1]) {
					break;
				}
				if (a[q] > a[q + 1]) {
					if (now_itr == q) {
						cost_back[i] += 2 * (n - 1 - now_itr);
						break;
					}
					else {
						if (now_itr == q + 1) {
							now_itr--;
							cost_back[i] += 2 * (n - 1 - now_itr);
							break;
						}
					}
				}
			}
		}
	}
	long long ans = cost_back[0];
	for (int i = 1; i <= n; ++i) {
		ans = min(ans, cost_back[i] + cost_front[i - 1]);
	}
	cout << ans << endl;
	return 0;
}

