    for (int i = 2; i <= n; ++i)
    {
        for (int j = 0; j < 64; ++j)
        {
            dp[i][j] = INF;
            for (int x = 0; x < 64; ++x)
            {
                if (a[i - 1] * mult[x] <= a[i] * mult[j])
                {
                    dp[i][j] = min(dp[i][j], dp[i - 1][x] + j);
                }
            }
        }
    }
    ll ans = INF;
    for (int j = 0; j < 64; ++j)
    {
        ans = min(ans, dp[n][j]);
    }
    cout << ans << endl;
