  scanf("%d", &n);

  for(int i=0;i<n;i++){
    scanf("%lld", a+i);
  }

  ll calc1 = 0, calc2 = 0;

  stack<pair<ll,int> > st, st2;
  st.push({LLINF, 0});
  st2.push({LLINF, n-1});

  dp1[0] = 1;
  ll prev = a[0];
  for(int i=1;i<n;i++){
    ll now = a[i];

    if(prev < now){
      ll r = log4(now, prev) * 2;
      prev *= pow2(r);
      while(r){
        auto p = st.top(); st.pop();
        ll r2 = min(p.first, r);
        r -= r2;
        p.first -= r2;
        calc1 += (ll)r2 * p.second;
        if(p.first > 0) st.push(p);
      }
    }

    ll e = log4(prev, now, false) * 2;

    if(e){
      st.push({e, i});
    }

    dp1[i] = calc1 + i + 1;
    debug(dp1[i]);
    prev = now;
  }


  dp2[n] = dp2[n-1] = 0;
  prev = a[n-1];
