struct RMaxQ {
    static const int N2 = 524288;
    int dat[N2];

    void init() {
        rep(i, N2) {
            dat[i] = 0;
        }
    }

    void updatem(int k) {
        k += N2 - 1;
        dat[k] -= 1;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = max(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    void update(int k, int a) {
        k += N2 - 1;
        dat[k] = a;
        while (k > 0) {
            k = (k - 1) / 2;
            dat[k] = max(dat[2 * k + 1], dat[2 * k + 2]);
        }
    }

    int query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l)return -INF;
        if (a <= l && r <= b)return dat[k];
        else {
            int m = (l + r) / 2;
            int vl = query(a, b, k * 2 + 1, l, m);
            int vr = query(a, b, k * 2 + 2, m, r);
            return max(vl, vr);
        }
    }

};

RMaxQ rMaxQ1;
RMaxQ rMaxQ2;

void preCalc() {
    rMaxQ1.init();
    rMaxQ2.init();
    int prev = INF;
    for (int i = 1; i <= N; ++i) {
