            prev *= 4;
            int R = i;//固定
            int can = 1;//動かす
            int cant = i + 1;
            while (cant - can > 1) {
                int m = (can + cant) / 2;
                if (rMaxQ1.query(m, R, 0, 0, rMaxQ1.N2) >= 1) {
                    can = m;
                } else {
                    cant = m;
                }
            }
            cnt += 2 * (i - can);
            rMaxQ1.updatem(can);
        }
        int aaa = 0;
        while (prev >= 4 * a) {
            aaa++;
            prev /= 4;
        }
        rMaxQ1.update(i, aaa);
        if (i == 1) {
            rMaxQ1.update(i, 1000000);
        }
        prev = a;
        X[i] = cnt + X[i - 1];
    }

    prev = INF;
    for (int i = N - 1; i >= 0; --i) {
        int cnt = 0;
        int a = A[i];
