int log2(ll p, ll q, bool f = true){
  int counter = 0;
  int cc = !!(p % q) * 2;
  ll v = p / q;
  while(v >= 2){
    if(v % 2) cc++;
    v /= 2;
    counter++;
  }
  debug(p); debug(q); debug(cc);
  return counter + (cc >= 1) * f;
}

int log2(ll v){
  int counter = 0;
  int cc = 0;
  while(v){
    if(v % 2) cc++;
    v /= 2;
    counter++;
  }
  return counter + (cc > 1);
}

ll pow2(int x) {
  ll res = 1;
  for(int i=0;i<x;i++) res *= 2;
  return res;
}

int main(){
