  scanf("%d", &n);

  for(int i=0;i<n;i++){
    scanf("%lld", a+i);
  }

  ll calc1 = 0, calc2 = 0;

  stack<pair<ll,int> > st, st2;
  st.push({LLINF, 0});
  st2.push({LLINF, n-1});

  dp1[0] = 1;
  ll prev = a[0] * 2;
  for(int i=1;i<n;i++){
    ll now = a[i] * 2;

    if(prev < now){
      ll r = (log2(now, prev) + 1) / 2 * 2;
      debug(log2(now, prev));
      prev *= pow2(r);
      while(r){
        auto p = st.top(); st.pop();
        ll r2 = min(p.first, r);
        r -= r2;
        p.first -= r2;
        calc1 += (ll)r2 * (i - p.second);
        if(p.first > 0) st.push(p);
      }
    }

    ll e = log2(prev, now, false) / 2 * 2;

    if(e){
      st.push({e, i});
    }

    dp1[i] = calc1 + i + 1;
    debug(dp1[i]);
    prev = now;
  }


  dp2[n] = dp2[n-1] = 0;
  prev = a[n-1];
  for(int i=n-2;i>=0;i--){
    ll now = a[i];

    if(prev < now){
      ll r = (log2(now, prev) + 1) / 2 * 2;
      debug(log2(now, prev));
      prev *= pow2(r);
      while(r){
        auto p = st2.top(); st2.pop();
        ll r2 = min(p.first, r);
        r -= r2;
        p.first -= r2;
        calc2 += (ll)r2 * (p.second - i);
        if(p.first > 0) st2.push(p);
      }
    }

    ll e = log2(prev, now, false) / 2 * 2;

    if(e){
      st2.push({e, i});
    }

    dp2[i] = calc2;
    prev = now;
  }


  ll ans = dp2[0];

