bool g(ll a,ll b,ll c,ll d){
	if(b == d)return a > c;
	if(b < d){
		while(b < d && a > c){
			c *= 4;
			d --;
		}
		return a > c;
	}
	else {
		while(b > d && a < c){
			a *= 4;
			b --;
		}
		return a > c;
	}
}

ll A[200010];
vector<P2> vec;
ll f(ll loc,ll x){
	ll ret = 0;
	P2 p = mp2(1,loc,loc,0,0);
	while(vec.size() > 0){
		P2 q = vec[vec.size()-1];
		vec.pop_back();
		if(g(A[p.sc.fr.sc],p.sc.sc.sc,A[q.sc.fr.fr],q.sc.sc.fr)){
			while(g(A[p.sc.fr.sc],p.sc.sc.sc,A[q.sc.fr.fr],q.sc.sc.fr)){
				q.sc.sc.fr ++;
				q.sc.sc.sc ++;
				ret += q.fr;
			}
			p.fr += q.fr;
			p.sc.fr.sc = q.sc.fr.sc;
			p.sc.sc.sc = q.sc.sc.sc;
		}
		else {
			vec.push_back(q);
			break;
		}
	}
	vec.push_back(p);
	return ret;
}

