//-------------------------------------------------------
long A[200000]; 
long Left[200001];
long Right[200001];
int R[200001];
int restL[200000];
int restR[200000];
void Calc(){
	int N = rei();
	for(int i=0;i<N;i++){
		A[i] = rel();
	}
	restL[0] = 100000000;
	stack<int> sp;
	sp.push(0);
	for(int i=1;i<N;i++){
		Left[i] = Left[i-1];
		if(A[i] > A[i-1]){
			long x = A[i-1];
			int c = 0;
			while(A[i] > x){
				c++;
				x *= 4;
			}
			while(c--){
				while(restL[sp.top()] == 0){
					sp.pop();
				}
				int p = sp.top();
				Left[i] += i-sp.top();
				restL[sp.top()]--;
			}
		}
		else{
			long x = A[i];
			int c = 0;
			while(x*4 <= A[i-1]){
				c++;
				x *= 4;
			}
			restL[i] = c;
			sp.push(i);
		}
	}
	restR[N-1] = 100000000;
	while(!sp.empty()){
		sp.pop();
	}
	sp.push(N-1);
	for(int i=N-2;i>=0;i--){
		Right[i] = Right[i+1];
		if(A[i] > A[i+1]){
			long x = A[i+1];
			int c = 0;
			while(A[i] > x){
				c++;
				x *= 4;
			}
			Right[i] = Right[i+1];
			while(c--){
				while(restR[sp.top()] == 0){
					sp.pop();
				}
				int p = sp.top();
				Right[i] += sp.top()-i;
				restR[sp.top()]--;
			}
		}
		else{
			long x = A[i];
			int c = 0;
			while(x*4 <= A[i+1]){
				c++;
				x *= 4;
			}
			restR[i] = c;
			sp.push(i);
		}
	}
	long ans = min(Left[N-1]*2+N,Right[0]*2);
	for(int i=1;i<N;i++){
		ans = min(Left[i-1]*2+i+Right[i]*2,ans);
	}
	cout << ans << endl;
}
int main(int argc,char** argv){
	ios::sync_with_stdio(false), cin.tie(0);
	cout.tie(0); Calc(); return 0;
}

