int main() {
	ll N;
	cin >> N;
	vector<ll> a(N);
	for (int i = 0; i < N; ++i) { cin >> a[i]; }


	vector<ll> cnt_p(N, 0);
	vector<ll> d_p(N, 0);
	d_p[N - 1] = a[N - 1];
	for (int i = N - 2; i >= 0; --i) {
		ll cnt = 0;
		ll x = a[i + 1];
		while (a[i] > x) {
			x *= 4;
			cnt += 2;
		}
		ll add = cnt;
		if ((x > d_p[i + 2]) && (i + 2 < N)) {
			add = cnt * (N - i - 1);
		}
		cnt_p[i] = cnt_p[i + 1] + add;
		d_p[i + 1] = x;
	}

	vector<ll> cnt_n(N, 0);
	cnt_n[0] = 1;
	vector<ll> d_n(N, 0);
	d_n[0] = -2 * a[0];
	for (int i = 1; i < N; ++i) {
		ll cnt = 0;
		ll x = a[i - 1] * (-2);
		while (x > (-2 * a[i])) {
			x *= 4;
			cnt += 2;
		}
		ll add = cnt + 1;
		if ((x < d_n[i - 2]) && (i - 2 >= 0)) {
			add = cnt * i + 1;
		}
		cnt_n[i] = cnt_n[i - 1] + add;
		d_p[i - 1] = x;
	}

	ll res = min(cnt_p[0], cnt_n[N - 1]);
	for (int i = 0; i < N - 1; ++i) {
		ll tmp = cnt_n[i] + cnt_p[i + 1];
		res = min(res, tmp);
	}

	cout << res << endl;

	return 0;
}

