template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }
int main() {
  i64 N;
  cin >> N;
  vector<i64> A(N);
  rep(i,0,N) {
    cin >> A[i];
  }
  auto func = [](i64 N, const vector<i64>& A, i64 mns) {
    const int H = 16;
    auto dp = ndvec(N + 1, H, i64(1LL << 60));
    rep(i,0,H) {
      dp[N][i] = 0;
      dp[N - 1][i] = 2 * i + mns;
    }
    for(int i = N - 1; i --> 0;) {
      i64 alpha = A[i];
      for(int j = 0; j < H; j++) {
        i64 beta = A[i + 1];
        i64 cnt = 0;
        while(alpha > beta) {
          beta *= 4;
          cnt++;
        }
        i64 bck = 0;
        if(cnt >= H) {
          bck = (cnt - H + 1) * 2 * i;
          cnt = H - 1;
        }
        chmin(dp[i][j], dp[i + 1][cnt] + 2 * j + bck + mns);
        alpha *= 4;
      }
    }
    return dp;
  };
  auto rdp = func(N, A, 0);
  reverse(all(A));
  auto ldp = func(N, A, 1);
  i64 ans = i64(1LL << 60);
  for(int i = 0;i <= N;i++) {
    chmin(ans, rdp[i][0] + ldp[N - i][0]);
  }
  cout << ans << endl;
}

