  cin.tie(nullptr);
  ll n;
  cin>>n;
  vector<tuple<int,int>> vt;
  REP(i,n) {
    int a;
    cin>>a;
    int sft = 0;
    while (a < (1 << 29)) {
      a <<= 1;
      --sft;
    }
    vt.emplace_back(sft, a);
  }
  vecll neg(n+1), pos(n+1);
  ll sum = 1;
  stack<int> pending;
  REP(i,n*30) pending.push(-1);
  REP(i,n-1) {
    neg[i+1] = sum;
    int li,lx,ri,rx;
    tie(li,lx) = vt[i];
    tie(ri,rx) = vt[i+1];
    int sft2 = 0;
    while (tie(li,lx) < tie(ri,rx)) {
      li += 2;
      ++sft2;
    }
    while (sft2) {
      sum += 2 * (i - pending.top());
      pending.pop();
      --sft2;
    }
    while (make_pair(li,lx) >= make_pair(ri+2,rx)) {
      ri += 2;
      pending.push(i);
    }
    ++sum;
  }
  neg[n] = sum;
  sum = 0;
  while (!pending.empty()) pending.pop();
  REP(i,n*30) pending.push(n);
  pos[n-1] = sum;
  for (int i = n-1; i > 0; --i) {
    int li,lx,ri,rx;
    tie(li,lx) = vt[i-1];
    tie(ri,rx) = vt[i];
    int sft2 = 0;
    while (tie(li,lx) > tie(ri,rx)) {
      ri += 2;
      ++sft2;
    }
    while (sft2) {
      sum += 2 * (pending.top() - i);
      pending.pop();
      --sft2;
    }
    while (make_pair(li+2,lx) <= make_pair(ri,rx)) {
      li += 2;
      pending.push(i+1);
    }
    pos[i-1] = sum;
  }
  ll ans = 2*n*n;
  REP(i,n+1) {
    ans = min(ans, neg[i] + pos[i]);
  }
  cout<<ans<<"\n";
  return 0;
}

