long long solveDP1(const vector<long long> &A, vector<long long>& DP1, int i, int shift) {
  int N = A.size();
  if (i >= N)
    return 0;
  if (i == N - 1)
    return shift;
  if (shift >= 40) {
    return solveDP1(A, DP1, i, shift - 2) + (N - i) * 2;
  }
  auto& ret = DP1[i * 40 + shift];
  if (ret >= 0)
    return ret;

  ret = LONG_LONG_MAX;
  long long q0 = A[i];
  long long q = A[i + 1];
  int t = 0;
  while (!(q0 <= q)) {
    q *= 4;
    t += 2;
  }
  while (q0 * 4 <= q) {
    q0 *= 4;
    t -= 2;
  }
  ret = solveDP1(A, DP1, i + 1, max(shift + t, 0)) + shift;
  return ret;
}

long long solve1(const vector<long long> &A) {
  int N = A.size();
  vector<long long> DP1(N * 40, -1);
  vector<long long> revA = A;
  vector<long long> revDP1(N * 40, -1);
  std::reverse(revA.begin(), revA.end());

  long long ans0 = LONG_LONG_MAX;
  for (int i = 0; i <= N; ++i) {
    long long ans = solveDP1(A, DP1, i, 0) + solveDP1(revA, revDP1, N - i, 0) + i;
    ans0 = min(ans, ans0);
  }
  return ans0;
}

