            else{
                pii ts=stk.top(); stk.pop();
                f[i]+=(ts.first-i)*2;
                if (--ts.second) stk.push(ts);
            }
        }
        ll cnt=0;
        while (now*4<=tmp) now*=4,cnt++;
        if (cnt) stk.push({i,cnt});
    }
    while (!stk.empty()) stk.pop();
    for (int i=2; i<=n; i++){
        g[i]=g[i-1];
