            for (auto it = s.lower_bound(i + 1); it != s.end(); ++it){
                int idx = *it;
                assert(idx > i);
                ans[0][i] += now * ll(idx - pre);
                now = upd(idx, now);
                pre = idx;
                if (now == -1) break;
                buff.pb(idx);
            }
            if (now != -1) ans[0][i] += ll(n - pre + 1) * now;
            for (int it : buff) s.erase(it);
        }
        ans[0][i] = ans[0][i] * 2 + ans[0][i + 1];
    }
    s.clear();
    reset(to, 0);
    FOR(i, 1, n - 1) if (a[i] >= 4 * a[i + 1]) {
            s.insert(-i);
            ll tmp = a[i + 1];
            while (a[i] >= tmp * 4) to[i]++, tmp *= 4;
        }
    ans[1][1] = 1;
    FOR(i, 2, n) {
        if (a[i] > a[i - 1]) {
            int now = 0;
            ll tmp = a[i - 1];
            while (tmp < a[i]) tmp *= 4, now++;
            vector<int> buff;
            int pre = i - 1;
            for (auto it = s.lower_bound(-pre); it != s.end(); ++it){
                int idx = -(*it);
                assert(idx < i);
                ans[1][i] += now * ll(pre - idx);
                now = upd(idx, now);
                pre = idx;
                if (now == -1) break;
                buff.pb(idx);
            }
            if (now != -1) ans[1][i] += ll(pre) * now;
            for (int it : buff) s.erase(-it);
        }
        ans[1][i] = ans[1][i] * 2 + ans[1][i - 1] + 1;
    }
    ll res = 1e18;
    FOR(i, 1, n + 1) res = min(res, ans[0][i] + ans[1][i - 1]);
    cout << res;
}

