int e[MAXN];
ld x[MAXN];

int F[MAXN];
int delta[MAXN];

int father(int x)
{
	return F[x] == x ? x : F[x] = father(F[x]);
}

int merge(int x, int y)
{
	F[father(x)] = father(y);
}

void solve(int *a, int b, ll *F)
{
	for (int i = 1; i <= n; ++ i)
	{
		e[i] = 0;
		x[i] = a[i];
		while (x[i] >= 1)
		{
			x[i] /= 4;
			e[i] ++;
		}
	}

	for (int i = 1; i <= n; ++ i)
		::F[i] = i;

	F[n] = 0;
	for (int i = n-1; i >= 1; -- i)
	{
		if (a[i] <= a[i+1])
		{
			F[i] = F[i+1];
			ll t = a[i];
			int c = 0;
			while (t <= a[i+1])
			{
				c ++;
				t *= b;
			}
			delta[i] = c-1;
			if (delta[i] == 0)
				merge(i, i+1);
			continue;
		}
		F[i] = F[i+1];
		ll t = a[i+1];
		int c = 0;
		while (a[i] > t)
		{
			c ++;
			t *= b;
		}
		int j = i+1;
		while (c)
		{
			j = father(j);
			if (j == n)
			{
				F[i] += (ll)c*(n-i);
				break;
			}
			int gap = min(delta[j], c);
			F[i] += (ll)gap*(j-i);
			c -= gap;
			delta[j] -= gap;
			if (delta[j] == 0)
				merge(j, j+1);
			j ++;
		}
		merge(i, i+1);
	}
}

