void func( int n , i64 *a , i64 *dp )
{
    dp[n] = 0 ;
    stack<int> st ;
    for(int i=1 ; i<=n ; i++) b[i] = a[i] ;
    for(int i=n-1 ; i>=1 ; i--)
    {
        dp[i] = dp[i+1] ;
        if( b[i] <= b[i+1] )
        {
            if( b[i]*4LL <= b[i+1] ) st.push(i) ;
            continue ;
        }
        int c = howMuch(b[i],b[i+1]) ;
        for(int j=i+1; j<=n ; j++)
        {
            dp[i] += c ; b[j] *= p[c] ;
            if( st.empty() )
            {
                dp[i] += (n-j)*c ;
                break ;
            }
            if( st.top() == j )
            {
                c = howMuch(b[j],b[j+1]) ;
                if( c==0 )
                {
                    break ;
                }
                else st.pop() ;
            }
        }
    }
    for(int i=1 ; i<=n ; i++) b[i] = a[i] ;
    i64 lastCnt = 0LL , ans = 0LL ;
    for(int i=2 ; i<=n ; i++)
    {
        if( b[i-1] <= b[i] )
        {
            while( lastCnt !=0 && b[i-1] <= b[i] )
            {
                lastCnt-- ;
                b[i-1] *= 4LL ;
            }
        }
        lastCnt += howMuch( b[i-1],b[i] ) ;
        ans += lastCnt ;
    }
  //  printf("%lld\n",ans*2) ;
    if( ans != dp[1] )
    {
      //  DBG ;
