long long dp_left[MAX_N], dp_right[MAX_N];
int n;
vector<long long> a, b;

long long cnt_log(long long temp) {
  int res = 0;
  while (temp >= 4) {
    res += 2; temp >>= 2;
  }
  return res;
}

void solve() {
  cin >> n; b.assign(n + 2, 0);
  rep(i, 1, n + 1) cin >> b[i];

  vector<pair<long long, int>> stack_;
  long long sum = 0;
  a = b;
  for (int i = n; i > 0; --i) {
    if (i < n) {
      if (a[i] > a[i + 1]) {
        long long height = 0;
        while (a[i + 1] < a[i]) {
          a[i + 1] *= 4;
          height += 2;
        }
        sum += height;
        int cnt = 1;
        while (!stack_.empty() && stack_.back().first <= height) {
          height -= stack_.back().first;
          sum += height * stack_.back().second;
          cnt += stack_.back().second;
          stack_.pop_back();
        }
        if (!stack_.empty()) stack_.back().first -= height;
        stack_.push_back({ 0, cnt });
      } else {
        stack_.push_back({ cnt_log(a[i + 1] / a[i]), 1 });
      }
    }
    dp_right[i] = sum;
  }


  stack_.clear();
  sum = 0;
  a = b;
  for (int i = 1; i <= n; ++i) {
    a[i] *= 2;
    if (i > 1) {
      if (a[i] > a[i - 1]) {
        long long height = 0;
        while (a[i - 1] < a[i]) {
          a[i - 1] *= 4;
          height += 2;
        }
        sum += height;
        int cnt = 1;
        while (!stack_.empty() && stack_.back().first <= height) {
          height -= stack_.back().first;
          sum += height * stack_.back().second;
          cnt += stack_.back().second;
          stack_.pop_back();
        }
        if (!stack_.empty()) stack_.back().first -= height;
        stack_.push_back({ 0, cnt });
      } else {
        stack_.push_back({ cnt_log(a[i - 1] / a[i]), 1 });
      }
    }
    dp_left[i] = sum + i;
  }


//  for (int i = 1; i <= n; ++i) debug_two(i, dp_right[i]); cout << '\n';
//  for (int i = 1; i <= n; ++i) debug_two(i, dp_left[i]);

  long long res = ll_inf;
  for (int i = 0; i <= n; ++i) {
    update_min(res, dp_left[i] + dp_right[i + 1]);
  }
  cout << res << '\n';
}

