        }
      } else {
        if (as[i] >= (as[i + 1] << (-j))) {
          rs[i] = j;
          break;
        }
      }
    }
  }
  // for (int i = 0; i < N; i++) {
  //   printf("%ld ", ls[i]);
  // }
  // printf("\n");
  // for (int i = 0; i < N; i++) {
  //   printf("%ld ", rs[i]);
  // }
  // printf("\n");
  // calculate ps
  long pminus = 0;
  ps[N - 1] = 0;
  for (long i = N - 2; i >= 0; i--) {
    const long l = ls[i + 1];
    if (l >= 0) {
      ps[i] = ps[i + 1] + max((N - 1 - i) * l + pminus, 0L);
    } else {
      ps[i] = ps[i + 1];
      pminus += l;
    }
  }
  // calculate ns
  long nminus = 0;
  ns[0] = 0;
  ns[1] = 1;
  for (long i = 2; i < N; i++) {
    const long r = rs[i - 2];
    if (r >= 0) {
      ns[i] = ns[i - 1] + 1 + max((i - 2) * r + nminus, 0L);
    } else {
      ns[i] = ns[i - 1] + 1;
      nminus += r;
    }
  }  
  // for (int i = 0; i < N; i++) {
  //   printf("%ld ", ps[i]);
  // }
  // printf("\n");
  // for (int i = 0; i < N; i++) {
  //   printf("%ld ", ns[i]);
  // }
  // printf("\n");

  // solve
  long ans = INF;
  for (int i = 0; i < N; i++) {
    const long num = ps[i] + ns[i];
    if (num < ans) {
      ans = num;
    }
  }
  printf("%ld\n", ans);

  return 0;
}

