    inc_cnt = inc_cnt * 2;
    if (v.at(i) > new_val) {
      new_val = 4 * new_val;
      inc_cnt += 2;
    }

    long long dec_cnt = (i - negative_last) * (i - negative_last);
    if (0 <= negative_last) {
      dec_cnt += 2 * (negative_last + 1);
    }

    if (dec_cnt <= inc_cnt) {
      negative_last = i;
      total_cnt += dec_cnt;
    } else {
      v.at(i+1) = new_val;
      total_cnt += inc_cnt;
    }
  }
  std::cout << total_cnt << std::endl;
  return 0;
