                    can = m;
                } else {
                    cant = m;
                }
            }
            cnt += 2 * (i - can);
            rMaxQ1.updatem(can);
        }
        int aaa = 0;
        while (prev >= 4 * a) {
            aaa++;
            prev /= 4;
        }
        rMaxQ1.update(i, aaa);
        if (i == 1) {
            rMaxQ1.update(i, 1000000);
