            if (pow4[x] * A[l] <= A[l+1]) dp1[l][x] = dp1[l+1][0] + x;
            else {
                LL k = ceil((log(pow4[x])+log(A[l])-log(A[l+1]))/log(4));
                if (k >= 15) dp1[l][x] = dp1[l+1][15] + x + (N-l-1) * (k-15);
                else dp1[l][x] = dp1[l+1][k] + x;
