void solve() {
	ll N;
	cin>>N;
	vector<ll> a(N);
	rep(i,N)cin>>a[i];

	auto makedp = [](vector<ll> &a, vector<vector<ll>> &dp){
		ll N=a.size();
		ll size=31;
		//dp[i][j] a[i]に4をj回かけたときa[i]-a[N-1]が単調増加するための4をかける回数
		dp.assign(N,vector<ll>(size,0));
		for(ll j=0;j<size;j+=2){
			dp[N-1][j]=j;
		}
		rrep(i,N-1){
			bll y=a[i];
			for(ll j=0;j<size;j+=2){
				if(j>0)y*=4;
				bll z=a[i+1];
				ll t=0;
				while(y>z)t+=2,z*=4;
				ll x=0,dif=0;
				if(t>0){
					x=t;
					if(size<=x){
						dif=(x-(size-1))*(N-i-1);
						x=size-1;
					}
				}
				dp[i][j]=dp[i+1][x]+j+dif;
			}
		}
		return dp;
	};
	vector<vector<ll>> dp,revdp;
	makedp(a,dp);
	rep(i,N)a[i]*=2;
	reverse(all(a));
	makedp(a,revdp);

