const int N = 2e5 + 10;
int a[N], need[N];
LL sum[N][2];
int main() {
	int n;
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) scanf("%d", a + i);
	for (int i = 2; i <= n; i++) {
		LL t1 = a[i - 1], t2 = a[i];
		if (t1 < t2) swap(t1, t2);
		while (t1 > t2) {
			t2 *= 4;
			need[i]++;
		}
	}
	vector<PII> v;
	//for (int i = 1; i <= n; i++) cout << need[i] << endl;
	v.emplace_back(n + 1, 0);
	for (int i = n - 1; i >= 1; i--) {
		sum[i][1] = sum[i + 1][1];
		if (a[i] > a[i + 1]) {
			int tmp = need[i + 1];
			int pos = i + 1;
			while (v.back().second <= tmp) {
				sum[i][1] += 1LL * (v.back().first - pos) * tmp;
				pos = v.back().first;
				if (pos == n + 1) break;
				tmp -= v.back().second;
				v.pop_back();
			}
			v.back().second -= tmp;
		} else {
			v.emplace_back(i + 1, need[i + 1]);
		}
		//cout << i << ' ' << sum[i][1] << endl;
	}
	for (int i = 1; i <= n; i++) a[i] *= 2;
	v.clear();
	v.emplace_back(0, 0);
	for (int i = 2; i <= n; i++) {
		sum[i][0] = sum[i - 1][0];
		if (a[i] > a[i - 1]) {
			int tmp = need[i];
			int pos = i - 1;
			while (v.back().second <= tmp) {
				sum[i][0] += 1LL * (pos - v.back().first) * tmp;
				pos = v.back().first;
				if (pos == 0) break;
				tmp -= v.back().second;
				v.pop_back();
			}
			v.back().second -= tmp;
		} else {
			v.emplace_back(i - 1, need[i]);
		}
	}
	LL ans = 1e18;
	for (int i = 0; i <= n; i++) {
		ans = min(ans, sum[i][0] * 2 + i + sum[i + 1][1] * 2);
		//cout << i << ' ' << ans << endl;
	}
	printf("%lld\n", ans);
	return 0;
}

