   }
   rep(i,1,n){
      ll s=1;
      rep(j,0,mx+1){
         int lg=0; ll t=1;
         while(a[i]*s>a[i-1]*t)t*=4,lg++;
         if(lg<=mx)neg[i][j]=neg[i-1][lg]+j;
         else neg[i][j]=neg[i-1][mx]+j+i*(lg-mx);
         s*=4;
      }
   }
