template<typename T>
struct Segtree {
    int64_t n;
    T e;
    vector<T> dat;
    typedef function<T(T a, T b)> Func;
    Func f;

    Segtree(){}
    Segtree(int64_t n_input, Func f_input, T e_input){
        initialize(n_input, f_input, e_input);
    }
    void initialize(int64_t n_input, Func f_input, T e_input){
        f = f_input;
        e = e_input;
        n = 1;
        while(n < n_input) n <<= 1;
        dat.resize(2*n-1, e);
    }

    void update(int64_t k, T a){
        k += n - 1;
        dat[k] = a;
        while(k > 0){
            k = (k - 1)/2;
            dat[k] = f(dat[2*k+1], dat[2*k+2]);
        }
    }

    T get(int64_t k){
        return dat[k+n-1];
    }

    T between(int64_t a, int64_t b){
        return query(a, b+1, 0, 0, n);
    }

    T query(int64_t a, int64_t b, int64_t k, int64_t l, int64_t r){
        if(r<=a || b<=l) return e;
        if(a<=l && r<=b) return dat[k];
        T vl = query(a, b, 2*k+1, l, (l+r)/2);
        T vr = query(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }

    int64_t bisect(int64_t i, int64_t n){
        int64_t ng = i, ok = n+1;
        while(ok-ng>1){
            int64_t mid = (ng+ok) / 2;
            (get(i) <= between(i+1, mid) ? ok : ng) = mid;
        }
        return ok;
    }
};


const int64_t M = 200010; 
int64_t ans[M];
int64_t height[M], heightsum[M];
int64_t shifted[M];

// shifted[i-1] > shifted[i]
int64_t need[M], needsum[M];
int64_t needsum_sum[M];

int64_t dp[M];

int main(){
    int64_t N;
    int64_t A[M];
    cin >> N;
    for(int64_t i=1; i<=N; i++){
        cin >> A[i];
        while(A[i] >> height[i]) height[i] += 2;
        shifted[i] = A[i]<<(32-height[i]);
    }

    Segtree<int> st(N+1, [](int64_t a, int64_t b){return min(a, b);}, 1e9);

    // REGULAR

    for(int64_t i=1; i<=N; i++){
        need[i] = (i>0 && shifted[i-1] > shifted[i]) * 2;
        needsum[i] = needsum[i-1] + need[i];
        needsum_sum[i] = needsum_sum[i-1] + needsum[i];
        st.update(i, height[i] - needsum[i]);

        heightsum[i] = heightsum[i-1] + height[i];
    }

    fill(dp, dp+N+2, 0);
    for(int64_t i=N-1; i>=1; i--){
        int64_t r = st.bisect(i, N);
        dp[i] = dp[r];
        int64_t diff = needsum_sum[r-1] - needsum_sum[i] - (int64_t) (needsum[i]) * (r-1 - i);
        diff += height[i] * (r-1 - i);
        diff -= heightsum[r-1] - heightsum[i];
        dp[i] += diff;
        ans[i-1] += dp[i];
    }

    // REVERSE

    reverse(height+1, height+N+1);
    reverse(shifted+1, shifted+N+1);

    for(int64_t i=1; i<=N; i++){
        need[i] = (i>0 && shifted[i-1] > shifted[i]);
        needsum[i] = needsum[i-1] + need[i];
        needsum_sum[i] = needsum_sum[i-1] + needsum[i];
        st.update(i, height[i] - needsum[i]);

        heightsum[i] = heightsum[i-1] + height[i];
    }

    fill(dp, dp+N+2, 0);
    for(int64_t i=N-1; i>=1; i--){
        int64_t r = st.bisect(i, N);
        dp[i] = dp[r];
        int64_t diff = needsum_sum[r-1] - needsum[i] - (int64_t) (needsum[i]) * (r-1 - i);
        diff += height[i] * (r-1 - i);
        diff -= heightsum[r-1] - heightsum[i];
        dp[i] += diff;
        ans[N-i+1] += dp[i];
    }

    for(int64_t i=1; i<=N; i++){
        ans[i] += i;
        cerr << i << " " << ans[i] << endl;
    }

    int64_t result = *min_element(ans, ans+N+1);
    cout << result << endl;
    return 0;
}

