	for(; !isdigit(ch); ch = getchar()) if(ch == '-') ops = 0;
	for(; isdigit(ch); ch = getchar()) res = res * 10 + ch - '0';
	return ops ? res : -res;
}

inline int gt(int x, int y) {
	ll tx = 1ll * x, ty = 1ll * y;
	int cnt = 0;
	for(; tx < ty; cnt++, tx *= 4);
	return cnt * 2;
}

