int N, a[200005], tops = 0;
ll f[200005], g[200005], ans = infll;
struct Node {int u, d;} stk[200005];

int main(){
	getint(N);
	for(register int i = 1; i <= N; i++) getint(a[i]);
	for(register int i = 2; i <= N; i++){
		f[i] = f[i - 1]; ll pre = a[i - 1], cur = a[i];
		while(pre < cur){
			pre <<= 2;
			if(!tops) f[i] += i - 1 << 1;
			else{
				Node p = stk[tops--];
				f[i] += i - p.u << 1;
				if(--p.d) stk[++tops] = p;
			}
		}
		int d = 0;
		while((cur << 2) <= pre) cur <<= 2, ++d;
		if(d) stk[++tops] = (Node){i, d};
	}
	tops = 0;
	for(register int i = N - 1; i >= 1; i--){
		g[i] = g[i + 1]; ll pre = a[i + 1], cur = a[i];
		while(pre < cur){
			pre <<= 2;
			if(!tops) g[i] += N - i << 1;
			else{
				Node p = stk[tops--];
				g[i] += p.u - i << 1;
				if(--p.d) stk[++tops] = p;
			}

		}
		int d = 0;
		while((cur << 2) <= pre) cur <<= 2, ++d;
		if(d) stk[++tops] = (Node){i, d};
	}
	for(register int i = 0; i <= N; i++) ans = min(ans, i + f[i] + g[i + 1]);
	return printf("%lld\n", ans), 0;
}

