vector<long long> solve(const vector<long long> &A) {
  int N = A.size();
  vector<long long> DP1(N + 1);
  for (int i = N - 1; i >= 0; --i) {
    int t = 0;
    if (i < N - 1) {
      long long q = A[i + 1];
      while (A[i] > q) {
        q *= 4;
        t += 2;
      }
    }
    DP1[i] = DP1[i + 1] + (N - 1LL - i) * t;
  }
  return DP1;
}

int main() {
  int N;
  std::cin >> N;
  vector<long long> A(N);
  for (int i = 0; i < N; ++i) {
    std::cin >> A[i];
  }
  const auto DP1 = solve(A);
  vector<long long> revA = A;
  std::reverse(revA.begin(), revA.end());
  const auto DP2 = solve(revA);

  long long ans0 = LONG_LONG_MAX;
  for (int i = 0; i <= N; ++i) {
    long long ans = DP1[i] + DP2[N - i] + i;
    ans0 = min(ans, ans0);
  }
  cout << ans0 << endl;
  return 0;
}

