	if(p>15){
		return g(i,15)+(p-15)*(i+1);
	}
	if(done[1][i][p]){
		return memo[1][i][p];
	}
	done[1][i][p] = true;
	if(i==0){
		memo[1][i][p] = p;
		return memo[1][i][p];
	}
	s = a[i];
	t = a[i-1];
	for(j=0; j<p; ++j){
		s *= 4ll;
	}
	while(s > t){
		t *= 4ll;
		++c;
	}
	memo[1][i][p] = g(i-1,c)+p;
	return memo[1][i][p];
}


int main(void){
