	fill(done[0][0],done[2][0],false);
	for(i=0; i<n; ++i){
		cin >> a[i];
	}
	ans = min(2*f(0,0),n+2*g(n-1,0));
	for(i=1; i<n; ++i){
		ans = min(ans,i+2*f(i,0)+2*g(i-1,0));
	}
	cout << ans << endl;
	return 0;
}

