int count(const vector<ld>& v, const int div)
{
	int res = 0;
	auto base = v[div];
	FOR(i, div + 1, N)
	{
		if(base > v[i])
		{
			auto diff = base-v[i];
			int times = ceil(diff / 2);
			base = v[i] + times * 2;
			res += times*2;
		}
		else
		{
			base = v[i];
		}
		//cout<<i<<":"<<base<<endl;
	}

	if(div==0)return res;
	res++;
	base = v[div-1];
	for(int i = div - 2; i >= 0; i--)
	{
		res++;
		auto opp = v[i];
		if(base > v[i])
		{
			auto diff = base - v[i];
			int times = ceil(diff/2);
			base = v[i] + times * 2;
			res += times*2;
		}
		else
		{
			base = v[i];
		}
		//cout << i << ":" << base << endl;
	}
	return res;
}

