struct Node {
    ll l,r,cnt;
    Node () {};
    Node (ll l, ll r , ll cnt) : l(l), r(r), cnt(cnt) {}
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int N; cin >> N;
    vector<ll> A(N);
    rep(i,N) cin >> A[i];

    vector<ll> L(N+1),R(N+1),overl(N),overr(N);
    rep(i,N-1) {
        ll tmpl = A[i], tmpr = A[i+1];
        if (A[i] < A[i+1]) {
            while (tmpl < tmpr) {
                tmpl *= 4;
                overl[i+1]++;
            }
        } else {
            while (tmpl >= tmpr*4) {
                tmpr *= 4;
                overl[i+1]--;
            }
        }

        tmpl = A[i];
        tmpr = A[i+1];
        if (A[i] > A[i+1]) {
            while (tmpl > tmpr) {
                tmpr *= 4;
                overr[i]++;
            }
        } else {
            while (tmpl *=4 <= tmpr) {
                tmpl *= 4;
                overr[i]--;
            }
        }
    }
    vector<Node> sta;
    rep(i,N) {
        Node node = Node(i,i+1,0);
        L[i+1] = L[i];
        while (true) {
            if (sta.empty() or node.cnt + overl[node.l] <= 0) {
                sta.emplace_back(node);
                break;
            }
            ll val = node.cnt + overl[node.l];
            auto top = sta.back(); sta.pop_back();
            L[i+1] += val*(top.r-top.l)*2;
            node.l = top.l;
            node.cnt = val;
        }
        L[i+1]++;
    }

    sta.clear();
    for (int i = N-1; i >= 0; i--) {
        Node node = Node(i-1,i,0);
        R[i] = R[i+1];
        while (true) {
            if (sta.empty() or node.cnt + overr[node.r] <= 0) {
                sta.emplace_back(node);
                break;
            }
            ll val = node.cnt + overr[node.r];
            auto top = sta.back(); sta.pop_back();
            R[i] += val*(top.r-top.l)*2;
            node.r = top.r;
            node.cnt = val;
        }
    }

    ll ans = 1e18;
    rep(i,N+1) {
        chmin(ans,L[i]+R[i]);
    }

    cout << ans << ln;
}

