int n;LL a[Maxn],Pow[20],f[Maxn],g[Maxn];
struct Seg{int l,r,lc,rc;LL sum;}tr[Maxn<<1];
int tot=0;
void up(int x)
{
	int lc=tr[x].lc,rc=tr[x].rc;
	tr[x].sum=tr[lc].sum+tr[rc].sum;
}
void build(int l,int r)
{
	int x=++tot;
	tr[x].l=l;tr[x].r=r;tr[x].sum=0;
	if(l==r)return;
	int mid=l+r>>1;
	tr[x].lc=tot+1,build(l,mid);
	tr[x].rc=tot+1,build(mid+1,r);
}
void modify(int x,int p,int v)
{
	if(tr[x].l==tr[x].r){tr[x].sum=v;return;}
	int lc=tr[x].lc,rc=tr[x].rc,mid=tr[x].l+tr[x].r>>1;
	if(p<=mid)modify(lc,p,v);
	else modify(rc,p,v);
	up(x);
}
int V;
int go(int x,int o)
{
	if(tr[x].l==tr[x].r){V=tr[x].sum;return tr[x].l;}
	int lc=tr[x].lc,rc=tr[x].rc;
	if(o==0)
	{
		if(tr[lc].sum)return go(lc,0);
		return go(rc,0);
	}
	else
	{
		if(tr[rc].sum)return go(rc,1);
		return go(lc,1);
	}
}
