int N;
vi a, aR;
vector<vector<ll>> dp, dpR;


void _build(vi& a, vector<vector<ll>>& dp) {
    dp.assign(N+1, vector<ll>(16, 0));

    vll last(16, LLONG_MAX), curr(16);

    for (int i=N-1; i>=0; --i) {
        curr[0] = a[i]; rep(j,15) curr[j+1] = curr[j] * 4LL;

        rep(j,16) {
            int ix = lower_bound(ALL(last), curr[j]) - last.begin();
            if (ix < 16) {
                dp[i][j] = dp[i+1][ix] + j;
            } else {
                assert(j > 0);
                dp[i][j] = dp[i][j-1] + (N-i);
            }
        }

        swap(last, curr);
    }
}

inline ll solve_neg(int hi) {
    if (hi == 0) return 0;
    return dpR[N-hi][0]*2+1;
}
inline ll solve_pos(int lo) {
    if (lo == N) return 0;
    return dp[lo][0]*2;
}


ll solve() {
    vi zeros;

    aR.assign(a.rbegin(), a.rend());
    rep(i,N) {
        if (a[i] == 0) zeros.pb(i);
    }
    int Z = zeros.size();
    if (Z >= 2) {
        rep(i,Z-1) if (zeros[i+1] - zeros[i] >= 2) return -1;
    }

    _build(a, dp);
    _build(aR, dpR);

    if (Z > 0) {
        return solve_neg(zeros[0]) + solve_pos(zeros.back()+1);
    }

    ll best = LLONG_MAX;

    for (int line=0; line<=N; ++line) {
        ll neg = solve_neg(line), pos = solve_pos(line);
        best = min(best, neg + pos);
    }

    return best;
}


