const int M = 200010; 

int64_t dp[M][16][2], dp_min[M][2];

int main(){
    int N;
    int64_t A[M];
    cin >> N;
    for(int i=0; i<N; i++) cin >> A[i];

    for(int i=0; i<N-1; i++) for(int k=0; k<2; k++) dp_min[i][k] = 1e18;

    for(int k=0; k<2; k++){
        for(int j=0; j<=15; j++) dp[N-1][j][k] = j;

        for(int i=N-2; i>=0; i--){
            for(int j=0; j<=15; j++){
                int64_t a = A[i] << (2*j);
                int j2 = 0;
                while(a > (A[i+1]<<(2*j2))) j2++;
                if(j2 <= 15){
                    dp[i][j][k] = dp[i+1][j2][k] + j;
                }else{
                    dp[i][j][k] = dp[i+1][15][k] + j + (N-1-i) * (j2-15);
                }
                dp_min[i][k] = min(dp_min[i][k], dp[i][j][k]);
            }
        }
        reverse(A, A+N);
    }

    int64_t ans = 1e18;
    for(int i=0; i<=N; i++){
        int64_t result = i + 2 * (dp_min[i][0] + dp_min[N-i][1]);
        ans = min(ans, result);
    }
    cout << ans << endl;
    return 0;
}

