ll mem[MX][16];
vi A;

ll dp(int idx, int x) {
	if (idx == 1)
		return x;
	if (x > 15)
		return dp(idx, 15) + (x - 15) * (idx - 1);
	ll& ret = mem[idx][x];

	if (ret != -1)
		return ret;
	ll currValue = A[idx] * (1LL << (x << 1));

	for (int i = 0;; ++i)
		if (A[idx - 1] * (1LL << (i << 1)) >= currValue)
			return ret = x + dp(idx - 1, i);
}

