il int Min4( rg ll a ){
	rg ll tot = 1;
	rg int cnt = 0;
	while( tot < a ){
		++cnt;
		tot <<= 2LL;
	}
	return cnt;
}
il int Max4( rg ll a ){
	rg ll tot = 1;
	rg int cnt = 0;
	while( (tot<<2LL) <= a ){
		++cnt;
		tot <<= 2LL;
	}
	return cnt;
}

