		if( ta[i] < 0 ){
			ta[i] = -2LL*ta[i];
			++cost2[i];
		}
		Forx(j,i,n-1){
			if( Pow4(ta[j],cnt[j]-cnt[j+1]) <= Pow4(ta[j+1],cnt[j+1]-cnt[j]) ){
				break;
			}
			ll a = ta[j], b = ta[j+1];
			// printf("Changing at pos %d\n",j);
			if( a >= b ){
				int min4 = Min4(a/b+(!!(a%b)));
				cost2[i] += (min4 + cnt[j])*2 - cnt[j+1];
				cnt[j+1] = min4 + cnt[j];
				// printf("a>=b, %d %d %d\n",a,b,min4);
				// printf("So cnt[%d] should be %d\n",j+1,min4 + k);
			}else{
				int max4 = Max4(a/b);
