ll dp[L][N];

int log4(ll x, ll y) {
    if (x >= y) {
        int e = 0;
        while (x > y) {
            y <<= 2;
            e++;
        }
        return e;
    } else {
        int e = 1;
        while (x <= y) {
            x <<= 2;
            e--;
        }
        return e;
    }
}

vector<ll> calc(const vector<int>& a) {
    int n = a.size();
    for (int j = 0; j < L; j++) {
        dp[j][n-1] = j;
    }
    for (int i = n-1; i >= 1; i--) {
        int e = log4(a[i-1], a[i]);
        for (int j = 0; j < L; j++) {
            dp[j][i-1] = j;
            int k = max(j+e, 0);
            dp[j][i-1] += k<L? dp[k][i] : dp[L-1][i] + (k-L+1)*(n-i);
        }
    }
    vector<ll> res(n);
    for (int i = 0; i < n; i++) {
        res[i] = dp[0][i] << 1;
