using namespace std;
vector<long long> solve(vector<int> A) {
	int N = A.size();
	vector<long long> dp(N);
	vector<double> diff(N - 1);
	set<int> four;
	for (int i = N - 2; i >= 0; --i) {
		dp[i] = dp[i + 1];
		diff[i] = double(A[i + 1]) / A[i];
		while (diff[i] < 0.9999999999) {
			diff[i] *= 4;
			dp[i] += (N - i - 1) * 2;
			if (!four.empty()) {
				int ptr = *four.begin();
				dp[i] -= (N - ptr - 1) * 2;
				diff[ptr] /= 4;
				if (diff[ptr] < 3.9999999999) four.erase(ptr);
			}
		}
		if (diff[i] >= 3.9999999999) four.insert(i);
	}
	return dp;
}
int main() {
	int N;
	cin >> N;
	vector<int> A(N);
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
	}
	vector<long long> ldp = solve(A);
	reverse(A.begin(), A.end());
	vector<long long> rdp = solve(A);
	reverse(rdp.begin(), rdp.end());
	long long ans = min(ldp[0], rdp[N - 1] + N);
	for (int i = 0; i < N - 1; ++i) {
		ans = min(ans, ldp[i + 1] + rdp[i] + i + 1);
	}
	cout << ans << endl;
	return 0;
}

