					pos = p.second;
					if (p.first == 0) break;
					st.pop();
					if (p.first < rest) {
						rest -= p.first;
					}
					else {
						p.first -= rest;
						if (p.first != 0) st.push(p);
						break;
					}
				}
			}
			b[i] = sum;
		}
		return b;
