      ll r = (log2(now, prev) + 1) / 2 * 2;
      debug(log2(now, prev));
      prev *= pow2(r);
      while(r){
        auto p = st.top(); st.pop();
        ll r2 = min(p.first, r);
        r -= r2;
        p.first -= r2;
        calc1 += (ll)r2 * p.second;
        if(p.first > 0) st.push(p);
      }
    }

    ll e = log2(prev, now, false) / 2 * 2;

    if(e){
      st.push({e, i});
    }

    dp1[i] = calc1 + i + 1;
    debug(dp1[i]);
    prev = now;
  }


  dp2[n] = dp2[n-1] = 0;
  prev = a[n-1];
