    for (int i = 0; i <= N; ++i) {
        //i-1番目まで負
        //i番目から正
        //cerr << X[i] << " " << Y[i] << endl;
        ans = min(ans, X[i] + Y[i]);
    }
    cout << ans << endl;
    return 0;
}

