				int cnt = 0; 
				while (tmp < a[i])
				{
					tmp *= 4;
					cnt += 2;
				}
				f[i] += 1ll * (n - i - pq.size()) * cnt; 
				lazy += cnt; 
				while (!pq.empty() && pq.top() - lazy <= 0)  
				{
					f[i] += lazy - pq.top();  
					pq.pop();
				}
			}
			else
			{
				ll tmp = a[i + 1] / a[i]; 
				if (tmp / 4) pq.push((tmp / 4) * 2);  
