const long long INF = 1LL<<60;
const int MAX = 16;
int N;
vector<long long> A;

vector<vector<long long>> calc(const vector<long long> &a, int offset = 0) {
    vector<vector<long long>> dp(N+1, vector<long long>(MAX, INF));
    for (int j = 0; j < MAX; ++j) dp[0][j] = 0, dp[1][j] = j*2 + offset;
    for (int i = 1; i < N; ++i) {
        long long s = a[N-i-1];
        for (int j = 0; j < MAX; ++j) {
            long long t = a[N-i];
            int need = 0;
            while (s > t) ++need, t *= 4;
            long long add = 0;

            //COUT(s); COUT(t);

            if (need >= MAX) {
                add = (need - MAX + 1) * i * 2;

                //cout << need << " -> " << MAX-1 << "(" << i << "): " << add << endl;

                need = MAX-1;


            }
            chmin(dp[i+1][j], dp[i][need] + j * 2 + add + offset);
            s *= 4;
        }
    }
    return dp;
}

long long solve() {
    const auto &right = calc(A);
    reverse(A.begin(), A.end());
    const auto &left = calc(A, 1);

    COUT(left);
    COUT(right);

    long long res = INF;
    for (int i = 0; i <= N; ++i) chmin(res, left[i][0] + right[N-i][0]);
    return res;
}

int main() {
    cin >> N;
    A.resize(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    cout << solve() << endl;
}

