const ll MOD=1e9+7;

bool ge(ll a,ll b){
	if(b==0) return false;
	if(a==0) return true;
	int t=__builtin_ctzll(a);
	a>>=t;
	t=__builtin_ctzll(b);
	b>>=t;
	return a<b;
}

void solve(vector<ll> a,vector<int> &re){
	int n=a.size();
	rep(i,n)if(a[i]>0){
		++re[i+1];
		a[i]*=-2;
	}
	for(auto &x:a) x*=-1;
	out(a,re,1);
	// dec!
	ll prv=MOD*16;
	rep(i,n){
		int tmp=64-__builtin_clzll(a[i])+re[i+1] - (64-__builtin_clzll(prv)+re[i]);
		out(tmp,1);
		if(tmp>0) re[i]+=(tmp+1)/2*2;
		if(tmp==0 && ge(prv,a[i])) re[i]+=2;
		prv=a[i];
	}
	rep(i,n) re[i]+=re[i+1];
	out(re,1);
}

