	rep(i,n-1){
		ll l=a[i];
		ll r=a[i+1];
		while(l>r){
			r*=2;
			++ge[i+1];
		}
		while(l*2<=r){
			l*=2;
			--ge[i+1];
		}
		l=a[i];
		r=a[i+1];
		while(l<r){
			l*=2;
			++le[i];
		}
		while(l>=r*2){
			r*=2;
			--le[i];
		}
	}
	out(ge,le,1);
	vector<ll> l(n);
	vector<pii> st{{MOD,-1}};
	rep(i,n-1){
		l[i+1]+=l[i];
		if(le[i]<0){
			st.eb((-le[i]-1)/2,i);
