	//	if (sdiff < 0) rf *= pow2[-sdiff];

	//	return cf <= rf;
	//}
};

ll fourDiff(Q l, Q r) {
	ll diff = 0;
	while (l.f > r.f) {
		r.f *= 4;
		diff -= 1;
	}
	while (l.f * 4 <= r.f) {
		l.f *= 4;
		diff += 1;
	}

	ll sdiff = r.s - l.s;
	return diff + sdiff;
}

struct P {
	Q l, r;
	int len;
};



vector<ll> f(vector<ll> a) {
	int n = sz(a);
	vector<P> v;
	vector<ll> ret;
	ll ans = 0;
	for (int i = n - 1; i >= 0; i--) {
		P p{ Q{a[i], 0}, Q{a[i], 0}, 1 };
		v.push_back(p);

		while (sz(v) >= 2) {
			auto nxt = v[sz(v) - 2];
			auto cur = v[sz(v) - 1];
			ll diff = fourDiff(cur.r, nxt.l);
			if (diff < 0) {
				ll add = abs(diff);
				nxt.l.s += add;
				nxt.r.s += add;
				ans += add * nxt.len;
				diff = 0;
			}

			if (diff == 0) {
				v.pop_back();
				v.pop_back();

				P np;
				np.l = cur.l;
				np.r = nxt.r;
				np.len = cur.len + nxt.len;
				v.push_back(np);
			} else {
				break;
			}
		}

		ret.push_back(ans);
	}

	reverse(ret.begin(), ret.end());
	return ret;
}

int main() {
