const long long INF = LLONG_MAX / 2;

void solve(const vector<long long>& a, vector<long long>& ans)
{
    int n = a.size();
    vector<long long> diff(n, 0);
    diff[0] = INF;
    for(int i=1; i<n; ++i){
        long long x = abs(a[i-1]);
        long long y = abs(a[i]);
        if(x > y)
            swap(x, y);

        if(a[i-1] <= a[i]){
            while(x < y){
                x *= 4;
                -- diff[i];
            }
        }
        else{
            while(x * 4 <= y){
                x *= 4;
                ++ diff[i];
            }
        }
    }

    ans.assign(n+1, 0);
    stack<int> stk;
    for(int i=0; i<n; ++i){
        ans[i+1] = ans[i];
        if(diff[i] > 0){
            stk.push(i);
            continue;
        }

        while(diff[i] < 0){
            int j = stk.top();
            ans[i+1] += i - j;
            ++ diff[i];
            -- diff[j];
            if(diff[j] == 0)
                stk.pop();
        }
    }
}


int main()
{
    int n;
    cin >> n;
    vector<long long> a(n);
    for(int i=0; i<n; ++i)
        cin >> a[i];

    vector<long long> v1;
    solve(a, v1);

    vector<long long> v2;
    reverse(a.begin(), a.end());
    solve(a, v2);

    long long ans = INF;
    for(int i=0; i<=n; ++i){
        long long cost = (i + v1[i] * 2) + (v2[n-i] * 2);
        ans = min(ans, cost);
    }
    cout << ans << endl;

    return 0;
}

