    V.clear();
    V.push_back(PI(n, 1000000000));
    ans = 0;
    for(int i = n - 1; i >= 1; i--) {
        ll a = A[i + 1], b = A[i];
        if(a > b) {
            ll cnt = 0;
            while(b * 4 <= a) b *= 4, cnt++;
            V.push_back(PI(i, cnt));
        } else {
            while(a < b) {
                ans += (V.back().f - i);
                if(!--V.back().s) V.pop_back();
                a *= 4;
            }
        }
        R[i] = ans;
