#include <bits/stdc++.h>
typedef long long ll; 

using namespace std;

int main() {
	const ll INF = 1e18;
	ll N;
	cin >> N;
	vector<ll> a(N);
	for (int i = 0; i < N; ++i) { cin >> a[i]; }

	vector<vector<ll>> dp_p(N, vector<ll>(16, INF));
	for (int i = N - 1; i >= 0; --i) {
		if (i == N - 1) {
			for (int j = 0; j < 16; ++j) {
				dp_p[i][j] = j;
			}
			continue;
		}
		for (int j = 0; j < 16; ++j) {
			ll x = a[i + 1] * pow(4LL, j);
			for (int k = 0; k < 16; ++k) {
				ll y = a[i] * pow(4LL, k);
				if (y > x) {
					ll tmp = k + dp_p[i + 1][j] + (N - i);
					dp_p[i][k] = min(dp_p[i][k], tmp);
					break;
				}
				dp_p[i][k] = min(dp_p[i][k], dp_p[i + 1][j] + k);
			}
		}
	}
	vector<vector<ll>> dp_n(N, vector<ll>(16, INF));
	for (int i = 0; i < N; ++i) {
		if (i == 0) {
			for (int j = 0; j < 16; ++j) {
				dp_n[i][j] = j;
			}
			continue;
		}
		for (int j = 0; j < 16; ++j) {
			ll x = a[i - 1] * pow(4LL, j);
			for (int k = 0; k < 16; ++k) {
				ll y = a[i] * pow(4LL, k);
				if (y > x) {
					ll tmp = k + dp_n[i - 1][j] + j;
					dp_n[i][k] = min(dp_n[i][k], tmp);
					break;
				}
				dp_n[i][k] = min(dp_n[i][k], dp_n[i - 1][j] + k);
			}
		}
	}

	ll res = INF;
	for (int i = -1; i < N; ++i) {
		ll p = INF, n = INF;
		if (i >= 0) {
			for (int j = 0; j < 16; ++j) {
				n = min(n, dp_n[i][j] * 2);
			}
			n += (i + 1);
		} else {
			n = 0;
		}
		if (i < N - 1) {
			for (int j = 0; j < 16; ++j) {
				p = min(p, dp_p[i + 1][j] * 2);
			}
		} else {
			p = 0;
		}

		res = min(res, p + n);
	}

	cout << res << endl;

	return 0;
}

