using namespace std;

int twos(long long int a,long long int b){
	int f=1;
	if(a<=b) return 0;
	int counter=0;
	while(1){
		b=4*b;
		counter=counter+f;
		if(a<=b){
			return counter;
			break;
		}
	}
}

int main (){
	long long int n,bp,a[200005],counter[200005],left[200005],lefts[200005],right[200005],rights[200005],i,j,k;
	cin >> n;
	for(i=1;i<=n;i++) cin >> a[i];
	left[n]=0; lefts[n]=0; bp=n;
	for(i=n-1;i>=1;i--){
		if(twos(a[i],a[i+1])+left[i+1]>0) left[i]=twos(a[i],a[i+1])+left[i+1];
		else left[i]=0;
		if(left[i]<=left[i+1]) {
			lefts[i]=lefts[i+1];
			if(left[i]<left[i+1]) bp=i;
		} else {
			lefts[i]=lefts[i+1]+(bp-i)*(left[i]-left[i+1]);
		}
	}
	right[1]=0; rights[1]=0; bp=1;
	for(i=2;i<=n;i++){
		if(twos(a[i],a[i-1])+right[i-1]>0) right[i]=twos(a[i],a[i-1])+right[i-1];
		else right[i]=0;
		if(right[i]<=right[i-1]) {
			rights[i]=rights[i-1];
			if(right[i]<right[i-1]) bp=i;
		} else {
			rights[i]=rights[i-1]+(i-bp)*(right[i]-right[i-1]);
		}
	}
	counter[0]=2*lefts[1];
	for(i=2;i<=n;i++) counter[i-1]=i-1+2*(lefts[i]+rights[i-1]);
	sort(counter,counter+n);
	cout << counter[0] << endl;
	return 0;
}

