				ll need = 0;
				while (a < b) {
					a *= 4;
					++need;
				}
				ll now = need*(i - 1 - q.size());
				add += need;
				while (!q.empty() && q.begin()->first - add <= 0) {
					ll s = q.begin()->first - add;
					int at = q.begin()->second;
					q.erase(q.begin());
					if (s) {
						set<pair<ll, int> >::iterator it;
						while (at > 1 && (it = q.find({ val[at - 1],at - 1 })) != q.end()) {
