	rep1(i, n - 1) {
			while (!q.empty()) {
				LP ne = q.top();
				if (ne.first > sum[i]) {
					nex[ne.second] = i; q.pop();
				}
				else {
					break;
				}
			}
			q.push({ sum[i],i });
	}
	while (!q.empty()) {
		P ne = q.top();q.pop();
		nex[ne.second] = n;
	}
	rep1(i, n - 1) {
		dfs(i);
	}
}
