//オーバーフローする可能性があれば掛け算にmodmul()を使う
long long modpow(long long base, long long exponent) {
  long long res = 1;
  while (exponent > 0) {
    if (exponent & 1)
      res = res * base;
    base = base * base;
    exponent >>= 1;
  }
  return res;
}
