        if (i % 2 == 0)
        {
            pref[1][i] = min(pref[1][i], dp[1][i]);
        }
    }
    suf[1][MAX_LOG - 1] = dp[1][MAX_LOG - 1];
    for (int i = MAX_LOG - 2; i >= 0; --i)
    {
