        for (int k = 1; k < MAX_LOG; ++k)
        {
            pref[i][k] = pref[i][k - 1];
            if (k % 2 == 0)
            {
                pref[i][k] = min(pref[i][k], dp[i][k]);
            }
        }
        suf[i][MAX_LOG - 1] = dp[i][MAX_LOG - 1];
        for (int k = MAX_LOG - 2; k >= 0; --k)
        {
            suf[i][k] = suf[i][k + 1];
            if (k % 2 == 1)
            {
                suf[i][k] = min(suf[i][k], dp[i][k]);
            }
        }
    }
    ll ans = INF;
    for (int j = 0; j < MAX_LOG; ++j)
    {
        ans = min(ans, dp[n][j]);
    }
    cout << ans << endl;
    return 0;
}

