    REP(i,16) hudp[0][i] = i;
    FOR(i,1,n){
        int cnt = 0;
        if(A[i] <= A[i - 1]){
            while(A[i] * ruijou[cnt] <= A[i-1]) cnt ++;
            cnt --;
            cnt *= -1;
        }
        else{
            while(A[i] > A[i-1] *ruijou[cnt]) cnt ++;
        }



        REP(j,16){
            int tmp = max(0,cnt + j);
            if(tmp >15){
                hudp[i][j] = j + hudp[i-1][15] + (tmp - 15)* i;  
            }
            else{
                hudp[i][j] = hudp[i-1][tmp] + j;
            }
        }

    }


    int ans = min(2 * dp[0][0] , 2 * hudp[n-1][0] + n);
    FOR(i,1,n){
        ans = min( ans,  2 * dp[i][0] + 2 * hudp[i-1][0] + i);
    }

    cout << ans << endl;

}

