int main(void) {

	cin >> N;
	for (int i = 1; i <= N; i++) {
		cin >> A[i];
	}

	R[N] = 0;
	for (int i = N - 1; i >= 1; i--) {
		if (A[i] <= A[i + 1]) { R[i] = R[i + 1]; }
		else {
			int M = 2;
			long long int tmp = 4;
			while (A[i] > A[i + 1] * tmp) {
				M+=2; tmp *= 4;
			}
			//cout << "M= " << M << endl;
			R[i] = R[i + 1] + M*(N - i);
		}
	}

	/*for (int i = N; i >= 1; i--) {
		cout << "R[" << i << "]= " << R[i] << endl;
	}*/

	L[1] = 0;
	for (int i = 2; i <= N; i++) {
		if (A[i - 1] >= A[i]) { L[i] = L[i - 1]; }
		else {
			int M = 1;
			long long int tmp = 4;
			while (A[i - 1] * tmp < A[i]) {
				M+=2; tmp += 4;
			}
			L[i] = L[i - 1] + M*(i - 1);
