        // msb 差が 0 以上なら減少するかも (sub は 30 くらい？)
        if(msb_posi[i] >= msb_posi[i+1]) {
            ll sub = msb_posi[i] - msb_posi[i+1];
            add = (sub + 1) / 2 * 2; // 偶数

            ll P = posi[i], Q = posi[i+1] << add;
            if(P > Q) add += 2;
        }
        suf[i+1] = suf[i+2] + add * (N-1-i);
    }

    // 減少列 (1 .. N)
    for(int i=1; i<N; i++) {
        ll add = 0;
        // msb 差が 0 以下なら増加するかも (sub は 30 くらい？)
        if(msb_nega[i-1] <= msb_nega[i]) {
            ll sub = msb_nega[i] - msb_nega[i-1];
            add = (sub + 1) / 2 * 2; // 偶数

            ll P = nega[i], Q = nega[i-1] << add;
            if(P > Q) add += 2;
        }
        pre[i+1] = pre[i] + add * i;
    }

    ll ans = LONGINF;
    for(int i=0; i<=N; i++) {
        // pre の長さ分だけ +1 (-2 倍するため)
        // fprintf(stderr, "i = %d: pre = %lld, suf = %lld\n", i, pre[i], suf[i+1]);
        chmin(ans, i + pre[i] + suf[i+1]);
    }
    cout << ans << endl;
    return 0;
}

