    for (int j = 0; j <= 29; ++j) {
      if (a[i] >> j & 1) {
        b[i] = j;
      }
    }
    a[i] <<= 29 - b[i];
  }
  f[n] = 0;
  suff[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    f[i] = b[i];
    suff[i] = suff[i + 1];
    for (int j = i + 1; j < n; ++j) {
      if (f[j] > f[j - 1] || (f[j] == f[j - 1] && a[j] >= a[j - 1])) {
        break;
      }
      int v = (f[j - 1] - f[j] + 1) / 2 * 2;
      if (f[j] + v == f[j - 1] && a[j] < a[j - 1]) {
        v += 2;
      }
      if (f[j] < 35) {
        f[j] += v;
        suff[i] += v;
      } else {
        suff[i] += (long long)v * (n - j);
        break;
      }
    }
  }
  long long ans = suff[0];
  long long pref = 0;
  for (int i = 0; i < n; ++i) {
    f[i] = b[i] + 1;
    pref += 1;
    for (int j = i - 1; j >= 0; --j) {
