  REP(i,n)adp[i]=a[i];

  StarrySkyTree<LL> sst(n);
  ll[n] = 0;
  ll[n-1] = 0;
  REP(i,n-1){
    int irev = n-2-i;
    LL target = a[irev];
    LL nbh    = a[irev+1];
    LL delta = delt(target,nbh);
    LL asgn = 0;
    if(delta >= 0){
      ll[irev] = ll[irev+1];
      sst.update(irev,delta);
    }else{
      while(-delta){
        int lb = irev+1;
        int ub = n-1;
        if(sst.max_element(irev+1,n) == 0){
          asgn += n-1-irev;
          delta++;
          continue;
        }
        while(lb < ub){
          int mid = (lb+ub)/2;
          if(sst.max_element(irev+1,mid+1) > 0){
            ub = mid;
          }else{
            lb = mid+1;
          }
        }
        sst.add(lb,-1LL);
        asgn += lb-irev;
        delta++;
      }

      ll[irev] = ll[irev+1]+asgn;
      sst.update(irev,0);
    }
  }

  StarrySkyTree<LL> sst2(n);

