            ub = mid;
          }else{
            lb = mid+1;
          }
        }
        sst2.add(lb,-1LL);
        asgn += lb-irev;
        delta++;
      }
      ll_rev[irev_idx] = ll_rev[irev_idx-1]+asgn;
      sst2.update(irev,0);
    }
  }

  /*REP(i,n+1)cerr<<ll[i]<<" ";
