#include <bits/stdc++.h>
using namespace std;

int n;
long long a[200010], pos[200010], neg[200010];

void calc_pos() {
    vector<long long> b(n);
    stack<pair<long long, int>> st;
    for (int i = n-1; i >= 0; i--) {
        b[i] = a[i], pos[i] = pos[i+1];
        if (b[i] < 0) pos[i]++, b[i] *= -2;
        if (i == n-1) continue;
        if (b[i] <= b[i+1]) {
            int cnt = 0;
            while (b[i] <= b[i+1]) {
                   cnt++, b[i+1] /= 4;
            }
            if (cnt > 1) st.emplace(i, cnt-1);
        } else {
            int cnt = 0;
            while (b[i] > b[i+1]) {
                cnt++, b[i+1] *= 4;
            }
            while (!st.empty() && cnt > 0) {
                int x = min(cnt, st.top().second);
                st.top().second -= x, cnt -= x;
                pos[i] += x * (st.top().first - i) * 2;
                if (st.top().second == 0) st.pop();
            }
            if (cnt > 0) pos[i] += (n - 1 - i) * cnt * 2;
        }
    }
}

void calc_neg() {
    vector<long long> b(n);
    stack<pair<long long, int>> st;
    for (int i = 0; i < n; i++) {
        b[i] = a[i], neg[i+1] = neg[i];
        if (b[i] < 0) b[i] *= -1;
        else neg[i+1]++, b[i] *= 2;
        if (i == 0) continue;
        if (b[i-1] >= b[i]) {
            int cnt = 0;
            while (b[i-1] >= b[i]) {
                   cnt++, b[i-1] /= 4;
            }
            if (cnt > 1) st.emplace(i, cnt-1);
        } else {
            int cnt = 0;
            while (b[i-1] < b[i]) {
                cnt++, b[i-1] *= 4;
            }
            while (!st.empty() && cnt > 0) {
                int x = min(cnt, st.top().second);
                st.top().second -= x, cnt -= x;
                neg[i+1] += x * (i - st.top().first) * 2;
                if (st.top().second == 0) st.pop();
            }
            if (cnt > 0) neg[i+1] += i * cnt * 2;
        }
    }
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    cin >> n;
    for (int i = 0; i < n; i++) cin >> a[i];
    calc_pos(), calc_neg();
    long long ans = 1e18;
    for (int i = 0; i < n; i++) {
        ans = min(ans, pos[i] + neg[i]);
    }
    cout << ans << "\n";
    return 0;
}

