using T = tuple<ll, ll, ll>;

vector<ll> get(vector<ll> a){
  ll n = SZ(a);
  vector<ll> res(0);
  stack<T> st;
  ll cnt = 0;
  res.pb(0);
  REP(i, n){
    ll last = a[i];
    ll csz = 1;
    while(!st.empty()){
      ll x, y, sz;
      tie(x, y, sz) = st.top();
      if(y >= last){
        break;
      }
      st.pop();
      while(y < last){
        x *= 4;
        y *= 4;
        cnt += sz;
      }
      csz += sz;
      last = x;
    }
    st.emplace(last, a[i], csz);
    res.pb(cnt);
  }
  return res;
}

