        // min x s.t. a[i] * 4**j <= a[i+1] * 4**x
        if(a[i] >= a[i+1]) {
            // min x s.t. 4**(x-j) >= a[i]/a[i+1]
            int q = ceil(a[i], a[i+1]);
            int d = 0; ll t = 1;
            while(t < q) {
                t *= 4;
                ++d;
            }
            int x = j + d;
            int tmp = solve(i + 1, x);
            return pos[i][j] = 2 * j + tmp;
        }
        else {
            // min x s.t. 4**(j-x) <= a[i+1]/a[i]
            // max d s.t. 4**d <= a[i+1]/a[i]
            int q = a[i+1] / a[i];
            int d = 0; ll t = 1;
            while (t <= q) {
                t *= 4;
                d++;
            }
            --d;
            int x = max(0, j - d);
            int tmp = solve(i + 1, x);
            return pos[i][j] = 2 * j + tmp;
