            while (t < q) {
                t *= 4;
                ++d;
            }
            int x = j + d;
            int tmp = solve2(i - 1, x);
            return neg[i][j] = 2 * j + 1 + tmp;
        }
        else {
            // 4 ** (j-x) <= a[i-1]/a[i]
            int d = 0; ll t = 1;
            int q = a[i-1] / a[i];
            while (t <= q) {
                d++;
                t *= 4;
            }
            d--;
            int x = max(0, j - d);
            return neg[i][j] = 2 * j + 1 + solve2(i-1, x);
        }
    };
