const long long INF=1LL<<61;

int main(){
	int n; scanf("%d",&n);
	vector<lint> a(n);
	rep(i,n) scanf("%lld",&a[i]);

	vector<lint> sum1(n+1);
	{
		auto tmp=a;

		vector<int> right(n);
		rep(i,n) right[i]=i;

		for(int i=n-2;i>=0;i--){
			sum1[i]=sum1[i+1];
			int pos=i;
			while(pos<n-1 && a[pos]>a[pos+1]){
				int r=right[pos+1];
				while(a[pos]>a[pos+1]){
					sum1[i]+=2*(r-pos);
					a[pos+1]*=4;
					if(pos+1<r) a[r]*=4;
				}
				pos=r;
			}
			right[i]=pos;
		}

		a=tmp;
	}

	vector<lint> sum2(n+1);
	{
		auto tmp=a;

		vector<int> left(n);
		rep(i,n) left[i]=i;

		for(int i=2;i<=n;i++){
			sum2[i]=sum2[i-1];

			int pos=i-1;
			while(pos>=1 && a[pos-1]<a[pos]){
				int l=left[pos-1];
				while(a[pos-1]<a[pos]){
					sum2[i]+=2*(pos-l);
					a[pos-1]*=4;
					if(l<pos-1) a[l]*=4;
				}
				pos=l;
			}
			left[i-1]=pos;
		}

		a=tmp;
	}

	lint ans=INF;
	rep(i,n+1) ans=min(ans,sum1[i]+sum2[i]+i);
	printf("%lld\n",ans);

	return 0;
}

