  for(int i = 1; i < N; i++) {
    int64 u = -A[i - 1], v = -A[i], times = 1;

    while(u > v) {
      u *= 4;
      times += 2;
    }
    if(times == 1) prefix[i] = prefix[i - 1] + 1;
    else prefix[i] = prefix[i - 1] + (times * i);
  }

  int64 ret = min(prefix[N - 1], suffix[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, prefix[i - 1] + suffix[i]);
  }
  cout << ret << endl;

}

