const int MAX_N = (1 << 18);
int nn;ll dat[2 * MAX_N - 1];
void init(int n_) {
	nn = 1;
	while (nn < n_)nn *= 2;
	rep(i, 2 * nn - 1)dat[i] = INF;
}
void update(int k, ll a) {
	k += nn - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = min(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}
ll query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l)return INF;
	if (a <= l && r <= b)return dat[k];
	else {
		ll vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		ll vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
}

int nex[1 << 18];
ll gen[1 << 18]; bool used[1 << 18];
ll dfs(int id) {
	if (used[id])return gen[id];
	used[id] = true;
	int to = nex[id];
	ll res = (to - id)*sum[id] + dfs(to);
	return gen[id] = res;
}
void initt() {
	priority_queue<P> q;
	rep1(i, n - 1) {
		if (sum[i] >= sum[i - 1]) {
			q.push({ sum[i],i });
		}
		else {
			while (!q.empty()) {
				P ne = q.top();
				if (ne.first > sum[i]) {
					nex[ne.second] = i; q.pop();
				}
				else {
					break;
				}
			}
			q.push({ sum[i],i });
		}
	}
	while (!q.empty()) {
		P ne = q.top();q.pop();
		nex[ne.second] = n;
	}
	rep1(i, n - 1) {
		dfs(i);
	}
}
