    vector<int_fast64_t> a(N), b(N), c(N), d(N);
    for(int i = 0; i < N; ++i)scanf("%lld", &a[i]);
    b[N - 1] = 0;
    {
        stack<int_fast64_t> stc;
        for(int_fast64_t i = N - 2; i >= 0; --i) {
            b[i] = b[i + 1];
            auto aa = a[i + 1], ab = a[i];
            while(aa < ab){
                int_fast64_t t = stc.empty() ? N - 1 : stc.top();
                b[i] += (t - i) * 2;
                if(!stc.empty()) stc.pop();
                aa *= 4;
            }
            while(aa >= ab * 4){
                stc.push(i);
                ab *= 4;
            }
        }
    }
    c[0] = 1;
    {
        stack<int_fast64_t> stc;
        for(int_fast64_t i = 1; i < N; ++i) {
            c[i] = c[i - 1] + 1;
            auto aa = a[i - 1], ab = a[i];
            while(aa < ab){
                int_fast64_t t = stc.empty() ? 0 : stc.top();
                c[i] += (i - t) * 2;
                if(!stc.empty()) stc.pop();
                aa *= 4;
            }
            while(aa >= ab * 4){
                stc.push(i);
                ab *= 4;
            }
        }
    }
    int_fast64_t ans(min(c[N - 1], b[0]));
    for(int i = 0; i < N - 1; ++i){
        ans = min(ans, c[i] + b[i + 1]);
    }
    printf("%lld\n", ans);
    return 0;
}

