using namespace std;
using ll = long long;
using pii = pair<int, int>;
static const int INF = 1000000000;

vector<ll> solve(const vector<ll>& a){
	const int n = a.size();
	vector<ll> incr(n);
	stack<pii> istack;
	istack.emplace(n, INF);
	for(int i = n - 2; i >= 0; --i){
		incr[i] = incr[i + 1];
		if(a[i + 1] < a[i]){
			for(ll j = 1; a[i + 1] * j < a[i]; j *= 4){
				while(istack.top().second == 0){ istack.pop(); }
				const auto t = istack.top();
				istack.pop();
				incr[i] += 2 * (t.first - i - 1);
				istack.emplace(t.first, t.second - 1);
			}
		}else{
			int margin = 0;
			for(ll j = 4; a[i] * j <= a[i + 1]; j *= 4){
				++margin;
			}
			istack.emplace(i + 1, margin);
		}
	}
	return incr;
}

