	const auto positive = solve(a);
	reverse(a.begin(), a.end());
	auto negative = solve(a);
	reverse(negative.begin(), negative.end());
	ll answer = INF;
	for(int i = 1; i < n; ++i){
		answer = min(answer, negative[i - 1] + i + positive[i]);
	}
	cout << answer << endl;
	return 0;
}

