inline void bs(int l,int r,long long e,long long u) {
	if(l>r) return;long long j;
	int mid=l+r>>1;long long now;
	for(now=e,j=1;j<=mid;++j,now*=4) if(now>1000000000000LL) {bs(l,mid-1,e,u);return;}
	if(now>=u) {sum=mid;bs(l,mid-1,e,u);}
	else bs(mid+1,r,e,u);
}
