		if(a[i]>a[i+1]) {bs(1,32,a[i+1],a[i]);right[i]+=sum*2*(n-i);}
		right[i]+=right[i+1];
	}
	for(int i=2;i<=n;++i) {
		if(a[i]>a[i-1]) {bs(1,32,a[i-1],a[i]);left[i]+=sum*2*(i-1);}
		left[i]+=left[i-1];
	}
	for(int i=0;i<=n;++i) ans=min(ans,i+left[i]+right[i+1]);
