// ta funkcja dziala w obie strony - sprawdza czy dodatnie sa mniejsze i czy ujemne sa wieksze
bool cmp(PII p1, PII p2, bool neg)
{
	int w = min(p1.second, p2.second);
	p1.second -= w; p2.second -= w;

	// spr czy mozesz bezpiecznie wymnozyc
	if (max(p1.second, p2.second) < LIM)
	{
		if (!neg)
			return p1.first*(1LL << p1.second) < p2.first*(1LL << p2.second);

		return p1.first*((p1.second % 2 ? -1 : 1)*(1LL << p1.second)) > p2.first*((p2.second % 2 ? -1 : 1)*(1LL << p2.second));
	}
	else // jesli reszta jest bardzo duza, to sprawdz czy nie ma jej w p1
		return !p1.second;
}


int main()
{
	vector<int> V;

	int N;
	scanf("%d", &N);
	REP(i, N)
	{
		int A;
		scanf("%d", &A);
		V.push_back(A);
	}

	// znajdz najdluzszy ciagly podciag niemalejacy - (dlugosc,poczatek)
	PII best(1, 0);
	for (int i = 0; i < N;)
	{
		int j = i + 1;
		while (j < N && V[j] >= V[j - 1])j++;

		best = max(best, MP(j - i, i));

		i = j;
	}

	int res = 0;

	{
		// od best do pierwszego wszystko malejace
		vector<PII> tmp;
		tmp.push_back(MP(V[best.second], 0));
		FORD(i, best.second, 0)
		{
			// tu pamietaj o nieparzystych
			PII p = MP(V[i], 0);

			if (!cmp(p, tmp.back(), 1))
			{
				tmp.push_back(p);
				continue;
			}

			p.second++;
			res++;
			while (cmp(p, tmp.back(), 1))
			{
				p.second += 2;
				res += 2;
			}

			tmp.push_back(p);
		}
	}

	{
		// od best do ostatniego wszystko rosnace
		vector<PII> tmp;
		tmp.push_back(MP(V[best.second + best.first - 1], 0));
		FOR(i, best.second + best.first, N)
		{
			PII p = MP(V[i], 0);
			while (cmp(p, tmp.back(), 0))
			{
				p.second += 2;
				res += 2;
			}

			tmp.push_back(p);
		}
	}

	printf("%d\n", res);

	return 0;
}

