void pop(vi &a, int n, vi &dp){
	rep(i,0,15) dd[n-1][i]=i; 
	dp[n-1]=0; 
	per(i,n-2,0){
		ll cur=a[i]; 
		ll nxt=a[i+1];
		int op=0; 
		rep(j,0,15){
			while(cur>nxt) { op++; nxt*=4; }
			dd[i][j]=j+((op<=15)?dd[i+1][op]:dd[i+1][15]+(op-15)*(n-1-i)); 
			cur<<=2; 
		}	
		dp[i]=2*dd[i][0]; 
	}
}

void solve(){
	int n; cin>>n; 
	vi a(n), dpl(n), dpr(n); 
	rep(i,0,n-1) cin>>a[i]; 	
	pop(a,n,dpr); 
	// rep(i,0,n-1) cout<<dpr[i]<<" " ; cout<<endl; 
	reverse(all(a)); 
	pop(a,n,dpl); 
	reverse(all(dpl)); 
	// rep(i,0,n-1) cout<<dpl[i]<<" " ; cout<<endl; 
	int ans=dpr[0]; 
	rep(i,1,n-1){
		ans=min(ans,dpr[i]+dpl[i-1]+i); 		
	}
	cout<<ans; 
}

int main() {
  clock_t beg=clock(); 
  boost;
  int t=1; 
  // cin>>t; 
  while(t--){
    solve(); 
  }
  clock_t end=clock(); 
  fprintf(stderr, "%lf\n", (double)(end-beg)/CLOCKS_PER_SEC);
}

