            exp_next--;
        }
        left[i] = left[i - 1] + 1;
        while(exp_end < exp_next || (exp_end == exp_next && fract_end < fract_next)){
            left[i] += 2 * (i - 1);
            exp_end += 2;
        }
        exp_end = exp_next;
        fract_end = fract_next;
