        long long exp_next = 0;
        while(fract_next < (1LL << 32LL)){
            fract_next <<= 1LL;
            exp_next--;
        }
        right[i] = right[i + 1];
        while(exp_end < exp_next || (exp_end == exp_next && fract_end < fract_next)){
