int N;
int64 a[MAXN];
int64 val[2][MAXN];
int64 s1[2][MAXN],s2[2][MAXN];
int64 calc(int l,int r,bool on) {
    if(!on) {
        return s2[0][r - 1] - s2[0][l - 1];
    }
    else {
        return (s1[1][r] - s1[1][l]) * (N + 1) - (s2[1][r] - s2[1][l]);
    }
}
void Solve() {
    read(N);
    for(int i = 1 ; i <= N ; ++i) read(a[i]);
    for(int i = 1 ; i < N ; ++i) {
        int64 t = a[i];
        while(t < a[i + 1]) {
            t *= 4;
            val[0][i] += 2;
        }
    }
    for(int i = N ; i > 1 ; --i) {
        int64 t = a[i];
        while(t < a[i - 1]) {
            t *= 4;
            val[1][i] += 2;
        }
    }
    for(int i = 1 ; i <= N ; ++i) {
        for(int l = 0 ; l <= 1 ; ++l) {
            s1[l][i] = s1[l][i - 1] + val[l][i];
            s2[l][i] = s2[l][i - 1] + val[l][i] * i;
        }
    }
    int64 ans = min(calc(1,N,0),calc(1,N,1));
    for(int i = 2 ; i <= N ; ++i) {
        ans = min(calc(1,i - 1,0) + (i - 1) + calc(i,N,1),ans);
    }
    out(ans);enter;
}
