      assert(jj==j);

      if(j<=15) dpr[i][x]=dpr[i+1][j]+x;
      else dpr[i][x]=dpr[i+1][15]+(LL)(N-1-i)*(j-15)+x;

      x4*=4;
    }
  }
  FOR(i,1,N) {
    LL x4=1;
    REP(x,16) {
      int j=0,jj=0;
      LL j4=1;
      while(A[i-1] * j4 < A[i] * x4) j4 *= 4,++j;
