      assert(j==jj);
      if(j<=15) dpl[i][x]=dpl[i-1][j]+x;
      else dpl[i][x]=dpl[i-1][15]+(LL)i*(j-15)+x;

      x4 *= 4;
    }
  }
  LL res=dpr[0][0]*2;
  FOR(i,1,N) SMIN(res,i+dpl[i-1][0]*2+dpr[i][0]*2);
