enum { inf = 1<<30 };

vector<int> calc(vector<i64> a)
{
    int n=size(a);
    struct info { int lp, cnt; };
    vector<info> s;
    s.push_back({n,inf});
    s.push_back({n-1,0});
    vector<int> ret{0,0};
    for(int k=n-1,tot=0; k--; )
    {
        int nc=s.back().cnt;
        {
            i64 nv=a[k];
            i64 pv=a[k+1];
            if(nv>pv)
            {
                while(nv>pv)
                {
                    pv*=4;
                    nc++;
                }
            }
            else
            {
                while(pv>=4*nv)
                {
                    nv*=4;
                    nc--;
                }
            }
        }
        while(nc>s.back().cnt)
        {
            int m=size(s);
            assert(m>1);
            int len=s[m-2].lp-s[m-1].lp;
            tot+=(nc-s.back().cnt)*len;
            s.pop_back();
        }
        s.push_back({k,nc});
        ret.emplace_back(tot);
    }
    assert(size(ret)==n+1);
    return ret;
}

