using namespace std;

long long dp0[200001][16];
long long dp1[200001][16];

long long calc_dp(long long dp[200001][16], int x, int p, vector<long long> &A){

    if(p < 16){
        if(dp[x][p] != -1)
            return dp[x][p];
        long long a = A[x] * (1LL << (2*p));
        long long b = A[x+1];
        long long pow = 0;
        while(a > b){
            while(a % 4 == 0 && b % 4 == 0){
                a /= 4;
                b /= 4;
            }
            b *= 4;
            pow++;
        }
        long long tmp = calc_dp(dp, x+1, pow, A);
        if(pow < 16)
            dp[x+1][pow] = tmp;
        return pow + tmp;
    }else{
        long long m = A.size()-x-1;
        dp[x][15] = calc_dp(dp, x, 15, A);
        return dp[x][15] + (p-15)*m;
    }
}

