#include<iostream>
#include<cstdint>
#include<stack>
#include<algorithm>
using namespace std;

const int MAX = 200001;
const int INF = 1073741823; // 10^30-1、使わない辺とかに用いる

int operate(int64_t l, int64_t r) { // 必要操作回数
	int ret = 0;
	while(l > r) {
		++ ret;
		r *= 4;
	}
	return ret;
}

struct graph {
	int A;
	int connect; // 自分より大きい、既にみたものの中で一番近い奴
	int num;
	int64_t pChange; // 正の方向と決め打った時の操作回数
	int64_t nChange; // 負の方向と決め打った時の操作回数
	void addChange(int right, int n) {
		pChange += operate(A, right) * n;
		num += n;
	}
	void addChange2(int left, int n) {
		nChange += operate(A, left) * n;
		num += n;
	}
};

int main() {
	int N;
	static graph A[MAX];
	cin >> N;
	A[0].A = INF; // A[0]さんはバグ防止の番兵として立ちはだかってもらう
	for (int i = 1;i <= N;++ i) cin >> A[i].A;

	stack<int> stk;
	stk.push(0);
	for (int i = 1;i <= N;++ i) {
		A[i].num = 1;
		A[i].pChange = 0;
		while (A[stk.top()].A <= A[i].A) stk.pop();
		A[i].connect = stk.top(); // 自分より大きい中で最も近い奴
		stk.push(i);
	}
	for (int i = N;i >= 1;-- i) A[A[i].connect].addChange(A[i].A, A[i].num);
	for (int i = N - 1;i >= 1;-- i) A[i].pChange += A[i + 1].pChange; // 累積和

	while(!stk.empty()) stk.pop(); // いったんstackを空にする
	stk.push(0);
	for (int i = N;i >= 1;-- i) {
		A[i].num = 1;
		A[i].nChange = 0;
		while (A[stk.top()].A <= A[i].A) stk.pop();
		A[i].connect = stk.top(); // 自分より大きい中で最も近い奴
		stk.push(i);
	}
	for (int i = 1;i <= N;++ i) A[A[i].connect].addChange2(A[i].A, A[i].num);
	for (int i = 2;i <= N;++ i) A[i].nChange += A[i - 1].nChange; // 累積和

	int64_t ans = INF;
	for (int i = 1;i <= N;++ i) ans = min(ans, i - 1 + (A[i].pChange + A[i].nChange) * 2);

	cout << ans;
	return 0;
}
/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり
また、コンテスト後に https://31536000.hatenablog.com/ で解説していると思うので、良かったら読んでねー

まず、ある値を境に負か正か変わる
ので、その境目をO(N)で決め打ってみる

面倒なので正の方向で考えると、境目を境にかならず単調増加な形になる
これはO(N)で求められるので、O(N^2)解は定まった
さて、次にこれの計算量を減らす必要がある
でも、これは単調増加なのを利用するとO(1)で求められるので実はO(N)
あ、いや前計算O(NlogA)があるので一応そっちが計算量になるね
*/

#include <iostream>
#include <string>
#include <vector>
#include <stack>
#include <algorithm>

using namespace std;
using ll = long long;
using pii = pair<int, int>;
static const int INF = 1000000000;

vector<ll> solve(const vector<ll>& a){
	const int n = a.size();
	vector<ll> incr(n);
	stack<pii> istack;
	istack.emplace(n, INF);
	for(int i = n - 2; i >= 0; --i){
		incr[i] = incr[i + 1];
		if(a[i + 1] < a[i]){
			for(ll j = 1; a[i + 1] * j < a[i]; j *= 4){
				while(istack.top().second == 0){ istack.pop(); }
				const auto t = istack.top();
				istack.pop();
				incr[i] += 2 * (t.first - i - 1);
				istack.emplace(t.first, t.second - 1);
			}
		}else{
			int margin = 0;
			for(ll j = 4; a[i] * j <= a[i + 1]; j *= 4){
				++margin;
			}
			istack.emplace(i + 1, margin);
		}
	}
	return incr;
}

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	cin >> n;
	vector<ll> a(n);
	for(int i = 0; i < n; ++i){ cin >> a[i]; }
	const auto positive = solve(a);
	reverse(a.begin(), a.end());
	auto negative = solve(a);
	reverse(negative.begin(), negative.end());
	ll answer = INF;
	for(int i = 0; i < n; ++i){
		answer = min(answer, negative[i] + i + positive[i]);
	}
	cout << answer << endl;
	return 0;
}

