#define int long long
#define rep(i, n) for(i = 0; i < n; i++)
using namespace std;

int INF = 1e+15;
int n;
int a[200000];
int b[200000];
int c[200000];
int costL[200001];
int costR[200001];

void calc(int *a, int *f) {
	static int ra[200000];
	static int r[200001];
	static int dp[200001];	//minA[i][j] = min(ra[i],…,ra[j])としたとき、dp[i] = sum(minA[i][j], j in i≦j<n), 0≦i≦n-1
	int i, j;

	//cout << "A = ";
	//for (i = 0; i < n; i++) cout << a[i] << " ";
	//cout << endl;

	ra[0] = a[0];
	for (i = 1; i < n; i++) ra[i] = ra[i - 1] + a[i];

	r[0] = 0;
	for (i = 1; i <= n; i++) r[i] = r[i - 1] + ra[i - 1];

	dp[n] = 0;
	for (i = n - 1; i >= 0; i--) {
		for (j = i + 1; j < n; j++) {
			if (ra[i] > ra[j]) break;
		}
		dp[i] = ra[i] * (j - i) + dp[j];
	}

	for (i = 0; i < n; i++) {
		int sumX = r[n] - r[i] - (n - i) * ra[i];
		int sumMinX = dp[i] - (n - i) * ra[i];
		f[i] = sumX - sumMinX;
	}
}

void reverse(int *a, int n) {
	int l = 0, r = n - 1;
	while (l < r) {
		swap(a[l], a[r]);
		l++; r--;
	}
}

signed main() {
	int i, j;

	cin >> n;
	rep(i, n) cin >> a[i];

	for (i = 1; i < n; i++) {
		int t = a[i];
		while (t < a[i - 1]) {
			t *= 4;
			b[i]++;
		}
		while (t >= a[i - 1] * 4) {
			t /= 4;
			b[i]--;
		}
	}

	for (i = n - 2; i >= 0; i--) {
		int t = a[i];
		while (t < a[i + 1]) {
			t *= 4;
			c[i]++;
		}
		while (t >= a[i + 1] * 4) {
			t /= 4;
			c[i]--;
		}
	}
	reverse(c, n);

	calc(c, costL);
	calc(b, costR);

	//マイナスをi個作る
	int ans = INF;
	for (i = 0; i <= n; i++) {
		int resL = costL[n - i] * 2 + i;
		int resR = costR[i] * 2;
		int res = resL + resR;
		ans = min(ans, res);
	}
	cout << ans << endl;
	return 0;
}

#include <iostream>
