ll f1(ll a , ll b){
  int cnt = 0;
  while(a < b)a *= 4,cnt += 2;
  return cnt;
}
ll f2(ll a , ll b){
  int cnt = 0;
  while(a > b)a *= 4,cnt += 2;
  return cnt;
}
int main() {
  cin >> n;
  for (int i = 1; i <= n; ++i){
    scanf("%lld",a+i);
    b[i] = a[i];
  }
  for (int i = n ; i >= 1 ; --i){
    b[i] = a[i];
    if(a[i] < 0)b[i] = a[i]*-2,suf[i]++;
    if(i==n)continue;
    ll go = f1(b[i+1],b[i]);
    suf[i] += suf[i+1]+go*(n-i);
  }
  for(int i = 1 ; i <= n ; ++i){
    b[i] = a[i];
    if(a[i]>0)b[i] = a[i]*-2,pre[i]++;
    if(i==1)continue;
    ll go = f2(b[i-1],b[i]);
    pre[i] += pre[i-1]+go*(i-1);
  }
  ll ans = min(pre[n],suf[1]);
  for(int i = 2 ; i <= n ; ++i)ans = min(ans,pre[i-1]+suf[i]);
  cout << ans << endl;
  return 0;
}

