#include <bits/stdc++.h>

using namespace std;

const int N = 1000 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
long long a[N], ldp[N], rdp[N];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 1; i <= n; ++i)
        cin >> a[i];

    return true;
}

void solve() {
    map<int, int> ids;

    for (int i = 1; i <= n; ++i) {
        ldp[i] = ldp[i - 1];

        for (auto x = a[i - 1]; i != 1 && x < a[i]; x *= 4)
            if (ids.empty()) {
                ldp[i] += 2 * (i - 1);
            } else {
                ldp[i] += 2 * (i - ids.rbegin()->first);

                if (--ids.rbegin()->second == 0)
                    ids.erase(--ids.end());
            }

        for (auto x = a[i]; i != 1 && 4 * x <= a[i - 1]; x *= 4)
            ++ids[i];
    }

    ids.clear();

    for (int i = n; i >= 1; --i) {
        rdp[i] = rdp[i + 1];

        for (auto x = a[i + 1]; i != n && x < a[i]; x *= 4)
            if (ids.empty()) {
                rdp[i] += 2 * (n - i);
            } else {
                rdp[i] += 2 * (ids.begin()->first - i);

                if (--ids.begin()->second == 0)
                    ids.erase(ids.begin());
            }

        for (auto x = a[i]; i != n && 4 * x <= a[i + 1]; x *= 4)
            ++ids[i];
    }

    auto ans = 1ll * MOD * MOD;

    for (int i = 0; i <= n; ++i)
        ans = min(ans, i + ldp[i] + rdp[i + 1]);

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

