int gt(long long x, int xd, long long y, int yd) {
	int dd = min(xd, yd);
	xd -= dd;
	yd -= dd;
	x <<= xd;
	y <<= yd;
	int res = 0;
	while (x > y) {
		y *= 4;
		res += 2;
	}
	return res;
}
int rf(int i) {
	if (rd[i].count(rm[i])) return rd[i][rm[i]];
	int &res = rd[i][rm[i]];
	res = rm[i];
	if (i == n - 1) {
		rc[i] = 1;
		return res;
	}
	int md = gt(a[i], rm[i], a[i+1], rm[i+1]);
	rc[i] |= rc[i+1] && md;
	if (rc[i+1]) {
		res += rf(i + 1) + md * (n - 1 - i);
	} else {
		rm[i+1] += md;
		res += rf(i + 1);
	}
	return res;
}
int lf(int i) {
	if (ld[i].count(lm[i])) return ld[i][lm[i]];
	int &res = ld[i][lm[i]];
	res = lm[i];
	if (i == 0) {
		lc[i] = 1;
		return res;
	}
	int md = gt(a[i], lm[i], a[i-1], lm[i-1]);
	lc[i] |= lc[i-1] && md;
	if (lc[i-1]) {
		res += lf(i - 1) + md * i;
	} else {
		lm[i-1] += md;
		res += lf(i - 1);
	}
	return res;
}
