int N;
vector<ll> A;

ll dp[200010][20];

int lg(ll A, int x, ll B) {
  for (int i = 0; i < x; i++) A *= 4;
  // A*4^x <= B*4^y
  for (int y = 0;; y++) {
    if (A <= B) {
      return y;
    }
    B *= 4;
  }
}

ll solve(int i, int x) {
  if (i == N - 1) return 0;
  if (x > 15) {
    return solve(i, 15) + (ll)(N - i - 1) * (x % 15);
  }
  ll& res = dp[i][x];
  if (res != -1) return res;
  int y = lg(A[i], x, A[i + 1]);
  return res = y + solve(i + 1, y);
}

int main() {
  while (cin >> N) {
    A.resize(N);
    for (int i = 0; i < N; i++) cin >> A[i];
    vector<ll> costA(N + 1, 0);
    {
      memset(dp, -1, sizeof(dp));
      for (int i = 0; i < N; i++) costA[i] = solve(i, 0) * 2;
    }
    vector<ll> costB(N + 1, 0);
    {
      reverse(A.begin(), A.end());
      memset(dp, -1, sizeof(dp));
      for (int i = 0; i < N; i++) costB[i] = solve(i, 0) * 2;
    }
    reverse(costB.begin(), costB.end());
    ll res = 1ll << 60;
    for (int i = 0; i <= N; i++) {
      ll cost = i + costA[i] + costB[i];
      res = min(res, cost);
    }
    cout << res << endl;
  }
  return 0;
}

