					x = q.front().second;
					q.pop();
				}
				f[i] += 1ll * (n - x) * cnt;
			}
			else
			{
				ll tmp = a[i];
				int cnt = 0;
				while (tmp * 4 <= a[i + 1])
				{
					tmp *= 4;
					cnt += 2;
				}
				if (cnt) q.push(pii(cnt, i));   
			}
		}
		while (!q.empty()) q.pop();
		g[1] = 1;
		b[1] = -a[1];
		for (int i = 2; i <= n; ++i)
		{
			g[i] = g[i - 1] + 1;
			b[i] = -a[i];
			if (b[i] < b[i - 1])
			{
				ll tmp = b[i - 1];
				int cnt = 0;
				while (tmp > b[i])
				{
					tmp *= 4;
					cnt += 2;
				}
				int x = i;
				while (!q.empty())
				{
					g[i] += 1ll * (x - q.front().second) * cnt; 
