                    dp[i] += p*(q.second-t);
                    q.first-=p;
                    st.push(q);
                    p = 0;
                }else{
                    dp[i] += p*(q.second-t);
                    p-= q.first;
                    t = q.second;
                }
            }
        }else{
            int p = calc(a[i+1],a[i]);
            st.push(MP(p,i+1));
        }
    }
    reverse(a.begin(),a.end());
    dp2[n-1] = 1;
    while(!st.empty()){
        st.pop();
    }
    for(int i=n-2;i>=0;i--){
        dp2[i] = dp2[i+1]+1;
        if(a[i]>a[i+1]){
            int p = calc(a[i],a[i+1]);
            int t = i; 
            while(p!=0){
                if(st.size()==0){
                    dp2[i] += p*(n-1-t);
                    p = 0;
                    break;
                }
                auto q = st.top();
                st.pop();
                if(q.first>p){
                    dp2[i] += p*(q.second-t);
                    q.first-=p;
                    st.push(q);
                    p = 0;
                }else{
                    dp2[i] += p*(q.second-t);
                    p-= q.first;
                    t = q.second;
                }
            }
        }else{
            int p = calc(a[i+1],a[i]);
            st.push(MP(p,i+1));
        }
    }
    ll ans = 1LL<<60;
