    // }
    // cerr << endl;
    ans = min(ans,dp[0]);
    ans = min(ans,dp2[0]);
    for(int i=1;i<n;i++){
        ans = min(ans,dp[i]+dp2[n-i]);
    }
    cout << ans << endl;
    return 0;
}

