bool cmp(ll af,ll ar,ll bf,ll br){
    ll vala=ar,valb=br;
    while(af<bf){
        if(ar<=br) break;
        br*=4;
        bf--;
    }
    while(af>bf){
        if(ar>=br) break;
        ar*=4;
        af--;
    }
    if(af==bf) return ar<br;
    else return af<bf;
}

void solve(bool minus,vector<ll> &res){
    vector<ll> B=A;
    if(minus) rep(i,N) B[i]*=2;
    else reverse(B.begin(),B.end());

    vector<pair<ll,ll>> four(N);
    rep(i,N){
        ll val=abs(B[i]);
        ll num=0;
        ll rest=0;
        while(val>0){
            val/=4;
            num++;
        }
        ll f=1;
        num--;
        rep(j,num) f*=4;
        rest=abs(B[i])-f;
        four[i]=mkp(num,rest);
        //cout<<i<<" "<<four[i].first<<" "<<four[i].second<<endl;
    }

    res.resize(N+1,0);
    ll pre=0;
    vector<int> back(N,0);
    rep(i,N) back[i]=i-1;
    vector<ll> diff(N,0);
    for(int i=1;i<N;i++){
        if(four[i-1]>=four[i]){
            res[i+1]=pre;
            continue;
        }

        int now=i;
        int ori=-1;
        ll sum=0;
        ll adv=(four[now].first-four[now-1].first);
        if(four[now-1].second<four[now].second) adv++;

        while(now>0){
            int tar=back[now];
            if(tar+1<now){
                if(tar>=0){
                    sum+=adv*(now-tar);
                    diff[tar]+=adv;
                }else sum+=adv*(now);
                back[i]=back[now];
                now=back[now];
            }else{
                ll nexadv=(four[now].first+diff[now]-(four[now-1].first+diff[now-1]));
                if(nexadv<0) break;
                diff[now-1]+=nexadv;
                if(cmp(diff[now-1],four[now-1].second,diff[now],four[now].second)){
                    diff[now-1]++;
                    nexadv++;
                };
                if(nexadv==0) break;
                adv=nexadv;
                //chmin(adv,nexadv);
                sum+=adv;
                back[i]=now-1;
                now=now-1;
            }
        }

        res[i+1]=pre+sum;
        pre+=sum;
    }

    if(minus==false) reverse(res.begin(),res.end());
    //rep(i,N+1) cout<<i<<" "<<res[i]<<endl;
}

