int dp[214514][16], rdp[214514][16],tdp[214514],trdp[214514];
signed main(){
	int n;
	cin>>n;
	if( n==1 ){ cout<<0<<endl; return 0; }
	vector<int> a,r;
	for(int i=0;i<n;i++){
		int x;
		cin>>x;
		a.pb(x); r.pb(x);
	}
	reverse( r.begin(), r.end() );
	for(int i=0;i<n;i++){
		tdp[i] = LINF;
		trdp[i] = LINF;
		for(int j=0;j<=15;j++){
			dp[i][j] = LINF;
			rdp[i][j] = LINF;
		}
	}
	for(int i=0;i<=15;i++){
		dp[n-1][i] = i;
	}
	for(int i=n-2;i>=0;i--){
		int cur = a[i];
		for(int j=0;j<=15;j++){
			int nex = a[i+1];
			int cnt = 0;
			while( cur > nex ){
				cnt ++ ;
				nex <<= 2;
			}
			if( cnt <= 15 ){
				dp[i][j] = dp[i+1][cnt] + j;
			}
			else{
				dp[i][j] = dp[i+1][15] + (cnt-15)*(n-i-1) + j;
			}
			cur *= 4;
		}
	}
	for(int i=0;i<=15;i++){
		rdp[n-1][i] = i;
	}
	for(int i=n-2;i>=0;i--){
		int cur = r[i];
		for(int j=0;j<=15;j++){
			int nex = r[i+1];
			int cnt = 0;
			while( cur > nex ){
				cnt ++ ;
				nex <<= 2;
			}
			if( cnt <= 15 ){
				rdp[i][j] = rdp[i+1][cnt] + j;
			}
			else{
				rdp[i][j] = rdp[i+1][15] + (cnt-15)*(n-i-1) + j;
			}
			cur *= 4;
		}
	}
	int ans = LINF;
	for(int i=0;i<n;i++){
		for(int j=0;j<=15;j++){
			tdp[i] = min(tdp[i],dp[i][j]);
			trdp[i] = min(trdp[i],rdp[i][j]);
		}
	}
	ans = min(ans,2*tdp[0]);
	//cout<<0<<" "<<2*tdp[0]<<" "<<0<<endl;
	for(int i=1;i<=n-1;i++){
		ans = min( ans, 2*tdp[i]+2*trdp[n-i]+i );
		//cout<<i<<" "<<2*tdp[i]<<" "<<2*trdp[n-i]<<endl;
	}
	ans = min(ans, 2*trdp[0] + n); 
	//cout<<n<<" "<<0<<" "<<2*trdp[0]<<endl;
	cout<<ans<<endl;
	return 0;
}

