void Calc(int a[], bool b)
{
	int i;

	fr(i,0,16)
	{
		if(b) pdp[n][i] = 2*i;
		else sdp[1][i] = 2*i;
	}

	fr(i, 2, n + 1)
	{
		int j;
		fr(j,0,16)
		{
			int x = a[i]*(1<<(2*j));
			int temp = inf;
			int k;
			fr(k,0,16)
			{
				if(a[i - 1]*(1<<(2*k)) >= x)
				{
					temp = min(temp, b?pdp[n - i + 2][k]:sdp[i - 1][k]);
				}
			}

			if(temp >= inf)
			{
				int y = a[i - 1]*(1<<30);
				int cnt = 0;
				while(y < x)
				{
					cnt++;
					y*=4;
				}
				temp = b*(pdp[n - i + 2][15] + j +cnt*(n - i)) + !b*(sdp[i - 1][15] + j +cnt*(i - 1));
			}

			if(b)pdp[n - i + 1][j] = temp + 2*j;
			else sdp[i][j] = temp + 2*j;
		}
	}
