int f[N], invf[N], inv2, inv3, a[N], b[N], pr[N], len[N], dp[2][N], n;
int nxt(int x){
    if (x == pr[x]) return x;
    return pr[x] = nxt(pr[x]);
}
void solve(int k){
    for (int i = 1; i <= n; i++){
        pr[i] = i;
        len[i] = 0;
        b[i] = 0;
    }
    dp[k][n] = 0;
    b[n] = 1e9;
  //  cout << "K = " << k << endl;
    for (int i = n - 1; i >= 1; i--){
        int x = a[i];
        if (x <= a[i + 1]){
            int c = 0;
            while(x + x + x + x <= a[i + 1]){
                c++;
                x += 3 * x;
            }
            if (c == 0){
                pr[i] = nxt(i + 1);
                len[pr[i]]++;
            } else b[i] = c;
            dp[k][i] = dp[k][i + 1];
           // cout << "! i = " << i << " " << dp[k][i] << endl;
        } else{
            int p = i + 1;
            int c = 0;
            int y = a[i + 1];
            while(y < x){
                y += 3 * y;
                c++;
            }
            int res = 0;
           // cout << "c = " << c << endl;
            while(p != n + 1){
                res += c * len[nxt(p)];
              //  cout << p << " -- " << nxt[p] << " " << nxt[4] << endl;
                p = nxt(p);
                if (p == 0) exit(0);
                if (b[p] > c){
                    res += c;
                    b[p] = b[p] - c;
                    c = 0;
                    break;
                } else
                if (b[p] <= c){
                    res += c;
                    c -= b[p];
                    b[p] = 0;
                   // cout << p << " qq " << nxt[p] << " " << b[5] << endl;
                    int z = len[nxt(p)];
                    pr[p] = nxt(p + 1);
                    len[nxt(p)] += z + 1;
                }
                res += c;
                p++;
              //  cout << i << " " << p << endl;
            }

            pr[i] = nxt(i + 1);
            len[nxt(i)]++;
            dp[k][i] = dp[k][i + 1] + res;
           // cout << "i = " << i << " " << dp[k][i] << endl;
        }
    }
}
