struct BIT {
	vector<int> bit;
	int n;

	BIT(int N) :n(N + 2), bit(N * 2) {}

	int sum(int i) {
		++i;
		int s = 0;
		while (i > 0) {
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, int x) {
		++i;
		while (i <= n) {
			bit[i] += x;
			i += i & (-i);
		}
	}
};

// x^n % mod
// O(log n)
template<typename T>
T mod_pow(T x, T n, T mod) {
	T res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % mod;
		x = x*x %mod;
		n >>= 1;
	}
	return res;
}


// x^n % mod
// O(log n)
template<typename T>
T Pow(T x, T n) {
	T res = 1;
	while (n > 0) {
		if (n & 1) res = res * x;
		x = x*x;
		n >>= 1;
	}
	return res;
}

void solve()
{
	int N; cin >> N;
	vector<int> A(N);
	REP(i, N) {
		int a; cin >> a;
		A[i] = a;
	}

	vector<vector<int> > dpRight(N, vector<int>(16));
	RFOR(i, 0, dpRight.size() - 1) {
		REP(j, dpRight[i].size()) {
			auto left = A[i] * Pow<int>(4, j);
			auto right = A[i + 1]; // left <= right
			int cnt = 0;
			while (left > right) {
				right *= 4;
				++cnt;
			}
			int index = min(cnt, static_cast<int>(dpRight[i].size() - 1));
			dpRight[i][j] = dpRight[i + 1][index] + cnt;
			if(cnt > index) dpRight[i][j] += (cnt - index) * (N-1-i);
		}
	}

	vector<vector<int> > dpLeft(N, vector<int>(16));
	FOR(i, 1, dpLeft.size()) {
		REP(j, dpLeft[i].size()) {
			auto left = A[i-1];
			auto right = A[i] * Pow<int>(4,j);
			int cnt = 0;
			while (left < right) {
				left *= 4;
				++cnt;
			}
			int index = min(cnt, static_cast<int>(dpLeft[i].size() - 1));
			dpLeft[i][j] = dpLeft[i - 1][index] + cnt;
			if(cnt > index) dpRight[i][j] += (cnt - index) * (i);
		}
	}

	int ans = min(dpLeft.back()[0]*2 + N,dpRight.front()[0]*2);
	REP(i, N-1) {
		auto left = i;
		auto right = i + 1;
		ans = min((dpLeft[left][0] + dpRight[right][0])*2 + (i + 1), ans);
	}
	cout << ans << endl;
}

