	p1[0] = 0;
	v1.push_back({ 0, 1 });
	for (int i = 1; i < N; i++) {
		p1[i] = p1[i - 1];

		if (A[i - 1] >= A[i]) {
			int d = A[i - 1] / A[i];
			int digit = -2;

			while (d > 0) { d /= 4; digit += 2; }
			if (digit == 0) {
				pair<int,ll> p = v1.back();
				v1.pop_back();

				p.second++;
				v1.push_back(p);
			}
			else {
				v1.push_back({ digit, 1 });
			}
		}
		else {
			ll a = A[i - 1], b = A[i];
			while (a < b) {
				a *= 4;

				pair<int, ll> p = v1.back();
				v1.pop_back();

				p1[i] += p.second * 2;
				p.first -= 2;

				if (v1.size() == 0) {
					v1.push_back(p);
				}
				else {
					if (p.first == 0) {
						v1[v1.size() - 1].second += p.second;
					}
					else {
						v1.push_back(p);
					}
