			v1[v1.size() - 1].second++;
		}
	}

	p2[0] = 0;
	v2.push_back({ 0, 1 });
	for (int i = 1; i < N; i++) {
		p2[i] = p2[i - 1];

		if (B[i - 1] >= B[i]) {
			int d = B[i - 1] / B[i];
			int digit = -2;

			while (d > 0) { d /= 4; digit += 2; }
			if (digit == 0) {
				pair<int, ll> p = v2.back();
				v2.pop_back();

				p.second++;
				v2.push_back(p);
			}
			else {
				v2.push_back({ digit, 1 });
			}
		}
		else {
			ll a = B[i - 1], b = B[i];
			while (a < b) {
				a *= 4;

				pair<int, ll> p = v2.back();
				v2.pop_back();

				p2[i] += p.second * 2;
				p.first -= 2;

				if (v2.size() == 0) {
					v2.push_back(p);
				}
				else {
					if (p.first == 0) {
						v2[v2.size() - 1].second += p.second;
					}
					else {
						v2.push_back(p);
					}
				}

			}
			v2[v2.size() - 1].second++;
		}
	}

	ll ans = min(p1[N - 1] + N, p2[N - 1]);
