void fix(deque<ii> &dq)
{
	while(dq.size()>=2&&dq[0].fi==0&&dq[1].fi==0)
	{
		dq[1].se+=dq[0].se;
		dq.pop_front();
	}
}

ll sub(deque<ii> &dq)
{
	if(dq.empty()) return 0;
	if(dq[0].fi>0)
	{
		dq[0].fi--;
		fix(dq); return 1;
	}
	ll ans = dq[0].se;
	if(dq.size()>=2)
	{
		dq[1].fi--; ans++;
	}
	fix(dq);
	return ans;
}

