int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);
    long N;
    cin >> N;
    VL A(N),Am(N);
    VVL dp1(N,VL(16,0)),dp2(N,VL(16,0));
    VL pow4(16,4);
    REP(i,N) {
        cin >> A[i];
        Am[i] = (-2) *  A[i];
    }
    REP(i,16) {
        dp1[N-1][i] = i;
        dp2[0][i] = i;
    }
    pow4[0] = 1;
    REP(i,15) pow4[i+1] *= pow4[i];
    for (long l = N-2;l >= 0;l--) {
        REP(x,16) {
            if (pow4[x] * A[l] <= A[l+1]) dp1[l][x] = dp1[l+1][0] + x;
            else {
                LL k = ceil(log(pow4[x]*A[l]/A[l+1])/log(4));
                if (k > 15) dp1[l][x] = dp1[l+1][15] + (N-l+1) * (k-15);
                else dp1[l][x] = dp1[l+1][k] + x;
            }
        }
    }
    for (long l = 1;l < N;l++) {
        REP(x,16) {
            if (pow4[x] * Am[l] >= Am[l-1]) {
                dp2[l][x] = dp2[l-1][0] + x;
            }
            else {
                LL k = ceil(log(pow4[x]*Am[l]/Am[l-1])/log(4));
                if (k > 15) dp2[l][x] = dp2[l-1][15] + (l+1) * (k-15);
                else dp2[l][x] = dp2[l-1][k] + x;
            }
        }
    }

    LL ans = min(2*dp1[0][0],2*dp2[N-1][0] + N);
    FOR(i,1,N-1) {
        ans = min(ans,i+2*(dp1[i][0]+dp2[i-1][0]));
    }

    cout << ans << endl;
}

