class ValueMonoid{
public:
    using value_type = int64;
    static value_type identity(){ return INF; }
		static value_type initializer(){ return 0; }
    static value_type operation(value_type a, value_type b){
        return min(a, b);
    }
};

class OpMonoid{
public:
    using value_type = int;
    static value_type identity(){ return INF; }
    static value_type operation(value_type a, value_type b){
        return a+b;
    }
};

class Modifier{
public:
    static ValueMonoid::value_type operation(
            ValueMonoid::value_type a, OpMonoid::value_type b){
        return a+b;
    }
};
