int main(void){
	int32 N;
	cin >> N;
	vector<ld> A(N);
	REP(i, N) cin >> A[i];
	ld pa = 1, pb = 0;
	int64 res = INF_LL, sum = 0;
	vector<int32> cost(N+1, 0);
	pa = INF; pb = 0;
	for(int32 i = N-1;i >= 0;i--){
		ld c = log2(A[i])-log2(pa)-pb;
		int32 x = max(0, (int)ceil(c));
		if(x%2) x++;
		cost[i] = cost[i+1]+x*(N-i-1);
		pa = A[i]; pb = 0;
	}
	res = cost[0];
	sum = cost[0];
	pa = INF_LL; pb = 0;
	REP(i, N){
		ld c = log2(A[i])+1-log2(pa)-pb;
		int32 x = max(0, (int)ceil(c));
		sum += x*i+1-cost[i]+cost[i+1];
		res = min(res, sum);
	}
	cout << res << endl;
}

