using namespace std;
long long positive[300001], negative[300001];
long long N, A[300000];

int main(void) {
	long long L, X, Y;
	//i = 0,...,N (N+1個の値を取る)
	//positive[i]は、A[N-i]からA[N-1]までをすべて正で昇順に並べるのにかかる手数
	//negative[i]は、A[0]からA[i-1]までをすべて負で昇順に並べるのにかかる手数
	scanf("%d", &N);
	for (int i = 0; i < N; i++) {
		scanf("%d", &A[i]);
	}

	//positiveの計算
	positive[0] = 0;
	positive[1] = 0;

	for (int i = 2; i < N + 1; i++) {
		//A[N-i]とA[N-i+1]を比較。A[N-i+1]を何回4倍すればA[N-i]以上になるか？
		L = 0;
		X = A[N - i];
		Y = A[N - i + 1];
		while (X > Y) {
			Y = 4 * Y;
			L = L + 2;
		}
		positive[i] = positive[i - 1] + L * (i - 1);
	}
	//negativeの計算
	negative[0] = 0;
	negative[1] = 1;

	for (int i = 2; i < N + 1; i++) {
		//A[i-2]とA[i-1]を比較。
		L = 0;
		X = A[N - i];
		Y = A[N - i + 1];
		while (X < Y) {
			X = 4 * X;
			L = L + 2;
		}
		negative[i] = negative[i - 1] + L * (i - 1) + 1;
	}

	long long ans = positive[0] + negative[N];

	for (int i = 0; i < N + 1; i++) {
		printf("pos %lld neg %lld\n", positive[i], negative[i]);
		if (ans > positive[i] + negative[N - i]) {
			ans = positive[i] + negative[N - i];
		}
	}
	printf("%lld\n", ans);
}

#include <bits/stdc++.h>
using i64 = long long;

i64 dp[200010][20];
i64 dp2[200010][20];
int n;

i64 get(int l, i64 x) {
    if (x < 15) return dp[l][x];
    return dp[l][15] + (x - 15) * (n - l + 1);
}

i64 get2(int l, i64 x) {
    if (x < 15) return dp2[l][x];
    return dp2[l][x] + (x - 15) * (n - l + 1);
}

int main() {
    std::cin >> n;
    std::vector<i64> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    for (int i = 0; i < 16; i++) {
        dp[n - 1][i] = i;
        dp2[0][i] = i;
    }

    for (int l = n - 2; l >= 0; l--) {
        i64 cc = a[l];
        i64 dd = a[l + 1];
        i64 cnt = 0;
        for (int x = 0; x < 16; x++) {
            if (x) {
                cc *= 4;
            }
            while (dd < cc) {
                dd *= 4;
                cnt++;
            }
            dp[l][x] = x + get(l + 1, cnt);
        }
    }

    for (int l = 1; l < n; l++) {
        i64 cc = a[l];
        i64 dd = a[l - 1];
        i64 cnt = 0;
        for (int x = 0; x < 16; x++) {
            if (x) {
                cc *= 4;
            }
            while (dd < cc) {
                dd *= 4;
                cnt++;
            }
            dp2[l][x] = x + get2(l - 1, cnt);
        }
    }

    auto ret = 2 * get(0, 0);
    for (int i = 0; i < n; i++) {
        // [0, i] are all negative
        auto curr = i + 1 + 2 * get2(i, 0) + 2 * get(i + 1, 0);
        ret = std::min(ret, curr);
    }

    std::cout << ret << std::endl;

    return 0;
}

