#define mp make_pair
#define maxn 200005
using namespace std;
typedef long long ll;
typedef pair<int,int> P;
const int inf = 0x3f3f3f3f;
int n; ll a[maxn];
int fir[maxn],lst[maxn];
P pos[maxn];//id,val.
int ta;
int dif(ll x,ll y){
	int cnt = 0;
	while(x <= y){
		x <<= 2;
		cnt++;
	}
	return cnt - 1;
}
int mul4(int x){
	int ret = pos[ta].first - x + 1;
	pos[ta].second--;
	if(pos[ta].second == 0) ta--;
	return ret;
}
int main(){
	scanf("%d",&n);
	for(int i=1;i<=n;i++) scanf("%lld",&a[i]);
	lst[n] = 0;
	pos[++ta] = mp(n,inf);
	for(int i=n - 1;i>=1;i--){
		lst[i] = lst[i + 1];
		if(a[i] <= a[i + 1]){
			int val = dif(a[i],a[i + 1]);
			if(val) pos[++ta] = mp(i,val);
		}else{
			ll tmp = a[i + 1];
			while(tmp < a[i]){
				lst[i] += mul4(i + 1) * 2;
				tmp <<= 2;
			}
		}
	}
	for(int i=1;i<=n;i++) a[i] *= 2;
	reverse(a + 1,a + n + 1);
	ta = 0;
	fir[n] = 0;
	pos[++ta] = mp(n,inf);
	for(int i=n - 1;i>=1;i--){
		fir[i] = fir[i + 1];
		if(a[i] <= a[i + 1]){
			int val = dif(a[i],a[i + 1]);
			if(val) pos[++ta] = mp(i,val);
		}else{
			ll tmp = a[i + 1];
			while(tmp < a[i]){
				fir[i] += mul4(i + 1) * 2;
				tmp <<= 2;
			}
		}
	}
	reverse(fir + 1,fir + n + 1);
	for(int i=1;i<=n;i++) fir[i] += i;
	int ans = inf;
	for(int i=1;i<=n + 1;i++){
		ans = min(ans,fir[i - 1] + lst[i]);
	}
	printf("%d\n",ans);
	return 0;
}

