int main(){
    int N;
    cin >> N;
    int A[N];
    for (int i=0;i<N;i++) cin >> A[i];

    long long B[N];
    B[0] = 0;
    for (int i=1;i<N;i++) {
        float frac = (float) A[N-1-i]/ (float) A[N-i];
        //cout << frac << endl;
        if (frac<=1) B[i] = B[i-1];
        else {
            int k = 1;
            while (pow(4,k)<frac) k += 1;
            B[i] = B[i-1] + 2*k*i;
        }
    }
    /*cout << "B : ";
    for (int i=0;i<N;i++) cout << B[i] << " ";
    cout << endl;*/

    long long C[N];
    C[0] = 0;
    for (int i=1;i<N;i++) {
        float frac = (float) A[i]/(float) A[i-1];
        //cout << frac << endl;
        if (frac<=1) C[i] = C[i-1];
        else {
            int k = 1;
            while (pow(4,k)<frac) k += 1;
            C[i] = C[i-1] + 2*k*i;
        }
    }
    /*cout << "C : ";
    for (int i=0;i<N;i++) cout << C[i] << " ";
    cout << endl;*/

    int D = B[N-1];
    int min = D;
    for (int i=1;i<N;i++) {
        D = i*1 + C[i-1] + B[N-i-1];
        //cout << D << endl;
        if (min>D) min = D;
    }
    D = N*1 + C[N-1];
    if (min>D) min = D;

    cout << min << endl;

    return 0;
}

