  for (int i = n - 1; i > 0; i--) {
    if (a[i] < a[i - 1]) {
      long long k = 4, j = 2;
      while (a[i - 1] > a[i] * k) {
        k *= 4;
        j += 2;
      }
      af += j * (n - i);
    }
    afs[i - 1] = af;
  }
