int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;
    vector<ll> a(n);
    for (int i = 0; i < n; i++)
    {
        int tmp;cin>>tmp;
        a[i] = tmp;
    }
    // dp0[i][j] := 左から降順にして,i番目をj回4倍するときの最小回数
    vector<vector<int>> dp0(n, vector<int>(16, 1e9)), dp1(n, vector<int>(16, 1e9));
    for (int j = 0; j <= 15; j++)
    {
        dp0[0][j] = j;
        dp1[n - 1][j] = j;
    }
    for (int i = 1; i < n; i++)
    {
        for (int j = 0; j <= 15; j++)
        {
            for (int k = 0; k <= 15; k++)
            {
                // a[i-1] * 4^k, a[i] * 4^j
                ll pre = a[i - 1] << (2 * (k - min(j, k)));
                ll cur = a[i] << (2 * (j - min(j, k)));
                int cnt = 0;
                while (pre < cur)
                {
                    cnt += i;
                    pre *= 4;
                }
                dp0[i][j] = min(dp0[i][j], dp0[i - 1][k] + cnt + j);
            }
        }
    }
    for (int i = n - 2; i >= 0; i--)
    {
        for (int j = 0; j <= 15; j++)
        {
            for (int k = 0; k <= 15; k++)
            {
                // a[i+1] * 4^k, a[i] * 4^j
                ll pre = a[i + 1] << (2 * (k - min(j, k)));
                ll cur = a[i] << (2 * (j - min(j, k)));
                int cnt = 0;
                while (cur > pre)
                {
                    cnt += n - i - 1;
                    pre *= 4;
                }
                dp1[i][j] = min(dp1[i][j], dp1[i + 1][k] + cnt + j);
            }
        }
    }
    int ret = min(2 * dp1[0][0], 2 * dp0[n - 1][0] + n);
    // i 番目から正
    for (int i = 1; i < n; i++)
    {
        ret = min(ret, 2 * dp0[i - 1][0] + i + 2 * dp1[i][0]);
    }
    cout << ret << endl;
}

