LL getNeedShift(LL v1, LL v2){
    LL cnt = 0;
    if(v1 <= v2){
        while(v1 * 4 <= v2){
            v1 <<= 2;
            cnt--;
        }
    }else{
        while(v2 < v1){
            v2 <<= 2;
            cnt++;
        }
    }
    return cnt;
}

vector<vector<LL>> calcOpCnt(vector<LL>& a){
    const LL LIM = 16;
    LL n = a.size();
    vector<vector<LL>> res(n, vector<LL>(LIM));
    for(LL j = 0; j < LIM; ++j){
        res[n-1][j] = j;
    }

    for(LL i = n-2; i >= 0; --i){
        LL s = getNeedShift(a[i], a[i+1]);
        for(LL j = 0; j < LIM; ++j){
            if(j + s >= LIM){
                res[i][j] = res[i+1][LIM-1] + (j + s - (LIM-1)) * (n-1 - i) + j;
            }else{
                res[i][j] = res[i+1][max<LL>(0, j + s)] + j;
            }
        }
    }
    return res;
}

