    vector<LL> b(a.begin(), a.end());
    reverse(b.begin(), b.end());

    vector<vector<LL>> right = calcOpCnt(a);
    vector<vector<LL>> left = calcOpCnt(b);
    reverse(left.begin(), left.end());
    LL ans = right[0][0]*2;
    for(LL i = 1; i < n; ++i){
        LL cand = right[i][0]*2 + left[i-1][0]*2 + i;
        //cerr << i << " : " << right2[i] << " " << left2[i] << " " << cand << endl;
        ans = min(ans, cand);
    }
    //cerr << right2 << endl;
    //cerr << left2 << endl;
    cout << ans << endl;

    return 0;
}

