using int64 = long long;
const int64 INF = 1LL << 60;


vector< int64 > solve(vector< int64 > A) {
  int N = (int) A.size();
  stack< int > st;
  vector< int64 > result(N);
  int64 ret = 0;

  st.emplace(N - 1);
  for(int i = (int) A.size() - 2; i >= 0; i--) {

    while(A[i] > A[i + 1]) {
      A[i + 1] *= 4;
      int r = st.top();
      st.pop();
      if(i + 1 != r) A[r] *= 4;
      ret += (r - i) * 2;
      if(r + 1 == N || A[r] * 4 <= A[r + 1]) st.emplace(r);
    }
    if(A[i] * 4 <= A[i + 1]) st.emplace(i);
    result[i] = ret;
  }
  return result;
}


