  for(int i = 0; i < N; i++) {
    A[i] *= 2;
  }
  reverse(begin(A), end(A));
  auto pre = solve(A);
  reverse(begin(pre), end(pre));
  int64 ret = min(pre[N - 1] + N, suf[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, pre[i - 1] + suf[i] + i);
  }
  cout << ret << endl;
}

