void calc(int *a, int *f) {
	int i, j;

	for (i = 0; i < n; i++) {
		int x = 0;
		int minX = 0;
		int sumX = 0;
		int sumMinX = 0;
		for (j = i + 1; j < n; j++) {
			x = x + a[j];
			minX = min(minX, x);
			sumX += x;
			sumMinX += minX;
		}
		f[i] = sumX - sumMinX;
	}
}

void reverse(int *a, int n) {
	int l = 0, r = n - 1;
	while (l < r) {
		swap(a[l], a[r]);
		l++; r--;
	}
}

