int dp[200002][100];

bool limitOk(ll x) {
  if (x >= LIMIT || x <= -LIMIT) {
    return false;
  }
  return true;
}

int dfs(int idx, int preMul) {
  if (idx == n) {
    return 0;
  }
  if (dp[idx][preMul] != -1) {
    return dp[idx][preMul];
  }

  ll preVal = a[idx - 1] * mul[preMul];
  int res = NOTHING;

  if (preVal >= a[idx]) {
    ll curVal = a[idx];
    int cnt = 0;

    for (int i = 0; i < 63; i += 2) {
      ll curVal = a[idx] * mul[i];
      if (!limitOk(curVal)) {
        break;
      }
      if (curVal >= preVal) {
        res = min(res, dfs(idx + 1, i) + i);
        break;
      }
    }
  } else {
    res = min(res, dfs(idx + 1, 0));

    for (int i = 1; i < 63; i += 2) {
      ll curVal = a[idx] * mul[i];
      if (!limitOk(curVal)) {
        break;
      }
      if (curVal < preVal) {
        break;
      }

      res = min(res, dfs(idx + 1, i) + i);
    }
  }

  return dp[idx][preMul] = res;
}

