          if (now <= nxt) {
            if (k <= len)
              dp[i][j] = dp[i + 1][k] + j;
            else
              dp[i][j] = dp[i + 1][len] + (k - len) * (n - 1 - i) + j;
            break;
          }
          nxt <<= 2;
        }
        now <<= 2;
      }
      res[i] = dp[i][0] << 1;
    }
    return res;
