#include <bits/stdc++.h>
using namespace std;

typedef long long llt;
typedef pair<llt, llt> pll;

const int MaxN = 200000 + 5;
const llt INF = 0x7F7F7F7F7F7F7F7F;

int N;
pll A[2][MaxN];
llt dp[2][MaxN];
int par[MaxN];

void init() {
    scanf("%d", &N);
    for (int i = 1; i <= N; ++i) {
        scanf("%lld", &A[1][i].first);
        A[0][i].first = A[1][i].first * 2;
    }
}

int Find(int x) {
    return x == par[x] ? x : par[x] = Find(par[x]);
}

// x <= y -> true  x > y -> false;
inline bool cmp(pll x, pll y) {
    if (x.second == y.second) return x.first <= y.first;
    else if (x.second <= y.second) {
        for (llt i = y.second; i > x.second; --i) {
            y.first *= 4;
            if (y.first >= x.first) return true;
        }
        return x.first <= y.first;
    } else {
        for (llt i = x.second; i > y.second; --i) {
            x.first *= 4;
            if (x.first > y.first) return false;
        }
        return x.first <= y.first;
    }
}

void solve() {
    for (int i = 1; i <= N; ++i) par[i] = i;
    dp[0][1] = 0;
    for (int i = 2; i <= N; ++i) {
        pll x = A[0][i]; dp[0][i] = dp[0][i - 1];
        if (cmp(x, A[0][i - 1]) == true) continue;
        while (cmp(x, A[0][i - 1]) == false) {
            int p = Find(i - 1);
            A[0][p].second++; A[0][i - 1].second++;
            while (p != 1 && cmp(A[0][p], A[0][p - 1]) == false) {
                int g = Find(p - 1);
                par[p] = g;
                A[0][g].second++;
                p = g;
            }
            dp[0][i] += (i - p) * 2;
        }
    }

    for (int i = 1; i <= N; ++i) par[i] = i;
    dp[1][N] = 0;
    for (int i = N - 1; i >= 1; --i) {
        pll x = A[1][i]; dp[1][i] = dp[1][i + 1];
        if (cmp(x, A[1][i + 1]) == true) continue;
        while (cmp(x, A[1][i + 1]) == false) {
            int p = Find(i + 1);
            A[1][p].second++; A[1][i + 1].second++;
            while (p != N && cmp(A[1][p], A[1][p + 1]) == false) {
                int g = Find(p + 1);
                par[p] = g;
                A[1][g].second++;
                p = g;
            }
            dp[1][i] += (p - i) * 2;
        }
    }

    llt ans = INF;
    for (int i = 0; i <= N; ++i) ans = min(ans, dp[0][i] + i + dp[1][i + 1]);
    cout << ans << endl;
}

int main() {
    init();
    solve();
    return 0;
}

