typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 29;
const int MOD = 1e9 + 7;

struct Node {
  int u, v, e;
  Node(int u, int v, int e): u(u), v(v), e(e) {}
};

void solve(const vector<int64>& a, vector<int64>& L) {
  int n = a.size();
  vector<Node> A;
  L[0] = 0;
  A.emplace_back(0, 1, 0);
  for (int i = 1; i < n; ++i) {
    L[i] = L[i - 1];
    if (a[i] <= a[i - 1]) {
      if (a[i] * 4 <= a[i - 1]) {
        A.emplace_back(i, i + 1, 0);
      } else {
        auto& t = A.back();
        t.v += 1;
        t.e = 0;
      }
    } else {
      for (auto& it : A) {
        int64 x = a[it.v - 1], cnt = 0;
        while (a[i] > x) {
          x *= 4;
          cnt += 2;
        }
        L[i] += (it.v - it.u) * (cnt - it.e);
        it.e = cnt;
      }
      auto& t = A.back();
      t.v += 1;
      t.e = 0;
    }
  }
}

int main() {
  int n;
  scanf("%d", &n);
  vector<int64> a(n);
  for (int i = 0; i < n; ++i) {
    scanf("%lld", &a[i]);
  }
  vector<int64> L(n), R(n);
  solve(a, L);
  reverse(a.begin(), a.end());
  solve(a, R);
  reverse(R.begin(), R.end());
  int64 ret = min(R[0], L[n - 1] + n);
  // trace(ret);
  for (int i = 1; i < n; ++i) {
    ret = min(ret, L[i - 1] + R[i] + i);
    // trace(i, L[i - 1], R[i]);
  }
  printf("%lld\n", ret);
  return 0;
}

