	vector<ll> A(N + 1);
	repn(i, N) cin >> A[i];

	vector<ll> pos(N + 2,0), neg(N + 2,0);

	for (ll i = N - 1; i >= 1; i--) {
		ll c = 0;
		for (ll x = A[i + 1]; A[i] > x; x *= 4) {
			c++;
		}

		pos[i] = pos[i + 1] + 2*c * (N - i);
		//cout << i<<" "<<pos[i] << endl;
	}


	for (ll i = 2; i <= N; i++) {
		ll c = 0;
		for (ll x = A[i - 1]; A[i] > x; x *= 4) {
			c++;
		}

		neg[i] = neg[i - 1] + 2*c * (i - 1);
		//cout << i << " " << neg[i] << endl;
	}

	ll ans = INF;
	rep(i, N + 1) {
		ans = min(ans, i+neg[i] + pos[i + 1]);
