#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef pair <ll, int> pii;

const int MAXN = 2e5 + 5;
const ll INF = 1e18;

int N;
int a[MAXN];
int even[MAXN], odd[MAXN];
ll suff[MAXN];
ll cum[MAXN], cumcum[MAXN];
stack <int> rig;
stack <pii> lft;

void load() {
	scanf("%d", &N);
	for (int i = 1; i <= N; i++)
		scanf("%d", a + i);
}

int div2(int x) {
	if (x >= 0 || !(x % 2))
		return x / 2;
	return (x - 1) / 2;
}

ll solve() {
	for (int i = 1; i < N; i++) {
		double tmp = log2((double)a[i] / a[i + 1]);
		even[i] = div2(ceil(tmp) + 1);
		odd[i] = div2(floor(tmp) - 1);
	}

	for (int i = 1; i <= N; i++)
		cum[i] = cum[i - 1] + even[i - 1];

	for (int i = 1; i <= N; i++)
		cumcum[i] = cumcum[i - 1] + cum[i];

	rig.push(N + 1);
	cum[N + 1] = -INF;
	for (int i = N; i; i--) {
		while (!rig.empty() && cum[rig.top()] > cum[i])
			rig.pop();
		suff[i] = cumcum[rig.top() - 1] - cumcum[i] - (rig.top() - i - 1) * cum[i] + suff[rig.top()];
		rig.push(i);
	}

	ll sol = 2 * suff[1], pref = 0, sum = 0;
	for (int i = 1; i <= N; i++) {
		pref += odd[i - 1];
		int len = 1;
		for (; !lft.empty() && lft.top().first > pref; lft.pop()) {
			sum += (ll)lft.top().second * (lft.top().first - pref);
			len += lft.top().second;
		}
		lft.push({pref, len});
		sol = min(sol, 2 * sum + i + 2 * suff[i + 1]);
	}

	return sol;
}

int main() {
	load();
	printf("%lld\n", solve());
	return 0;
}

