int main(){
    int N;
    cin >> N;

    vector<ll> A(N);
    for(auto& e : A){
        cin >> e;
    }

    vector<ll> right = A;
    vector<ll> ans_right(N, 0);
    int right_edge = N - 1;
    for(int i=N - 2;i>=0;i--){
        ans_right[i] = ans_right[i + 1];
        if(right[i] <= right[i + 1]){
            // ok
        }else{
            for(int j=i;j+1<right_edge;j++){
                while(right[j + 1] < right[j]){
                    right[j + 1] *= 4;
                    ans_right[i] += 2;
                }
            }
            while(right[right_edge] < right[right_edge - 1]){
                right[right_edge] *= 4;
                ans_right[i] += 2 * (N - right_edge);
            }
            while(i < right_edge && right[right_edge] < 4 * right[right_edge - 1]){
                assert(right[right_edge - 1] <= right[right_edge]);
                right_edge--;
            }
        }
    }

    vector<ll> left = A;
    for(int i=0;i<N;i++){
        left[i] *= -2;
    }
    vector<ll> ans_left(N, 0);
    ans_left[0] = 1;
    int left_edge = 0;
    for(int i=1;i<N;i++){
        ans_left[i] = ans_left[i - 1] + 1;
        if(left[i - 1] <= left[i]){
            // ok
        }else{
            for(int j=i;j-1>left_edge;j--){
                while(left[j - 1] > left[j]){
                    assert(left[j - 1] < 0);
                    left[j - 1] *= 4;
                    ans_left[i] += 2;
                }
            }
            while(left[left_edge] > left[left_edge + 1]){
                left[left_edge] *= 4;
                ans_left[i] += 2 * (left_edge + 1);
            }
            while(left_edge < i && left[left_edge] > 4 * left[left_edge + 1]){
                assert(left[left_edge] <= left[left_edge + 1]);
                left_edge++;
            }
        }
    }

    // for(int i=0;i<N;i++){
    //     cout << ans_left[i] << " " << ans_right[i] << endl;
    // }

    ll ans = min(ans_left[N - 1], ans_right[0]);
    for(int i=1;i<N;i++){
        ans = min(ans_left[i - 1] + ans_right[i], ans);
    }
    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
using i64 = long long;

i64 dp[200010][20];
i64 dp2[200010][20];
int n;

i64 get(i64 l, i64 x) {
    if (x < 15) return dp[l][x];
    return dp[l][15] + (x - 15) * (n - l);
}

i64 get2(i64 l, i64 x) {
    if (x < 15) return dp2[l][x];
    return dp2[l][15] + (x - 15) * (l + 1);
}

int main() {
    std::cin >> n;
    std::vector<i64> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    for (int i = 0; i < 16; i++) {
        dp[n - 1][i] = i;
        dp2[0][i] = i;
    }

    for (int l = n - 2; l >= 0; l--) {
        i64 cc = a[l];
        i64 dd = a[l + 1];
        for (int x = 0; x < 16; x++) {
            if (x) cc *= 4;
            i64 i = 0;
            while (cc > dd * (1ll << (2 * i))) i++;
            dp[l][x] = x + get(l + 1, i);
        }
    }

    for (int l = 1; l < n; l++) {
        i64 cc = a[l];
        i64 dd = a[l - 1];
        for (int x = 0; x < 16; x++) {
            if (x) cc *= 4;
            i64 i = 0;
            while (cc > dd * (1ll << (2 * i))) i++;
            dp2[l][x] = x + get2(l - 1, i);
        }
    }

    auto ret = 2 * get(0, 0);
    for (int i = 0; i < n - 1; i++) {
        // [0, i] are all negative
        auto curr = i + 1 + 2 * get2(i, 0) + 2 * get(i + 1, 0);
        ret = std::min(ret, curr);
    }
    ret = std::min(ret, 2 * get2(n - 1, 0) + n - 1);

    std::cout << ret << std::endl;

    return 0;
}

