constexpr int INF=1e9;
constexpr int MOD=1e9+7;
constexpr double EPS=1e-9;

ll calc(vl a)
{
	ll res=0;
	double cur=0;
	rep(i,a.size()){
		double x;
		if(a[i]<0){
			x=log2(a[i]*-2);
			res++;
		}
		else
			x=log2(a[i]);
		if(cur>x){
			ll cnt=ceil((cur-x)/2)*2;
			x+=cnt;
			res+=cnt;
		}
		cur=x;
	}
	return res;
}

ll calc(vl a,int p)
{
	// positive
	ll resp=calc(vl(begin(a)+p,end(a)));

	// negative
	vl b(begin(a),begin(a)+p);
	reverse(all(b));
	rep(i,b.size()) b[i]*=-1;
	ll resn=calc(b);

	return resp+resn;
}

