            suf[i]=suf[i+1];
        }
        else
        {
            ll need=0,dummy=a[i+1];
            while(dummy<a[i]) dummy*=2,need++;
            if(need&1) need++;
            ll pos=i;
            if(t==0) suf[i]+=need*(n-i);
            while(t>0&&need>0) 
            {
                suf[i]+=need*(st[t-1].F-pos);
                if(st[t-1].S>need) {st[t-1].S-=need; break;}
                else
                {
                    need-=st[t-1].S;
                    pos=st[t-1].F;
                    if(need&1) need++;
                    t--;
                }
            }
            suf[i]+=suf[i+1];
