        cin >> A[i];
    }

    for(int i = 0; i < 16; i++){
        dp[N][i] = 0;
        dp[N-1][i] = i*2;
    }
    for(int i = N-2; i >= 0; i--){
        //cout << i << endl;
        long cnt = 0;
        if(A[i+1] < A[i]){
            long tmp = A[i+1];
            while(tmp < A[i]){
                tmp*=4;
                cnt++;
            }
            for(int j = 0; j <= 15; j++){
                if(j+cnt <= 15) dp[i][j] = dp[i+1][j+cnt] + 2*j;
                else dp[i][j] = dp[i+1][15] + (N - i - 1)*(j+cnt-15) + 2*j;
            }
        }else{
            long tmp1 = A[i];
            while(tmp1 < A[i+1]){
                tmp1*=4;
                cnt++;
                //cout << 'U' << endl;
            }
            for(int j = 0; j < cnt; j++){
                dp[i][j] = dp[i+1][0] + 2*j;
            }
            for(int j = cnt; j <= 15; j++){
                dp[i][j] = dp[i+1][j-cnt+1] + 2*j;
            }
        }
        //cout << endl;
    }

    for(int i = 0; i < 16; i++){
        dp_[0][i] = 0;
        dp_[1][i] = 1+i*2;
    }
    for(int i = 2; i <= N; i++){
        //cout << i << endl;
        long cnt = 0;
