                tmp*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j <= 15; j++){
                if(j+cnt <= 15) dp_[i][j] = dp_[i-1][j+cnt]+ 1 + 2*j;
                else dp_[i][j] = dp_[i+1][15] + (N - i - 1)*(j+cnt-15) + 1 + 2*j;
            }
        }else{
            long tmp1 = A[i-1];
            while(tmp1 < A[i-2]){
                tmp1*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j < cnt; j++){
                dp_[i][j] = dp_[i-1][0] + 2*j + 1;
            }
            for(int j = cnt; j <= 15; j++){
                dp_[i][j] = dp_[i-1][j-cnt+1] + 2*j + 1;
            }
        }
        //cout << endl;
    }
    long ans = INT32_MAX;
    for(int i = 0; i <= N; i++){
        long min1, min2;
