const int MN = 200010;

int N;
ll A[MN];
ll df[MN], df2[MN];
ll r[MN], l[MN];

int main() {
	cin >> N;

	rep(i, N) {
		cin >> A[i];
	}

	rep(i, N-1) {
		ll x = A[i], y = A[i+1];
		int c = 0;
		if (x >= y) {
			while (x > y) {
				y *= 4;
				c += 2;
			}
		} else {
			while (x < y) {
				x *= 4;
				c -= 2;
			}
		}
		df[i] = c;
	}

	for (int i = 1; i < N; ++i) {
		ll x = A[i-1], y = A[i];
		int c = 0;
		if (x <= y) {
			while (x < y) {
				x *= 4;
				c += 2;
			}
		} else {
			while (x > y) {
				y *= 4;
				c -= 2;
			}
		}
		df2[i] = c;		
	}

	r[N-1] = 0;

	multiset<ll> st;
	ll s = 0;

	for (int i = N-2; i >= 0; --i) {
		r[i] = r[i+1];

		if (df[i] < 0) {
			st.insert(df[i]);
			continue;
		}

		s += df[i];

		ll ad = df[i] * (N - 1 - i - (int)st.size());

		while (st.size()) {
			auto it = st.end(); --it;
			if (*it + s >= 0) {
				ad += *it + s;
				st.erase(it);
			} else {
				break;
			}
		}

		r[i] += ad;
	}

	l[0] = 0;

	st.clear();
	s = 0;

	for (int i = 1; i < N; ++i) {
		l[i] = l[i-1];

		if (df2[i] < 0) {
			st.insert(df2[i]);
			continue;
		}

		s += df2[i];

		ll ad = df2[i] * (i - (int)st.size());

		while (st.size()) {
			auto it = st.end(); --it;
			if (*it + s >= 0) {
				ad += *it + s;
				st.erase(it);
			} else {
				break;
			}
		}

		l[i] += ad;
	}

	ll ret = LLONG_MAX;

	for (int i = 0; i <= N; ++i) { //odd
		ll t = i;
		if (i > 0) {
			t = (t + l[i-1]);
		}
		if (i < N) {
			t = (t + r[i]);
		}

		ret = min(ret, t);
	}

	cout << ret << endl;

	return 0;
}

