long long solve() {
    vector<long long> left(N+1, 0), right(N+1, 0);
    left[1] = 1;
    for (int i = 1; i < N; ++i) {
        long long s = A[i-1] * (-2), t = A[i] * (-2);
        long long need = 0;
        while (s > t) s *= 4, need += 2;
        left[i+1] = left[i] + need * i + 1;

        s = A[N-i-1], t = A[N-i];
        need = 0;
        while (s > t) t *= 4, need += 2;
        right[i+1] = right[i] + need * i;
    }

    //COUT(A); COUT(left); COUT(right);

    long long res = 1LL<<60;
    for (int i = 0; i <= N; ++i) chmin(res, left[i] + right[N-i]);
    return res;
}

