using namespace std;
typedef long long int ll;
typedef pair<int, int> pii;
typedef pair<ll, int> pli;

const int MAX_N = 200000;
const int K = 16;

int N;
ll A[MAX_N];
ll dp0[MAX_N][K], dp1[MAX_N][K];

ll solve() {
    for (int k = 0; k < K; k++) {
        dp0[N - 1][k] = k;
        dp1[0][k] = k;
    }

    for (int i = N - 2; i >= 0; i--) {
        ll k4 = 1;
        for (int k = 0; k < K; k++) {
            int j = 0;
            ll j4 = 1;
            while (A[i] * k4 > A[i + 1] * j4) {
                j++;
                j4 *= 4;
            }
            if (j <= 15) {
                dp0[i][k] = dp0[i + 1][j] + k;
            } else {
                dp0[i][k] = dp0[i + 1][15] + (N - i - 1) * (j - 15) + k;
            }

            k4 *= 4;
        }
    }

    for (int i = 1; i < N; i++) {
        ll k4 = 1;
        for (int k = 0; k < K; k++) {
            int j = 0;
            ll j4 = 1;
            while (A[i - 1] * j4 < A[i] * k4) {
                j++;
                j4 *= 4;
            }
            if (j <= 15) {
                dp1[i][k] = dp1[i - 1][j] + k;
            } else {
                dp1[i][k] = dp1[i - 1][15] + i * (j - 15) + k;
            }

            k4 *= 4;
        }
    }

    ll ans = dp0[0][0] * 2;
    for (int i = 1; i < N; i++) {
        ans = min(ans, i + dp1[i - 1][0] * 2 + dp0[i][0] * 2);
    }

    return ans;
}

int main() {
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
    }

    cout << solve() << endl;

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

struct UnionFindRange {
  vector< int > data;
  vector< int > left, right;

  UnionFindRange(int sz) {
    data.assign(sz, -1);
    left.resize(sz);
    right.resize(sz);
    for(int i = 0; i < sz; i++) left[i] = i;
    for(int i = 0; i < sz; i++) right[i] = i;
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    left[x] = min(left[x], left[y]);
    right[x] = max(right[x], right[y]);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  pair< int, int > range(int k) {
    k = find(k);
    return {left[k], right[k]};
  };

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};


int main() {
  int N;
  cin >> N;
  vector< double > A(N);
  for(int i = 0; i < N; i++) {
    cin >> A[i];
    A[i] = log(A[i]);
  }

  const double log4 = log(4);

  vector< int64 > suffix(N);
  {
    vector< double > add(N);
    UnionFindRange uf(N + 1);

    auto add2 = [&](int idx) {
      return add[uf.range(idx).first];
    };

    for(int i = N - 2; i >= 0; i--) {
      int64 times = 0;
      for(int j = i + 1; j < N; j = uf.range(j).second + 1) {
        if(A[j - 1] + add2(j - 1) <= A[j] + add2(j)) break;
        while(A[j - 1] + add2(j - 1) > A[j] + add2(j)) {
          add[uf.range(j).first] += log4;
          times += 2 * uf.size(j);
        }
        if(A[j - 1] + add2(j - 1) + log4 > A[j] + add2(j)) {
          uf.unite(j - 1, j);
        }
      }
      suffix[i] = suffix[i + 1] + times;
    }
  }
  vector< int64 > prefix(N);
  {
    vector< double > add(N);
    prefix[0] = 1;

    UnionFindRange uf(N + 1);

    auto add2 = [&](int idx) {
      return add[uf.range(idx).first];
    };

    for(int i = 1; i < N; i++) {
      int64 times = 1;
      for(int j = i - 1; j >= 0; j = uf.range(j).first - 1) {
        if(A[j] + add2(j) >= A[j + 1] + add2(j + 1)) break;
        while(A[j] + add2(j) < A[j + 1] + add2(j + 1)) {
          add[uf.range(j).first] += log4;
          times += 2 * uf.size(j);
        }
        if(A[j] + add2(j) + log4 < A[j + 1] + add2(j + 1)) { // えーなにかが起こる
          uf.unite(j, j + 1);
        }
      }
      prefix[i] = prefix[i - 1] + times;
    }
  }

  int64 ret = min(prefix[N - 1], suffix[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, prefix[i - 1] + suffix[i]);
  }
  cout << ret << endl;

}

