int solve(int m, vector<int> a) {
	int cnt = 0;
	int n = a.size();
	if (m < 0 || m > n) return INF;
	if (m != 0 && a[m - 1] > 0) {
		a[m - 1] *= -2; cnt++;
	}
	if (m != n && a[m] < 0) {
		a[m] *= 2; cnt++;
	}
	for (int i = m - 2; i >= 0; i--) {
		while (a[i] > a[i + 1]) {
			a[i] *= -2; cnt++;
		}
	}
	for (int i = m + 1; i < n; i++) {
		while (a[i - 1] > a[i]) {
			a[i] *= -2; cnt++;
		}
	}
	return cnt;
}

