      dp[i][j1] = dp[i + 1][0] + j1;
      c1 *= 4;
      j1++;
    }

    while (j2 < 16 && c2 <= c1) {
      c2 *= 4;
      j2++;
    }

    while (j1 < 16) {
      if (j2 > 15) {
        dp[i][j1] = dp[i + 1][15] + j2 * (n - 1 - i) + j1;
      }
      else {
        dp[i][j1] = dp[i + 1][j2] + j1;
      }
      j1++;
      j2++;
    }
