int main()
{
    size_t n;
    std::cin >> n;
    std::vector<size_t> xs(n), count_f(n + 1, 0), count_b(n + 1, 0);
    for (size_t i = 0; i < n; i++) {
        size_t x;
        std::cin >> x;
        xs[i] = x;
    }

    for (size_t mi = 2; mi <= n; mi++) {
        size_t i = n - mi;
        count_f[i] = count_f[i + 1] + (n - i - 1) * diff(xs[i], xs[i + 1]);
        if (count_f[i] < count_f[i + 1]) {
            count_f[i] = std::numeric_limits<size_t>::max();
        }
        //std::cerr << ">>" << i << ' ' << count_f[i] << std::endl;
    }

    for (size_t i = 2; i <= n; i++ ) {
        count_b[i] = count_b[i - 1] + (i - 2) * diff(xs[i - 1], xs[i - 2]);
        if (count_b[i] < count_b[i - 1]) {
            count_b[i] = std::numeric_limits<size_t>::max();
        }

    }

    size_t min = std::numeric_limits<size_t>::max();
