LL solve() {
  p4[0]=1; FOR(i,1,40) p4[i]=p4[i-1]*4;
  REP(i,N)REP(j,20)dpl[i][j]=dpr[i][j]=Inf;
  REP(j,20) dpr[N-1][j]=dpl[0][j]=j;

  for(int i=N-2; i>=0; --i) {
    LL x4=1;
    REP(x,16) {
      int j=0,jj=0;
      LL j4=1;
      while(A[i] * x4 > A[i+1] * j4) j4 *= 4,   ++j;
