      if(jj!=j) dump(x,jj,j,A[i],A[i+1]);
      assert(jj==j);

      if(j<=15) dpr[i][x]=dpr[i+1][j]+x;
      else dpr[i][x]=dpr[i+1][15]+(LL)(N-1-i)*(j-15)+x;

      x4*=4;
    }
  }
  FOR(i,1,N) {
    LL x4=1;
    REP(x,16) {
      int j=0,jj=0;
      LL j4=1;
      while(A[i-1] * j4 < A[i] * x4) j4 *= 4,++j;
      while(p4[jj]*A[i-1]<p4[x]*A[i]) ++jj;
      assert(j==jj);
      if(j<=15) dpl[i][x]=dpl[i-1][j]+x;
      else dpl[i][x]=dpl[i-1][15]+(LL)i*(j-15)+x;

      x4 *= 4;
    }
  }
  LL res=dpr[0][0]*2;
  FOR(i,1,N) SMIN(res,i+dpl[i-1][0]*2+dpr[i][0]*2);
  return res;
}


