int main() {
	int N;
	cin >> N;
	vll a(N);
	cin >> a;
	vll num1(N + 1, 0), num2(N + 1, 0);

	stack<int> red;
	int count = 0;
	reprev(i, N - 1) {
		num1[i] = num1[i + 1];
		if (a[i] > a[i + 1]) {
			int p = 0;
			ll b = a[i + 1];
			while (a[i] > b) {
				b *= 4;
				p++;
			}
			// 4^p倍する必要あり
			count++;
			num1[i] += (ll)count * p * 2;
			while (p > 0 && !red.empty()) {
				int t = red.top();
				red.pop();
				if (t < p) {
					num1[i] += (p - t) * 2;
					p -= t;
					count++;
				}
				else {
					num1[i] += p * 2;
					red.push(t - p);
					break;
				}
			}
		}
		else {
			int p = 0;
			ll b = a[i];
			while (b <= a[i + 1]) {
				b *= 4;
				p++;
			}
			p--;
		}
	}

	stack<int> red2;
	count = 0;
	rep(i, N - 1) {
		num2[i + 2] = num2[i + 1];
		if (a[i] < a[i + 1]) {
			int p = 0;
			ll b = a[i];
			while (a[i + 1] > b) {
				b *= 4;
				p++;
			}
			// 4^p倍する必要あり
			count++;
			num2[i + 2] += (ll)count * p * 2;
			while (p > 0 && !red2.empty()) {
				int t = red2.top();
				red2.pop();
				if (t < p) {
					num2[i + 2] += (p - t) * 2;
					p -= t;
					count++;
				}
				else {
					num2[i + 2] += p * 2;
					red2.push(t - p);
					break;
				}
			}
		}
		else {
			int p = 0;
			ll b = a[i + 1];
			while (a[i] >= b) {
				b *= 4;
				p++;
			}
			p--;
			red2.push(p);
		}
	}

	ll ans = INFL;
	rep(i, N + 1) {
		ans = min(ans, num1[i] + num2[i] + i);
	}

	cout << ans << endl;

	return 0;
}

