const int LIM = 31;

// ta funkcja dziala w obie strony - sprawdza czy dodatnie sa mniejsze i czy ujemne sa wieksze
bool cmp(PII p1, PII p2, bool neg)
{
	int w = min(p1.second, p2.second);
	p1.second -= w; p2.second -= w;

	// spr czy mozesz bezpiecznie wymnozyc
	if (max(p1.second, p2.second) < LIM)
	{
		if (!neg)
			return p1.first*(1LL << p1.second) < p2.first*(1LL << p2.second);

		return p1.first*((p1.second % 2 ? -1 : 1)*(1LL << p1.second)) > p2.first*((p2.second % 2 ? -1 : 1)*(1LL << p2.second));
	}
	else // jesli reszta jest bardzo duza, to sprawdz czy nie ma jej w p1
		return !p1.second;
}

map<PII, int> dp1;

int go1(int pos, int k, const vector<int> &V)
{
	if (!pos)
		return 0;

	auto it = dp1.find(MP(pos, k));
	if (it != dp1.end())
		return it->second;

	// wszystko maleje
	auto akt = MP(V[pos], k);
	// tu pamietaj o nieparzystych
	PII p = MP(V[pos - 1], 0);
	int res = 0;

	if (cmp(p, akt, 1))
	{
		p.second++;
		res++;
		while (cmp(p, akt, 1))
		{
			p.second += 2;
			res += 2;
		}
	}

	return dp1[MP(pos, k)] = res + go1(pos - 1, res, V);
}

map<PII, int> dp2;
int go2(int pos, int k, const vector<int> &V)
{
	if (pos == V.size() - 1)
		return 0;

	auto it = dp2.find(MP(pos, k));
	if (it != dp2.end())
		return it->second;

	// wszystko rosnie
	auto akt = MP(V[pos], k);
	// tu pamietaj o nieparzystych
	PII p = MP(V[pos + 1], 0);

	int res = 0;

	while (cmp(p, akt, 0))
	{
		p.second += 2;
		res += 2;
	}

	return dp2[MP(pos, k)] = res + go2(pos + 1, res, V);
}

int main()
{
	vector<int> V;

	int N;
	scanf("%d", &N);
	REP(i, N)
	{
		int A;
		scanf("%d", &A);
		V.push_back(A);
	}

	int res = 1e9 + 7;
	for (int i = 0; i < N;)
	{
		int j = i + 1;
		while (j < N && V[j] >= V[j - 1])j++;

		int tmp = go1(i, 0, V) + go2(j - 1, 0, V);

		res = min(res, tmp);

		i = j;
	}

	printf("%d\n", res);

	return 0;
}

