const int64_t inf = (1LL << 50);

#define int int64_t

int64_t dp[200010][15];

vector<int64_t> computeScore(const std::vector<int64_t>& a) {
    int n = a.size();
    for (int x = 0; x < 15; x++) {
        dp[n - 1][x] = 2 * x;
    }

    for (int i = n - 2; i >= 0; i--) {
        int64_t cur = a[i];

        for (int x = 0; x < 15; x++) {
            dp[i][x] = inf;

            int64_t nxt = a[i + 1];

            for (int y = 0; y < 15; y++) {
                // 4^x * a_i <= 4^y * a_{i+1}
                if (cur <= nxt) {
                    dp[i][x] = min(dp[i][x], dp[i + 1][y] + 2 * x);
                } else {
                    dp[i][x] = min(dp[i][x], dp[i + 1][y] + 2 * (x + 15 * (n - i - 1)));
                }
                nxt *= 4;
            }
            cur *= 4;
        }
    }

    vector<int64_t> score(n);
    for (int i = 0; i < n; i++) {
        score[i] = dp[i][0];
    }
    return score;
}

signed main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n;
    cin >> n;

    vector<int64_t> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    auto score1 = computeScore(a);

    reverse(a.begin(), a.end());

    auto score2 = computeScore(a);

    reverse(score2.begin(), score2.end());

    int64_t ans = (1LL << 50);

    for (int i = 0; i < n; i++) {
        ans = min(ans, i + score1[i] + (i > 0 ? score2[i - 1] : 0));
    }
    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const long long INF = 1LL<<60;
const int MAX = 16;
int N;
vector<long long> A;

vector<vector<long long>> calc(const vector<long long> &a, int offset = 0) {
    vector<vector<long long>> dp(N+1, vector<long long>(MAX, INF));
    for (int j = 0; j < MAX; ++j) dp[0][j] = 0, dp[1][j] = j*2 + offset;
    for (int i = 1; i < N; ++i) {
        long long s = a[N-i-1];
        for (int j = 0; j < MAX; ++j) {
            long long t = a[N-i];
            int need = 0;
            while (s > t) ++need, t *= 4;
            long long add = 0;

            if (need >= MAX) {
                add = (need - MAX + 1) * i * 2;
                need = MAX-1;
            }
            dp[i+1][j] = min(dp[i][need] + j * 2 + add + offset , dp[i+1][j]);
            s *= 4;
        }
    }
    return dp;
}

long long solve() {
    const auto &right = calc(A);
    reverse(A.begin(), A.end());
    const auto &left = calc(A, 1);
    long long res = INF;
    for (int i = 0; i <= N; ++i) {
     res = min(res ,left[i][0] + right[N-i][0] );
    }
    return res;
}

int main() {
    cin >> N;
    A.resize(N);
    for (int i = 0; i < N; ++i) cin >> A[i];
    cout << solve() << endl;
}

