const double EPS = 1e-10;
const double PI  = acos(-1.0);
const LL MOD = 1e9+7;

LL naive(LL N, VL& xs){
  LL sum = 1e15;
  for(int i=0;i<N;++i){
	VL ys = xs;
	LL ans = 0;
	for(int j=i+1;j<N;++j){
	  while(ys[j-1] > ys[j]){
		ys[j] *= -2;
		++ans;
	  }
	}

	for(int j=i-1;j>=0;--j){
	  ++ans;
	  ys[j] *= -2;
	}

	for(int j=i-2;j>=0;--j){
	  while(ys[j] > ys[j+1]){
		ys[j] *= -2;
		++ans;
	  }
	}

	mini(sum, ans);
  }

  VL ys = xs;
  LL ans = 0;
  for(int j=0+1;j<N;++j){
	while(ys[j-1] > ys[j]){
	  ys[j] *= -2;
	  ++ans;
	}
  }
  mini(sum, ans);


  return sum;
}

void solve(int N, VL xs, VL& ans){
  LL sum = 0;
  VL q;
  VL cap;
  for(int i=N-2;i>=0;--i){
	LL l = xs[i];
	LL r = xs[i+1];
	LL need = 0;
	if(l > r){
	  while(l > r){
		r *= 4;
		need += 2;
	  }

	  LL e = 1e15;
	  while(!q.empty()){
		int ix = q.back();
		LL ca = cap.back();
		if(ca < need){
		  q.pop_back();
		  cap.pop_back();
		  e = ix;
		  sum += (need - ca) * (e - i - 1);
		  need -= ca;
		}
		else{
		  e = ix;
		  sum += need * (e - i - 1);
		  cap.back() -= need;
		  need = 0;
		  break;
		}
	  }
	  if(q.empty()){
		e = N;
		sum += need * (e - i - 1);
	  }
