const int mod=1000000007,MAX=200005;
const ll INF=1LL<<60;
const long double eps=1e-13;

int par[MAX],size[MAX];

void init(int n){
    for(int i=0;i<n;i++){
        par[i]=i;
        size[i]=1;
    }
}

int root(int a){
    if(par[a]==a) return a;
    else return par[a]=root(par[a]);
}

void unite(int a,int b,bool turn){
    if(root(a)==root(b)) return;

    if(turn==0) if(root(a)>root(b)) swap(a,b);

    if(turn==1) if(root(a)<root(b)) swap(a,b);

    size[root(a)]+=size[root(b)];
    par[root(b)]=root(a);
}

bool check(int a,int b){
    return root(a)==root(b);
}


int main(){

    std::ifstream in("text.txt");
    std::cin.rdbuf(in.rdbuf());
    cin.tie(0);
    ios::sync_with_stdio(false);


    int N;cin>>N;
    vector<long double> A(N+2,INF),B(N+2,INF);
    vector<ll> a(N+2,0),b(N+2);
    for(int i=0;i<N;i++){
        long double c;cin>>c;
        A[i+1]=log2(c)+1.0;
        B[i+1]=log2(c);
        a[i+1]++;
    }

    init(N+2);

    for(int i=1;i<=N;i++){
        a[i]+=a[i-1];

        if(A[i-1]-A[i]>-eps){
            if(A[i-1]-A[i]<=2.0-eps) unite(i-1,i,0);
            continue;
        }
        int now=i;
        while(1){
            while(A[now-1]-A[now]<=-eps){
                A[now-1]+=2.0;
                if(root(now-1)!=now-1) A[root(now-1)]+=2.0;
                a[i]+=2*(now-root(now-1));
            }
            if(A[now-1]-A[now]<=2.0+eps) unite(now-1,now,0);
            now=root(now-1);

            if(now==1) break;
        }
    }
    a[N+1]=a[N];

    init(N+2);

    for(int i=N;i>=1;i--){
        b[i]+=b[i+1];

        if(B[i+1]-B[i]>-eps){
            if(B[i+1]-B[i]<=2.0-eps) unite(i+1,i,1);
            continue;
        }
        int now=i;
        while(1){
            while(B[now+1]-B[now]<=-eps){
                B[now+1]+=2.0;
                if(root(now+1)!=now+1) B[root(now+1)]+=2.0;
                b[i]+=2*(root(now+1)-now);
            }
            if(B[now+1]-B[now]<=2.0+eps) unite(now+1,now,1);
            now=root(now+1);

            if(now==N) break;
        }
    }
    b[0]=b[1];

    ll ans=INF;

    for(int i=0;i<N+1;i++){
        ans=min(ans,a[i]+b[i+1]);
    }

    cout<<ans<<endl;
}

