const int MAX = 200010;
int N;
LL a[MAX];

LL calc(int mid) {
    // a[mid] > 0
    LL cnt1 = 0;
    if (mid > 0) {
        LL pre = 1;
        cnt1++;//最初分
        RREP(i, mid - 1) {
            // minus
            if (a[i] >= a[i + 1]) {
                cnt1 += pre;
            } else {
                LL div = a[i + 1] / a[i];
                pre += ((div / 4) + (div % 4 != 0)) * 2;
                cnt1 += pre;
            }
        }
    }
    LL cnt2 = 0;
    {
        LL pre = 0;
        FOR(i, mid + 1, N) {
            // plus
            if (a[i - 1] <= a[i]) {
                cnt2 += pre;
            } else {
                // a[i - 1] > a[i]
                LL div = a[i - 1] / a[i];
                pre += ((div / 4) + (div % 4 != 0)) * 2;
                cnt2 += pre;
            }
        }
    }
    return cnt1 + cnt2;
}

