        // a[mid] > 0
        const int mid1 = (high + low + low) / 3;
        const int mid2 = (high + high + low) / 3;
        if (calc(mid1) <= calc(mid2)) low = mid1;
        else high = mid2;
    }
    LL ans = LLINF;
    FOR(i, low, high + 1) {
        chmin(ans, calc(i));
    }
    cout << (ans == LLINF ? -1 : ans) << endl;
}

