const int N = 610000;
const int K = 19;
const int mod = 1e9 + 7;
int f[N], invf[N], inv2, inv3, a[N], b[N], nxt[N], len[N], dp[2][N], n;
void solve(int k){
    for (int i = 1; i <= n; i++){
        nxt[i] = i;
        len[i] = 0;
        b[i] = 0;
    }
    dp[k][n] = 0;
    b[n] = 1e9;
  //  cout << "K = " << k << endl;
    for (int i = n - 1; i >= 1; i--){
        int x = a[i];
        if (x <= a[i + 1]){
            int c = 0;
            while(x + x + x + x <= a[i + 1]){
                c++;
                x += 3 * x;
            }
            if (c == 0){
                nxt[i] = nxt[i + 1];
                len[i] = len[i + 1] + 1;
            } else b[i] = c;
            dp[k][i] = dp[k][i + 1];
           // cout << "! i = " << i << " " << dp[k][i] << endl;
        } else{
            int p = i + 1;
            int c = 0;
            int y = a[i + 1];
            while(y < x){
                y += 3 * y;
                c++;
            }
            int res = 0;
           // cout << "c = " << c << endl;
            while(p != n + 1){
                res += c * len[p];
              //  cout << p << " -- " << nxt[p] << " " << nxt[4] << endl;
                p = nxt[p];
                if (p == 0) exit(0);
                if (b[p] > c){
                    res += c;
                    b[p] = b[p] - c;
                    c = 0;
                    break;
                } else
                if (b[p] <= c){
                    res += c;
                    c -= b[p];
                    b[p] = 0;
                   // cout << p << " qq " << nxt[p] << " " << b[5] << endl;
                    len[p] = len[p] + len[nxt[p]] + 1;
                    nxt[p] = nxt[nxt[p]];
                }
                res += c;
                p++;
              //  cout << i << " " << p << endl;
            }

            nxt[i] = nxt[i + 1];
            len[i] = len[i + 1] + 1;
            dp[k][i] = dp[k][i + 1] + res;
           // cout << "i = " << i << " " << dp[k][i] << endl;
        }
    }
}
