int N;

vl gen(vi v) {
    ll cans = 0;
    vpi st;
    vl res(sz(v)+1);

    F0Rd(i,sz(v)) {
        if (i == sz(v)-1) st.pb({0,1});
        else {
            if (v[i] <= v[i+1]) {
                ll tmp = v[i], num = 0;
                while (tmp*4 <= v[i+1]) tmp *= 4, num += 2;
                st.pb({num,1});
            } else {
                ll tmp = v[i+1], num = 0, zz = 1;
                while (tmp < v[i]) tmp *= 4, num += 2;
                while (sz(st) && num >= 0) {
                    cans += st.back().s*num; 
                    zz += st.back().s;
                    num -= st.back().f;
                    st.pop_back();
                }
                st.pb({-num,zz});
            }
        }
        res[i] = cans;
    }
    // pr(res);
    return res;
}

