using Int = long long;
vector<Int> func(const vector<int>& B)
{
    vector<array<Int, 16>> dp(B.size() + 1); // dp[i][j]: A[i] に j 回 4 を掛けたときの回数
    for (int j = 0; j < 16; j++) {
        dp[B.size()][j] = j;
    }
    for (int i = B.size()-1; i >= 0; i--) {
        for (int j = 0; j < 16; j++) {
            int t = max(0, j + B[i]);
            if (t >= 16) {
                dp[i][j] = j + dp[i+1][15] + (t - 15) * (B.size() - i);
            } else {
                dp[i][j] = j + dp[i+1][t];
            }
        }
    }
    vector<Int> ans(B.size() + 2);
    for (int i = 0; i < B.size(); i++) ans[i] = dp[i][0];
    return ans;
}
int main()
{
    int N; cin >> N;
    vector<int> A(N), B(N-1), C(N-1);
    for (auto &a : A) cin >> a;
    // B[i]: A[i] <= A[i+1] * 4^x を満たす最小の整数 x
    for (int i = 0; i < N-1; i++) {
        B[i] = ceil((log(A[i]) - log(A[i+1]) - 1e-10) / log(4));
        C[i] = ceil((log(A[i+1]) - log(A[i]) - 1e-10) / log(4));
    }
    reverse(begin(C), end(C));
    auto D = func(B), E = func(C);
    Int ans = 1e18;
    for (int i = 0; i <= N; i++) {
        ans = min<Int>(ans, D[i] * 2 + E[N - i] * 2 + i);
    }
    cout << ans << '\n';
    return 0;
}

