            s *= -2LL;
        }
        for(ll j = 0; j <= 15; j++) {
            ll tt = t;
            ll l = -1;
            for(int k = 0; k <= 15; k++) {
                if(s <= tt) {
                    chmin(dp1[i][k], dp1[i - 1][j] + k * 2LL + c);
                    l = k;
                } else {
                    chmin(dp1[i][k], dp1[i - 1][j] + k * 2LL + c +
                                         (i - 1LL) * (k - l) * 2LL);
                }
                tt *= 4LL;
            }
            s *= 4LL;
        }
    }
    for(ll i = n - 1; i >= 1; i--) {
        ll s = a[i + 1], t = a[i];
        for(ll j = 0; j <= 15; j++) {
            ll tt = t;
            ll l = -1;
            for(ll k = 0; k <= 15; k++) {
                if(tt <= s) {
                    chmin(dp2[i][k], dp2[i + 1][j] + k * 2LL);
                    l = k;
                } else {
                    chmin(dp2[i][k],
                          dp2[i + 1][j] + k * 2LL + (n - i) * (k - l) * 2LL);
                }
                tt *= 4LL;
            }
            s *= 4LL;
        }
    }
    ll ans = LINF;
    for(int i = 0; i <= n; i++) {
        ll l = LINF, r = LINF;
        for(int j = 0; j <= 15; j++) {
            chmin(l, dp1[i][j]);
            chmin(r, dp2[i + 1][j]);
        }
        chmin(ans, l + r);
    }
    cout << ans << endl;
}

