			while(tmp<=A[i-1]){
				tmp*=4;
				table[i]--;
			}
			table[i]++;
		}
		else{
			int tmp=A[i-1];
			while(tmp<A[i]){
				tmp*=4;
				table[i]++;
			}
		}
	}


	int num=0;
