			deq[p-1].se++;
			p--;
		}
		if(p==0){
			num+=n;
		}
		else{
			num+=deq.size()-p;
		}
	};

	auto nor=[&](){
		while(deq.size()>1&&deq.front().se-deq[1].se==table[deq[1].fi]){
