      else dp1[i][j]=min(dp1[i][j],dp1[i+1][x]+j);
    }
  }
  for(ll i=0;i<=15;i++) {
    dp2[0][i]=0;
    dp2[1][i]=i;
  }
  for(ll i=2;i<=n;i++){
    for(ll j=0;j<=15;j++){
      ll dis=(ar[i]*(1<<(2*j))/ar[i-1]);
      ll x=0;
      while(dis>0){
        dis/=4;
        x++;
      }
      if(x>=15) dp2[i][j]=min(dp2[i][j],(i-1)*(x-15)+dp2[i-1][15]+j);
      else dp2[i][j]=min(dp2[i][j],dp2[i-1][x]+j);
    }
  }
  ll ans=inf;
  for(ll i=0;i<=n;i++){
    ans=min(ans,i+(dp2[i][0]+dp1[i+1][0])*2);
  }
  cout<<ans<<endl;
}

