i64 pos(const vector<i64> &b, int l, int r)
{
  i64 cnt = 0;
  i64 res = 0;
  for (int i = l + 1; i < r; i++)
  {
    i64 x = b[i - 1];
    i64 y = b[i];
    if (y < 0)
    {
      y *= -2;
      res++;
    }
    i64 rem;
    if (x <= y)
    {
      rem = -ceil(log2(1.0 * y / x));
    }
    else
    {
      rem = ceil(log2(1.0 * x / y));
    }
    rem += cnt;
    if (rem < 0)
      rem = 0;
    rem += rem & 1;
    res += rem;
    cnt = rem;
  }
  return res;
}

i64 neg(const vector<i64> &b, int l, int r)
{
  i64 cnt = 0;
  i64 res = 0;

  for (int i = r - 2; i >= l; i--)
  {
    i64 x = b[i];
    i64 y = b[i + 1];
    if (x > 0)
    {
      x *= -2;
      res++;
    }
    i64 rem;
    if (x <= y)
    {
      rem = -ceil(log2(1.0 * x / y));
    }
    else
    {
      rem = ceil(log2(1.0 * y / x));
    }
    rem += cnt;
    if (rem < 0)
      rem = 0;
    rem += rem & 1;
    res += rem;
    cnt = rem;
  }

  return res;
}

const i64 MAX = LONG_MAX / 2;

i64 solve(vector<i64> a)
{
  i64 N = a.size();
  if (N == 1)
  {
    cout << 0 << endl;
    return 0;
  }

  vector<i64> b = a;

  i64 res = MAX;

  for (int i = 0; i + 1 < N; i++)
  {
    int j = i + 1;
    i64 c = -1;
    for (i64 x = a[i]; abs(x) <= MAX; x *= -2)
    {
      c++;
      i64 d = -1;
      for (i64 y = a[j]; abs(y) <= MAX; y *= -2)
      {
        d++;
        if (x <= y)
        {
          b[i] = x;
          b[j] = y;
          i64 ne = neg(b, 0, j);
          i64 po = pos(b, j, N);
          i64 temp = ne + po + c + d;
          res = min(temp, res);
          b[i] = a[i];
          b[j] = a[j];
        }
      }
    }
  }
  return res;
}

