  int N; cin >> N;
  VI A(N);
  REP (i, N) cin >> A[i];
  VVI dp(2, VI(N));
  REP (k, 2) {
    map<int, int> mp;
    for (int i = N - 2; i >= 0; i--) {
      dp[k][i] = dp[k][i + 1];
      int dif = count(A[i], A[i + 1]);
      int pt = i;
      if (dif == 0) {
        continue;
      } else if (dif < 0) {
        mp[i] = -dif;
      } else {
        for (auto it = mp.begin(); it != mp.end(); ) {
          dp[k][i] += dif * (it->fi - pt);
          pt = it->fi;
          if (it->se <= dif) {
            dif -= it->se;
            mp.erase(it++);
          } else {
            it->se -= dif;
            dif = 0;
            break;
          }
        }
        dp[k][i] += dif * (N - 1 - pt);
      }
    }
    reverse(ALL(A));
  }
  int ans = 1e18;
  REP (i, N) {
    ans = min(ans, i + 2 * (dp[0][i] + (i == 0 ? 0 : dp[1][N - i])));
  }
  cout << ans << endl;
}

