		c = calc(must, yoyu);
		std::reverse(ALL(c));
	}

	int ans = INFLL;
	REP(i, n + 1) {
		int t = i;
		if (i > 0) t += c[i - 1];
		if (i < n) t += b[i];
		CHMIN(ans, t);
	}
	OUT(ans)BR;
	return 0;
}

