ll n;

vector<ll> calc(vector<ll> &a) {
    vector<ll> sum(n);
    stack<ll> stack;
    ll cnt = 0;
    rep1(i,n-1){
        ll pre = a[i-1], cur = a[i];
        if (pre >= cur) {
            while (pre >= cur*4) {
                cur *= 4;
                stack.push(i);
            }
        } else {
            while (pre < cur) {
                if (stack.empty()) {
                    cnt += i*2;
                } else {
                    ll k = stack.top(); stack.pop();
                    cnt += (i-k)*2;
                }
                pre *= 4;
            }
        }
        sum[i] = cnt;
    }
    return sum;
}

