typedef long long ll;

ll N, A[200000];

const double EPS = 1e-10;
double l2;

vector<ll> solve(vector<double> &a) {
  vector<double> x(a);

  vector<ll> ret(N);
  ll cnt = 0;

  stack<ll> stk;
  for (int i = N - 1; i >= 0; i--) {
    ret[i] = cnt;
    if (i == 0) break;

    stk.push(i + 1);
    while (x[i - 1] > x[i] + EPS) {
      ll k;
      while (1) {
        k = stk.top();
        if (k == N) break;
        stk.pop();
        if (x[k - 1] + l2 * 2 < x[k] + EPS) break;
      }

      x[i] += l2 * 2;
      cnt += (k - i) * 2;
    }
  }

  return ret;
}

