vector<ll> lol() {
	vector<pair<int,int>> v;
	vector<ll> vv(n+5);
	ll u = 0;
	for (int i = n-1; i >= 1; i--) {
		int c = 0;
		if (a[i] < a[i+1]) {
			ll b = a[i];
			while (b*4 < a[i+1]) {b *= 4; c--;}
		} else {
			ll b = a[i+1];
			while (b < a[i]) {b *= 4; c++;}
		}
		if (c >= 0) {
			int k = i;
			while (v.size()) {
				u += (v.back().first-k)*c;
				k = v.back().first+1;
				if (v.back().second >= c) {
					v.back().second -= c;
					if (v.back().second == 0) v.pop_back();
					break;
				} else {
					c -= v.back().second;
					u += c;
					v.pop_back();
				}
			}
			u += (n-k)*c;
		} else {
			v.push_back({i,-c});
		}
		vv[i] = u;
	}
	return vv;
}

