int main() {
    int N;
    long long a[200001], dp[200001]; // [threshold]{times}, a[:thres]<0,a[thres:]>0
    cin >> N;
    for (int i=0; i<N; i++) cin >> a[i];
    // a[0] ... a[N-1]

    for (int i=0; i<N+1; i++) {
        dp[i] = i;
    }
    for (int i=1; i<N; i++) {
        if (a[i-1] < a[i]) {
            long long factor = 1;
            int time = 0;
            while (a[i-1] * factor < a[i]) {
                factor *= 4; time++;
            }
            // error if i<thres
            for (int j=i+1; j<N+1; j++) {
                dp[j] += time * i * 2;
            }
        }
        if (a[N-i-1] > a[N-i]) {
            long long factor = 1;
            int time = 0;
            while (a[N-i-1] > a[N-i] * factor) {
                factor *= 4; time++;
            }
            // error if thres <= N-i-1
            for (int j=0; j<=N-i-1; j++) {
                dp[j] += time * i * 2;
            }
        }
    }
    long long min_dp = -1;
    int thres = -1;
    for (int i=0; i<N+1; i++) {
        if (min_dp == -1 || min_dp > dp[i]) {
            min_dp = dp[i];
            thres = i;
        }
    }
    cout << min_dp << endl;
    //cerr << thres << endl;

    return 0;
}

