template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return 1; } return 0; }

int n;
vector<int> x;
const int MAX = 16;

vector<vector<int>> calc(vector<int> a, int offset = 0) {
	vector<vector<int>> dp(n + 1, vector<int>(MAX, INF));
	rep(j, MAX) {
		dp[0][j] = 0;
		dp[1][j] = 2 * j + offset;
	}
	for(int i = 1; i < n; ++ i) {
		int s = a[n - 1 - i];
		rep(j, MAX) {
			int t = a[n - i];
			int need = 0;
			while(s > t) {
				++ need;
				t *= 4;
			}
			int add = 0;
			if(need >= MAX) {
				add = (2 * need - 2 * (MAX - 1)) * i;
				need = MAX - 1;
			}
			chmin(dp[i + 1][j], dp[i][need] + j * 2 + offset + add);
			s *= 4;
		}
	}
	return dp;
}

