int NOTHING = INT_MAX / 4;
ll LIMIT = LONG_LONG_MAX / 4;
ll mul[70];
int n;
ll a[200000];
int dp[200002][100];

int dfs(int idx, int preMul) {
  if (idx == n) {
    return 0;
  }
  if (dp[idx][preMul] != -1) {
    return dp[idx][preMul];
  }

  ll preVal = a[idx - 1] * mul[preMul];
  int res = NOTHING;

  if (preVal >= a[idx]) {
    ll curVal = a[idx];
    int cnt = 0;

    while (curVal < preVal) {
      curVal *= 4;
      if (curVal >= LIMIT) {
        cnt = NOTHING;
        break;
      }
      cnt += 2;
    }
    if (cnt != NOTHING) {
      int tmp = dfs(idx + 1, cnt);
      if (tmp != NOTHING) {
        res = tmp + cnt;
      }
    }
  } else {
    int tmp = dfs(idx + 1, 0);
    if (tmp != NOTHING) {
      res = min(res, tmp);
    }

    for (int i = 1; i < 62; i += 2) {
      ll curVal = a[idx] * mul[i];
      if (curVal >= LIMIT) {
        break;
      }
      if (curVal < preVal) {
        break;
      }

      int tmp = dfs(idx + 1, i);
      if (tmp != NOTHING) {
        res = min(res, tmp + i);
      }
    }
  }

  return dp[idx][preMul] = res;
}

