typedef long long lint;

int calculate(lint x, lint y) {
    int res = 0;
    while (x > y) {
        y *= 4;
        ++res;
    }
    return res;
}

int calculate2(lint x, lint y) {
    int res = 0;
    while (x * 4 <= y) {
        ++res;
        x *= 4;
    }
    return res;
}

std::vector<int> solve(const std::vector<lint>& vec) {
    int N = vec.size();
    std::vector<int> res(N);
    std::stack<int> next;
    next.push(N);
    for (int i = N - 2; i >= 0; --i) {
        res[i] += res[i + 1];
        int need = calculate(vec[i], vec[i + 1]);
        if (need == 0) {
            int push = calculate2(vec[i], vec[i + 1]);
            while (push--) next.push(i + 1);
            continue;
        }
        int add = 0, prev = i + 1;
        for (int coeff = need; coeff > 0; --coeff) {
            int border = next.top();
            add += (border - prev) * coeff;
            prev = border;
            if (border == N) {
                break;
            }
            next.pop();
        }
        res[i] += add;
    }
    return res;
}

