lint power(lint x, lint n, lint MOD=10000000000000000)
{
    lint ans = 1;
    while (n>0)
    {
        if (n & 1) (ans *= x) %= MOD;
        (x *= x) %= MOD;
       n >>= 1;
    }
   return ans;
}

vector<lint> counts(vector<lint> A)
{
    int N = A.size();
    vector<lint> ans(N + 1);

    ans[1] = 0;
    map<lint, pint> ma;
    ma[A[N - 1]] = pint(1, 1000000000);

    FOR(i, 1, N)
    {
        ans[i + 1] = ans[i];
        lint q = A[N - 1 - i];

        int p = 0;
        while (ma.begin()->first * power(2, p) < q) p += 2;

        while (p > 0)
        {
            pint pa = ma.begin()->second;
            int decl = min(p, pa.second);
            ma.begin()->second.second -= decl;
            p -= decl;
            ans[i + 1] += ma.begin()->second.first * decl;

            while (ma.begin()->second.second == 0)
            {
                pint merge_info = next(ma.begin())->second;
                ma.begin()->second.first += merge_info.first;
                ma.begin()->second.second = merge_info.second;
                ma.erase(next(ma.begin()));
            }
        }

        int ppp = 0;
        while (q * power(2, ppp + 2) <= A[N - i]) ppp += 2;
        if (ppp) ma[q] = pint(1, ppp);
        else
        {
            pint info = ma.begin()->second;
            ma.erase(ma.begin());
            ma[q] = info;
            ma[q].first++;
        }
    }
    return ans;
}

