  for(int i = 1; i < n; ++i) {
    long long cnt = 0, now = a[i - 1];
    memo[i][0] = memo[i - 1][0];
    while(a[i] > now) {
      cnt += 2LL;
      now *= 4LL;
    }
    memo[i][0] += cnt * i;
  }
  for(int i = n - 2; i >= 0; --i) {
