      now *= 4LL;
    }
    memo[i][1] += cnt * (n - 1 - i);
  }
  ans = min(memo[n - 1][0] + n, memo[0][1]);
  for(int i = 0; i < n - 1; ++i) {
    long long now = 0;
    now += memo[i][0] + memo[i + 1][1] + i + 1;
