        left[i+1]=left[i]+1;
        while (cnt&&!margin.empty()){
            left[i+1]+=cnt*(i-margin.top().first);
            if (cnt<margin.top().second) cnt=0,margin.top().second-=cnt;
            else cnt-=margin.top().second,margin.pop();
        }
        left[i+1]+=cnt*i;
        if (m) margin.emplace(i,m);
    }
    margin=decltype(margin)();
    for (int i=N-2;i>=0;--i){
        ll cnt=0,m=0,c=C[i];
