        nr=i-1ll;
        k=0;
        t2[i]*=1ll*(-2);
        v2[i]=v2[i-1]+1ll;
        while(t2[i]<t2[i-1])
        {
            t2[i-1]*=4ll;
            k+=2ll;
        }
        v2[i]+=1ll*nr*k;
    }
    for(long long i=1;i<=n+1;++i)
    {
        sol=min(sol,v1[i]+v2[i-1]);
    }
    cout<<sol;
    return 0;
}

