	for (int i = n - 2; i >= 0; i--) {
		ll temp = a[i];
		ll now = 0;
		ll next = a[i + 1];
		REP(j, 16) {
			if (temp > next) {
				while (temp > next) {
					next *= 4;
					now++;
				}
			}
			if (now <= 15) {
				dp[i][j] = dp[i + 1][now] + j;
			}
			else {
				dp[i][j] = dp[i + 1][15] + (now - 15)*(n - i - 1);
			}
			temp *= 4;
		}
	}
	REP(i, 16)dp2[0][i] = i;
	rep(i, 1, n) {
		ll temp = a[i];
		ll now = 0;
		ll prev = a[i - 1];
		REP(j, 16) {
			if (temp > prev) {
				while (temp > prev) {
					prev *= 4;
					now++;
				}
			}
			if (now <= 15) {
				dp2[i][j] = dp2[i - 1][now] + j;
			}
			else {
				dp2[i][j] = dp2[i - 1][15] + (now - 15)*i;
			}
			temp *= 4;
		}
	}
