struct S{
	ll l, r, fr;
	S(ll x):l(x), r(x), fr(1) {}
	ll operator +=(S const &o){
		ll t = o.l, an = 0, nr = o.r;
		while (r > t)t <<= 2, nr <<= 2, an += o.fr << 1;
		fr += o.fr;
		r = nr;
		return an;
	}
};

void go(ll dp[]){
	ll an = 0;
	deque<S> dq;
	f(i, 1, n + 1){
		S c(x[i]);
		while (!dq.empty() && dq.front().l < c.r)an += (c += dq.front()), dq.pop_front();
		dq.push_front(c);
		dp[i] = an;
	}
}

