struct num {
    int x, s;
    num(int x_ = 0, int s_ = 0) {
        x = x_, s = s_;
    }
};

bool operator<=(num a, num b) {
    int x = min(a.s, b.s);
    a.s -= x;
    b.s -= x;
    if (a.s == 0) {
        while (a.x > b.x && b.s > 0) {
            --b.s;
            b.x *= 4;
        }
        return a.x <= b.x;
    }
    else {
        while (a.x <= b.x && a.s > 0) {
            a.x *= 4;
            --a.s;
        }
        return a.x <= b.x;
    }
}

void solve(vi &arri, vi &res) {
    int n = arri.size();
    vi prev(n, -1);
    res[0] = res[1] = 0;
    vc<num> arr(n);
    for (int i = 0; i < n; ++i) {
        arr[i] = num(arri[i], 0);
    }
    for (int i = 1; i < n; ++i) {
        if (arr[i] <= arr[i - 1]) {
            auto t = arr[i];
            ++t.s;
            if (t <= arr[i - 1]) {
                prev[i] = i - 1;
            }
            else {
                prev[i] = prev[i - 1];
            }
            res[i + 1] = res[i];
        }
        else {
            int j = i;
            int glob_delta = 0;
            while (j != 0) {
                int delta = 0;
                while (!(arr[j] <= arr[j - 1])) {
                    ++arr[j - 1].s;
                    ++delta;
                }
                int cnt = delta;
                if (cnt == 0) {
                    break;
                }
                delta *= j - 1 - prev[j - 1];
                glob_delta += delta;

                bool two_or_more_elements = (j - 1 - prev[j - 1] >= 2);
                j = prev[j - 1] + 1;
                if (two_or_more_elements) {
                    arr[j].s += cnt;
                }
            }
            prev[i] = j - 1;
            res[i + 1] = res[i] + glob_delta * 2;
        }
    }
}

