vint f() {
    stack<pint> st;
    st.push({INT_MAX, 0});
    vint ret{0, 0};
    reps(i, N - 1) {
        int v = 0;
        while (A[i] > A[i - 1] << (v * 2)) { v++; }
        while (A[i] << ((-v + 1) * 2) <= A[i - 1]) { v--; }
        ret.push_back(ret.back());
        int cur = i;
        while (v > 0) {
            if (v >= st.top().first) {
                ret.back() += (cur - st.top().second) * v, cur = st.top().second, v -= st.top().first, st.pop();
            } else {
                ret.back() += (cur - st.top().second) * v, cur = st.top().second, st.top().first -= v, v = 0;
            }
        }
        if (v < 0) { st.push({-v, i}); }
    }
    return ret;
}
