V< ll > dp, pd;

void comp(const V< ll >& tab, V< ll >& dp)
{
    dp.resize(tab.size());
    stack< pair< int, int > > S;
    S.push({0, 1e9});
    ll pp = 1e18;
    for (int i = 0; i < tab.size(); ++i)
    {
        dump(i, tab[i], S.size());
        dp[i] = (i > 0? dp[i - 1] : 0);
        ll v = tab[i];
        while (v > pp)
        {
            dp[i] += 2 * (i - S.top().st);
            --S.top().nd;
            if (not S.top().nd) 
                S.pop();
            pp *= 4;
        }
        if (i != 0)
        {
            ll tmp = v;
            int cnt = 0;
            while (tmp * 4 <= pp)
                ++cnt, tmp *= 4;
            if (cnt)
                S.push({i, cnt});
        }
        pp = v;
    }
}

