#define all(obj) (obj).begin(), (obj).end()
typedef long long int ll;
typedef long double ld;
using namespace std;

ll n, INF = 1000000000000000000;

vll dat;

vvl calc(){
  vvl dp = VV(n+1, 16, INF, ll);
  dp[0][0] = 0;
  for(ll i=0;i<=15;i++) dp[1][i] = 2*i;
  for(ll i=2;i<=n;i++){

    ll min_upd = 0;
    ll lef = dat[n-i], ri = dat[n-i+1];
    if(lef>ri) {
      while(lef>ri) lef/=4, min_upd++;
    }else {
      while(4LL*lef<=ri) ri/=4, min_upd--;
    }
    for(ll j=0;j<=15;j++){
      ll tmp = max(min_upd + j, 0LL);
      //iでj回操作を行う場合、a[i]*4^j <= a[i+1]*4^kを満たす
      //kが更新対象、dp[i][j] = dp[i-1][k] + j
      //k==15については dp[i][j] = dp[i-1][15] + L*(k - 15);
      for(ll k=tmp;k<=15;k++) dp[i][j] = min(dp[i][j], dp[i-1][k] + 2*j);
      if(tmp>=15) dp[i][j] = min(dp[i][j], dp[i-1][15] + 2*(i-1)*(tmp-15) + 2*j);
    }
  }
  return dp;
}
int main(int argc, char const *argv[]) {
  std::cin >> n;
  dat.resize(n);
  re(i, n) scanf("%lld", &dat[i]);
  vvl R = calc();
  reverse(all(dat));
  vvl L = calc();
  ll ans = INF;
  //for(int i=0;i<=n;i++) std::cout << R[i][0] << (i==n?"\n":" ");
  //for(int i=0;i<=n;i++) std::cout << L[i][0] << (i==n?"\n":" ");

  for(int i=0;i<=n;i++) {
    //std::cout << L[i][0] << " " <<  R[n-i][0] << " " << i << '\n';
    ans = min(ans, L[i][0] + R[n-i][0] + i);
  }
  std::cout << ans << '\n';
  return 0;
}

