		{
			sta[++top]=calc(a[u+1],a[u]);
			sta1[top]=u+1;
			suf[u]=suf[u+1];
		}
		else
		{
			LL t=calc(a[u],a[u+1]);
			while (top>0&&sta[top]<t)	{t=t-sta[top];top--;}
			sta[top]-=t;
			suf[u]=suf[u+1]+calc(a[u],a[u+1])*(sta1[top]-u-1);
