int N, A[200000];

int main() {
  cin >> N;
  for(int i = 0; i < N; i++) {
    cin >> A[i];
  }
  // どこかまで負 → 奇数回の操作を行う
  // どこかから正 → 偶数回の操作を行う

  vector< int64 > suffix(N);
  for(int i = N - 2; i >= 0; i--) {
    // [0,i) が負
    // [i,N) が正 → [i+1,N)の条件が最小回数で成立 → iのままにして [i+1,N]を偶数回操作してたぴゃ～する
    // [i+1]の要素はもとのままなので
    int64 u = A[i], v = A[i + 1], times = 0;
    while(u > v) {
      v *= 2;
      ++times;
    }
    if(times % 2 == 1) ++times;
    suffix[i] = suffix[i + 1] + (times * (N - i - 1));
  }

  vector< int64 > prefix(N);
  prefix[0] = 1;
  for(int i = 1; i < N; i++) {
    int64 u = A[i - 1], v = A[i], times = 0;
    while(-u > -v) {
      u *= 2;
      ++times;
    }
    if(times % 2 == 0) ++times;
    prefix[i] = prefix[i - 1] + (times * i);
  }

  int64 ret = min(prefix[N - 1], suffix[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, prefix[i - 1] + suffix[i]);
  }
  cout << ret << endl;

}

