using namespace std;
typedef long long int ll;
typedef pair <ll,int> P;

ll A[SIZE],memo[SIZE];
int right[SIZE];
ll ans[SIZE];
ll sum[SIZE];
ll rt[SIZE];
P pos[SIZE];
int n;

ll get(int s,int t)
{
	return rt[t]-(s==0?0:rt[s-1]);
}
void solve()
{
	for(int i=n-2;i>=0;i--)
	{
		right[i]=0;
		if(A[i]>A[i+1])
		{
			ll now=A[i+1];
			while(now<A[i])
			{
				now*=4LL;
				right[i]++;
			}
		}
		else
		{
			ll now=A[i];
			while(now<=A[i+1])
			{
				now*=4LL;
				right[i]--;
			}
			right[i]++;
		}
	}
	sum[0]=0;
	for(int i=1;i<n;i++) sum[i]=sum[i-1]+(ll) right[i-1];
	for(int i=0;i<n;i++)
	{
		rt[i]=sum[i];
		if(i>0) rt[i]+=rt[i-1];
	}
	int sz=0;
	pos[sz++]=P(-1000000000,n);
	ans[n]=0;
	for(int i=n-1;i>=0;i--)
	{
		while(sz>0&&pos[sz-1].first>=sum[i]) sz--;
		int to=pos[sz-1].second;
		ans[i]=get(i,to-1)-(ll) (to-i)*sum[i]+ans[to];
		pos[sz++]=P(sum[i],i);
	}
	//for(int i=0;i+1<n;i++) printf("%d ",right[i]);puts("");
	//for(int i=0;i<n;i++) printf("%lld ",A[i]);puts("");
	//for(int i=0;i<n;i++) printf("%lld ",ans[i]);puts("");
}
