	for(int i=0;i<n;i++) scanf("%lld",&A[i]);
	if(n==1)
	{
		puts("0");
		return 0;
	}
	solve();
	for(int i=0;i<n;i++) memo[i]=ans[i]*2LL;
	memo[n]=0;
	for(int l=0,r=n-1;l<r;l++,r--) swap(A[l],A[r]);
	solve();
	for(int l=0,r=n-1;l<r;l++,r--) swap(ans[l],ans[r]);
	for(int i=0;i<n;i++) memo[i+1]+=ans[i]*2LL+i+1;
	ll ret=memo[0];
	for(int i=1;i<=n;i++) ret=min(ret,memo[i]);
	printf("%lld\n",ret);
	return 0;
}

