typedef long double ld;

#define int long long

const int INF = 1e18 + 239;

struct Segment {
	ld l;
	ld r;

	int len;

	Segment(ld x) {
		l = x;
		r = x;
		len = 1;
	}

	Segment(ld l_, ld r_, int len_) {
		l = l_;
		r = r_;
		len = len_;
	}

	Segment(const Segment &a, const Segment &b) {
		l = a.l;
		r = b.r;
		len = a.len + b.len;
	}

	void apply(int x) {
		l += 2 * x;
		r += 2 * x;
	}
};

vector<int> calc(int n, vector<ld> a) {
	vector<int> ans(n + 1);
	vector<Segment> st = {Segment(a[0])};
	int cost = 0;
	for (int i = 1; i < n; i++) {
		// cerr << "+ " << i << endl;

		while (st.back().r < a[i]) {
			// cerr << "it: " << endl;
			// cerr << "st: " << endl;
			// for (auto t : st) {
			// 	cerr << t.l << ' ' << t.r << ' ' << t.len << endl;
			// }
			int ssz = (int)st.size();
			int can = ceil((a[i] - st.back().r) / 2);
			if (ssz > 1) {
				ld dl = (st[ssz - 2].r - st[ssz - 1].l) / 2;
				can = min(can, (int)dl);
			}
			cost += can * st.back().len;
			st.back().apply(can);
			if (ssz > 1 && st[ssz - 2].r < st[ssz - 1].l + 2) {
				auto bc = st.back();
				st.pop_back();
				st.back() = Segment(st.back(), bc);
			}
			// cerr << "st: " << endl;
			// for (auto t : st) {
			// 	cerr << t.l << ' ' << t.r << ' ' << t.len << endl;
			// }
		}
		// cerr << "- " << i << endl;
		st.push_back(Segment(a[i]));
		ans[i + 1] = cost;
	}
	return ans;
}

