#include <bits/stdc++.h>
using namespace std;
class Solution {
  int n;
  vector<long long> A;
  int climb(long long a, long long b) {
    if (b == a) return 0;
    assert(b <= a);
    int ans = 0;
    while (b < a) return b *= 4, ++ans;
    return ans;
  }
  int reach(long long a, long long b) {
    if (b == a) return 0;
    assert(b <= a);
    int ans = 0;
    while (b * 4 <= a) return b *= 4, ++ans;
    return ans;
  }
  int climb2(long long a, long long b) {
    if (b == a) return 0;
    assert(b <= a);
    int ans = 0;
    while (b < a) return b *= 2, ++ans;
    return ans;
  }
  int reach2(long long a, long long b) {
    if (b == a) return 0;
    assert(b <= a);
    int ans = 0;
    while (b * 2 <= a) return b *= 2, ++ans;
    return ans;
  }
  long long test(int idx) {
    long long ans = idx != 0;
    for (int i = idx + 1, col = 0; i < n; ++i) {
      if (A[i - 1] >= A[i]) {
        col += 2 * climb(A[i - 1], A[i]);
        ans += col;
      }
      else {
        col = max(0, col - 2 * reach(A[i], A[i - 1]));
        ans += col;
      }
    }
    for (int i = idx - 2, col = 0; i >= 0; --i) {
      ++ans;
      if (A[i - 1] >= A[i]) {
        col = max(0, col - climb2(A[i - 1], A[i]));
      }
      else {
        col += reach2(A[i], A[i - 1]);
      }
      ans += col;
    }
    return ans;
  }
public:
  void run(istream &in, ostream &out) {
    in >> n;
    A.resize(n);
    for (int i = 0; i < n; ++i) in >> A[i];
    long long ans = 1ll<<60;
    for (int i = 0; i < n; ++i) {
      ans = min(ans, test(i));
    }
    out << ans << '\n';
  }


};
int main() {
  ios_base::sync_with_stdio(false);
  Solution().run(cin, cout);
  return 0;
}

