struct I {
    ll i, cnt;
};

vector<ll> calc(const vector<ll> &v){
    vector<ll> ret(v.size(), 0);
    ll pre = v[0];
    stack<I> st;
    for(ll i = 1; i < v.size(); i++){
        ret[i] = ret[i - 1];
        if(v[i] <= pre){
            ll cnt = 0;
            ll tmp = v[i];
            while(tmp * 4 <= pre){
                tmp *= 4;
                cnt++;
            }
            if(cnt) st.push(I{i, cnt});
        }else{
            ll cnt = 0;
            ll tmp = pre;
            while(tmp < v[i]){
                tmp *= 4;
                cnt++;
            }
            while(cnt && st.size()){
                I tmp = st.top();
                st.pop();
                if(cnt > tmp.cnt){
                    cnt -= tmp.cnt;
                    ret[i] += (i - tmp.i) * tmp.cnt;
                }else{
                    tmp.cnt -= cnt;
                    ret[i] += (i - tmp.i) * tmp.cnt;
                    if(tmp.cnt) st.push(tmp);
                }
            }
            if(cnt) ret[i] += cnt * i;
        }
        pre = v[i];
    }
    return ret;
}

