const ll MAX_N = 2e5, MAX_X = 16;
ll N;
ll A[MAX_N]; //0-indexed
ll dp_pos[MAX_N][MAX_X + 1];
ll dp_neg[MAX_N][MAX_X + 1];

ll positive(ll l, ll x){
   //A_l, ..., A_N-1に対し、A_lに*4をx回するという条件下で*4倍を合計何回すれば単調増加列を作れるか？
   if (dp_pos[l][x] >= 0) return dp_pos[l][x];
   else if (l >= N) return 0;
   else if (x > MAX_X) return (positive(l, MAX_X) + (x - MAX_X) * (N - l));
   else if (l == N - 1) {
      dp_pos[l][x] = x;
      return x;
   }
   else{
      ll k = 0;
      unsigned long long tmp1 = A[l] * (1ull << (2*x));
      unsigned long long tmp2 = A[l + 1];
      while (tmp2 < tmp1){
         tmp2 *= 4;
         k ++;
      }
      dp_pos[l][x] = positive(l + 1, k) + x;
      return dp_pos[l][x];     
   }
}

ll negative(ll l, ll x){
   /*
   A0, A1, ..., A_lに対し, A_lに*4をx回したときに合計*4を何回すれば単調減少列を作れるか？
   */
  if (dp_neg[l][x] >= 0) return dp_neg[l][x];
  else if (l < 0) return 0;
  else if (x > MAX_X) return (negative(l, MAX_X) + (x - MAX_X) * (l + 1));
  else if (l == 0){
     dp_neg[l][x] = x;
     return x;
  }
  else{
     ll k = 0;
     unsigned long long  tmp1 = A[l] * (1ll << (2 * x));
     unsigned long long  tmp2 = A[l - 1];
     while (tmp2 < tmp1){
        tmp2 *= 4;
        k++;
     }
     dp_neg[l][x] = negative(l - 1, k) + x;
     return dp_neg[l][x];
   }
}

