  FOR (i, 1, n) {
    //cnt1[i+1];
    if (a[i-1] >= a[i]) {
      cnt1[i+1] = cnt1[i] + 1;
    } else {
      double r = (double)a[i] / a[i-1];
      ll add = ceil(log(r) / log(4)) * i * 2;
      cnt1[i+1] = cnt1[i] + 1 + add;
