LL getNeedShift(LL v1, LL v2){
    LL cnt = 0;
    while(v2 < v1){
        v2 <<= 2;
        cnt += 2;
    }
    return cnt;
}

int main(){
    LL n;
    cin >> n;
    vector<LL> a(n);
    for(LL i = 0; i < n; ++i){
        cin >> a[i];
    }
    vector<LL> right2(n);
    vector<LL> left2(n);
    for(LL i = n-2; i >= 0; --i){
        right2[i] = right2[i+1] + getNeedShift(a[i], a[i+1]) * (n-1-i);
    }
    for(LL i = 1; i < n; ++i){
        left2[i] = left2[i-1] + getNeedShift(a[i], a[i-1]) * i;
    }
    LL ans = right2[0];
    for(LL i = 1; i < n; ++i){
        LL cand = right2[i] + left2[i-1] + i;
        //cerr << i << " : " << right2[i] << " " << left2[i] << " " << cand << endl;
        ans = min(ans, cand);
    }
    //cerr << right2 << endl;
    //cerr << left2 << endl;
    cout << ans << endl;

    return 0;
}

