long long solve() {
    if (n == 1) return 0;
    if (n == 2) {
        return a[2] < a[1];
    }
    for(int i = n; i >= 2; i--) {
        long long cur = a[i];
        long long use = 0;
        while (cur < a[i - 1]) cur <<= 2, use += 2;
        f[0][i] = f[0][i + 1] + (use * (n - i + 1));
    }

    for(int i = 1; i < n; i++) {
        long long cur = a[i] * 2;
        long long use = 0;
        while (cur < a[i + 1] * 2) cur <<= 2, use += 2;
        f[1][i] = f[1][i - 1] + use * i + 1;
    }
    long long ans = min(f[0][2], f[1][n - 1] + 1);
    for(int i = 1; i < n; i++) {
        ans = min(ans, f[1][i - 1] + 1 + f[0][i + 2]);
    }
    return ans;
}
