inline int getint() {
	char ch = getchar(); int res = 0, ops = 1;
	for(; !isdigit(ch); ch = getchar()) if(ch == '-') ops = 0;
	for(; isdigit(ch); ch = getchar()) res = res * 10 + ch - '0';
	return ops ? res : -res;
}

void getf() {
	f[n] = 0, f[n + 1] = 0;
	stack<int> stk;
	for(int i = n - 1; i >= 1; i--) {
		f[i] = f[i + 1];
		ll cur = 1ll * a[i], lst = 1ll * a[i + 1]; 
		while(cur > lst) {
			int tmp = n;
			if(!stk.empty()) tmp = stk.top(), stk.pop();
			f[i] += 2ll * (tmp - i);
			lst *= 4;
		}
		while(cur * 4 < lst) {
			stk.push(i);
			cur *= 4;
		}
	}
}
void getg() {
	g[1] = 1, g[0] = 0;
	stack<int> stk;
	for(int i = 2; i <= n; i++) {
		g[i] = g[i - 1] + 1;
		ll cur = 1ll * a[i], lst = 1ll * a[i - 1]; 
		while(cur > lst) {
			int tmp = 1;
			if(!stk.empty()) tmp = stk.top(), stk.pop();
			g[i] += 2ll * (i - tmp + 1);
			lst *= 4;
		}
		while(cur * 4 < lst) {
			stk.push(i);
			cur *= 4;
		}
	}
}

int main() {
	n = getint();
	for(int i = 1; i <= n; i++) a[i] = getint();
	getf();
	getg();
