//	for(int i = 1; i <= n; i++) printf("%d%c", g[i], " \n"[i == n]);
	for(int i = 1; i <= n + 1; i++) ans = min(ans, g[i - 1] + f[i]);
	cout << ans << endl;
	return 0;
}

