int main(){
    long long N;
    long long A[200001];
    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> A[i];
    }

    for(int i = 0; i < 16; i++){
        dp[N][i] = 0;
        dp[N-1][i] = i*2;
    }
    for(int i = N-2; i >= 0; i--){
        //cout << i << endl;
        long long cnt = 0;
        if(A[i+1] < A[i]){
            long long tmp = A[i+1];
            while(tmp < A[i]){
                tmp*=4;
                cnt++;
            }
            for(int j = 0; j <= 15; j++){
                if(j+cnt <= 15) dp[i][j] = dp[i+1][j+cnt] + 2*j;
                else dp[i][j] = dp[i+1][15] + 2*(N-i-1)*(j+cnt-15) + 2*j;
            }
        }else{
            long long tmp1 = A[i];
            while(4*tmp1 <= A[i+1]){
                tmp1*=4;
                cnt++;
                //cout << 'U' << endl;
            }
            for(int j = 0; j <= cnt; j++){
                dp[i][j] = dp[i+1][0] + 2*j;
            }
            for(int j = cnt+1; j <= 15; j++){
                dp[i][j] = dp[i+1][j-cnt] + 2*j;
            }
        }
        //cout << endl;
    }

    for(int i = 0; i < 16; i++){
        dp_[0][i] = 0;
        dp_[1][i] = 1+i*2;
    }
    for(int i = 2; i <= N; i++){
        //cout << i << endl;
        long long cnt = 0;
        if(A[i-2] < A[i-1]){
            long long tmp = A[i-2];
            while(tmp < A[i-1]){
                tmp*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j <= 15; j++){
                if(j+cnt <= 15) dp_[i][j] = dp_[i-1][j+cnt]+ 1 + 2*j;
                else dp_[i][j] = dp_[i-1][15] + 2*(i-1)*(j+cnt-15) + 1 + 2*j;
            }
        }else{
            long long tmp1 = A[i-1];
            while(4*tmp1 <= A[i-2]){
                tmp1*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j <= cnt; j++){
                dp_[i][j] = dp_[i-1][0] + 2*j + 1;
            }
            for(int j = cnt+1; j <= 15; j++){
                dp_[i][j] = dp_[i-1][j-cnt] + 2*j + 1;
            }
        }
        //cout << endl;
    }
    long long ans = INT32_MAX;
    for(int i = 0; i <= N; i++){
        long long min1, min2;
        min1 = dp[i][0];
        min2 = dp_[i][0];

        for(int j = 0; j <=15; j++){
            min1 = min(min1, dp[i][j]);
            min2 = min(min2, dp_[i][j]);
            cout << dp[i][j] << ' ' << dp_[i][j] << endl;
            //cout << min1 << ' ' << min2 << endl;
        }
        //cout << min1 << ' ' << min2 << endl;
        ans = min(ans, min1+min2);
    }
    cout << ans << endl;
}

