//dp1[i][j]:[1,i]が負かつ単調増加になっていて、i番目でj回操作したときの操作数の和のmin
//dp2[i][j]:[i,N]が正かつ単調増加になっていて、i番目でj回操作したときの操作数の和のmin
int main(){
	int n;cin>>n;
	vector<ll> a(n+10),s(20);
	vector<vector<int>> dp1(n+10,vector<int>(20,INF)),dp2(n+10,vector<int>(20,INF));
	for(int i=1;i<=n;i++)cin>>a[i];
	s[0]=1;
	for(int i=1;i<=15;i++){
		s[i]=s[i-1]*4LL;
	}
	for(int i=2;i<=n;i++){
		for(int j=0;j<=15;j++){
			for(int k=0;k<=15;k++){
				if(a[i-1]*s[k]>a[i]*s[j])continue;
				dp1[i][j]=min(dp1[i][j],dp1[i-1][k]+j*2+1);
			}
		}
	}
	for(int j=0;j<=15;j++)dp2[n][j]=j*2;
	for(int i=n-1;i>=1;i--){
		for(int j=0;j<=15;j++){
			for(int k=0;k<=15;k++){
				if(a[i]*s[j]>a[i+1]*s[k])continue;
				dp2[i][j]=min(dp2[i][j],dp2[i+1][k]+j*2);
			}
		}
	}
	int ans=INF;
	dp1[0][0]=0,dp2[n+1][0]=0;
	for(int i=0;i<=n;i++){
		int mi1=INF,mi2=INF;
		for(int j=0;j<=15;j++){
			mi1=min(mi1,dp1[i][j]);
			mi2=min(mi2,dp2[i+1][j]);
		}
		ans=min(ans,mi1+mi2);
	}
	if(ans==INF){
		cout<<-1<<endl;
		return 0;
	}
	cout<<ans<<endl;
}

