#define MAXN 200010

int n;
ll a[MAXN];

ll ta[MAXN];
ll dp1[MAXN][17];
void Solve1(){	// 全正不降
	memcpy(ta,a,sizeof ta);
	fOR(i,n){
		int add = 0;
		if( ta[i] < 0 ){
			ta[i] *= -2;
			add = 1;
		}
		ll ota = ta[i];
		int vcnt = 0;
		For0(j,16){
			if( i == n ){ dp1[i][j] = j*2+add; continue; }
			while( ta[i] > ta[i+1] ){
				ta[i+1] *= 4;
				vcnt++;
			}
			if( vcnt > 15 ) dp1[i][j] = dp1[i+1][15] + 1LL*(n-i)*(vcnt-15)*2;
			else dp1[i][j] = dp1[i+1][vcnt];
			dp1[i][j] += j*2+add;
			ta[i] *= 4;
		}
		ta[i] = ota;
	}
}

ll dp2[MAXN][17];
void Solve2(){
	memcpy(ta,a,sizeof ta);
	For(i,n){
		int add = 0;
		if( ta[i] > 0 ){
			ta[i] *= -2;
			add = 1;
		}
		int ota = ta[i];
		int vcnt = 0;
		For0(j,16){
			if( i == 1 ){ dp2[i][j] = j*2+add; continue; }
			while( ta[i] < ta[i-1] ){
				ta[i-1] *= 4;
				vcnt++;
			}
			if( vcnt > 15 ) dp2[i][j] = dp2[i-1][15] + 1LL*(i-1)*(vcnt-15)*2;
			else dp2[i][j] = dp2[i-1][vcnt];
			dp2[i][j] += j*2+add;
			ta[i] *= 4;
		}
		ta[i] = ota;
	}
}

