	// For(i,n) cout << dp2[i][1] << " "; cout << endl;
	// For(i,n) cout << dp2[i][2] << " "; cout << endl;

	ll ans = LINF;
	For(i,n+1){
		ll tans = dp2[i-1][0] + dp1[i][0];
