int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);

  int n;
  cin >> n;
  vector<int> a(n), b(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
    b[n - i - 1] = a[i];
  }

  auto solve = [n](vector<int> &a) {
    const int LOG = 31;
    vector< vector<int> > dp(n + 1, vector<int>(LOG));
    iota(dp[1].begin(), dp[1].end(), 0);
    // dp[i + 1][0] = dp[i][need]

    auto cnt = [](long long from, long long to) {
      int res = 0;
      while (from > to) {
        to *= 4;
        res++;
      }
      return 2 * res;
    };

    for (int i = 1; i < n; i++) {
      for (int j = 0; j < LOG; j += 2) {
        int need = cnt(a[n - i - 1] * (1LL << j), a[n - i]);
        need += need & 1;
        if (need < LOG) {
          dp[i + 1][j] = j + dp[i][need];
        } else {
          dp[i + 1][j] = j + dp[i][LOG - 1] + i * (need - LOG + 1);
        }
      }
    }

    vector<int> res(n + 1);
    for (int i = 0; i <= n; i++) {
      res[i] = dp[i][0];
    }
    return res;
  };

  auto dp_pos = solve(a);
  auto dp_neg = solve(b);
  debug(dp_pos);
  debug(dp_neg);

  int ans = 1e9;
  for (int i = 0; i <= n; i++) {
    ans = min(ans, dp_pos[n - i] + dp_neg[i] + i);
  }
  cout << ans << '\n'; 
  return 0;
}

