inline void work(ll*f){
	vector<pii>v;v={pii(1,N)};
	for(i=2;i<=n;++i)if(a[i-1]>=a[i]){
		int x=0;
		for(;a[i]<<(x+1)*2<=a[i-1];++x);
		f[i]=f[i-1];
		if(x)v.push_back(pii(i,x));
	}else{
		int x=0,y;
		for(;a[i-1]<<x*2<a[i];++x);
		f[i]=f[i-1];
		for(;x;){
			y=v.size()==1?x:min(v.back().second,x);
			f[i]+=(i-v.back().first)*y;
			x-=y;if(v.size()>1)v.back().second-=y;if(!v.back().second)v.pop_back();
		}
	}
}
