		}
		R[i]=cur;
	}

	while(S.size())S.pop();
	cur=0;
	S.push(make_pair(mod,0));
	for(int i=1;i<a;i++){
		if(lp[i-1]>0){
			int req=lp[i-1];
			while(req>0){
				pair<int,int>tmp=S.top();
				S.pop();
				int C=min(tmp.first,req);
				cur+=min(tmp.first,req)*(i-tmp.second);
				req-=min(tmp.first,req);

				tmp.first-=C;
				if(tmp.first){
					S.push(tmp);
				}
			}
		}else if(lp[i-1]<0){
			S.push(make_pair(-lp[i],i));
		}
		L[i]=cur;
	}

	//for(int i=0;i<a;i++)printf("%lld %lld\n",L[i],R[i]);
	long long ret=inf;
	for(int i=0;i<=a;i++){
		long long tmp=0;
		if(i)tmp+=L[i-1]*2+i;
		if(i<a)tmp+=R[i]*2;
		ret=min(ret,tmp);
	}printf("%lld\n",ret);
}

