    for(LL i = 1; i < n; ++i){
        need_shift[i] = getNeedShift(a[i-1], a[i]);
    }
    vector<LL> right2(n+1);
    vector<LL> left2(n+1);
    for(LL i = n-2; i >= 0; --i){
        right2[i] = right2[i+1] + need_shift[i+1] * (n-1-i);
    }
    for(LL i = 1; i < n-1; ++i){
        left2[i] = left2[i-1] + need_shift[i-1] * (i-1);
    }
    LL ans = LL(1e+17);
