	buf.pb(n + 1);
	buf.pb(n);
	per1(i, n-1, 1){
		rsum[i] = rsum[i+1];
		int v = num[i+1];
		LL v1 = a[i], v2 = a[i+1];
		if( v1 > v2){
			while(v1 > v2){
				v2 *= 2;
				v--;
			}
		}
		if(v >= 0){
			buf.pb(i); continue;
		}
		v = -v;
		int need = v;
		need = (need + 1) / 2 * 2;
		while( need ){
			int pos = buf.back();
			v = num[pos+1] - num[pos];
			if(a[pos+1] >= a[pos]){
				v1 = a[pos+1], v2 = a[pos];
				while(v1 >= v2){
					v2 *= 2;
					v++;
				}
				v--;
			} else{
				v1 = a[pos+1], v2 = a[pos];
				while(v1 < v2){
					v1 *= 2;
					v--;
				}
			}
			v = (v / 2)*2;
			if(v > need){
				rsum[i] += need*1ll*(pos - i);
				a[pos] += need;
				break;
			} else{
				need -= v;
				rsum[i] += v*1ll*(pos-i);
				a[pos] += v;
				buf.pop_back();
			}
		}
	}
	//rep1(i, 1, n+1) printf("%lld%c", rsum[i], " \n"[i == n]);
