using namespace std;

long long N, X[200009], E[200009], G;

vector<long long> solve() {
	G = X[0];
	for (int i = 1; i < N; i++) {
		if (G <= X[i]) { G = X[i]; E[i] = 0; }
		else {
			if (X[i - 1] >= X[i]) {
				for (int j = 0; j < 16; j++) {
					if (X[i - 1] <= (1LL << (2 * j))*X[i]) { E[i] = E[i - 1] + j; break; }
				}
			}
			else {
				for (int j = 0; j < 16; j++) {
					if ((1LL << (2 * j)) * X[i - 1] > X[i]) { E[i] = E[i - 1] - (j - 1); break; }
				}
			}
			G = X[i];
			for (int j = 0; j < E[i]; j++) {
				G *= 4; if (G >= (1LL << 60)) { G = (1LL << 60); break; }
			}
		}
	}

	long long sum = 0, ret = 0, retsum = 0, pos = 0; for (int i = 0; i < N; i++) sum += E[i];
	vector<long long>res; res.push_back(sum * 2);

	for (int i = 0; i < N - 1; i++) {
		for (int j = i + 1; j < N; j++) {
			long long JURAI = E[j]; if (j > pos) JURAI -= retsum;

			if (j == i + 1) {
				E[i + 1] = 0; G = X[i + 1];
			}
			else {
				if (G <= X[j]) { G = X[j]; E[j] = 0; }
				else {
					if (X[j - 1] >= X[j]) {
						for (int k = 0; k < 36; k++) {
							if (X[j - 1] <= (1LL << (2 * k))*X[j]) { E[j] = E[j - 1] + k; break; }
						}
					}
					else {
						for (int k = 0; k < 16; k++) {
							if ((1LL << (2 * k)) * X[j - 1] > X[j]) { E[j] = E[j - 1] - (k - 1); break; }
						}
					}
				}
			}
			G = X[j];
			for (int k = 0; k < E[j]; k++) {
				G *= 4; if (G >= (1LL << 60)) { G = (1LL << 60); break; }
			}
			sum -= (JURAI - E[j]);
			if (E[j] >= 15 || j == N - 1 || JURAI - E[j] == 0) {
				ret = JURAI - E[j]; retsum += ret; pos = max(pos, 1LL * j); sum -= ret * (N - pos - 1);
				res.push_back(sum * 2);
				break;
			}
		}
	}
	res.push_back(0);
	return res;
}

int main() {
	cin >> N;
	for (int i = 0; i < N; i++) cin >> X[i];

	vector<long long> v1 = solve(); reverse(X, X + N);
	vector<long long> v2 = solve();
	reverse(v2.begin(), v2.end());
	long long minx = (1LL << 60);
	for (int i = 0; i <= N; i++) minx = min(minx, v1[i] + v2[i] + i);
	cout << minx << endl;
	return 0;
}

