using namespace std;

long dp[200001][16];
long dp_[200001][16];

int main(){
    long N;
    long A[200001];
    cin >> N;
    for(int i = 0; i < N; i++){
        cin >> A[i];
    }

    for(int i = 0; i < 16; i++){
        dp[N][i] = 0;
        dp[N-1][i] = i*2;
    }
    for(int i = N-2; i >= 0; i--){
        //cout << i << endl;
        long cnt = 0;
        if(A[i+1] < A[i]){
            long tmp = A[i+1];
            while(tmp < A[i]){
                tmp*=4;
                cnt++;
            }
            for(int j = 0; j <= 15; j++){
                if(j+cnt <= 15) dp[i][j] = dp[i+1][j+cnt] + 2*j;
                else dp[i][j] = dp[i+1][15] + 2*(N - i - 1)*(j+cnt-15) + 2*j;
            }
        }else{
            long tmp1 = A[i];
            while(4*tmp1 <= A[i+1]){
                tmp1*=4;
                cnt++;
                //cout << 'U' << endl;
            }
            for(int j = 0; j <= cnt; j++){
                dp[i][j] = dp[i+1][0] + 2*j;
            }
            for(int j = cnt+1; j <= 15; j++){
                dp[i][j] = dp[i+1][j-cnt] + 2*j;
            }
        }
        //cout << endl;
    }

    for(int i = 0; i < 16; i++){
        dp_[0][i] = 0;
        dp_[1][i] = 1+i*2;
    }
    for(int i = 2; i <= N; i++){
        //cout << i << endl;
        long cnt = 0;
        if(A[i-2] < A[i-1]){
            long tmp = A[i-2];
            while(tmp < A[i-1]){
                tmp*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j <= 15; j++){
                if(j+cnt <= 15) dp_[i][j] = dp_[i-1][j+cnt]+ 1 + 2*j;
                else dp_[i][j] = dp_[i-1][15] + 2*i*(j+cnt-15) + 1 + 2*j;
            }
        }else{
            long tmp1 = A[i-1];
            while(4*tmp1 <= A[i-2]){
                tmp1*=4;
                cnt++;
                //cout << 'V' << endl;
            }
            for(int j = 0; j <= cnt; j++){
                dp_[i][j] = dp_[i-1][0] + 2*j + 1;
            }
            for(int j = cnt+1; j <= 15; j++){
                dp_[i][j] = dp_[i-1][j-cnt] + 2*j + 1;
            }
        }
        //cout << endl;
    }
    long ans = INT32_MAX;
    for(int i = 0; i <= N; i++){
        long min1, min2;
        min1 = dp[i][0];
        min2 = dp_[i][0];

        for(int j = 0; j <=15; j++){
            min1 = min(min1, dp[i][j]);
            min2 = min(min2, dp_[i][j]);
            cout << dp[i][j] << ' ' << dp_[i][j] << endl;
            //cout << min1 << ' ' << min2 << endl;
        }
        //cout << min1 << ' ' << min2 << endl;
        ans = min(ans, min1+min2);
    }
    cout << ans << endl;
}

#include <bits/stdc++.h>

using namespace std;

const int max_n = 200222;
const long long inf = 1000111222000111222LL;

int n, a[max_n];
long long pref[max_n], suf[max_n];

int main() {
    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &a[i]);
    }

    suf[n + 1] = 0;
    suf[n] = 0;
    for (int i = n - 1; i >= 0; --i) {
        long long x = a[i + 1];
        int cnt = 0;
        while (a[i] > x) {
            x *= 4;
            cnt += 2;
        }
        suf[i] = suf[i + 1] + 1LL * cnt * (n - i);
    }

    pref[0] = 0;
    pref[1] = 0;
    for (int i = 1; i <= n; ++i) {
        a[i] *= 2;
    }
    for (int i = 2; i <= n; ++i) {
        long long x = a[i - 1];
        int cnt = 0;
        while (a[i] > x) {
            x *= 4;
            cnt += 2;
        }
        pref[i] = pref[i - 1] + 1LL * cnt * (i - 1);
    }

    for (int i = 1; i <= n; ++i) {
        pref[i] += i;
    }
    long long ans = inf;
    for (int i = 0; i <= n; ++i) {
        ans = min(ans, pref[i] + suf[i + 1]);
        //cout << i << ": " << pref[i] << " " << suf[i + 1] << endl;
    }
    printf("%lld\n", ans);
    return 0;
}

