    ll minim=INF;
    for (int i=1; i<=n+1; i++)
        for (int j=0; j<=15; j++)
            if (dp2[i-1][j]+dp[i][j]<minim)
                minim=dp2[i-1][j]+dp[i][j];
    printf("%lld", minim);
    return 0;
}

