long long int logni(long long int n)
{	long long int count=0;
	long long int hikaku=1;
	while(n>hikaku)
	{
		count++;
		hikaku=4*hikaku;
	}
	return count;
}

int main()
{	
	long long int N;
	scanf("%lld", &N);
	long long int a[N];
	for(long long int i=0;i<N;i++){
		scanf("%lld", &a[i]);
	}
	long long int b[N-1];
	for(long long int i=0;i<N-1;i++){
		if(a[i]>=a[i+1])
		{
			if(a[i]%a[i+1]==0)
			{b[i]=-logni(a[i]/a[i+1]);}
			else{b[i]=-logni(a[i]/a[i+1]+1);}
		}
		else
		{
			if(a[i+1]%a[i]==0)
			{b[i]=logni(a[i+1]/a[i]);}
			else{b[i]=logni(a[i+1]/a[i]+1);}
		}
	}
	long long int ans[N+1];
	ans[0]=0;
	for(long long int i=0;i<N-1;i++){

		if(b[i]<0)
		{	
			ans[0]+=2*(-b[i])*(N-i-1);
		}
	}
	long long int kari=0;
	if(b[0]<0){kari=2*b[0]*(N-1);}
	ans[1]=ans[0]+1+kari;
	for(long long int i=2;i<N+1;i++)
	{
		long long int kari1=0;	
		long long int kari2=0;
		if(b[i-1]<0){kari1=2*b[i-1]*(N-i);}
		if(b[i-2]>0){kari2=b[i-2]*2*(i-1);}
		ans[i]=ans[i-1]+1+kari1+kari2;
	}
	long long int answer=200000;
	for(long long int i=0;i<N+1;i++)
	{	
		if(ans[i]<answer){answer=ans[i];}
	}
	printf("%lld", answer);
}

