const ll INF = 1e18;

int d(ll x, ll y) {
	int res = 0;
	if (x > y) {
		while (y < x) {
			y *= 4;
			res++;
		}
	}	else {
		while (x * 4 <= y) {
			x *= 4;
			res--;
		}
	}
	return res;
}

vector <ll> get(vector <ll> & v) {
	int n = v.size();
	vector <ll> c(n - 1), f(n);
	for (int i = 0; i < n - 1; i++) {
		c[i] = d(v[i], v[i + 1]);
	}
	stack <pr <ll>> st;
	st.push({n - 1, INF});
	for (int i = n - 2; i >= 0; i--) {
		f[i] = f[i + 1];
		if (c[i] < 0) {
			st.push({i, -c[i]});
		}	else {
			int x = c[i];
			while (x--) {
				f[i] += st.top()[0] - i;
				st.top()[1]--;
				if (!st.top()[1]) {
					st.pop();
				}
			}
		}
	}
	return f;
}

