using int64 = long long;

struct UnionFindRange {
  vector< int > data;
  vector< int > left, right;

  UnionFindRange(int sz) {
    data.assign(sz, -1);
    left.resize(sz);
    right.resize(sz);
    for(int i = 0; i < sz; i++) left[i] = i;
    for(int i = 0; i < sz; i++) right[i] = i;
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    // if(data[x] > data[y]) swap(x, y);
    left[x] = min(left[x], left[y]);
    right[x] = max(right[x], right[y]);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  pair< int, int > range(int k) {
    k = find(k);
    return {left[k], right[k]};
  };

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};


int main() {
  int N;
  cin >> N;
  vector< double > A(N);
  for(int i = 0; i < N; i++) {
    cin >> A[i];
    A[i] = log(A[i]);
  }

  const double log4 = log(4);

  vector< int64 > suffix(N);
  {
    vector< double > add(N);
    UnionFindRange uf(N + 1);

    auto add2L = [&](int idx) {
      return add[uf.range(idx).first];
    };

    auto add2R = [&](int idx) {
      return add[uf.range(idx).second];
    };

    for(int i = N - 2; i >= 0; i--) {
      int64 times = 0;
      for(int j = i + 1; j < N; j = uf.range(j).second + 1) {
        if(A[j - 1] + add2L(j - 1) <= A[j] + add2R(j)) break;
        int64 v = ceil((A[j - 1] + add2L(j - 1) - (A[j] + add2R(j))) / log4);
        times += v * 2 * uf.size(j);
        add[uf.range(j).first] += v * log4;
        if(uf.size(j) > 1) add[uf.range(j).second] += v * log4;
        if(A[j - 1] + add2L(j - 1) + log4 > A[j] + add2R(j)) {
          add[uf.range(j).second] = add[uf.range(j).second];
          uf.unite(j - 1, j);
        }

      }
      suffix[i] = suffix[i + 1] + times;
    }
  }
  vector< int64 > prefix(N);
  {
    vector< double > add(N);
    prefix[0] = 1;

    UnionFindRange uf(N + 1);

    auto add2L = [&](int idx) {
      return add[uf.range(idx).first];
    };

    auto add2R = [&](int idx) {
      return add[uf.range(idx).second];
    };

    for(int i = 1; i < N; i++) {
      int64 times = 1;
      for(int j = i - 1; j >= 0; j = uf.range(j).first - 1) {
        if(A[j] + add2R(j) >= A[j + 1] + add2L(j + 1)) break;
        int64 v = ceil((A[j + 1] + add2L(j + 1) - (A[j] + add2R(j))) / log4);
        times += v * 2 * uf.size(j);
        add[uf.range(j).first] += log4 * v;
        if(uf.size(j) > 1) add[uf.range(j).second] += v * log4;

        if(A[j] + add2R(j) + log4 < A[j + 1] + add2L(j + 1)) {
          add[uf.range(j + 1).second] = add[uf.range(j + 1).second];
          uf.unite(j, j + 1);
        }

      }
      prefix[i] = prefix[i - 1] + times;
    }
  }

  int64 ret = min(prefix[N - 1], suffix[0]);
  for(int i = 1; i < N; i++) {
    ret = min(ret, prefix[i - 1] + suffix[i]);
  }
  cout << ret << endl;

}

