		mn = my_min(mn, calc(n / 2 - i, 1), n/2 - i);
		mn = my_min(mn, calc(n / 2 + i, 1), n / 2+ i);

		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;
	}

	long long R = calc(0, 1);
	mn = min(mn, R);

	for (int iter = 0; ; iter++) {
		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;

		long long x = 0;
		if (iter > 0)
			x = rand() % (n / 3);
		long long dx = 1;
		while (x <= n) {
			x += dx;
			long long new_R = calc(max(0LL, min(0LL+n,x)), 1);
			mn = min(mn, new_R);

			if (new_R >= R)
				dx *= 2;
			else
				dx = 1;

			R = new_R;

			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}
	}

	for (int i = 0; i < 40; i++) {
		mn = my_min(mn, calc(n / 4 - i, 1), n / 4 - i);
		mn = my_min(mn, calc(n / 4 + i, 1), n / 4 + i);

		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;
	}

	for (int i = 0; i < 40; i++) {
		mn = my_min(mn, calc(3*n / 4 - i, 1), 3*n / 4 - i);
		mn = my_min(mn, calc(3*n / 4 + i, 1), 3*n / 4 + i);

		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;
	}

	for (int i = 0; i < 40; i++) {
		mn = my_min(mn, calc(3 * n / 5 - i, 1), 3 * n / 5 - i);
		mn = my_min(mn, calc(3 * n / 5 + i, 1), 3 * n / 5 + i);

		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;
	}

	for (int i = 0; i < 40; i++) {
		mn = my_min(mn, calc(2 * n / 5 - i, 1), 2 * n / 5 - i);
		mn = my_min(mn, calc(2 * n / 5 + i, 1), 2 * n / 5 + i);

		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;
	}

	int move = 1234;
	while (move > 1) {
		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
			break;

		for (int i = min_pos + move; i <= n; i += move) {
			long long val = calc(i, 1);
			if (val < mn) {
				mn = val;
				min_pos = i;
				break;
			}
			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}
		for (int i = min_pos - move; i >= 0; i -= move) {
			long long val = calc(i, 1);
			if (val < mn) {
				mn = val;
				min_pos = i;
				break;
			}
			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}
		move /= 2;
	}

	for (int i = min_pos - 20; i <= min_pos + 20; i++)
		if (i >= 0 && i <= n) {
			mn = my_min(mn, calc(i, 1), i);
			if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) >= TL)
				break;
		}

	while (1)
		if ((((double)(clock() - t_BG)) / (CLOCKS_PER_SEC)) < TL) {
			mn = min(mn, calc(rand() % n, 1));
		}
		else
			break;
	cout << mn;
	return 0;
}

