	reps(i, 1, N) {
		if (mi < v[i]) {
			ll x = (v[i] / mi + 4 - 1) / 4;
			r[i+1] = x * i * 2 + r[i];
		} else {
			r[i+1] = r[i];
		}
		mi = v[i];
	}
}

