constexpr lint mod = 1e9+7;
constexpr lint INF = mod * mod;
constexpr int MAX = 200010;

struct range{
    lint len, li, lc, ri, rc;
    range(lint len, lint li, lint lc, lint ri, lint rc):
    len(len), li(li), lc(lc), ri(ri), rc(rc){}
};

lint push(stack<range> &st, range a, vector<lint> &lim){
    if(a.rc - st.top().lc <= lim[a.ri]){
        st.push(a);
        return 0;
    }
    auto t = st.top(); st.pop();
    lint x = a.rc + t.lc - lim[a.ri];
    return x * t.len + push(st, {a.len + t.len, a.li, a.lc, t.ri, t.ri + x}, lim);
}

vector<lint> solve(int n, vector<lint> a){
    vector<lint> lim(n, mod);
    rep(i, n-1){
        lim[i] = 0;
        if(a[i] <= a[i+1]){
            lint tmp = a[i];
            while(tmp < a[i+1]){
                tmp *= 4;
                ++lim[i];
            }
        }
        else{
            lint tmp = a[i+1];
            while(tmp < a[i]){
                tmp *= 4;
                --lim[i];
            }
        }
    }

    stack<range> st;
    st.push({0, n, mod, n, mod});
    vector<lint> R(n+1, 0);
    rrep(i, n) R[i] = R[i+1] + push(st, {1, i, 0, i, 0}, lim);
    return R;
}

