int main(int argc, char *argv[])
{
  int N;
  cin >> N;
  vector<ll> A(N);
  REP(i, N) cin >> A[i];
  vector<ll> negative_work_count(N), positive_work_count(N);
  negative_work_count[0] = 1;
  stack<int> neg_pos, pos_pos;

  REP2(i, 1, N) {
    negative_work_count[i] = 1 + negative_work_count[i - 1];
    ll num0 = A[i - 1];
    ll num1 = A[i];

    if (num0 < num1) {
      while (num0 < num1) {
        num0 *= 4;
        if (neg_pos.empty()) {
          negative_work_count[i] += i * 2;
        } else {
          negative_work_count[i] += (i - neg_pos.top()) * 2;
          neg_pos.pop();
        }
      }
    } else {
      while (num0 >= num1 * 4) {
        num1 *= 4;
        neg_pos.push(i);
      }
    }
  }
  positive_work_count[N - 1] = 0;
  REPD(i, N - 1) {
    positive_work_count[i] = positive_work_count[i + 1];
    ll num0 = A[i];
    ll num1 = A[i + 1];
    if (num0 > num1) {
      while (num0 > num1) {
        num1 *= 4;
        if (pos_pos.empty()) {
          positive_work_count[i] += (N - i - 1) * 2;
        } else {
          positive_work_count[i] += (pos_pos.top() - i) * 2;
          pos_pos.pop();
        }
      }
    } else {
      while (num1 >= num0 * 4) {
        num0 *= 4;
        pos_pos.push(i);
      }
    }
  }

  ll res = 1e18;
  REP(i, N + 1) {
    ll neg = i > 0 ? negative_work_count[i - 1] : 0;
    ll pos = i < N ? positive_work_count[i] : 0;
    // cout << neg << " " << pos << endl;
    res = min(res, neg + pos);
  }
  cout << res << endl;
  return 0;
}

