ll suf[MAX_N][MAX_LOG]; //odd

double al[MAX_N];

int solve()
{
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i];
        al[i] = log2((double)a[i]);
        //cerr << al[i] << endl;
    }
    for (int i = 0; i < MAX_LOG; ++i)
    {
        dp[1][i] = i;
    }
    pref[1][0] = dp[1][0];
    for (int i = 1; i < MAX_LOG; ++i)
    {
        pref[1][i] = pref[1][i - 1];
        if (i % 2 == 0)
        {
            pref[1][i] = min(pref[1][i], dp[1][i]);
        }
    }
    suf[1][MAX_LOG - 1] = dp[1][MAX_LOG - 1];
    for (int i = MAX_LOG - 2; i >= 0; --i)
    {
        suf[1][i] = suf[1][i + 1];
        if (i % 2 == 1)
        {
            suf[1][i] = min(suf[1][i], dp[1][i]);
        }
        //cerr << i << ' ' << suf[1][i] << endl;
    }
    for (int i = 2; i <= n; ++i)
    {
        for (int k = 0; k < MAX_LOG; ++k)
        {
            dp[i][k] = INF;
            if (k % 2 == 0)
            {
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
                dp[i][k] = min(dp[i][k], suf[i - 1][0] + k);
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
                int ind = floor(al[i] - al[i - 1] + k);
                if (ind >= 0)
                {
                    dp[i][k] = min(dp[i][k], pref[i - 1][ind] + k);
                }
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
            }
            else
            {
                int ind = ceil(al[i] - al[i - 1] + k);
                if (ind <= n)
                {
                    dp[i][k] = min(dp[i][k], suf[i - 1][max(0, ind)] + k);
                }
            }
        }
        pref[i][0] = dp[i][0];
        for (int k = 1; k < MAX_LOG; ++k)
        {
            pref[i][k] = pref[i][k - 1];
            if (k % 2 == 0)
            {
                pref[i][k] = min(pref[i][k], dp[i][k]);
            }
        }
        suf[i][MAX_LOG - 1] = dp[i][MAX_LOG - 1];
        for (int k = MAX_LOG - 2; k >= 0; --k)
        {
            suf[i][k] = suf[i][k + 1];
            if (k % 2 == 1)
            {
                suf[i][k] = min(suf[i][k], dp[i][k]);
            }
        }
    }
    ll ans = INF;
    for (int j = 0; j < MAX_LOG; ++j)
    {
        ans = min(ans, dp[n][j]);
    }
    cout << ans << endl;
    return 0;
}

