    rep(i,0,N) B[i]=-B[i];
    vi cp=dp;
    REP(i,0,N) dp[i]=0;
    memo.clear();
    memo[0]=INF;
    rep(i,0,N){
        dp[i+1]=dp[i];
        if(i==0) continue;
        if(B[i-1]<=B[i]){
            ll sum=0;
            ll X=B[i];
            while(1){
                if(B[i]*4<B[i-1]) break;
                B[i]*=4;
                sum+=2;
            }
            B[i]=X;
            if(sum>0) memo[i]=sum;
        }
        else{
            ll sum=0;
            while(1){
                if(B[i-1]<=B[i]) break;
                B[i-1]*=4;
                sum+=2;
            }
            auto it=rbegin(memo);
            vi x;
            ll y=-1,z;
            while(sum>0){
                auto p=*it;
                if(p.second<=sum){
                    sum-=p.second;
                    x.pb(p.first);
                    dp[i+1]+=(i-p.first)*p.second;
                }
                else{
                    dp[i+1]+=(i-p.first)*sum;
                    y=p.first,z=sum;
                    sum=0;
                }
                it--;
            }
            memo[y]-=z;
            rep(j,0,x.size()){
                ll X=x[j];
                memo.erase(X);
            }
        }
    }
    ll ans=INF;
    REP(i,0,N) ans=std::min(ans,dp[i]+cp[N-i]);
    cout<<ans<<endl;
}

