    for (int i = 1; i <= n; ++i) {
        a[i] *= 2;
    }
    reverse(a + 1, a + n + 1);
    calc(pref);
    reverse(pref + 1, pref + n + 2);
    for (int i = 0; i < n + 1; ++i) {
        pref[i] = pref[i + 1] + i;
    }

    long long ans = inf;
    for (int i = 0; i <= n; ++i) {
        ans = min(ans, pref[i] + suf[i + 1]);
        //cout << i << ": " << pref[i] << " " << suf[i + 1] << endl;
    }
    printf("%lld\n", ans);
    return 0;
}

