int dp[MAX_LOG];

int pref[2][MAX_LOG]; //even
int suf[2][MAX_LOG]; //odd

double al[MAX_N];

int solve()
{
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i];
        al[i] = log2((double)a[i]);
        //cerr << al[i] << endl;
    }
    for (int i = 0; i < MAX_LOG; ++i)
    {
        dp[i] = i;
    }
    pref[1][0] = dp[0];
    for (int i = 1; i < MAX_LOG; ++i)
    {
        pref[1][i] = pref[1][i - 1];
        if (i % 2 == 0)
        {
            pref[1][i] = min(pref[1][i], dp[i]);
        }
    }
    suf[1][MAX_LOG - 1] = dp[MAX_LOG - 1];
    for (int i = MAX_LOG - 2; i >= 0; --i)
    {
        suf[1][i] = suf[1][i + 1];
        if (i % 2 == 1)
        {
            suf[1][i] = min(suf[1][i], dp[i]);
        }
        //cerr << i << ' ' << suf[1][i] << endl;
    }
    for (int i = 2; i <= n; ++i)
    {
        int i1 = i % 2;
        for (int k = 0; k < MAX_LOG; ++k)
        {
            dp[k] = INF;
            if (k % 2 == 0)
            {
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
                dp[k] = min(dp[k], suf[i1 ^ 1][0] + k);
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
                int ind = floor(al[i] - al[i - 1] + k);
                if (ind >= 0)
                {
                    dp[k] = min(dp[k], pref[i1 ^ 1][min(MAX_LOG - 1, ind)] + k);
                }
                //cerr << i << ' ' << k << ' ' << dp[i][k] << endl;
            }
            else
            {
                int ind = ceil(al[i] - al[i - 1] + k);
                if (ind < MAX_LOG)
                {
                    dp[k] = min(dp[k], suf[i1 ^ 1][max(0, ind)] + k);
                }
            }
        }
        pref[i1][0] = dp[0];
        for (int k = 1; k < MAX_LOG; ++k)
        {
            pref[i1][k] = pref[i1][k - 1];
            if (k % 2 == 0)
            {
                pref[i1][k] = min(pref[i1][k], dp[k]);
            }
        }
        suf[i1][MAX_LOG - 1] = dp[MAX_LOG - 1];
        for (int k = MAX_LOG - 2; k >= 0; --k)
        {
            suf[i1][k] = suf[i1][k + 1];
            if (k % 2 == 1)
            {
                suf[i1][k] = min(suf[i1][k], dp[k]);
            }
        }
    }
    int ans = INF;
    for (int j = 0; j < MAX_LOG; ++j)
    {
        ans = min(ans, dp[j]);
    }
    if (ans == INF)
    {
        cout << -1 << endl;
        return 0;
    }
    cout << ans << endl;
    return 0;
}

