ll N;
vector<ll> A;

// l から u を昇順にするのにかかるコスト
ll asc(ll l, ll u) {
    if(l >= u) { return 0; }
    ll ret = 0;
    ll prev = A[l];
    for(int i = l+1; i <= u; ++i) {
        DBG("A[%lld]: %lld prev: %lld\n", i, A[i], prev);
        if(A[i] < prev) {
            ll tmp = A[i];
            while(tmp < prev) {
                tmp *= 4;
                ret += 2;
            }
            prev = tmp;
        } else {
            prev = A[i];
        }
    }
    return ret;
}
// u から l を降順にしてからマイナスにするのにかかるコスト
ll des(ll l, ll u) {
    if(l == u) { return 1; }
    if(l > u) { return 0; }
    ll ret = 0;
    ll prev = A[u];
    for(int i = u-1; i >= l; --i) {
        if(A[i] < prev) {
            ll tmp = A[i];
            while(tmp < prev) {
                tmp *= 4;
                ret += 2;
            }
            prev = tmp;
        } else {
            prev = A[i];
        }
    }
    return ret + (u - l) + 1;
}

ll solve() {
    ll ret = LLINF;
    // 全部昇順にする
    ll candi = asc(0, N-1);
    ret = min(ret, candi);
    DBG("%lld\n", candi);
    // 全部降順にする
    candi = des(0, N-1);
    ret = min(ret, candi);
    DBG("%lld\n", candi);
    // 最も連続に降順になるところ
    pair<ll, ll> cand = make_pair(-1, -1);     // 降順の最後, 続いた数
    ll cnt = 0;
    for(int i = 1; i < N; ++i) {
        if(A[i-1] < A[i]) {
            if(cand.second < cnt) {
                cand.first = i-1;
                cand.second = cnt;
            }
            cnt = 0;
        } else {
            cnt++;
        }
    }
    if(cand.second < cnt) {
        cand.first = N-1;
        cand.second = cnt;
    }
    ll candi1 = des(0, cand.first);
    ll candi2 = asc(cand.first+1, N-1);
    candi = candi1 + candi2;
    ret = min(ret, candi);
    DBG("[0, %lld] %lld + [%lld, %lld] %lld = %lld\n",
            cand.first, candi1, cand.first+1, N-1, candi2, candi);
    // 最も連続に昇順になるところ
    cand = make_pair(-1, -1);       // 昇順の始まりの一つ手前, 続いた数
    cnt = 0;
    ll pos = 0;
    for(int i = 1; i < N; ++i) {
        if(A[i-1] > A[i]) {
            if(cand.second < cnt) {
                cand.first = pos;
                cand.second = cnt;
            }
            cnt = 0;
            pos = i-1;
        } else {
            cnt++;
        }
    }
    if(cand.second < cnt) {
        cand.first = pos;
        cand.second = cnt;
    }
    candi1 = des(0, cand.first);
    candi2 = asc(cand.first+1, N-1);
    candi = candi1 + candi2;
    ret = min(ret, candi);
    DBG("[0, %lld] %lld + [%lld, %lld] %lld = %lld\n",
            cand.first, candi1, cand.first+1, N-1, candi2, candi);
    return ret;
}

signed main()
{
    cin >> N;
    A.assign(N, 0);
    REP(i, N) { cin >> A[i]; }
    ll ans = solve();
    printf("%lld\n", ans);
    return 0;
}

