int solve(int m, vector<double> a) {
	int cnt = 0;
	int n = a.size();
	if (m < 0 || m > n) return INF;
	if (m != 0) { a[m - 1]++;  cnt++; }
	for (int i = m - 2; i >= 0; i--) {
		a[i]++; cnt++;
		if (a[i] < a[i + 1]) {
			double d = (a[i + 1] - a[i] - EPS + 2) / 2.0;
			int d_ = d;
			a[i] += 2 * d_;
			cnt += 2 * d_;
		}
	}
	for (int i = m + 1; i < n; i++) {
		if (a[i - 1] > a[i]) {
			double d = (a[i - 1] - a[i] - EPS + 2) / 2.0;
			int d_ = d;
			a[i] += 2 * d_;
			cnt += 2 * d_;
		}
	}
	return cnt;
}

