    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    rep(i,n){
        cin >> a[i];
    }
    l[0] = 0, l[1] = 1;
    stack<P> prv;
    rep(i,n-1){
        if(a[i] >= a[i+1]){
            l[i+2] = l[i+1]+1;
            ll res = log4(a[i]/a[i+1]) - 1;
            if(res) prv.push(P(i, res));
        }else{
            ll res = log4((a[i+1]-1)/a[i]);
            ll ad = 1;
            while(!prv.empty()){
                P p = prv.top();
                prv.pop();
                if(p.se > res){
                    prv.push(P(p.fi, p.se-res));
                    ad += 2*res*(i-p.fi);
                    break;
                }else if(p.se < res){
                    res -= p.se;
                    ad += 2*p.se*(i-p.fi);
                }else{
                    ad += 2*res*(i-p.fi);
                    break;
                }
            }
            if(res) ad += 2*res*(i+1);
            l[i+2] = l[i+1] + ad;
        }
    }
    r[n] = r[n-1] = 0;
    stack<P> prv2;
    for(int i = n-2; i >= 0; i--){
        if(a[i] <= a[i+1]){
            r[i] = r[i+1];
            ll res = log4(a[i+1]/a[i]) - 1;
            if(res) prv2.push(P(i, res));
        }else{
            ll res = log4((a[i]-1)/a[i+1]);
            ll ad = 0;
            while(!prv.empty()){
                P p = prv2.top();
                prv2.pop();
                if(p.se > res){
                    prv2.push(P(p.fi, p.se-res));
                    ad += 2*res*(p.fi-i);
                    break;
                }else if(p.se < res){
                    res -= p.se;
                    ad += 2*p.se*(p.fi-i);
                }else{
                    ad += 2*res*(p.fi-i);
                    break;
                }
            }
            if(res) ad += 2*res*(n-1-i);
            r[i] = r[i+1] + ad;
        }
    }
    // sar(l, n+1), sar(r, n+1);
    ll ans = INF;
    rep(i,n+1){
        cmn(ans, l[i]+r[i]);
