    return s;
  }

  ll sum(int a, int b)
  { // [a, b)
    return sum(b - 1) - sum(a - 1);
  }

  void add(int i, ll x)
  {
    while (i <= N)
    {
      data[i] += x;
      i += i & -i;
    }
  }

  void add(int i)
  {
    add(i, 1);
  }
};

ll calc(ll x, ll y)
{
  if (x > y)
  {
    ll res = 0;
    ll mult = 1;
    while (x > y * mult)
    {
      res += 2;
      mult *= 4;
    }
    return res;
  }
  else
  {
    ll res = 0;
    ll mult = 1;
    while (x * (mult * 4) <= y)
    {
      res -= 2;
      mult *= 4;
    }
    return res;
  }
}

int N;
