  for (auto i = 1; i < N; i++)
  {
    imos_X[i] = X[i] + imos_X[i - 1];
    // cerr << "imos_X[" << i << "] = " << imos_X[i] << endl;
  }
  ll sum = imos_X[N - 1];
  ll mini = imos_X[N - 1];
  ans_X[N - 1] = 0;
  for (auto i = N - 2; i >= 0; i--)
  {
    mini = min(imos_X[i], mini);
    ans_X[i] = sum - mini * (N - i - 1);
    sum += imos_X[i];
  }
  for (auto i = 0; i < N; i++)
  {
    B[i] = A[i];
  }
  reverse(B, B + N);
  Y[0] = 0;
  for (auto i = 1; i < N; i++)
  {
    Y[i] = calc(B[i - 1], B[i]);
  }
  imos_Y[0] = 0;
  for (auto i = 1; i < N; i++)
  {
    imos_Y[i] = Y[i] + imos_Y[i - 1];
  }
  sum = imos_Y[N - 1];
  mini = imos_Y[N - 1];
  ans_Y[N - 1] = 0;
  for (auto i = N - 2; i >= 0; i--)
  {
    mini = min(imos_Y[i], mini);
    ans_Y[i] = sum - mini * (N - i - 1);
    sum += imos_Y[i];
  }
