void calc_counts(V<ll> &counts, const V<ll> &alist, ll n)
{
    deque<t2> stack;

    counts.pb(0LL);
    counts.pb(0LL);

    srep (i, 1LL, n) {
        debug_printf("-------------i = %lld\n", i);

        ll pa = alist[i-1];
        ll na = alist[i];
        ll mcount = 0LL;

        if (pa >= na) {
            na *= 4LL;
            while (pa >= na) {
                na *= 4LL;
                mcount++;
            }
            debug_printf("xx0\n");
            stack.push_back(t2(i, mcount));
            counts.pb(*(counts.end() - 1));
            continue;
        }

        assert(pa < na);

        while (pa < na) {
            pa *= 4LL;
            mcount++;
        }

        ll remain_a = i;
        ll count = *(counts.end() - 1);
        while (!stack.empty()) {
            t2 idx_cnt = stack.back(); stack.pop_back();
            ll pidx = get<0>(idx_cnt);
            ll pmcount = get<1>(idx_cnt);
            if (mcount <= pmcount) {
                if (mcount < pmcount) {
                    stack.push_back(t2(pidx, pmcount - mcount));
                }
                debug_printf("xx1 (remain_a=%lld pidx=%lld) count=%lld --> ",
                             remain_a, pidx, count);
                count += (mcount * (remain_a - pidx) * 2LL);
                debug_printf("%lld\n", count);
                mcount = 0LL;
                break;
            }

            debug_printf("xx2 count=%lld --> ", count);
            count += (mcount * (remain_a - pidx) * 2LL);
            debug_printf("%lld\n", count);
            remain_a = pidx;
            mcount -= pmcount;
        }

        debug_printf("xx3 count=%lld --> ", count);
        count += (mcount * remain_a * 2LL);
        debug_printf("%lld\n", count);
        counts.pb(count);
    }
}

