};

int a[200000];
long long right[200001];
long long left[200001];

int main() {
    int n, i;
    long long ans = 1e18;
    deque <block> d;

    scanf("%d", &n);

    for (i = 0; i < n; i++) scanf("%d", &a[i]);

    d.push_back(block(1, 0));

    for (i = n - 2; i >= 0; i--) {
        long long x = a[i], y = a[i + 1];

        right[i] = right[i + 1];

        while (x > y) {
            y *= 4;
            right[i] += d[0].size * 2;
            d[0].count--;

            if (d.size() > 1 && d[0].count == 0) {
                d[1].size += d[0].size;
                d.pop_front();
            }
        }

        if (x * 4 > y) {
            d[0].size++;
        } else {
            int count = 0;

            while (x * 4 <= y) {
                x *= 4;
                count++;
            }

            d.push_front(block(1, count));
        }
    }

    d.clear();
    d.push_back(block(1, 0));

    for (i = 1; i < n; i++) {
        long long x = a[i - 1], y = a[i];

        left[i + 1] = left[i];

        while (x < y) {
            x *= 4;
            left[i + 1] += d[0].size * 2;
            d[0].count--;

            if (d.size() > 1 && d[0].count == 0) {
                d[1].size += d[0].size;
                d.pop_front();
            }
        }

        if (y * 4 > x) {
            d[0].size++;
        } else {
            int count = 0;

            while (y * 4 <= x) {
                y *= 4;
                count++;
            }

            d.push_front(block(1, count));
        }
    }

    for (i = 0; i <= n; i++) ans = min(ans, left[i] + right[i] + i);

    printf("%lld\n", ans);

