const int MAXN = (int)2e5 + 100;

int n;
ll a[MAXN];
ll pows[MAXN];

int a_delt[MAXN], b_delt[MAXN];
ll pref[MAXN], suff[MAXN];

vector<pii> cur;

int solve()
{
    cin >> n;
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    pows[0] = 1;
    for (int i = 1; i <= n; i++)
        pows[i] = pows[i - 1] * 4ll;

    for (int i = 2; i <= n; i++)
    {
        for (int j = 0; ; j++)
            if (a[i] * pows[j] >= a[i - 1])
            {
                a_delt[i] = 2 * j;
                break;
            }
        if (a_delt[i] == 0)
        {
            for (int j = 0; ; j++)
                if (a[i] < pows[j] * a[i - 1])
                {
                    a_delt[i] = -2 * j + 2;
                    break;
                }
        }
        //cerr << i << ' ' << a_delt[i] << endl;
    }

    for (int i = 1; i < n; i++)
    {
        for (int j = 0; ; j++)
            if (a[i] * pows[j] >= a[i + 1])
            {
                b_delt[i] = 2 * j;
                break;
            }
        if (b_delt[i] == 0)
        {
            for (int j = 0; ; j++)
                if (a[i] < a[i + 1] * pows[j])
                {
                    b_delt[i] = -2 * j + 2;
                    break;
                }
        }
    }

    for (int i = n - 1; i > 0; i--)
    {
        suff[i] = suff[i + 1];
        if (a_delt[i + 1] < 0)
            cur.pb(mp(i + 1, a_delt[i + 1]));
        else
        {
            while (!cur.empty() && a_delt[i + 1] > 0)
            {
                if (-cur.back().Y > a_delt[i + 1])
                {
                    cur.back().Y += a_delt[i + 1];
                    suff[i] += (cur.back().X - i - 1) * a_delt[i + 1];
                    a_delt[i + 1] = 0;
                }
                else
                {
                    suff[i] += (cur.back().X - i - 1) * a_delt[i + 1];
                    a_delt[i + 1] += cur.back().Y;
                    cur.pop_back();
                }
            }
            if (a_delt[i + 1] > 0)
                suff[i] += (n - i) * a_delt[i + 1];
        }
        //cerr << suff[i] << endl;
    }
    cur.clear();
    for (int i = 2; i <= n; i++)
    {
        pref[i] = pref[i - 1];
        if (b_delt[i - 1] < 0)
            cur.pb(mp(i - 1, b_delt[i - 1]));
        else
        {
            while (!cur.empty() && b_delt[i - 1] > 0)
            {
                if (-cur.back().Y > b_delt[i - 1])
                {
                    cur.back().Y += b_delt[i - 1];
                    suff[i] += (i - cur.back().X - 1) * b_delt[i - 1];
                    b_delt[i - 1] = 0;
                }
                else
                {
                    suff[i] += (i - cur.back().X - 1) * b_delt[i - 1];
                    b_delt[i - 1] += cur.back().Y;
                    cur.pop_back();
                }
            }
            if (b_delt[i - 1] > 0)
                pref[i] += (i - 1) * b_delt[i - 1];
        }
    }

    ll ans = 1e18;
    for (int i = 1; i <= n + 1; i++)
        ans = min(ans, i - 1 + pref[i - 1] + suff[i]);
    cout << ans << endl;
    return 0;
}

