using namespace std;
typedef long long ll;

vector<ll> solve(ll n, vector<ll> a) {
  stack<pair<ll, ll>> stk;
  vector<ll> ret(n);
  ll cnt = 0;

  for (ll i = n - 1; i >= 0; i--) {
    ret[i] = cnt;
    if (i == 0) break;

    ll x = a[i - 1], y = a[i];
    if (x > y) {
      while (x > y) {
        ll k = n;
        if (!stk.empty()) {
          k = stk.top().first;
          stk.top().second--;
          if (stk.top().second == 0) {
            stk.pop();
          }
        }
        cnt += (k - i) * 2;
        y *= 4;
      }
    } else {
      ll r = 0;
      while (x * 4 <= y) {
        r++;
        x *= 4;
      }
      stk.push(make_pair(i, r));
    }
  }

  return ret;
}

