	{
		for (int i = 1; i <= n; ++i) scanf("%lld", a + i);
		queue <pii> q;
		f[n] = 0; 
		for (int i = n - 1; i >= 1; --i) 
		{
			f[i] = f[i + 1];
			if (a[i] > a[i + 1]) 
			{
				ll tmp = a[i + 1];
				int cnt = 0; 
				while (tmp < a[i]) 
				{
					tmp *= 4;
					cnt += 2;
				} 
				int x = i;
				while (!q.empty())
				{
					f[i] += 1ll * (q.front().second - x) * cnt;
					if (q.front().first > cnt) cnt -= q.front().first;
					else
					{
						pii tmpp = q.front();
						tmpp.first -= cnt;
						cnt = 0;
						q.pop();
						q.push(tmpp);
						break; 
					}
					x = q.front().second - 1; 
					q.pop();
				}
				f[i] += 1ll * (n - x) * cnt;
			}
			else
			{
				ll tmp = a[i]; 
				int cnt = 0;
				while (tmp * 4 <= a[i + 1]) 
				{
					tmp *= 4;
					cnt += 2;
				}
				if (cnt) q.push(pii(cnt, i));  
			}
		}
