			g[i] = g[i - 1] + 1;
			b[i] = -a[i];
			if (b[i] < b[i - 1])
			{
				ll tmp = b[i - 1];
				int cnt = 0;
				while (tmp > b[i])
				{
					tmp *= 4;
					cnt += 2;
				}
				int x = i;
				while (!q.empty())
				{
					g[i] += 1ll * (x - q.front().second) * cnt;
					if (q.front().first < cnt) cnt -= q.front().first; 
