ll N, a[200000], p[200000], q[200000], MIN;

ll pw(int x, int n) {
	ll y = 1;
	ll p = x;
	while (n != 0) {
		if (n % 2) {
			y = y*p;
		}
		p = p*p;
		n = n / 2;
	}
	return y;
}

int main() {
	cin >> N;
	for (int i = 0; i != N; ++i) {
		cin >> a[i];
	}
	for (int i = N - 2; i != -1; --i) {
		p[i] = p[i + 1];
		if (a[i] > a[i + 1]) {
			ll t;
			for (t = 2; a[i] > a[i + 1] * pw(2, t); t += 2);
			p[i] += (N - i - 1) * t;
		}
	}
	q[0] = 1;
	for (int i = 1; i != N; ++i) {
		q[i] = q[i - 1] + 1;
		if (a[i - 1] < a[i]) {
			ll t;
			for (t = 2; a[i - 1] * pw(2, t) < a[i]; t += 2);
			q[i] += (i - 1) * 2;
		}
	}
	MIN = min(p[0], q[N - 1]);
	for (int i = 0; i != N - 1; ++i) {
		MIN = min(MIN, q[i] + p[i + 1]);
	}
	cout << MIN << endl;
	return 0;
}

