// a*(4^n) <= b, return min(n)
ll count_bigger(ll a, ll b) {
	ll ans = 0;
	for(; a<b; a*=4LL) {
		ans+=2;
	}
	for(; a/4LL>=b; a/=4LL) {
		ans-=2;
	}
	return ans;
}

ll calc(vector<ll> &arr, int c) {
	ll count = c;
	ll base;
	base = 0;
	for(int i = c+1; i < arr.size(); i++) {
		base += ptb[i];
		if(base<0) base = 0;
		count += base;
	}
	base = 0;
	for(int i = c-2; i >= 0; i--) {
		base += ptp[i];
		if(base<0) base = 0;
		count += base;
	}
	return count;
}

