vector<ll> calc(ll n, vector<ll> &a){
    vector<ll> l_cnt(n);

    rep(i,1,n){
        ll l = a[i-1], r = a[i];
        bool is_rev = false;
        ll temp;
        if(!(l > r)){
            is_rev = true;
            swap(l, r);
            temp = l / (r * 4);
        }
        else{
            temp = (l + r - 1) / r;
            temp--;
        }
        ll p = 0;
        while(temp){
            p++;
            temp /= 4;
        }
        l_cnt[i] = p * 2 * (is_rev ? -1 : 1);
    }

    debug(l_cnt);
    vector<ll> l_sum(n+1);
    rep(i,0,n){
        l_sum[i+1] = l_sum[i] + l_cnt[i];
        chmax(l_sum[i+1], 0LL);
    }
    vector<ll> l_sum2 = l_sum;
    rep(i,0,n)l_sum2[i+1] += l_sum2[i];
    vector<ll> l_pos(n);
    ll id = n;
    rrep(i,n,0){
        l_pos[i] = id;
        if(l_cnt[i] > 0)id = i;
    }

    debug(l_sum, l_sum2, l_pos);
    vector<ll> res;;
    rep(i,0,n+1){
        ll t = 0;
        if(i < n){
            t = l_sum2[n] - l_sum2[l_pos[i]];
            t -= l_sum[l_pos[i]] * (n-l_pos[i]);
        }
        res.emplace_back(t);
    }
    return res;
}
