        for(int j=0; j<16; j++){
            dp0[i][j] = -1;
            dp1[i][j] = -1;
        }
    }

    for(int i=N-1; i>=0; i--)
        for(int j=0; j<16; j++)
            dp0[i][j] = calc_dp(dp0, i, j, A);

    reverse(A.begin(), A.end());
    for(int i=N-1; i>=0; i--)
        for(int j=0; j<16; j++)
            dp1[i][j] = calc_dp(dp1, i, j, A);

    long long ans = 1LL<<60;
    for(int i=0; i<=N; i++){
        long long tmp1 = 2*dp0[i][0];
        long long tmp2 = 2*dp1[N-i][0] + i;
        ans = min(ans, tmp1+tmp2);
    }
    cout << ans << endl;
    return 0;
}

