int main()
{
	int n;
	scanf("%d", &n);
	std::vector<long long> a(n);
	for (int i = 0; i < n; i++) scanf("%lld", &a[i]);
	std::vector<long long> dp(n + 1);
	std::stack<std::pair<int, int>> free;
	dp[1] = 1;
	long long left{-2 * a[0]};
	for (int i = 2; i <= n; i++)
	{
		long long next{-2 * a[i - 1]};
		dp[i] = dp[i - 1] + 1;
		while (left > next)
		{
			if (free.empty())
				dp[i] += 2 * (i - 1);
			else
			{
				free.top().second--;
				dp[i] += 2 * (i - free.top().first);
				if (free.top().second == 0)
					free.pop();
			}
			left *= 4;
		}
		if (left <= 4 * next)
		{
			free.push({i, 0});
			long long tmp{next};
			while (left <= 4 * tmp)
			{
				free.top().second++;
				tmp *= 4;
			}
		}
		left = next;
	};
	std::vector<long long> dp_rev(n + 1);
	std::stack<std::pair<int, int>> free_rev;
	long long right{a[n - 1]};
	for (int i = n - 2; i >= 0; i--)
	{
		long long next{a[i]};
		dp_rev[i] = dp_rev[i + 1];
		while (next > right)
		{
			if (free_rev.empty())
				dp_rev[i] += 2 * (n - 1 - i);
			else
			{
				free_rev.top().second--;
				dp_rev[i] += 2 * (free_rev.top().first - i);
				if (free_rev.top().second == 0)
					free_rev.pop();
			}
			right *= 4;
		}
		if (4 * next <= right)
		{
			free_rev.push({i, 0});
			long long tmp{next};
			while (4 * tmp <= right)
			{
				free_rev.top().second++;
				tmp *= 4;
			}
		}
		right = next;
	}
	long long min{(long long)1 << 60};
	for (int i = 0; i < n + 1; i++)
		min = std::min(min, dp[i] + dp_rev[i]);
	printf("%lld\n", min);

	return 0;
}

