            vector<int> buff;
            int pre = i + 1;
            for (auto it = s.lower_bound(i + 1); it != s.end(); ++it){
                int idx = *it;
                assert(idx > i);
                ans[0][i] += now * ll(idx - pre);
                now = upd(idx, now);
                pre = idx;
                if (now == -1) break;
                buff.pb(idx);
            }
            if (now != -1) ans[0][i] += ll(n - pre + 1) * now;
            for (int it : buff) s.erase(it);
        }
        ans[0][i] = ans[0][i] * 2 + ans[0][i + 1];
