using namespace std;
const int N = 2e5 + 1;
const int mod = 998244353;
int power(int a, int b){
    int res = 1;
    while(b > 0){
        if(b & 1){
            res = 1LL * res * a % mod;
        }
        a = 1LL * a * a % mod;
        b >>= 1;
    }
    return res;
}
long long a[N], b[N];
long long n, dpa[N][30], dpb[N][30];
long long funa(int idx, int j){
    if(idx == n + 1) return 0;
    long long &ret = dpa[idx][j], tot = j;
    if(ret != -1) return ret;
    long long val = a[idx], prev = a[idx - 1];
    while(tot--){
        prev *= 4;
        if(prev > 3e18 / 4) return 1e8;
    }
    int cnt = 0;
    while(val < prev){
        cnt++;
        if(cnt >= 30 || val > 3e18 / 4) return 1e8;
        val *= 4;
    }
    return ret = 2 * cnt + funa(idx + 1, cnt);
}
long long funb(int idx, int j){
    if(idx == 0) return 0;
    long long &ret = dpb[idx][j], tot = j;
    if(ret != -1) return ret;
    long long val = b[idx], prev = b[idx + 1];
    while(tot--){
        prev *= 4;
        if(prev > 3e18 / 4) return 1e8;
    }
    int cnt = 0;
    while(val < prev){
        cnt++;
        if(cnt >= 30 || val > 3e18 / 4) return 1e8;
        val *= 4;
    }
    return ret = 2 * cnt + funb(idx - 1, cnt);
}
int main(){
    long long ans = 3e18, tot = 0, bb = 0, mindp[2] = {0};
    memset(dpa, -1, sizeof(dpa));
    memset(dpb, -1, sizeof(dpb));
    scanf("%lld", &n);
    for(int i = 1; i <= n; i++){
        scanf("%lld", &a[i]);
        b[i] = 2LL * a[i];
    }
    for(int i = 1; i <= n; i++){
        mindp[bb] = 3e18;
        for(int j = 0; j < 30; j++){
            mindp[bb] = min(mindp[bb], i + 2 * j + funb(i - 1, j));
            ans = min(ans, mindp[bb ^ 1] + 2 * j + funa(i + 1, j));
        }
        bb ^= 1;
    }
    printf("%lld\n", ans);
    return 0;
}

