            ll pre = i;
            while(cnt != 0){
                pll p = st.top();
                st.pop();

                if(cnt <= p.first){
                    p.first -= cnt;
                    cnt1[i] += cnt * (pre - p.second);
                    cnt = 0;
                    if(p.second == 1) st.push({linf, 1});
                    else if(p.first != 0) st.push(p);
                }else{
                    cnt1[i] += cnt * (pre - p.second);
                    cnt -= p.first;
                    pre = p.second;
                }
            }
        }else{
            cp = A[i];
            while(cp * 4 <= A[i - 1]) cp *= 4, cnt += 2;
            if(cnt != 0) st.push({cnt, i});
        }
    }

    while(!st.empty()) st.pop();
    st.push({linf, N});
    for(int i = N - 1; i >= 1; --i){
        cnt2[i] = cnt2[i + 1];
        ll cp = A[i + 1];
        ll cnt = 0;

        if(cp < A[i]){
            while(cp < A[i]) cp *= 4, cnt += 2;
            ll pre = i;
            while(cnt != 0){
                pll p = st.top();
                st.pop();

                if(cnt <= p.first){
                    p.first -= cnt;
                    cnt2[i] += cnt * (p.second - pre);
                    cnt = 0;
                    if(p.second == 1) st.push({linf, N});
                    else if(p.first != 0) st.push(p);
                }else{
                    cnt2[i] += cnt * (p.second - pre);
                    cnt -= p.first;
                    pre = p.second;
                }
            }
        }else{
            cp = A[i];
            while(cp * 4 <= A[i + 1]) cp *= 4, cnt += 2;
            if(cnt != 0) st.push({cnt, i});
        }
    }
    ll ans = linf;
    for(int i = 0; i <= N; ++i){
        chmin(ans, cnt1[i] + cnt2[i + 1]);
    }
    cout << ans << endl;
    return 0;
}

