		j = pow4sub(A[i + 1], A[i]);
		if(j == 0){
			B2[i] = B2[i + 1];
			update(i, i + 1, 0, pow4sub(A[i], A[i + 1] + 1) - 1, t);
			if(pow4sub(A[i], A[i + 1] + 1) - 1 > 0){
				nonzero = i;
			}
		}
		else{
			l = nonzero - 1;
			r = N - 1;
			while(r - l > 1){
				h = (l + r) / 2;
				if(query(i + 1, h, t) >= j){
					r = h;
				}
				else{
					l = h;
				}
			}
			B2[i] = B2[i + 1] + j * (r - i) - query(i + 1, r, t);
			s = query(i + 1, r + 1, t);
			update(i + 1, r, 0, 0, t);
			update(r, r + 1, 1, j - s, t);
			nonzero = r;
		}
	}
/*	printf("B2:\n");
	for(i = 0; i < N; i++){
		printf("%lld ", B2[i]);
	}
	printf("\n");
*/	int ans = min(2 * B1[0], 2 * B2[0] + N);
	for(i = 1; i < N; i++){
		ans = min(ans, 2 * B1[i] + 2 * B2[N - i] + i);
	}
	printf("%d\n", ans);
	return 0;
}

