  int64 min=10000000000000;
  int64 *b=(int64 *)calloc(n,sizeof(int64));
  for(i=0;i<n;i++){
    int64 cnt=0;
    b[i]=a[i];
    int j;
    for(j=i+1;j<n;j++){
      b[j]=a[j];
      while(b[j]<b[j-1]){
	b[j]*=4;
	cnt+=2;
      }
    }
    if(i>0){
      b[i-1]=-2*a[i-1];
      cnt++;
      for(j=i-2;j>=0;j--){
	b[j]=-2*a[j];
	while(b[j]>b[j+1]){
	  b[j]*=4;
	  cnt+=2;
	}
      }
    }
    if(cnt<min) min=cnt;
  }
  printf("%lld\n",min);
}

