        private int numChars;

        public FastScanner(InputStream stream) {
            this.stream = stream;
            // stream = new FileInputStream(new File("dec.in"));

        }

        int read() {
            if (numChars == -1)
                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++)
                array[i] = nextInt();

            return array;
        }

        int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextIntArray(m);
            }
            return map;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++)
                array[i] = nextLong();

            return array;
        }

        long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextLongArray(m);
            }
            return map;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++)
                array[i] = nextDouble();

            return array;
        }

        double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextDoubleArray(m);
            }
            return map;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++)
                array[i] = next();

            return array;
        }

        String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int[] a = new int[n];
		for (int i=0;i<n;i++) {
			a[i]=sc.nextInt();
		}

		double[] ratio = new double[n-1];
		for (int i=0;i<n-1;i++) {
			if (a[i]<a[i+1]) {
				int x = a[i];
				int y = a[i+1];
				int count = 0;
				while (x<y) {
					x*=2;
					count++;
				}
				ratio[i] = x==y ? count : count-0.5;
			} else if (a[i]>a[i+1]) {
				int x = a[i+1];
				int y = a[i];
				int count = 0;
				while (x<y) {
					x*=2;
					count++;
				}
				ratio[i] = -( x==y ? count : count-0.5);
			} else {
				ratio[i]=0;
			}
		}

		int[] left = new int[n];
		int[] right = new int[n];

		for (int i=0;i<n-1;i++) {
			left[i+1] = left[i] + (ratio[i]<=0 ? 0 : (int)Math.ceil(ratio[i]/2)*2*(i+1));

		}
		for (int i=n-1;i>0;i--) {
			right[i-1] = right[i] + (ratio[i-1]>=0 ? 0 : (int)Math.ceil(-ratio[i-1]/2)*2*(n-i));
		}

		int ans = right[0];
		for (int i=0;i<n-1;i++) {
			ans=Math.min(ans, left[i]+(i+1)+right[i+1]);
		}
		ans = Math.min(ans, left[n-1]+n);

		System.out.println(ans);
	}


}

import java.util.*;

public class Main {
	static class Range {
		int size;
		long lv, rv;
		int lp, rp;
		public Range(int size, long lv, long rv) {
			this.size = size;
			this.lv = lv;
			this.rv = rv;
		}

	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		long[] A = new long[N];
		for(int i=0; i<N; i++)
			A[i] = sc.nextLong();

		int[][] dp = new int[2][];

		dp[0] = dp(A);
		long[] B = new long[A.length];
		for(int i=0; i<N; i++)
			B[i] = A[N-1-i];
		dp[1] = new int[N+1];

		int ans = Integer.MAX_VALUE;
		for(int i=0; i<=N; i++)
			ans = Math.min(ans, dp[0][i]+dp[1][N-i]+i);

		System.out.println(ans);
		sc.close();
	}

	public static int[] dp(long[] A) {
		int N = A.length;
		int[] ans = new int[N+1];

		LinkedList<Range> list = new LinkedList<>();
		ans[N] = 0;
		for(int i=N-1; i>=0; i--) {
			ans[i] = ans[i+1];
			list.push(new Range(1, A[i], A[i]));

			while(list.size() > 1) {
				Range cur = list.pop();
				if(compare(cur.rv, cur.rp, list.peek().lv, list.peek().lp)<=0) {
					list.push(cur);
					break;
				}
				Range next = list.pop();
				while(compare(cur.rv, cur.rp, next.lv, next.lp)>0) {
					next.lp+=2;
					next.rp+=2;
					ans[i] += 2*next.size;
				}
				cur.size += next.size;
				cur.rv = next.rv;
				cur.rp = next.rp;
				list.push(cur);
			}
		}

		return ans;
	}

	public static int compare(long lv, int lp, long rv, int rp) {
		int pdiff = lp-rp;
		if(pdiff>=0) {
			if(pdiff>=30)
				return 1;
			else
				return Long.compare(lv<<pdiff, rv);
		} else {
			if(pdiff<=-30)
				return -1;
			else
				return Long.compare(lv, rv<<(-pdiff));
		}
	}
}

import java.util.ArrayDeque;
import java.util.Deque;

public class Main {

  private static void solve() {
    int n = ni();
    int[] a = na(n);

    long[] neg = new long[n];
    Deque<long[]> q = new ArrayDeque<>();
    for (int i = 0; i < n; i++) {
      long v = a[i];
      if (v > 0) {
        neg[i]++;
        v *= -2;
      }
      if (q.size() == 0) {
        q.addLast(new long[] {v, 1});
      } else {
        long cnt = 0;
        long min = q.peekLast()[0];
        while (q.size() > 0 && q.peekLast()[0] > v) {
          cnt += q.pollLast()[1];
        }
        while (min > v) {
          min *= 4;
          neg[i] += cnt * 2;
        }
        q.add(new long[] {v, cnt + 1});
      }
      if (i > 0) {
        neg[i] += neg[i - 1];
      }
    }

    long[] posi = new long[n];
    q.clear();
    for (int i = n - 1; i >= 0; i--) {
      int v = a[i];
      if (v < 0) {
        posi[i]++;
        v *= -2;
      }
      if (q.size() == 0) {
        q.addLast(new long[] {v, 1});
      } else {
        long cnt = 0;
        long min = q.peekLast()[0];
        while (q.size() > 0 && q.peekLast()[0] < v) {
          cnt += q.pollLast()[1];
        }
        while (min < v) {
          min *= 4;
          posi[i] += cnt * 2;
        }
        q.add(new long[] {v, cnt + 1});
      }
      if (i < n - 1) {
        posi[i] += posi[i + 1];
      }
    }

    long ret = Math.min(neg[n - 1], posi[0]);
    for (int i = 0; i < n - 1; i++) {
      ret = Math.min(ret, neg[i] + posi[i + 1]);
    }

    System.out.println(ret);
  }

  public static void main(String[] args) {
    new Thread(null, new Runnable() {
      @Override
      public void run() {
        long start = System.currentTimeMillis();
        String debug = args.length > 0 ? args[0] : null;
        if (debug != null) {
          try {
            is = java.nio.file.Files.newInputStream(java.nio.file.Paths.get(debug));
          } catch (Exception e) {
            throw new RuntimeException(e);
          }
        }
        reader = new java.io.BufferedReader(new java.io.InputStreamReader(is), 32768);
        solve();
        out.flush();
        tr((System.currentTimeMillis() - start) + "ms");
      }
    }, "", 64000000).start();
  }

  private static java.io.InputStream is = System.in;
  private static java.io.PrintWriter out = new java.io.PrintWriter(System.out);
  private static java.util.StringTokenizer tokenizer = null;
  private static java.io.BufferedReader reader;

  public static String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  private static double nd() {
    return Double.parseDouble(next());
  }

  private static long nl() {
    return Long.parseLong(next());
  }

  private static int[] na(int n) {
    int[] a = new int[n];
    for (int i = 0; i < n; i++)
      a[i] = ni();
    return a;
  }

  private static char[] ns() {
