    public HpReader(String dir, String inFile, String outFile) {
      initAndRedirectInOut(dir, inFile, outFile);
    }

    private int ivl(String val) {
      return Integer.parseInt(val);
    }

    private long lvl(String val) {
      return Long.parseLong(val);
    }

    private void initAndRedirectInOut(String dir, String inFile, String outFile) {
      if (dir != null) {
        try {
          String containingDirPath = dir.endsWith(File.separator) ? dir : dir + File.separator;
          if (isDebug && inFile != null)
            System.setIn(new FileInputStream(new File(containingDirPath + inFile)));
          if (isDebug && outFile != null)
            System.setOut(new PrintStream(new File(containingDirPath + outFile)));
        } catch (FileNotFoundException e) {
          // Do nothing, stdin & stdout are not redirected
        }
      }
      in = new BufferedReader(new InputStreamReader(System.in));
      out = new PrintWriter(System.out);
    }

    private String nextSingleStr() throws IOException {
      return in.readLine();
    }

    private String[] nextLineStr() throws IOException {
      return nextLineStr(0);
    }

    private String[] nextLineStr(int offset) throws IOException {
      String[] inp = nextSingleStr().split(" ");
      String[] rs = new String[offset + inp.length];
      System.arraycopy(inp, 0, rs, offset, inp.length);
      return rs;
    }

    private int nextSingleInt() throws IOException {
      if (lineIndex == -1 || lineIndex == lineIntMem.length) {
        lineIndex = 0;
        lineIntMem = nextLineInt();
      }

      return lineIntMem[lineIndex++];
    }

    private int[] nextLineInt() throws IOException {
      return nextLineInt(0);
    }

    private int[] nextLineInt(int offset) throws IOException {
      String[] inp = nextLineStr();
      int[] rs = new int[offset + inp.length];
      for (int i = 0; i < inp.length; i++) rs[offset + i] = ivl(inp[i]);
      return rs;
    }

    private long nextSingleLong() throws IOException {
      if (lineIndex == -1 || lineIndex == lineLongMem.length) {
        lineIndex = 0;
        lineLongMem = nextLineLong();
      }

      return lineLongMem[lineIndex++];
    }

    private long[] nextLineLong() throws IOException {
      return nextLineLong(0);
    }

    private long[] nextLineLong(int offset) throws IOException {
      String[] inp = nextLineStr();
      long[] rs = new long[offset + inp.length];
      for (int i = 0; i < inp.length; i++) rs[offset + i] = lvl(inp[i]);
      return rs;
    }

    private int[][] nextMatInt(int lineCount) throws IOException {
      return nextMatInt(lineCount, 0, 0);
    }

    private int[][] nextMatInt(int lineCount, int rowOffset, int colOffset) throws IOException {
      int[][] rs = new int[rowOffset + lineCount][];
      for (int i = rowOffset; i < rs.length; i++) rs[i] = nextLineInt(colOffset);
      return rs;
    }
  }

  private static class HpHelper {
    private static final String LOCAL_DEBUG_FLAG = "COM_PROG_DEBUG";

    private static boolean isDebug() {
      try {
        return Boolean.parseBoolean(System.getenv(HpHelper.LOCAL_DEBUG_FLAG));
      } catch (Exception e) {
        return false;
      }
    }

    private static String createDelimiter(String delimiter) {
      return delimiter == null ? " " : delimiter;
    }

    private static void println(int[] data, String delimiter) {
      delimiter = createDelimiter(delimiter);
      for (int t : data) out.print(t + delimiter);
      out.println();
    }

    private static void println(long[] data, String delimiter) {
      delimiter = createDelimiter(delimiter);
      for (long t : data) out.print(t + delimiter);
      out.println();
    }

    private static <T> void println(T[] data, String delimiter) {
      delimiter = createDelimiter(delimiter);
      for (T t : data) {
        if (t instanceof int[]) {
          println((int[]) t, delimiter);
        } else if (t instanceof long[]) {
          println((long[]) t, delimiter);
        } else if (t instanceof Object[]) {
          println((Object[]) t, delimiter);
        } else {
          out.print(t + delimiter);
        }
      }
      out.println();
    }
  }

  private static boolean isDebug = HpHelper.isDebug();
  private static HpReader in = new HpReader("/Users/henryhuypham/Workspace/Data/CompetitiveProg", "in.txt", null);
  private static PrintWriter out;

  public static void main(String[] args) throws IOException {
    int n = in.nextSingleInt(), rs = 0;
    long[] data = in.nextLineLong();

    for (int i = 1; i < n; i++) {
      if (data[i] >= data[i - 1]) {
        continue;
      }

      if (data[i - 1] * -2 < data[i] && (i - 2 < 0 || data[i - 2] <= data[i - 1] * -2)) {
        rs++;
      } else {
        long count = 0, focus = data[i];
        while (focus < data[i - 1]) {
          focus *= -2;
          count++;
        }
        rs += count * (n - i);
      }
    }

    out.print(rs);
    out.flush();
  }
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		// 16 1 4 1 16
		// 2 2 0

		// +4 -2 +2 -4
		// 4 2 4 0

		long[] pref = make(a);
		long[] suff = make(rev(a));
		for(int i = 0;i < suff.length;i++){
			suff[i] += (suff.length-i);
		}

		long ans = Math.min(pref[0], suff[0]);
		for(int i = 0;i < n-1;i++){
			ans = Math.min(pref[i+1] + suff[n-1-i], ans);
		}
		out.println(ans);
	}

	public static int[] rev(int[] a)
	{
		int[] b = new int[a.length];
		for(int i = 0;i < a.length;i++)b[a.length-1-i] = a[i];
		return b;
	}


	static long[] make(int[] a)
	{
		int n = a.length;
		int[] pl = new int[n-1];
		for(int i = n-2;i >= 0;i--){
			long v = a[i+1];
			int num = 0;
			while(a[i] > v){
				v *= 4;
				num++;
			}
			long q = a[i];
			while(q*4 <= v){
				q *= 4;
				num--;
			}
			pl[i] = num;
		}

		int[] cum = new int[n];
		for(int i = 0;i < n-1;i++){
			cum[i+1] = cum[i] + pl[i];
		}
		st = buildP(cum);

		ans = new long[n];
		dfs(0, n, cum, 0L);

		long[] prefix = new long[n];
		for(int i = 0;i < n;i++){
			prefix[i] = ans[i] * 2;
		}
		return prefix;
	}

	static int[][][] st;

	public static int[][][] buildP(int[] a)
	{
		int n = a.length;
		int b = 32-Integer.numberOfLeadingZeros(n);
		int[][] ret = new int[b][];
		int[][] pos = new int[b][];
		for(int i = 0, l = 1;i < b;i++, l*=2) {
			if(i == 0) {
				ret[i] = a;
				pos[i] = new int[n];
				for(int j = 0;j < n;j++)pos[i][j] = j;
			}else {
				ret[i] = new int[n-l+1];
				pos[i] = new int[n-l+1];
				for(int j = 0;j < n-l+1;j++) {
					if(ret[i-1][j] == ret[i-1][j+l/2]){
						ret[i][j] = ret[i-1][j];
						pos[i][j] = Math.max(pos[i-1][j], pos[i-1][j+l/2]);
					}else if(ret[i-1][j] < ret[i-1][j+l/2]){
						ret[i][j] = ret[i-1][j];
						pos[i][j] = pos[i-1][j];
					}else{
						ret[i][j] = ret[i-1][j+l/2];
						pos[i][j] = pos[i-1][j+l/2];
					}
				}
			}
		}
		return new int[][][]{ret, pos};
	}

	public static int rmqpos(int[][][] st, int a, int b)
	{
		int t = 31-Integer.numberOfLeadingZeros(b-a);
		if(st[0][t][a] < st[0][t][b-(1<<t)]){
			return st[1][t][a];
		}else{
			return st[1][t][b-(1<<t)];
		}
	}

	public static int rmqval(int[][][] st, int a, int b)
	{
		int t = 31-Integer.numberOfLeadingZeros(b-a);
		if(st[0][t][a] < st[0][t][b-(1<<t)]){
			return st[0][t][a];
		}else{
			return st[0][t][b-(1<<t)];
		}
	}

	public static int[] rmq(int[][][] st, int a, int b)
	{
		int t = 31-Integer.numberOfLeadingZeros(b-a);
		if(st[0][t][a] < st[0][t][b-(1<<t)+1]){
			return new int[]{st[0][t][a], st[1][t][a]};
		}else{
			return new int[]{st[0][t][b-(1<<t)+1], st[1][t][b-(1<<t)+1]};
		}
	}


	static long[] ans;

	static void dfs(int l, int r, int[] cum, long offset)
	{
		if(l >= r)return;
//		tr(l, r-1);
		int min = -1, arg = -1;
		if(l == r-1){
			min = cum[l];
			arg = l;
		}else{
			int[] va = rmq(st, l, r-1);
			min = va[0];
			arg = va[1];
		}
//		tr(min, arg, cum, l, r, offset);
		long s = offset;
		for(int i = arg;i < r;i++){
			s += cum[i] - min;
		}
//		tr(s, offset, arg);
		ans[arg] = s;
		dfs(l, arg, cum, s);
		dfs(arg+1, r, cum, offset);
	}

	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		Thread t = new Thread(null, null, "~", Runtime.getRuntime().maxMemory()){
			@Override
			public void run() {
				solve();
				out.flush();
			}
		};
		t.start();
		t.join();

		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
		while(p < n && !(isSpaceChar(b))){
			buf[p++] = (char)b;
			b = readByte();
		}
		return n == p ? buf : Arrays.copyOf(buf, p);
	}

	private static char[][] nm(int n, int m)
	{
		char[][] map = new char[n][];
		for(int i = 0;i < n;i++)map[i] = ns(m);
		return map;
	}

	private static int[] na(int n)
	{
		int[] a = new int[n];
		for(int i = 0;i < n;i++)a[i] = ni();
		return a;
	}

	private static int ni()
	{
		int num = 0, b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static long nl()
	{
		long num = 0;
		int b;
		boolean minus = false;
		while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
		if(b == '-'){
			minus = true;
			b = readByte();
		}

		while(true){
			if(b >= '0' && b <= '9'){
				num = num * 10 + (b - '0');
			}else{
				return minus ? -num : num;
			}
			b = readByte();
		}
	}

	private static void tr(Object... o) { if(INPUT.length() != 0)System.out.println(Arrays.deepToString(o)); }
}

import java.io.*;
import  java.util.*;

import static java.lang.System.in;

class Main{
    static TreeMap<Long,Integer> tm = new TreeMap<>();
    public static void main(String[] args)throws IOException{
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long[] a = new long[n];
        for(int i=0;i<n;i++) a[i]=sc.nextLong();
        long base = 1;
        for(int i=0;i<=31;i++){
            tm.put(base,i);
            base *= i<31?4:1;
        }
        long[] rev = new long[n];
        for(int i=0;i<n;i++) rev[i] = a[n-1-i];
        long[] right = help(a), left = help(rev);
        long ans = 2*right[0];
        for(int i=1;i<n;i++){
            long cur = 2*(right[i]+left[n-i])+i;
            ans = Math.min(ans,cur);
        }
        ans = Math.min(ans,2*left[0]+n);
        System.out.println(ans);

    }
    static long[] help(long[] A){
        int n = A.length;
        long[][] dp = new long[n][16];
        for(int j=0;j<16;j++) dp[n-1][j]=j;
        for(int i=n-2;i>=0;i--){
            int dt = 0;
            long a = A[i],b=A[i+1];
            if(A[i]>A[i+1]){
                while(4*b<a) {
                    a *= 4;
                    dt++;
                }
                dt++;
            }else if(A[i]<A[i+1]){
                while(a<=b){
                    dt--;
                    a *= 4;
                }
                dt++;
            }
            for(int j=0;j<16;j++){
                int t = j+dt;
                if(t<15) dp[i][j] = j+dp[i+1][Math.max(t,0)];
                else dp[i][j] = j+dp[i+1][15]+(t-15)*(n-i-1);
            }
        }
        long[] ans = new long[n];
        for(int i=0;i<n;i++) ans[i] = dp[i][0];
        return ans;
    }
}

import java.util.*;

public class Main {
	static class Range {
		int size;
		long lv, rv;
		int lp, rp;
		public Range(int size, long lv, long rv) {
			this.size = size;
			this.lv = lv;
			this.rv = rv;
		}

	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		long[] A = new long[N];
		for(int i=0; i<N; i++)
			A[i] = sc.nextLong();

		int[][] dp = new int[2][];

		dp[0] = dp(A);
		long[] B = new long[A.length];
		for(int i=0; i<N; i++)
			B[i] = A[N-1-i];
		dp[1] = dp(B);

		int ans = Integer.MAX_VALUE;
		for(int i=0; i<=N; i++)
			ans = Math.min(ans, dp[0][i]+dp[1][N-i]+i);

		System.out.println(ans);
		sc.close();
	}

	public static int[] dp(long[] A) {
		int N = A.length;
		int[] ans = new int[N+1];

		LinkedList<Range> list = new LinkedList<>();
		ans[N] = 0;
		for(int i=N-1; i>=0; i--) {
			ans[i] = ans[i+1];
			list.push(new Range(1, A[i], A[i]));

			while(list.size() > 1) {
				Range cur = list.pop();
				if(compare(cur.rv, cur.rp, list.peek().lv, list.peek().lp)<=0) {
					list.push(cur);
					break;
				}
				Range next = list.pop();
				while(compare(cur.rv, cur.rp, next.lv, next.lp)>0) {
					next.lp+=2;
					next.rp+=2;
					ans[i] += 2*next.size;
				}
				cur.size += next.size;
				cur.rv = next.rv;
				cur.rp = next.rp;
				list.push(cur);
			}
		}

		return ans;
	}

	public static int compare(long lv, int lp, long rv, int rp) {
		int pdiff = lp-rp;
		if(pdiff>=0) {
			if(pdiff>=30)
				return 1;
			else
				return Long.compare(lv<<pdiff, rv);
		} else {
			if(pdiff<=-30)
				return -1;
			else
				return Long.compare(lv, rv<<(-pdiff));
		}
	}
}

import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final long[] as;

  Solver(int n, long[] as) {
    this.n = n;
    this.as = as;
  }

  private long calculate(int positiveIndex) {
//    System.err.printf("positiveIndex: %d\n", positiveIndex);
    long answer = 0;
    {
      long prevShift = 0;
      for (int i = positiveIndex + 1; i < n; i++) {
        long shift = prevShift;
        if (as[i - 1] < as[i]) {
          for (int j = 0; shift >= 2 && (as[i - 1] << (2 * j)) <= as[i]; j++) {
            shift -= 2;
          }
        } else {
          for (int j = 0; as[i - 1] > (as[i] << (2 * j)); j++) {
            shift += 2;
          }
        }
//        System.err.printf("p i: %d, shift: %d\n", i, shift);
        answer += shift;
        prevShift = shift;
      }
    }

    {
      answer += positiveIndex;
      long prevShift = 0;
      for (int i = positiveIndex - 2; i >= 0; i--) {
        long shift = prevShift;
        if (as[i] < as[i + 1]) {
          for (int j = 0; shift >= 2 && (as[i] << (2 * j)) <= as[i + 1]; j++) {
            shift -= 2;
          }
        } else {
          for (int j = 0; as[i] > (as[i + 1] << (2 * j)); j++) {
            shift += 2;
          }
        }
//        System.err.printf("n i: %d, shift: %d\n", i, shift);
        answer += shift;
        prevShift = shift;
      }
    }
//    System.err.println(answer);
//    System.err.println();
    return answer;
  }

  public long solve() {
    int minPositiveIndex = 0;
    int maxPositiveIndex = n;
    while (maxPositiveIndex - minPositiveIndex >= 3) {
      int mid1PositiveIndex = (2 * maxPositiveIndex + 1 * minPositiveIndex) / 3;
      int mid2PositiveIndex = (1 * maxPositiveIndex + 2 * minPositiveIndex) / 3;
      long mid1Cost = calculate(mid1PositiveIndex);
      long mid2Cost = calculate(mid2PositiveIndex);
      if (mid1Cost <= mid2Cost) {
        minPositiveIndex = mid2PositiveIndex;
      } else {
        maxPositiveIndex = mid1PositiveIndex;
      }
    }
    long answer = Long.MAX_VALUE;
    for (int i = minPositiveIndex; i <= maxPositiveIndex; i++) {
      answer = Math.min(answer, calculate(i));
    }
    return answer;
  }
}

public class Main {
  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    long[] as = reader.nextLong(n);
    out.println(new Solver(n, as).solve());
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

class ContestReader {
  private BufferedReader reader;
  private StringTokenizer tokenizer;

  ContestReader(InputStream in) {
    reader = new BufferedReader(new InputStreamReader(in));
  }

  public String next() {
    while (tokenizer == null || !tokenizer.hasMoreTokens()) {
      try {
        tokenizer = new java.util.StringTokenizer(reader.readLine());
      } catch (Exception e) {
        throw new RuntimeException(e);
      }
    }
    return tokenizer.nextToken();
  }

  public int nextInt() {
    return Integer.parseInt(next());
  }

  public long nextLong() {
    return Long.parseLong(next());
  }

  public double nextDouble() {
    return Double.parseDouble(next());
  }

  public String[] next(int n) {
    String[] array = new String[n];
    for (int i = 0; i < n; i++) {
      array[i] = next();
    }
    return array;
  }

  public int[] nextInt(int n) {
    int[] array = new int[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextInt();
    }
    return array;
  }

  public long[] nextLong(int n) {
    long[] array = new long[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextLong();
    }
    return array;
  }

  public double[] nextDouble(int n) {
    double[] array = new double[n];
    for (int i = 0; i < n; i++) {
      array[i] = nextDouble();
    }
    return array;
  }

  public char[] nextCharArray() {
    return next().toCharArray();
  }

  public int[][] nextInt(int n, int m) {
    int[][] matrix = new int[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextInt();
      }
    }
    return matrix;
  }

  public long[][] nextLong(int n, int m) {
    long[][] matrix = new long[n][m];
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        matrix[i][j] = nextLong();
      }
    }
    return matrix;
  }

  public double[][] nextDouble(int n, int m) {
    double[][] matrix = new double[n][m];
