	}

	Map<String,Long> map = new HashMap<String,Long>();
	Map<String,Long> mapRev = new HashMap<String,Long>();

	long count(int i, long b, long[] a){
		if(i >= a.length ){
			return 0;
		}

		String key = i+"_"+b;
		if(map.containsKey(key)){
			return map.get(key);
		}

		long res = 0;
		long x = 0;
		long now = a[i] << (b*2L);

		if(i+1 < a.length){
			x = (Long.numberOfLeadingZeros(a[i+1]) - Long.numberOfLeadingZeros(now))/2 - 1;			
			for(;now > (a[i+1] << (x*2L));x++){}
			res = count(i+1,x, a) + x;
		}

		map.put(key, res);
		return res;
	}

	long countRev(int i, long b, long[] a){
