import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Main m = new Main();
		m.run();
	}

	Scanner sc = new Scanner(System.in);

	void run() {
		int n  =sc.nextInt();
		long a[] = new long[n];

		for(int i =0 ;i < n ; i++){
			a[i] = sc.nextInt();
		}

		long ans = Long.MAX_VALUE;
		for(int i = 0;  i< n ; i++){

			long x = count(i,0,a , ans - i);
			if(x <0 ){
				continue;
			}
			long y = countRev(i,0,a , ans - x - i);
			if(y < 0){
				continue;
			}
//			System.out.println( i);
//			System.out.println( count(i,0,a)*2);
//			System.out.println( countRev(i,0,a)*2);
			ans = Math.min(i+x+y, ans);
		}
		System.out.println(ans);
	}

	Map<Long,Long> map = new HashMap<Long,Long>();
	Map<Long,Long> mapRev = new HashMap<Long,Long>();

	long count(int i, long b, long[] a , long ans){
		if(i >= a.length ){
			return 0;
		}

		long key = b*a.length+i;
		if(map.containsKey(key)){
			return map.get(key);
		}

		long res = 0;
		long x = 0;
		long now = a[i] << (b*2L);

		if(i+1 < a.length){
			x = Math.max(0,(Long.numberOfLeadingZeros(a[i+1]) - Long.numberOfLeadingZeros(now))/2 - 1);			
			for(;now > (a[i+1] << (x*2L));x++){}

			long z = count(i+1,x, a, ans - x*2);
			if(z < 0){
				return ans;
			}

			res = z + x*2;
		}
		if(res > ans ){
			return ans;
		}
		map.put(key, res);
		return res;
	}

	long countRev(int i,long b, long[] a, long ans){
		if(i < 0){
			return 0;
		}

		long key = b*a.length+i;
		if(mapRev.containsKey(key)){
			return mapRev.get(key);
		}

		long res = 0;

		long x = 0;
		long now = a[i] << (b*2);

		if(i - 1 >= 0){
			x = Math.max(0,(Long.numberOfLeadingZeros(a[i-1]) - Long.numberOfLeadingZeros(now))/2 - 1);			
			for(;now > (a[i-1] << (x*2L));x++){}

			long z = countRev(i-1,x, a, ans - x*2);
			if(z < 0){
				return ans;
			}

			res = z + x*2;
		}
		if(res > ans ){
			return ans;
		}

		mapRev.put(key, res);
		return res;
	}



}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		int[] a = na(n);
		long[] suffix = new long[n];
		for(int i = n-2;i >= 0;i--){
			long v = a[i+1];
			long num = 0;
			while(a[i] > v){
				v *= 4;
				num += 2;
			}
			suffix[i] = suffix[i+1] + num * (n-1-i);
		}
		long[] prefix = new long[n];
		prefix[0] = 1;
		for(int i = 1;i < n;i++){
			long v = a[i-1];
			long num = 0;
			while(a[i] > v){
				v *= 4;
				num += 2;
			}
			prefix[i] = prefix[i-1] + 1 + num * i;
		}
		long ans = Math.min(prefix[n-1], suffix[0]);
		for(int i = 0;i < n-1;i++){
			ans = Math.min(prefix[i] + suffix[i+1], ans);
		}
		out.println(ans);
	}

	public static void main(String[] args) throws Exception
	{
		long S = System.currentTimeMillis();
		is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
		out = new PrintWriter(System.out);

		solve();
		out.flush();
		long G = System.currentTimeMillis();
		tr(G-S+"ms");
	}

	private static boolean eof()
	{
		if(lenbuf == -1)return true;
		int lptr = ptrbuf;
		while(lptr < lenbuf)if(!isSpaceChar(inbuf[lptr++]))return false;

		try {
			is.mark(1000);
			while(true){
				int b = is.read();
				if(b == -1){
					is.reset();
					return true;
				}else if(!isSpaceChar(b)){
					is.reset();
					return false;
				}
			}
		} catch (IOException e) {
			return true;
		}
	}

	private static byte[] inbuf = new byte[1024];
	static int lenbuf = 0, ptrbuf = 0;

	private static int readByte()
	{
		if(lenbuf == -1)throw new InputMismatchException();
		if(ptrbuf >= lenbuf){
			ptrbuf = 0;
			try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
			if(lenbuf <= 0)return -1;
		}
		return inbuf[ptrbuf++];
	}

	private static boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
//	private static boolean isSpaceChar(int c) { return !(c >= 32 && c <= 126); }
	private static int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

	private static double nd() { return Double.parseDouble(ns()); }
	private static char nc() { return (char)skip(); }

	private static String ns()
	{
		int b = skip();
		StringBuilder sb = new StringBuilder();
		while(!(isSpaceChar(b))){
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	private static char[] ns(int n)
	{
		char[] buf = new char[n];
		int b = skip(), p = 0;
