        for (int i = 1; i < N; i++) {
            int cnt = 0;
            for (long l = A[i - 1]; l < A[i]; l <<= 2)
                cnt += 2;
            dcc[i + 1] = dcc[i] + i * cnt + 1;
        }
        final int[] acc = new int[N + 1];
        for (int i = N - 1; i > 0; i--) {
            int cnt = 0;
            for (long l = A[i]; A[i - 1] > l; l <<= 2)
                cnt += 2;
            acc[i - 1] = acc[i] + (N - i) * cnt;
        }
