    int n = a.length;
    int[] pcnt = f(a);
    rev(a);
    int[] ncnt = f(a);
    rev(ncnt);
    rev(a);


    int ret = Integer.MAX_VALUE;

    for (int i = 0; i <= n; i ++) {
      int now = 0;
      if (i < n) {
        now += pcnt[i];
      }
      if (i > 0) {
        now += ncnt[i - 1] + i;
      }


      ret = Math.min(ret, now);
    }
    return ret;
  }

  private static void rev(int[] a) {
    int n = a.length;
    for (int i = 0, j = n - 1; i < j; i ++, j --) {
      int tmp = a[i];
      a[i] = a[j];
      a[j] = tmp;
    }
  }

  private static int[] f(int[] a) {
    int n = a.length;
    int[] pcnt = new int[n];
    int[] inf = new int[] {n - 1, Integer.MAX_VALUE};
    ArrayDeque<int[]> q = new ArrayDeque<>();
    for (int i = n - 2; i >= 0; i --) {
      long y = a[i + 1];
      long x = a[i];
      pcnt[i] = pcnt[i + 1];
      if (x > y) {
        while (x > y) {
          int[] e = q.size() > 0 ? q.peek() : inf;
          y *= 4;
          pcnt[i] += 2 * (e[0] - (i - 1) - 1);
          e[1] --;
          if (e[1] == 0) {
            q.poll();
          }
        }
      } else {
        int af = 0;
        while (x * 4 <= y) {
          af ++;
          x *= 4;
        }
        if (af > 0) {
          q.add(new int[] {i, af});
        }
      }
    }
