import java.util.*;

public class Main {
	static class Range {
		int size;
		long lv, rv;
		public Range(int size, long lv, long rv) {
			this.size = size;
			this.lv = lv;
			this.rv = rv;
		}

	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		long[] A = new long[N];
		for(int i=0; i<N; i++)
			A[i] = sc.nextLong();

		int[][] dp = new int[2][N+1];

		LinkedList<Range> list = new LinkedList<>();
		dp[0][N] = 0;
		for(int i=N-1; i>=0; i--) {
			dp[0][i] = dp[0][i+1];
			list.push(new Range(1,A[i],A[i]));

			while(list.size() > 1) {
				Range cur = list.pop();
				if(cur.rv <= list.peek().lv) {
					list.push(cur);
					break;
				}
				Range next = list.pop();
				while(cur.rv > next.lv) {
					next.lv *= 4;
					next.rv *= 4;
					dp[0][i] += 2*next.size;
				}
				cur.size += next.size;
				cur.rv = next.rv;
				list.push(cur);
			}
		}

		list.clear();
		dp[1][0] = 0;
		for(int i=1; i<=N; i++) {
			dp[1][i] = dp[1][i-1]+1;
			list.push(new Range(1,-2*A[i-1],-2*A[i-1]));

			while(list.size() > 1) {
				Range cur = list.pop();
				if(list.peek().rv <= cur.lv) {
					list.push(cur);
					break;
				}
				Range next = list.pop();
				while(next.rv > cur.lv) {
					next.lv *= 4;
					next.rv *= 4;
					dp[0][i] += 2*next.size;
				}
				cur.size += next.size;
				cur.lv = next.lv;
				list.push(cur);
			}
		}

		int ans = Integer.MAX_VALUE;
		for(int i=0; i<=N; i++)
			ans = Math.min(ans, dp[0][i]+dp[1][i]);

		System.out.println(ans);
		sc.close();
	}

}

import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final long[] as;

  Solver(int n, long[] as) {
    this.n = n;
    this.as = as;
  }

  private long calculate(int positiveIndex) {
//    System.err.printf("positiveIndex: %d\n", positiveIndex);
    long answer = 0;
    {
      long prevShift = 0;
      for (int i = positiveIndex + 1; i < n; i++) {
        long shift = prevShift;
        if (as[i - 1] < as[i]) {
          for (int j = 1; shift >= 2 && (as[i - 1] << (2 * j)) <= as[i]; j++) {
            shift -= 2;
          }
        } else {
          for (int j = 0; as[i - 1] > (as[i] << (2 * j)); j++) {
            shift += 2;
          }
        }
//        System.err.printf("p i: %d, shift: %d\n", i, shift);
        answer += shift;
        prevShift = shift;
      }
    }

    {
      answer += positiveIndex;
      long prevShift = 0;
      for (int i = positiveIndex - 2; i >= 0; i--) {
        long shift = prevShift;
        if (as[i] < as[i + 1]) {
          for (int j = 1; shift >= 2 && (as[i] << (2 * j)) <= as[i + 1]; j++) {
            shift -= 2;
          }
        } else {
          for (int j = 0; as[i] > (as[i + 1] << (2 * j)); j++) {
            shift += 2;
          }
        }
//        System.err.printf("n i: %d, shift: %d\n", i, shift);
        answer += shift;
        prevShift = shift;
      }
    }
//    System.err.println(answer);
//    System.err.println();
    return answer;
  }

  public long solve() {
    int minPositiveIndex = 0;
    int maxPositiveIndex = n;
    while (maxPositiveIndex - minPositiveIndex >= 3) {
      int mid1PositiveIndex = (2 * maxPositiveIndex + 1 * minPositiveIndex) / 3;
      int mid2PositiveIndex = (1 * maxPositiveIndex + 2 * minPositiveIndex) / 3;
      long mid1Cost = calculate(mid1PositiveIndex);
      long mid2Cost = calculate(mid2PositiveIndex);
      if (mid1Cost <= mid2Cost) {
        minPositiveIndex = mid2PositiveIndex;
      } else {
        maxPositiveIndex = mid1PositiveIndex;
      }
    }
    long answer = Long.MAX_VALUE;
    for (int i = minPositiveIndex; i <= maxPositiveIndex; i++) {
      answer = Math.min(answer, calculate(i));
    }
    return answer;
  }
}

