            long[] ans = new long[A.length];
            int n = A.length;
            ans[A.length - 1] = 0;
            dq.addFirst(new Block(A[n - 1], A[n - 1], 1));
            for (int i = A.length - 2; i >= 0; i--) {
                ans[i] = ans[i + 1];
                while (dq.peekFirst().head < A[i]) {
                    Block first = dq.removeFirst();
                    first.inc();
                    ans[i] += first.size;
                    if (!dq.isEmpty() && first.tail * 4 > dq.peekFirst().head) {
                        first = Block.merge(first, dq.removeFirst());
                    }
                    dq.addFirst(first);
                }
                Block added = new Block(A[i], A[i], 1);
                if (A[i] * 4 > dq.peekFirst().head) {
                    added = Block.merge(added, dq.removeFirst());
                }
                dq.addFirst(added);
            }
            return ans;
        }

    }

    static class FastInput {
        private final InputStream is;
        private byte[] buf = new byte[1 << 13];
        private int bufLen;
        private int bufOffset;
        private int next;

        public FastInput(InputStream is) {
            this.is = is;
        }

        public void populate(long[] data) {
            for (int i = 0; i < data.length; i++) {
                data[i] = readLong();
            }
        }

        private int read() {
            while (bufLen == bufOffset) {
                bufOffset = 0;
                try {
                    bufLen = is.read(buf);
                } catch (IOException e) {
                    bufLen = -1;
                }
                if (bufLen == -1) {
                    return -1;
                }
            }
            return buf[bufOffset++];
        }

        public void skipBlank() {
            while (next >= 0 && next <= 32) {
                next = read();
            }
        }

        public int readInt() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            int val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

        public long readLong() {
            int sign = 1;

            skipBlank();
            if (next == '+' || next == '-') {
                sign = next == '+' ? 1 : -1;
                next = read();
            }

            long val = 0;
            if (sign == 1) {
                while (next >= '0' && next <= '9') {
                    val = val * 10 + next - '0';
                    next = read();
                }
            } else {
                while (next >= '0' && next <= '9') {
                    val = val * 10 - next + '0';
                    next = read();
                }
            }

            return val;
        }

    }

    static class Block {
        long head;
        long tail;
        int size;

        public Block(long head, long tail, int size) {
            this.head = head;
            this.tail = tail;
            this.size = size;
        }

        public void inc() {
            head *= 4;
            tail *= 4;
        }

        public static Block merge(Block a, Block b) {
            Block ans = new Block(a.head, b.tail, a.size + b.size);
            return ans;
        }

    }

    static class SequenceUtils {
        public static void swap(long[] data, int i, int j) {
            long tmp = data[i];
            data[i] = data[j];
            data[j] = tmp;
        }

        public static void reverse(long[] data) {
            reverse(data, 0, data.length - 1);
        }

        public static void reverse(long[] data, int l, int r) {
            while (l < r) {
                swap(data, l, r);
                l++;
                r--;
            }
        }

    }

    static class FastOutput implements AutoCloseable, Closeable, Appendable {
        private StringBuilder cache = new StringBuilder(10 << 20);
        private final Writer os;

        public FastOutput append(CharSequence csq) {
            cache.append(csq);
            return this;
        }

        public FastOutput append(CharSequence csq, int start, int end) {
            cache.append(csq, start, end);
            return this;
        }

        public FastOutput(Writer os) {
            this.os = os;
        }

        public FastOutput(OutputStream os) {
            this(new OutputStreamWriter(os));
        }

        public FastOutput append(char c) {
            cache.append(c);
            return this;
        }

        public FastOutput append(long c) {
            cache.append(c);
            return this;
        }

        public FastOutput println(long c) {
            return append(c).println();
        }

        public FastOutput println() {
            cache.append(System.lineSeparator());
            return this;
        }

        public FastOutput flush() {
            try {
                os.append(cache);
                os.flush();
                cache.setLength(0);
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
            return this;
        }

        public void close() {
            flush();
            try {
                os.close();
            } catch (IOException e) {
                throw new UncheckedIOException(e);
            }
        }

        public String toString() {
            return cache.toString();
        }

    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static int solve() {
        int[][] dp1 = new int[N][16];
        for (int i = N-2; i >= 0; i--) {
            int d = delta(A[i], A[i+1]);
            for (int j = 0; j <= 15; j++) {
                int j2 = Math.max(j+d, 0);
                if( j2 > 15 ) {
                    dp1[i][j] = j2 + dp1[i+1][15] + (j2 - 15) * (N-i-1);

                } else {
                    dp1[i][j] = j2 + dp1[i+1][j2];
                }
            }
        }
        int[][] dp2 = new int[N][16];
        for (int i = 1; i < N; i++) {
            int d = delta(A[i], A[i-1]);
            for (int j = 0; j <= 15; j++) {
                int j2 = Math.max(j+d, 0);
                if( j2 > 15 ) {
                    dp2[i][j] = j2 + dp2[i-1][15] + (j2 - 15) * i;

                } else {
                    dp2[i][j] = j2 + dp2[i-1][j2];
                }
            }
        }

        int ans = Math.min(dp1[0][0]*2, dp2[N-1][0]*2 + N);
        for (int i = 0; i < N-1; i++) {
            ans = Math.min(dp2[i][0]*2 + (i+1) + dp1[i+1][0]*2, ans);
        }
        return ans;
    }

    // 昇順にするのに必要な数 or 吸収できる数
    // *4 = 1
    static int delta(long a, long b) {
        if( a <= b ) {
            // a = 3, b = 18
            int time = 0;
            while( a * 4 <= b ) {
                time++;
                a *= 4;
            }
            return -time;

        } else {
            int time = 0;
            while( a > b ) {
                b *= 4;
                time++;
            }
            return time;
        }
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
