import java.util.TreeSet;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        MyInput in = new MyInput(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        int n;
        long[] a;

        public void solve(int testNumber, MyInput in, PrintWriter out) {
            n = in.nextInt();
            a = in.nextLongArray(n);

            long[] r = calc();
            for (int i = 0; i < n / 2; i++) {
                swap(a, i, n - 1 - i);
            }
            for (int i = 0; i < n; i++) a[i] *= 2;
            long[] l = calc();
            for (int i = 0; i < n; i++) l[i] += n - i;

            long ans = Long.MAX_VALUE;
            for (int i = 0; i <= n; i++) {
                ans = Math.min(ans, l[n - i] + r[i]);
            }

            out.println(ans);
        }

        long[] calc() {
            long[] cur = new long[n + 1];
            for (int i = 0; i < n; i++) {
                cur[i] = a[i];
            }
            cur[n] = Long.MAX_VALUE;

            TreeSet<Integer> set = new TreeSet<>();
            long[] times = new long[n + 1];
            long ans = times[n - 1];
            for (int i = n - 1; i >= 0; i--) {
                while (cur[i] > cur[i + 1]) {
                    final int j = set.first();
                    times[i] += 2 * (j - i);
                    if (4 * cur[j] > cur[j + 1]) {
                        set.pollFirst();
                    }
                    cur[i + 1] *= 4;
                }
                if (4 * cur[i] <= cur[i + 1]) set.add(i);
                times[i] += times[i + 1];
            }

            return times;
        }

        static void swap(long[] xs, int i, int j) {
            long t = xs[i];
            xs[i] = xs[j];
            xs[j] = t;
        }

    }

    static class MyInput {
        private final BufferedReader in;
        private static int pos;
        private static int readLen;
        private static final char[] buffer = new char[1024 * 8];
        private static char[] str = new char[500 * 8 * 2];
        private static boolean[] isDigit = new boolean[256];
        private static boolean[] isSpace = new boolean[256];
        private static boolean[] isLineSep = new boolean[256];

        static {
            for (int i = 0; i < 10; i++) {
                isDigit['0' + i] = true;
            }
            isDigit['-'] = true;
            isSpace[' '] = isSpace['\r'] = isSpace['\n'] = isSpace['\t'] = true;
            isLineSep['\r'] = isLineSep['\n'] = true;
        }

        public MyInput(InputStream is) {
            in = new BufferedReader(new InputStreamReader(is));
        }

        public int read() {
            if (pos >= readLen) {
                pos = 0;
                try {
                    readLen = in.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (readLen <= 0) {
                    throw new MyInput.EndOfFileRuntimeException();
                }
            }
            return buffer[pos++];
        }

        public int nextInt() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            int ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public long nextLong() {
            int len = 0;
            str[len++] = nextChar();
            len = reads(len, isSpace);
            int i = 0;
            long ret = 0;
            if (str[0] == '-') {
                i = 1;
            }
            for (; i < len; i++) ret = ret * 10 + str[i] - '0';
            if (str[0] == '-') {
                ret = -ret;
            }
            return ret;
        }

        public char nextChar() {
            while (true) {
                final int c = read();
                if (!isSpace[c]) {
                    return (char) c;
                }
            }
        }

        int reads(int len, boolean[] accept) {
            try {
                while (true) {
                    final int c = read();
                    if (accept[c]) {
                        break;
                    }
                    if (str.length == len) {
                        char[] rep = new char[str.length * 3 / 2];
                        System.arraycopy(str, 0, rep, 0, str.length);
                        str = rep;
                    }
                    str[len++] = (char) c;
                }
            } catch (MyInput.EndOfFileRuntimeException e) {
            }
            return len;
        }

        public long[] nextLongArray(final int n) {
            final long[] res = new long[n];
            for (int i = 0; i < n; i++) {
                res[i] = nextLong();
            }
            return res;
        }

        static class EndOfFileRuntimeException extends RuntimeException {
        }

    }
}

import java.util.*;

public class Main {
	static class Range {
		int size;
		long lv, rv;
		public Range(int size, long lv, long rv) {
			this.size = size;
			this.lv = lv;
			this.rv = rv;
		}

	}
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		long[] A = new long[N];
		for(int i=0; i<N; i++)
			A[i] = sc.nextLong();

		int[][] dp = new int[2][N+1];

		LinkedList<Range> list = new LinkedList<>();
		dp[0][N] = 0;
		for(int i=N-1; i>=0; i--) {
			dp[0][i] = dp[0][i+1];
			list.push(new Range(1,A[i],A[i]));

			while(list.size() > 1) {
				Range cur = list.pop();
				if(cur.rv <= list.peek().lv) {
					list.push(cur);
					break;
				}
				Range next = list.pop();
				while(cur.rv > next.lv) {
					next.lv *= 4;
					next.rv *= 4;
					dp[0][i] += 2*next.size;
				}
				cur.size += next.size;
				cur.rv = next.rv;
				list.push(cur);
			}
		}

		list.clear();
		dp[1][0] = 0;
		for(int i=1; i<=N; i++) {
			dp[1][i] = dp[1][i-1]+1;
			list.push(new Range(1,-2*A[i-1],-2*A[i-1]));

			while(list.size() > 1) {
				Range cur = list.pop();
				if(list.peek().rv <= cur.lv) {
					list.push(cur);
					break;
				}
				Range next = list.pop();
				while(next.rv > cur.lv) {
					next.lv *= 4;
					next.rv *= 4;
					dp[1][i] += 2*next.size;
				}
				cur.size += next.size;
				cur.lv = next.lv;
				list.push(cur);
			}
		}

		int ans = Integer.MAX_VALUE;
		for(int i=0; i<=N; i++)
			ans = Math.min(ans, dp[0][i]+dp[1][i]);

		System.out.println(ans);
		sc.close();
	}

}

