				kaisu++;
			}
			if(kaisu>0){
				//pl(Arrays.toString(Arrays.copyOf(stack,10)));
				while(kaisu>0){
					int ind=(size>0)?stack[--size]:n-1;
					temp+=ind-i;
					kaisu--;
				}

			}else{
