            min *= 4;
            max *= 4;
            neg[i] += cnt * 2;
          }
          totalCnt += cnt;
          q.pollLast();
          now = max;
        }
        q.addLast(new long[] {v, now, totalCnt});
      }
      neg[i]++;
      if (i > 0) {
        neg[i] += neg[i - 1];
      }
    }

