        long now = v;
        while (q.size() > 0 && q.peekLast()[0] < now) {
          long min = q.peekLast()[0];
          long max = q.peekLast()[1];
          long cnt = q.peekLast()[2];
          while (min < now) {
            min *= 4;
            max *= 4;
            posi[i] += cnt * 2;
          }
          totalCnt += cnt;
          q.pollLast();
          now = max;
        }
        q.addLast(new long[] {v, now, totalCnt});
      }
      if (i < n - 1) {
        posi[i] += posi[i + 1];
      }
    }

    long ret = Math.min(neg[n - 1], posi[0]);
    for (int i = 0; i < n - 1; i++) {
      ret = Math.min(ret, neg[i] + posi[i + 1]);
    }
    System.out.println(ret);
  }

