    static class ENegativeDoubling {
        long inf = Long.MAX_VALUE;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();

            int[] a = in.nextIntArray(n);

            //pos sta
            int lo = 0;
            int hi = n;

            long ans = inf;
            while (lo <= hi) {
                int mid = (lo + hi) / 2;

                long val1 = solve(a, mid, n);

                if (mid < hi) {
                    long val2 = solve(a, mid + 1, n);

                    if (val1 < val2) {
                        ans = Math.min(ans, val1);
                        hi = mid - 1;
                    } else {
                        ans = Math.min(ans, val2);
                        lo = mid + 2;
                    }
                } else {
                    ans = Math.min(ans, val1);
                    break;
                }
            }

            out.println(ans);
        }

        long solve(int[] a, int st, int n) {

            //long[] pow = new long[300000];

            long ans = 0;
            if (st < n) {
                int ind = 0;
                //pow[0] = a[st];
                for (int i = st + 1; i < n; i++) {
                    if (a[i] == a[i - 1]) {
                    } else if (a[i] > a[i - 1]) {
                        long num = a[i];

                        int exp = 0;

                        while (num >= a[i - 1]) {
                            num /= 2;
                            exp++;
                        }

                        exp--;

                        ind -= exp;

                    } else {
                        long num = a[i];

                        int exp = 0;
                        while (num < a[i - 1]) {
                            num *= 2;
                            exp++;
                        }

                        ind += exp;
                    }

                    if (ind < 0)
                        ind = 0;

                    if (ind % 2 == 1)
                        ind++;

                    ans += ind;
                }
            }

            if (st > 0) {
                ans++;
                int ind = 1;
                for (int i = st - 2; i >= 0; i--) {
                    if (a[i] == a[i + 1]) {
                    } else if (a[i] > a[i + 1]) {
                        long num = a[i];

                        int exp = 0;

                        while (num >= a[i + 1]) {
                            num /= 2;
                            exp++;
                        }

                        exp--;

                        ind -= exp;

                    } else {
                        long num = a[i];

                        int exp = 0;
                        while (num < a[i + 1]) {
                            num *= 2;
                            exp++;
                        }

                        ind += exp;
                    }

                    if (ind < 0)
                        ind = 0;

                    if (ind % 2 == 0)
                        ind++;

                    ans += ind;
                }
            }

            return ans;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

