import java.io.*;
import java.util.*;

class Solver {
  final int n;
  final long[] as;

  Solver(int n, long[] as) {
    this.n = n;
    this.as = as;
  }

  private long[] calculateCost(long[] vs) {
    long[] cost = new long[n];

    ArrayDeque<Integer> countStack = new ArrayDeque<>();
    ArrayDeque<Integer> diffStack = new ArrayDeque<>();
    countStack.addFirst(1);
    diffStack.addFirst(Integer.MAX_VALUE);

    cost[n-1] = 0;
    for (int i = n-2; i >= 0; i--) {
      cost[i] = cost[i+1];

      long current = vs[i];
      long prev = vs[i+1];
      if (current > prev) {
        while (current > prev) {
          prev *= 4;
          cost[i] += countStack.peekFirst() * 2;
          if (diffStack.peekFirst() <= 1) {
            diffStack.pollFirst();
            int count1 = countStack.pollFirst();
            int count2 = countStack.pollFirst();
            countStack.addFirst(count1 + count2);
          } else {
            diffStack.addFirst(diffStack.pollFirst() - 1);
          }
        }
        countStack.addFirst(countStack.pollFirst() + 1);
      } else if (4 * current > prev) {
        countStack.addFirst(countStack.pollFirst() + 1);
      } else {
        int count = 0;
        while (4 * current <= prev) {
          count++;
          current *= 4;
        }
        countStack.addFirst(1);
        diffStack.addFirst(count);
      }
    }
    return cost;
  }

  public long solve() {
    long[] costFromBack = calculateCost(as);
    /*
    for (int i = 0; i < n; i++) {
      System.err.printf("%d %d\n", i, costFromBack[i]);
    }
    */

    long[] reverseAs = new long[n];
    for (int i = 0; i < n; i++) {
      reverseAs[n - 1 - i] = as[i];
    }
    long[] reverseCostFromHead = calculateCost(reverseAs);
    long[] costFromHead = new long[n];
    for (int i = 0; i < n; i++) {
      costFromHead[n - 1 - i] = reverseCostFromHead[i] + 1;
    }
    long minCost = Math.min(costFromBack[0], costFromHead[n - 1]);
    for (int i = 1; i < n; i++) {
      minCost = Math.min(minCost, costFromHead[i-1] + costFromBack[i]);
    }
    return minCost;
  }
}

