class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
    long[,] dp = new long[n,50];//左端に4をかけた回数
    long[,] dpr = new long[n,50];//右端に4をかけた回数
    long answer = long.MaxValue;

    for(int i = 0; i < 50; i++)
    {
      dp[0,i] = 2*i;
      dpr[0,i] = 0;
      dpr[1,i] = 2*i;
    }

    for(int i = 1; i < n; i++)
    {
      int multiplyCount = 0;
      long numMemob = nums[n-i-1];//右端の数
      for(int j = 0; j < 18; j++)
      {
        dp[i,j] = 2*j;

        if(nums[n-i-1] > nums[n-i] && multiplyCount == 0)
        {
          long numMemo = nums[n-i];//次の数
          while(true)
          {
            if(numMemo >= nums[n-i-1]) break;
            multiplyCount++;
            numMemo *= 4;
          }
        }else
        {
          if(multiplyCount != 0)
          {
            multiplyCount++;
            //Console.WriteLine(j+" "+multiplyCount+"b");
          }else
          {
            if(numMemob > nums[n-i]) multiplyCount++;
            numMemob *= 4;
          }
        }
        //Console.WriteLine(j+" "+multiplyCount+"a");
        dp[i,j] += dp[i-1,multiplyCount];
        //Console.WriteLine(j+" "+dp[i,j]+" "+dp[i-1,multiplyCount]);
      }
    }

    for(int i = 2; i < n; i++)//dprの計算
    {
      int multiplyCount = 0;
      long numMemob = nums[i-1];//右端の数
      for(int j = 0; j < 18; j++)
      {
        dpr[i,j] = 2*j;

        if(nums[i-2] < nums[i-1] && multiplyCount == 0)
        {
          long numMemo = nums[i-2];//次の数
          while(true)
          {
            if(numMemo >= nums[i-1]) break;
            multiplyCount++;
            numMemo *= 4;
          }
        }else
        {
          if(multiplyCount != 0)
          {
            multiplyCount++;
          }else
          {
            if(numMemob > nums[i-2]) multiplyCount++;
            numMemob *= 4;
          }
        }

        dpr[i,j] += dpr[i-1,multiplyCount];
      }
    }

    for(int i = 0; i < n; i++)
    {
      //Console.WriteLine(dp[i,0]+" "+dpr[n-i-1,0]);
      answer = Math.Min(answer, dp[i,0]+dpr[n-i-1,0]+(n-1-i));
    }

		Console.WriteLine(answer);
	}
}

