	public class Solver {
		Random rnd = new Random();
		public void Solve() {
			var n = ri;
			var a = Enumerate(n, x => rl);
			var dpR = new long[n, 16];
			for (int i = 0; i < n; i++) for (int j = 0; j < 16; j++) dpR[i, j] = INF;
			for (int i = 0; i < 16; i++) dpR[n - 1, i] = i * 2;
			for (int i = n - 2, cnt = 1; i >= 0; i--, cnt++)
				for (int j = 0; j < 16; j++)
					for (int k = 0; k < 16; k++) {
						var val = dpR[i + 1, j] + k * 2;
						var num = 0;
						var u = a[i] << (k * 2);
						var v = a[i + 1] << (j * 2);
						while (v < u) { v *= 4; num++; }
						val += 2L * num * cnt;
						dpR[i, k] = Min(dpR[i, k], val);
					}
			var dpL = new long[n, 16];
			for (int i = 0; i < n; i++) for (int j = 0; j < 16; j++) dpL[i, j] = INF;
			for (int i = 0; i < 16; i++) dpL[0, i] = i * 2 + 1;
			for (int i = 1, cnt = 1; i < n; i++, cnt++) {
				for (int j = 0; j < 16; j++)
					for (int k = 0; k < 16; k++) {
						var val = dpL[i - 1, j] + k * 2 + 1;
						var num = 0;
						var u = a[i] << (k * 2);
						var v = a[i - 1] << (j * 2);
						while (v < u) { v *= 4; num++; }
						val += 2L * num * cnt;
						dpL[i, k] = Min(dpL[i, k], val);
					}
			}
			var ans = Min(dpL[n - 1, 0], dpR[0, 0]);
			for (int i = 1; i < n; i++) {
				Debug.WriteLine(ans);
				ans = Min(ans, dpL[i - 1, 0] + dpR[i, 0]);
			}
			Console.WriteLine(ans);
		}
		const long INF = 1L << 60;
		static int[] dx = { -1, 0, 1, 0 };
		static int[] dy = { 0, 1, 0, -1 };
		int ri { get { return sc.Integer(); } }
		long rl { get { return sc.Long(); } }
		double rd { get { return sc.Double(); } }
		string rs { get { return sc.Scan(); } }
		public IO.StreamScanner sc = new IO.StreamScanner(Console.OpenStandardInput());

		static T[] Enumerate<T>(int n, Func<int, T> f) {
			var a = new T[n];
			for (int i = 0; i < a.Length; ++i) a[i] = f(i);
			return a;
