    static void Main()
    {
        int n = sc.Int;
        var a = sc.LongArr;
        var cnt1 = new long[n + 1];
        var st = new Stack<P>();
        for (int i = n - 2; i >= 0 ; i--)
        {
            cnt1[i] = cnt1[i + 1];
            if (a[i] == a[i + 1]) continue;
            if (a[i] < a[i + 1]) {
                long p = a[i];
                int c = 0;
                while (p * 4 <= a[i + 1]) {
                    p *= 4;
                    ++c;
                }
                st.Push(new P(c, i));
                continue;
            }
            int ofst = 0;
            {
                long p = a[i + 1];
                while (p < a[i]) {
                    p *= 4;
                    ++ofst;
                }
            }
            int j = i;
            while (st.Any()) {
                var p = st.Pop();
                cnt1[i] += (p.v2 - j) * (long)ofst;
                j = p.v2;
                if (p.v1 > ofst) {
                    p.v1 -= ofst;
                    ofst = 0;
                    st.Push(p);
                    break;
                }
                if (p.v1 == ofst) {
                    ofst = 0;
                    break;
                }
                ofst -= p.v1;
            }
            cnt1[i] += (n - j - 1) * (long)ofst;
        }
        var cnt2 = new long[n + 1];
        st = new Stack<P>();
        for (int i = 2; i <= n; i++)
        {
            cnt2[i] = cnt2[i - 1];
            if (a[i - 2] == a[i - 1]) continue;
            if (a[i - 2] > a[i - 1]) {
                long p = a[i - 1];
                int c = 0;
                while (p * 4 <= a[i - 2]) {
                    p *= 4;
                    ++c;
                }
                st.Push(new P(c, i - 2));
                continue;
            }
            int ofst = 0;
            {
                long p = a[i - 2];
                while (p < a[i - 1]) {
                    p *= 4;
                    ++ofst;
                }
            }
            int j = i - 2;
            while (st.Any()) {
                var p = st.Pop();
                cnt2[i] += (j - p.v2) * (long)ofst;
                j = p.v2;
                if (p.v1 > ofst) {
                    p.v1 -= ofst;
                    ofst = 0;
                    st.Push(p);
                    break;
                }
                if (p.v1 == ofst) {
                    ofst = 0;
                    break;
                }
                ofst -= p.v1;
            }
            cnt2[i] += (j + 1) * (long)ofst;
        }
