    public long Long => long.Parse(Str);
    public double Double => double.Parse(Str);
    public string Str => Console.ReadLine().Trim();
    public pair<T, U> Pair<T, U>() where T : IComparable<T> where U : IComparable<U> {
        T a; U b;
        Multi(out a, out b);
        return new pair<T, U>(a, b);
    }
    public P P {
        get {
            int a, b;
            Multi(out a, out b);
            return new P(a, b);
        }
    }
    public int[] IntArr => StrArr.Select(int.Parse).ToArray();
    public long[] LongArr => StrArr.Select(long.Parse).ToArray();
    public double[] DoubleArr => StrArr.Select(double.Parse).ToArray();
    public string[] StrArr => Str.Split(new[]{' '}, StringSplitOptions.RemoveEmptyEntries);
    bool eq<T, U>() => typeof(T).Equals(typeof(U));
    T ct<T, U>(U a) => (T)Convert.ChangeType(a, typeof(T));
    T cv<T>(string s) => eq<T, int>()    ? ct<T, int>(int.Parse(s))
                       : eq<T, long>()   ? ct<T, long>(long.Parse(s))
                       : eq<T, double>() ? ct<T, double>(double.Parse(s))
                       : eq<T, char>()   ? ct<T, char>(s[0])
                                         : ct<T, string>(s);
    public void Multi<T>(out T a) => a = cv<T>(Str);
    public void Multi<T, U>(out T a, out U b)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); }
    public void Multi<T, U, V>(out T a, out U b, out V c)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); c = cv<V>(ar[2]); }
    public void Multi<T, U, V, W>(out T a, out U b, out V c, out W d)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); c = cv<V>(ar[2]); d = cv<W>(ar[3]); }
    public void Multi<T, U, V, W, X>(out T a, out U b, out V c, out W d, out X e)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); c = cv<V>(ar[2]); d = cv<W>(ar[3]); e = cv<X>(ar[4]); }
    public void Multi<T, U, V, W, X, Y>(out T a, out U b, out V c, out W d, out X e, out Y f)
    { var ar = StrArr; a = cv<T>(ar[0]); b = cv<U>(ar[1]); c = cv<V>(ar[2]); d = cv<W>(ar[3]); e = cv<X>(ar[4]); f = cv<Y>(ar[5]); }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		int n = int.Parse(Console.ReadLine());
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
    long[,] dp = new long[n,20];//左端に4をかけた回数
    long[,] dpr = new long[n,20];//右端に4をかけた回数
    long answer = long.MaxValue;

    for(int i = 0; i < 20; i++)
    {
      dp[0,i] = 2*i;
      dpr[0,i] = 0;
    }

    for(int i = 1; i < n; i++)
    {
      int multiplyCount = 0;
      long numMemob = nums[n-i-1];//右端の数
      for(int j = 0; j < 18; j++)
      {
        dp[i,j] = 2*j;

        if(nums[n-i-1] > nums[n-i] && multiplyCount == 0)
        {
          long numMemo = nums[n-i];//次の数
          while(true)
          {
            if(numMemo >= nums[n-i-1]) break;
            multiplyCount++;
            numMemo *= 4;
          }
        }else
        {
          if(multiplyCount != 0)
          {
            multiplyCount++;
            //Console.WriteLine(j+" "+multiplyCount+"b");
          }else
          {
            if(numMemob > nums[n-i]) multiplyCount++;
            numMemob *= 4;
          }
        }
        //Console.WriteLine(j+" "+multiplyCount+"a");
        dp[i,j] += dp[i-1,multiplyCount];
        //Console.WriteLine(j+" "+dp[i,j]+" "+dp[i-1,multiplyCount]);
      }
    }

    for(int i = 1; i < n; i++)//dprの計算
    {
      int multiplyCount = 0;
      long numMemob = nums[i];//右端の数
      for(int j = 0; j < 18; j++)
      {
        dpr[i,j] = 2*j;

        if(nums[i-1] < nums[i] && multiplyCount == 0)
        {
          long numMemo = nums[i-1];//次の数
          while(true)
          {
            if(numMemo >= nums[i]) break;
            multiplyCount++;
            numMemo *= 4;
          }
        }else
        {
          if(multiplyCount != 0)
          {
            multiplyCount++;
          }else
          {
            if(numMemob > nums[i-1]) multiplyCount++;
            numMemob *= 4;
          }
        }

        dpr[i,j] += dpr[i-1,multiplyCount];
      }
    }

    for(int i = 0; i < n; i++)
    {
      //Console.WriteLine(dp[i,0]+" "+dpr[n-i-1,0]);
      answer = Math.Min(answer, dp[i,0]+dpr[n-i-1,0]+(n-1-i));
    }

		Console.WriteLine(answer);
	}
}

