		//         A[i] > A[i+1] => A[i] <= 2^n A[i+1] となる最小の n (>=1) にたいし, rat[i] = n
		for (var i = 0; i < N - 1; i++)
			if (A[i] <= A[i + 1])
			{
				var a = A[i];
				var b = A[i + 1];
				while (a <= b) { a *= 2; rat[i]++; }
				rat[i] = 1 - rat[i];
			}
			else
			{
				var a = A[i];
				var b = A[i + 1];
				while (a > b) { b *= 2; rat[i]++; }
			}
		if (N > 10000) throw new Exception();
		var re = new long[N - 1];
		for (var i = 0; i < N - 1; i++) re[i] = (rat[i] + 1) / 2;
		var ro = new long[N - 1];
		for (var i = 0; i < N - 1; i++) ro[i] = (-rat[N - i - 2] + 1) / 2;
		var se = GiveSum3(re);
		var so = GiveSum3(ro);
		var min = long.MaxValue;
		for (var n = 0; n < N; n++) min = Min(min, n + 2 * so[N - 1 - n] + 2 * se[n]);
		WriteLine(min);
	}
	long[][] GiveSum(long[] r)
	{
		var N = r.Length;
		var depth = -r.Min() * 2;
		var dp = new long[N + 2][];
		for (var i = 0; i < N + 2; i++) dp[i] = new long[depth + 1];
		for (var d = 0; d <= depth; d++) dp[N][d] = d;
		for (var n = N - 1; n >= 0; n--)
		{
			for (var d = 0; d <= depth; d++)
			{
				var e = Max(d + r[n], 0);
				dp[n][d] = d + dp[n + 1][Min(e, depth)] + Max(e - depth, 0) * (N - n);
			}
		}
		var sum = new long[N + 2];
		for (var i = 0; i <= N + 1; i++) sum[i] = dp[i][0];
		return dp;
	}
	// -20<=r[i]<=20, 0<=i<N
	// f(x):=max(x,0)
	// e[i,n,x], n<=i<=N, 0<=n<=N+1, x>=0
	// e[n,n,x]=x (0<=n<=N+1)
	// e[i+1,n,x]=f(e[i,n,x]+r[i]) (n<=i<N)
	// sum[n,x]=sum(n<=i<=N,e[i,n,x]) (0<=n<=N)
	long[][] GiveSum2(long[] r)
	{
		var N = r.Length;
		var depth = -r.Min() + 30;
		var e = new long[N + 1];
		var sum = new long[N + 2][];
		sum[N + 1] = new long[depth + 1];
		for (var n = 0; n <= N; n++)
		{
			sum[n] = new long[depth + 1];
			for (var d = 0; d <= depth; d++)
			{
				var s = 0L;
				s += e[n] = d;
				for (var i = n; i < N; i++) s += e[i + 1] = Max(e[i] + r[i], 0);
				sum[n][d] = s;
			}
		}
		return sum;
	}
	long[] GiveSum3(long[] r)
	{
		var N = r.Length;
		var e = new long[N + 1];
		var sum = new long[N + 2];
		for (var n = 0; n <= N; n++)
		{
			var s = 0L;
			e[n] = 0;
			for (var i = n; i < N; i++) s += e[i + 1] = Max(e[i] + r[i], 0);
			sum[n] = s;
		}
		return sum;
	}
	(long[], long) Dec(long[] a)
	{
		var N = a.Length;
		var d = a[N - 1] - a[N - 2];
		var i = N - 1;
		while (i > 0 && d == a[i] - a[i - 1]) i--;
		if (i <= 0) return (new[] { a[0] }, d);
		return (a.Take(i + 1).ToArray(), d);
	}
}

