class Sol{
	public void Solve(){
		if(N == 1){
			Console.WriteLine(0);
			return;
		}

		int l = 0;
		int r = N - 1;
		while(r - l > 1){
			int c = (l + r) / 2;
			long t0 = calc(c);
			long t1 = calc(c+1);
			if(t1 > t0){
				l = c;
			} else {
				r = c;
			}
		}

		long min = (long)1e18;
		for(int i=l-100;i<l+100;i++){
			if(i < 0 || i >= N) continue;
			min = Math.Min(min, calc(i));
		}
		Console.WriteLine(min);
	}

	long calc(int idx){

		long[] cnt = new long[N];

		for(int j=idx + 1;j<N;j++){
			long now = A[j];
			long prev = A[j - 1];

			cnt[j] = cnt[j - 1];
			if(now > prev){
				while(cnt[j] >= 2 && now > prev * 4){
					cnt[j] -= 2;
					now /= 4;
				}
			} else if(now < prev){
				while(now < prev){
					now *= 4;
					cnt[j] += 2;
				}
			}
		}

		for(int j=idx - 1;j >= 0;j--){
			long now = A[j];
			long prev = A[j + 1];

			cnt[j] = cnt[j + 1];
			if(cnt[j] % 2 == 1){
				now *= 2;
				prev *= 2;

				if(now > prev){
					while(cnt[j] >= 3 && now > prev * 4){
						cnt[j] -= 2;
						now /= 4;
					}
				} else if(now < prev){
					while(now < prev){
						now *= 4;
						cnt[j] += 2;
					}
				}
			} else {
				if(now > prev){
					cnt[j] = 1;
				}
			}
		}

		long tot = 0;
		for(int i=0;i<N;i++) tot += cnt[i];
		return tot;

	}



