          long numMemo = nums[n-i];//次の数
          while(true)
          {
            if(numMemo >= nums[n-i-1]) break;
            multiplyCount++;
            numMemo *= 4;
          }
        }else
        {
          if(multiplyCount != 0)
          {
            multiplyCount++;
            //Console.WriteLine(j+" "+multiplyCount+"b");
          }else
          {
            if(numMemob > nums[n-i]) multiplyCount++;
            numMemob *= 4;
          }
        }
        //Console.WriteLine(j+" "+multiplyCount+"a");
        dp[i,j] += dp[i-1,multiplyCount];
        //Console.WriteLine(j+" "+dp[i,j]+" "+dp[i-1,multiplyCount]);
      }
    }

    for(int i = 1; i < n; i++)//dprの計算
    {
      int multiplyCount = 0;
      long numMemob = nums[i];//右端の数
      for(int j = 0; j < 18; j++)
      {
        dpr[i,j] = 2*j;

        if(nums[i-1] < nums[i] && multiplyCount == 0)
        {
          long numMemo = nums[i-1];//次の数
          while(true)
          {
            if(numMemo >= nums[i]) break;
            multiplyCount++;
            numMemo *= 4;
          }
