			for (var i = n; i < N; i++) s += e[i + 1] = Max(e[i] + r[i], 0);
			sum[n] = s;
		}
		return sum;
	}
	Tuple<long[], long> Dec(long[] a)
	{
		var N = a.Length;
		var d = a[N - 1] - a[N - 2];
		var i = N - 1;
		while (i > 0 && d == a[i] - a[i - 1]) i--;
		if (i <= 0) return new Tuple<long[], long> (new[] { a[0] }, d);
		return new Tuple<long[], long>(a.Take(i + 1).ToArray(), d);
	}
}

