    int upper_bound(List<pair> arr, BigInteger val)
    {
        int low = 0, high = arr.Count();
        int mid;

        while (low < high)
        {
            mid = ((high - low) >> 1) + low;
            if (arr[mid].f <= val) low = mid + 1;
            else high = mid;
        }
