    for(int i = 1; i < n; i++)
    {
      long memoNum = nums[i];
      long memoCount = 0;
      while(true)
      {
        if(memoNum < leftNum)
        {
          memoNum *= 4;
          answer += 2;
          memoCount += 1;
        }else break;
      }
      leftNum = nums[i];
      for(int j = 0; j < memoCount; j++)
      {
        leftNum *= 4;
      }
    }

    for(int i = 1; i < n; i++)
    {
      if(i > 0 && nums[i-1] <= nums[i]) continue;//最小になり得ない
      if(answer <= i) break;//負にすると最小になり得ない
      answerMemo = i;//負にする個数

      answer = Math.Min(answerMemo, answer);
    }

