func Count(C [][]int) []int {
  Z, K := 0, 1
  for i := range C[2:] {
    Z = (Z + K * C[i + 1][1] % p) % p
    K = (K + Z * (C[i + 2][0] - C[i + 1][0]) % p) % p
  }
  return []int{Z, K}
}

const p = 1000000007

func Solve() {
  var N int
  NextInt(&N)
  var A []int
  NextIntVec(&A)
  C := make([][]int, N + 1)
  for i := range C {
    C[i] = []int{0, 0}
  }
  for i, a := range A[1:] {
    C[i + 2][1]++
    if a < A[i] {
      for _a := a; _a < A[i]; _a *= 4 {
        C[i][0]++
        C[i + 2][1]--
      }
    } else {
      for _a := A[i]; 4 * _a <= a; _a *= 4 {
        C[i][0]--
        C[i + 2][1]++
        if 4 * _a == a { C[i + 2][1]-- }
      }
    }
  }
  D := make([][]int, N + 1)
  for i := range D {
    D[i] = make([]int, 2)
  }
  for i := N - 2; 0 <= i; i-- {
    D[i][0] = D[i + 1][0] + C[i][0] * (N - 1 - i)
  }
  for i := 2; i <= N; i++ {
    D[i][1] = D[i - 1][1] + C[i][1] * (i - 1)
  }
  E := make([]int, N + 1)
  for i := range E {
    E[i] = 2 * (D[i][0] + D[i][1]) + i
    E[i] -= 2 * MinInt(C[i][0], 0) * (N - 1 - i)
    E[i] -= 2 * MinInt(C[i][1], 0) * (i - 1)
  }
  Write(MinInt(E...))
}

