var ans int

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)

	scanner.Scan()
	var n int
	fmt.Sscanf(scanner.Text(), "%d", &n)

	as := make([]int, n)
	for i := 0; i < n; i++ {
		scanner.Scan()
		fmt.Sscanf(scanner.Text(), "%d", &as[i])
	}

	ans := math.MaxInt64
loop:
	for p := 0; p <= n; p++ {
		arr := make([]int, n)
		copy(arr, as)

		count := 0
		// fmt.Println("before", arr)
		if (p-1) >= 0 && arr[p-1] > 0 {
			arr[p-1] = arr[p-1] * (-2)
			count++
		}
		if p < n && arr[p] < 0 {
			arr[p] = arr[p] * (-2)
			count++
		}

		for i := p - 1; i >= 1; i-- {
			if arr[i-1] == 0 {
				continue loop
			}
			if arr[i-1] > 0 {
				arr[i-1] = arr[i-1] * (-2)
				count++
			}
			if arr[i-1] > arr[i] {
				var c int
				arr[i-1], c = mult4x(arr[i-1], arr[i])
				count = count + c
				// if count >= ans {
				// continue loop
				// }
			}
		}
		for i := p; i <= n-2; i++ {
			if arr[i+1] == 0 {
				continue loop
			}
			if arr[i+1] < 0 {
				arr[i+1] = arr[i+1] * (-2)
				count++
			}
			if arr[i] > arr[i+1] {
				var c int
				arr[i+1], c = mult4x(arr[i+1], arr[i])
				count = count + c
				// if count >= ans {
				// continue loop
				// }
			}
		}
		// fmt.Println("after ", arr)
		// fmt.Println("count", count)
		// fmt.Println("-------------")
		ans = min(ans, count)
	}

	if ans == math.MaxInt64 {
		fmt.Println(-1)
	} else {
		fmt.Println(ans)
	}

}

func mult4x(start, cirteria int) (int, int) {
	count := int(math.Ceil(math.Log2(float64(cirteria)/float64(start)) / 2.0))
	ret := start * int(math.Pow(4, float64(count)))
	return ret, count * 2
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

