var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  buffer := make([]byte, 0)
  for true {
    line, isPrefix, err := reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
    if !isPrefix { break }
  }
  return string(buffer)
}
func NextInt(A ...*int) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.Atoi(L[i])
  }
}
func NextIntVec(A *[]int) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]int, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.Atoi(l)
  }
}
func NextFloat(A ...*float64) {
  L := strings.Split(NextLine(), " ")
  for i, a := range A {
    *a, _ = strconv.ParseFloat(L[i], 64)
  }
}
func NextFloatVec(A *[]float64) {
  L := strings.Split(NextLine(), " ")
  (*A) = make([]float64, len(L))
  for i, l := range L {
    (*A)[i], _ = strconv.ParseFloat(l, 64)
  }
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func WriteIntVec(A []int) {
  S := make([]string, len(A))
  for i, a := range A {
    S[i] = strconv.Itoa(a)
  }
  Write(strings.Join(S, " "))
}
func Output() {
  _ = writer.Flush()
}

func MaxInt(A ...int) int {
  max := A[0]
  for _, a := range A {
    if max < a { max = a }
  }
  return max
}
func MinInt(A ...int) int {
  min := A[0]
  for _, a := range A {
    if a < min { min = a }
  }
  return min
}
func SumInt(A ...int) int {
  sum := 0
  for _, a := range A {
    sum += a
  }
  return sum
}
func AbsInt(x int) int {
  if x < 0 { x = -x }
  return x
}

func Solve() {
  var N int
  NextInt(&N)
  var A []int
  NextIntVec(&A)
  DP := make([][]int, N)
  DP2 := make([][]int, N)
  for i := range DP {
    DP[i] = make([]int, 16)
    DP2[i] = make([]int, 16)
    for j := range DP[i] {
      DP[i][j] = j
      DP2[i][j] = j
    }
  }
  for i := N - 2; 0 <= i; i-- {
    k := 0
    for a := A[i + 1]; a < A[i]; a *= 4 { k++ }
    for a := A[i]; 4 * a <= A[i + 1]; a *= 4 { k-- }
    for j := range DP[i] {
      DP[i][j] += DP[i + 1][MaxInt(MinInt(j + k, 15), 0)]
      DP[i][j] += (N - 1 - i) * MaxInt(j + k - 15, 0)
    }
  }
  for i := 1; i < N; i++ {
    k := 0
    for a := A[i - 1]; a < A[i]; a *= 4 { k++ }
    for a := A[i]; 4 * a <= A[i - 1]; a *= 4 { k-- }
    for j := range DP2[i] {
      DP2[i][j] += DP2[i - 1][MaxInt(MinInt(j + k, 15), 0)]
      DP2[i][j] += i * MaxInt(j + k - 15, 0)
    }
  }
  C := make([]int, N + 1)
  for i := range C {
    C[i] = i
  }
  for i := range DP {
    C[i] += 2 * DP[i][0]
    C[i + 1] += 2 * DP2[i][0]
  }
  Write(MinInt(C...))
}

func main() {
  Solve()
  Output()
}

