  long[] bs = new long[N+1];
  {
    long[] ds = new long[N];
    long t = 0;
    foreach(i; 1..N) {
      bs[i+1] += bs[i];
      long k = 1;
      while(as[i-1]*k < as[i]) {
        k *= 4;
        while (i-1-t >= 0 && ds[i-1-t] == 0) {
          t++;
        }
        if (i-1-t>=0 && ds[i-1-t] > 0) {
          ds[i-1-t]--;
        }
        bs[i+1] += t;
      }
      long p = 4;
      while(as[i-1]*k >= as[i]*p) {
        p *= 4;
        ds[i-1]++;
      }
    }
  }

  long[] cs = new long[N+1];
  {
    long[] ds = new long[N];
    long t = 0;
    foreach(i; 1..N) {
      cs[i+1] += cs[i];
      long k = 1;
      while(as[$-i]*k < as[$-i-1]) {
        k *= 4;
        while (N-i+t < N && ds[$-i+t] == 0) {
          t++;
        }
        if (N-i+t<N && ds[$-i+t] > 0) {
          ds[$-i+t]--;
        }
        cs[i+1] += t;
      }
      long p = 4;
      while(as[$-i]*k >= as[$-i-1]*p) {
        p *= 4;
        ds[$-1]++;
      }
    }
  }

