enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

void main() {
  long N;
  scanln(N);
  long[] as = readln.split.to!(long[]);

  long[] bs = new long[N+1];
  {
    long[] ds = new long[N];
    long t = 0;
    long k = 1;
    foreach(i; 1..N) {
      long p = 4;
      while(as[i-1]*k >= as[i]*p) {
        p *= 4;
        ds[i-1]++;
      }
      bs[i+1] += bs[i];
      k = 1;
      while(as[i-1]*k < as[i]) {
        k *= 4;
        while (i-1-t >= 0 && ds[i-1-t] == 0) {
          t++;
        }
        if (i-1-t>=0 && ds[i-1-t] > 0) {
          ds[i-1-t]--;
        }
        bs[i+1] += t;
      }
    }
  }

  long[] cs = new long[N+1];
  {
    long[] ds = new long[N];
    long t = 0;
    long k = 1;
    foreach(i; 1..N) {
      long p = 4;
      while(as[$-i]*k >= as[$-i-1]*p) {
        p *= 4;
        ds[$-1]++;
      }
      cs[i+1] += cs[i];
      k = 1;
      while(as[$-i]*k < as[$-i-1]) {
        k *= 4;
        while (N-i+t < N && ds[$-i+t] == 0) {
          t++;
        }
        if (N-i+t<N && ds[$-i+t] > 0) {
          ds[$-i+t]--;
        }
        cs[i+1] += t;
      }
    }
  }

  long ans = INF;
  foreach(i; 0..N+1) {
    long s = i + 2*(bs[i] + cs[$-i-1]);
    ans.ch!min(s);
  }
  ans.writeln;
}

