long f(long x1, long x2) {
  if(x1 <= x2) {
    long ans = 0;
    while(x1 <= x2) {
      x1 *= 4;
      ++ans;
    }
    return ans - 1;
  } else {
    long ans = 0;
    while(x2 < x1) {
      x2 *= 4;
      --ans;
    }
    return ans;
  }
}

long solve(long[] a) {
