enum long INF = long.max/3;
enum long MOD = 10L^^9+7;

struct P {
  long index;
  long value;
}

void main() {
  long N;
  scanln(N);
  BigInt[] as = readln.split.to!(long[]).map!(a => BigInt(a)).array;

  long[] bs = new long[N+1];
  {
    auto stack = DList!P();
    foreach(i; 1..N) {
      BigInt l = 4;
      P p = P(i-1, 0);
      while(as[i-1] >= as[i]*l) {
        l *= 4;
        p.value++;
      }
      stack.insertBack(p);

      bs[i+1] += bs[i];
      BigInt k = 1;
      while(as[i-1]*k < as[i]) {
        k *= 4;
        while(!stack.empty) {
          P q = stack.back;
          stack.removeBack;
          if (q.value > 0) {
            q.value--;
            stack.insertBack(q);
            break;
          }
        }
        long t = 0;
        if (stack.empty) {
          t = i;
        } else {
          t = i - 1 - stack.back.index;
        }
        bs[i+1] += t;
      }
    }
  }

  long[] cs = new long[N+1];
  {
    auto stack = DList!P();

    foreach(i; 1..N) {
      BigInt l = 4;
      P p = P(N-i, 0);
      while(as[$-i] >= as[$-i-1]*l) {
        l *= 4;
        p.value++;
      }
      stack.insertBack(p);

      cs[i+1] += cs[i];
      BigInt k = 1;
      while(as[$-i]*k < as[$-i-1]) {
        k *= 4;
        while(!stack.empty) {
          P q = stack.back;
          stack.removeBack;
          if (q.value > 0) {
            q.value--;
            stack.insertBack(q);
            break;
          }
        }
        long t = 0;
        if (stack.empty) {
          t = i;
        } else {
          t = i - 1 - (N - stack.back.index - 1);
        }
        cs[i+1] += t;
      }
    }
  }

  long ans = INF;
  foreach(i; 0..N+1) {
    long s = i + 2*(bs[i] + cs[$-i-1]);
    ans.ch!min(s);
  }
  ans.writeln;
}

