long f(long x1, long x2) {
  if(x1 <= x2) {
    long ans = 0;
    while(x1 <= x2) {
      x1 *= 4;
      ++ans;
    }
    return ans - 1;
  } else {
    long ans = 0;
    while(x2 < x1) {
      x2 *= 4;
      --ans;
    }
    return ans;
  }
}

long solve(long[] a) {
  long ans = 0;
  long t = 0;
  if(a.empty()) {
    return 0;
  }
  foreach(i; iota(a.length - 1)) {
    auto alpha = f(a[i], a[i+1]);
    t = max(0, t - f(a[i], a[i+1]));
    ans += t;
  }
  return ans;
}

