  long ans = long.max;
  long[] b;
  foreach(i; iota(n + 1)) {
    ans = min(ans, solve(b) * 2 + solve(a) * 2 + i);
    if(!a.empty()) {
      b ~= a[0] * 2;
      a = a[1..$];
    }
