const M = 15

proc main() =
  let n = readInt1()
  let a = readSeq().map(parseInt)

  var dp1 = newSeq2[int](n + 1, M + 1)
  block:
    dp1[n].fill(0)
    for j in 0..M:
      dp1[n - 1][j] = 2 * j

    for i in countdown(n - 2, 0):
      for j in 0..M:
        let a0 = a[i] * (4 ^ j)

        var a1 = a[i + 1]
        var cnt = 0
        while a0 > a1:
          a1 *= 4
          cnt += 1

        dp1[i][j] = 2 * j + dp1[i + 1][min(cnt, M)] + (n - 1 - i) * max(cnt - M, 0)

  var dp2 = newSeq2[int](n + 1, M + 1)
  block:
    dp2[0].fill(0)

    for j in 0..M:
      dp2[1][j] = 2 * j + 1

    for i in 2..n:
      for j in 0..M:
        let a0 = -2 * a[i - 1] * (4 ^ j)

        var a1 = -2 * a[i - 2]
        var cnt = 0
        while a1 > a0:
          a1 *= 4
          cnt += 1

        dp2[i][j] = 2 * j + 1 + dp2[i - 1][min(cnt, M)] + (i - 1) * max(cnt - M, 0)

  var ans = INF
  for i in 0..n:
    ans = min(ans, dp1[i][0] + dp2[i][0])
  echo ans

main()

