# k個目を固定すると仮定したときの操作回数
def process(A, k):
  left = 0
  t = A[k]
  for i in range(k-1, -1, -1):
    a = A[i]
    if a > t:
      if t > 0:
        left += 1
        t = a * (-2)
      else:
        l = math.ceil(math.log2(abs(t)) - math.log2(abs(a)))
        if l % 2 == 0:
          l += 1 # 奇数にする
        left += l
        t = -(a * 2 ** l)
    else:
      t = a
  right = 0
  t = A[k]
  for i in range(k+1, N):
    a = A[i]
    if t > a:
      l = math.ceil(math.log2(abs(t)) - math.log2(abs(a)))
      if l % 2 == 1:
        l += 1 # 偶数にする
      right += l
      t = a * 2 ** l
    else:
      t = a
  return left + right

