def multi_times(border):
    ans = 0
    num = 1
    for i in range(border, n):
        if num <= a[i]:
            num = a[i]
        else:
            cnt = int(math.log2(num/a[i])/2 + 0.99999)
            num = (4**cnt) * cnt * a[i]
            ans += cnt * 2

    num = 1
    for i in range(0, border)[::-1]:
        ans += 1
        if num <= a[i]:
            num = a[i]
        else:
            cnt = int(math.log2(num/a[i])/2 + 0.99999)
            num = (4**cnt) * a[i]
            ans += cnt * 2
    return ans

