def create_dp_table(aaa):
    dp = [list(range(16)) for _ in range(n)]
    for i, (pa, a, dpp, dpi) in enumerate(zip(aaa, aaa[1:], dp, dp[1:])):
        ds = ceil(log(a / pa, 4))
        for j in range(16):
            k = j + ds
            if k < 16:
                dpi[j] += dpp[max(0, k)]
            else:
                dpi[j] += dpp[15] + (k - 15) * (i + 1)
    return dp


