def eval(a, m):
    ret = m
    if m > 0:
        tmp = a[m - 1]
        for i in range(m - 1, 0, -1):
            if a[i - 1] < tmp:
                cnt = math.ceil(math.log(tmp / a[i - 1], 4))
                ret += cnt * 2
                tmp = a[i - 1] * 4 ** cnt
            else:
                tmp = a[i - 1]
            if tmp > 1e100:
                return -1
    tmp = a[m]
    for i in range(m + 1, len(a)):
        if a[i] < tmp:
            cnt = math.ceil(math.log(tmp / a[i], 4))
            if cnt < -1:
                return -1
            ret += cnt * 2
            tmp = a[i] * 4 ** cnt
        else:
            tmp = a[i]
        if tmp > 1e100:
            return -1
    return ret


