def process(A, k):
  left = 0
  t = A[k]
  for i in range(k-1, -1, -1):
    a = A[i]
    if a > t:
      if t > 0:
        left += 1
        t = a * (-2)
      else:
        abst = abs(t)
        if abst not in log2:
          log2[abst] = math.log(abst, 2)
        l = math.ceil(log2[abst] - log2[a])
        if l % 2 == 0:
          l += 1 # 奇数にする
        left += l
        t = -(a * 2 ** l)
    else:
      t = a
  right = 0
  t = A[k]
  for i in range(k+1, N):
    a = A[i]
    if t > a:
      if t not in log2:
        log2[t] = math.log(t, 2)
      l = math.ceil(log2[t] - log2[a])
      if l % 2 == 1:
        l += 1 # 偶数にする
      right += l
      t = a * 2 ** l
    else:
      t = a
  return left + right

