fn diff(mut a: i64, mut b: i64) -> i64 {
    let mut w = 0;
    if a <= b {
        while 4*a <= b {
            a *= 4;
            w += 1;
        }
        w
    } else {
        while a > b {
            b *= 4;
            w -= 1;
        }
        w
    }
}

fn solve(a: Vec<i64>) -> Vec<i64> {
    let n = a.len();
    let maxw = 17;
    let mut dp = dvec!(0; n+1, maxw);
    for f in 1..n+1 {
        for i in 0..maxw {
            dp[f][i] = i as i64;
        }
    }

    for i in 1..n {
        let ti = i+1;
        let d = diff(a[n-i-1], a[n-i]);
        if d >= 0 {
            let di = d as usize;
            for j in 0..maxw {
                let lj = ifv!(j <= di, 0, j-di);
                dp[ti][j] += dp[i][lj];
            }
        } else {
            let di = (-d) as usize;
            for j in 0..maxw {
                let lj = j+di;
                dp[ti][j] += ifv!(lj < maxw, dp[i][lj], dp[i][maxw-1] + ((lj - maxw + 1) * (n - ti + 1)) as i64);
            }
        }
    }

    dp.iter().cloned().map(|a| a[0]).collect::<Vec<_>>()
}

const INF: i64 = 1e12 as i64;

fn main() {
    input! {
        n: usize,
        a: [i64; n]
    };

    let mut ap = a.iter().cloned().map(|x| x * 2).collect::<Vec<_>>();
    ap.reverse();

    let right = solve(a);
    let left = solve(ap);
    assert_eq!(left.len(), n+1);
    assert_eq!(right.len(), n+1);

    // debug!(left, right);

    let mut ans = INF;
    for i in 0..n+1 {
        ans = min(ans, right[i] * 2 + left[n-i] * 2 + (n-i) as i64);
    }

    println!("{}", ans);
}

