fn construct_dp(a: &Vec<u64>) -> Vec<Vec<usize>> {
    let mut dp = vec![vec![0; 16]; a.len()];
    for i in 0..16 {
        dp[a.len() - 1][i] = i;
    }

    for i in (1..a.len()).rev() {
        for j in 0..16 {
            dp[i - 1][j] = j;
            if a[i - 1] * (1 << j) <= a[i] {
                dp[i - 1][j] += dp[i][0];
            } else {
                let mut inc = ((a[i - 1] as f64 * 4.0f64.powf(j as f64) / a[i] as f64).log2() * 0.5).ceil() as usize;
                // println!("i {0} a[i - 1] {1} a[i] {2} inc {3}", i , a[i - 1], a[i], inc);
                if inc > 15 {
                    dp[i - 1][j] += (inc - 15) * (a.len() - 1 - i);
                    inc = 15;
                }
                dp[i - 1][j] += dp[i][inc];
            }
        }
    }
    dp
}

fn main() {
    let n: usize = read();
    let mut a = read_vec::<u64>();
    let dp_forward = construct_dp(&a);

    a.reverse();
    let dp_backward = construct_dp(&a);
    let mut ans = std::cmp::min(dp_forward[0][0] * 2, dp_backward[0][0] * 2 + a.len());

    for i in 1..n-1 {
        // println!("{:?}", dp_forward[i]);
        let tmp_ans = dp_forward[i][0] * 2 + i + dp_backward[n - i - 1][0] * 2;
        // println!("i {0} dp_forward[i][0] {1} dp_backward[n - i - 1][0] {2} {3}",
        //          i, dp_forward[i][0] * 2, dp_backward[n - i - 1][0] * 2, tmp_ans);
        ans = std::cmp::min(ans, tmp_ans);
    }

    println!("{:?}", ans);
}

