fn gen_suffix(a: &Vec<i64>) -> Vec<usize> {
    let n = a.len();
    let mut suffix = vec![0; n + 1];
    let mut stack: Vec<(i64, usize)> = vec![];
    for i in (0..n).rev() {
        let cur = a[i];
        let mut cost = 0;
        while !stack.is_empty() && stack[stack.len() - 1].0 < cur {
            let mut head = stack.pop().unwrap();
            head.0 *= 4;
            cost += 2 * head.1;
            if !stack.is_empty() && stack[stack.len() - 1].0 < cur * 4 {
                let s = stack.len() - 1;
                stack[s].0 = head.0;
                stack[s].1 += head.1;
            } else {
                stack.push(head);
            }
        }
        if stack.is_empty() || stack[stack.len() - 1].0 >= cur * 4 {
            stack.push((cur, 1));
        } else {
            let mut head = stack.pop().unwrap();
            head.0 = cur;
            head.1 += 1;
            stack.push(head);
        }
        suffix[i] = suffix[i + 1] + cost;
    }

    suffix
}

fn gen(a: &Vec<i64>) -> Vec<usize> {
    let n = a.len();

    let mut prefix = vec![0; n + 1];
    let mut stack: Vec<(i64, usize)> = vec![];
    for i in 0..n {
        let cur = -2 * a[i];
        let mut cost = 1;
        while !stack.is_empty() && stack[stack.len() - 1].0 > cur {
            let mut tail = stack.pop().unwrap();
            tail.0 *= 4;
            cost += 2 * tail.1;
            if !stack.is_empty() && stack[stack.len() - 1].0 > cur * 4 {
                let s = stack.len() - 1;
                stack[s].0 = tail.0;
                stack[s].1 += tail.1;
            } else {
                stack.push(tail);
            }
        }
        if stack.is_empty() || stack[stack.len() - 1].0 <= cur * 4 {
            stack.push((cur, 1));
        } else {
            let mut x = stack.pop().unwrap();
            x.0 = cur;
            x.1 += 1;
            stack.push(x);
        }
        prefix[i + 1] = cost + prefix[i];
    }
    prefix
}

