fn solve(a: Vec<usize>) -> usize {
    struct Solver {
        a: Vec<usize>,
        m: Vec<Vec<Option<usize>>>,
    }
    impl Solver {
        fn new(a: Vec<usize>) -> Self {
            let len = a.len();
            Solver {
                a: a,
                m: vec![vec![None; len]; 16],
            }
        }
        // i-1番目(0-origin)の項目をc*2回-2倍して、
        // j in [0,i-1) の項目の絶対値を |a[j]| => |a[j+1]| にするための `-2倍の 適用回数/2 ` を返す
        fn get(&mut self, i: usize, c: usize) -> usize {
            if i == 0 {
                return 0;
            }
            if i == 1 {
                return c;
            }

            if c >= self.m.len() {
                let d = c - self.m.len() + 1;
                return self.get(i, c - d) + d;
            }
            if let Some(value) = self.m[c][i - 2] {
                return value;
            }
            let mut c_next = c;
            let a0 = self.a[i - 2];
            let mut a1 = self.a[i - 1];
            if a0 < a1 {
                c_next += (a1 - 1) / a0 / 4 + 1;
            } else {
                while c_next > 0 && a0 * 4 >= a1 {
                    c_next -= 1;
                    a1 *= 4;
                }
            }
            let value = c + self.get(i - 1, c_next);
            self.m[c][i - 1] = Some(value);
            value
        }
    }
    let a_len = a.len();

    let a0 = a.clone();
    let mut a1 = a;
    a1.reverse();

    let mut s0 = Solver::new(a0);
    let mut s1 = Solver::new(a1);

    (0..a_len)
        .map(|x| s0.get(x, 0) * 2 + x + s1.get(a_len - x, 0) * 2)
        .min()
        .unwrap()
}

