fn solve(pos: usize, k: i64, a: &[i64], rtbl: &mut Vec<Vec<Option<i64>>>) -> i64 {
    if pos + 1 >= a.len() {
        return 0;
    }

    if k >= 16 {
        return solve(pos, 15, a, rtbl) + (k - 15) * (a.len() - pos - 1) as i64;
    }

    if let &Some(ret) = &rtbl[pos][k as usize] {
        return ret;
    }

    // a[pos] * 4^k <= a[pos+1] * 4^m
    // a[pos] <= a[pos+1] * 4^(m - k)

    let d = if a[pos] < a[pos + 1] {
        let mut d = 0;
        while a[pos] * 4i64.pow(d) < a[pos + 1] {
            d += 1
        }
        -(d as i64 - 1)
    } else {
        let mut d = 0;
        while a[pos] > a[pos + 1] * 4i64.pow(d) {
            d += 1
        }
        d as i64
    };

    let nk = d + k;
    let nk = std::cmp::max(nk, 0);

    // println!("* {} * 4^{} <= {} * 4^{}", a[pos], k, a[pos + 1], nk);

    let ret = solve(pos + 1, nk, a, rtbl) + nk;

    rtbl[pos][k as usize] = Some(ret);
    ret
}

