fn step(mut a: i64, mut b: i64) -> (i64, bool) {
    if a <= b {
        (0, a == b)
    } else {
        let mut cnt = 0;
        while b < a {
            b *= 4;
            cnt += 1;
        }
        (cnt, a == b)
    }
}

const INF: i64 = 1e12 as i64;

fn solve(a: Vec<i64>) -> Vec<i64> {
    let n = a.len();

    let mut dp = vec![0; n+1];
    let mut last = a[n-1];
    let mut deq = VecDeque::new();
    deq.push_back((INF, n-1));
    for i in (0..n-1).rev() {
        dp[i] = dp[i+1];

        let (mut c, sm) = step(a[i], last);
        if c == 0 {
            let (c0, sm) = step(last, a[i]);
            if c0 >= 1 {
                deq.push_front((c0, i));
            }
            last = a[i];
            continue;
        }
        // debug!(c, sm, a[i], last, deq);

        last = a[i];

        let mut now = i;
        let mut total = 0;
        let mut rem = 0;
        let mut tweaklast = false;
        for w in 0..deq.len() {
            let &(cnt, idx) = deq.get(w).unwrap();
            total += ((idx - now) as i64) * c;
            if cnt >= c {
                if cnt == c {
                    rem += 1;
                } else {
                    tweaklast = true;
                }
                break;
            } else {
                c -= cnt;
                rem += 1;
            }
        }
        for l in 0..rem {
            deq.pop_front();
        }
        if tweaklast {
            let (c1, idx) = deq.pop_front().unwrap();
            deq.push_front((c1-c, idx));
        }
        dp[i] += total;
    }
    dp
}


fn main() {
    input! {
        n: usize,
        a: [i64; n]
    };

    let front = solve(a.clone());
    let mut a = a;
    for i in 0..n {
        a[i] *= 2;
    }
    a.reverse();
    let back = solve(a);

    // debug!(front,back);

    let mut best = INF;
    for f in 0..n {
        let take_f = n-f;
        let take_b = n-take_f;
        let b = n-take_b;

        best = min(best, 2 * (front[f] + back[b]) + (take_b as i64));
    }
    println!("{}", best);
}

