fn counts(a: &[usize]) -> Vec<usize> {
    let mut ss = vec![[None; 16]; a.len()];
    let mut rs = Vec::with_capacity(a.len() + 1);
    let mut cs = Vec::with_capacity(a.len());

    rs.push(0);
    rs.push(0);

    for i in 1..a.len() {
        cs.clear();
        let mut c = 0;
        let mut j = i;
        while j > 0 {
            let mut c_ext = 0;
            if c >= 16 {
                c_ext = c - 16 + 1;
                c -= c_ext;
            }

            if let Some(c_j) = ss[j][c] {
                c = c_j + c_ext * (j + 1);
                break;
            }
            cs.push((c, c_ext));

            let log = (a[j - 1] as f64 / a[j] as f64).log(4.0);
            if log >= 1.0 {
                c -= std::cmp::min(c, log as usize);
            }
            if log < 0.0 {
                c += (-log.floor()) as usize;
            }
            j -= 1;
        }
        while let Some((c_j, c_j_ext)) = cs.pop() {
            j += 1;
            ss[j][c_j] = Some(c + c_j);
            c += c_j + c_j_ext * (j + 1);
        }
        rs.push(c);
    }
    rs
}
fn solve(mut a: Vec<usize>) -> usize {
    let cs0 = counts(&a);
    a.reverse();
    let cs1 = counts(&a);

    (0..a.len())
        .map(|x| cs0[x] * 2 + x + cs1[a.len() - x] * 2)
        .min()
        .unwrap()
}

