fn count(a: &Vec<f64>) -> Vec<i64> {
    let mut last_num = a[0];
    let mut count = vec![0i64; a.len()];
    for i in 1..a.len() {
        let mut num = a[i];
        if num < last_num {
            let mut temp_inc = (last_num - num).ceil() as i64;
            if temp_inc % 2 == 1 {
                temp_inc += 1;
            }
            count[i] = temp_inc;
            num += temp_inc as f64;
        } else {
            count[i] = 0;
        }
        last_num = num;
    }
    count
}

