    let mut sum_sum_ans1 = vec![0i64; n];
    sum_sum_ans1[0] = sum_ans1[0];
    for i in 1..n {
        sum_sum_ans1[i] = sum_sum_ans1[i - 1] + sum_ans1[i];
    }
    // println!("{:?}", sum_sum_ans1);
    let mut sum_ans2 = vec![0i64; n];
    sum_ans2[0] = ans2[0];
    for i in 1..n {
        sum_ans2[i] = sum_ans2[i - 1] + ans2[i];
    }
    let mut sum_sum_ans2 = vec![0i64; n];
    sum_sum_ans2[0] = sum_ans2[0];
    for i in 1..n {
        sum_sum_ans2[i] = sum_sum_ans2[i - 1] + sum_ans2[i];
    }
    // println!("{:?}", sum_sum_ans2);
    let mut ans = std::cmp::min(sum_sum_ans1[n - 1], sum_sum_ans2[n - 1]);
    for i in 1..n - 1 {
        let mut temp_ans = sum_sum_ans1[n - 1] - sum_sum_ans1[i] * (n - i) as i64;
        // println!("{:?}", (sum_sum_ans1[n - 1], sum_sum_ans1[i], n - i));
        temp_ans += sum_ans2[n - 1] - sum_sum_ans2[n - i] * (i) as i64;
        // println!("{:?}", (sum_sum_ans2[n - 1], sum_sum_ans2[n - i], i));
        temp_ans += i as i64;
        // println!("temp_ans {:?}", temp_ans);
        ans = std::cmp::min(ans, temp_ans);
    }

    println!("{:?}", ans);
}

