fn solve(a: Vec<usize>) -> usize {
    let mut a0 = a.clone();
    let mut a1 = a;

    let mut c0 = Vec::new();
    let mut c = 0usize;
    c0.push(0);
    c += 1;
    c0.push(c);

    for i in 1..a0.len() {
        for j in (0..i).rev() {
            if a0[j] < a0[j + 1] {
                let x = a0[j + 1] / a0[j] / 4 + 1;
                a0[j] *= x;
                c += x * 2;
            }
        }
        c += 1;
        c0.push(c);
    }

    a1.reverse();

    let mut c1 = Vec::new();
    let mut c = 0usize;
    c1.push(0);
    c1.push(0);
    for i in 1..a1.len() {
        for j in (0..i).rev() {
            while a1[j] < a1[j + 1] {
                a1[j] *= 4;
                c += 2;
            }
        }
        c1.push(c);
    }
    c1.reverse();

    c0.iter().zip(c1.iter()).map(|x| x.0 + x.1).min().unwrap()
}

