fn count(aa: &Vec<u64>, n: usize) -> Vec<Vec<usize>> {
    let mut dp = vec![vec![0; 16]; n+1];
    for i in 0..16 {
        dp[n-1][i] = i;
    }
    for i in (0..n-1).rev() {
        for p in 0..16 {
            let a1 = aa[i]*4u64.pow(p as u32);
            let mut a2 = aa[i+1];
            let mut x = 0;
            while a2 < a1 {
                x += 1;
                a2 *= 4;
            }
            let p = p as usize;
            let x = x as usize;
            if x < 16 {
                dp[i][p] = dp[i+1][x] + p;
            } else {
                dp[i][p] = dp[i+1][15] + p + (x - 15) * (n-i-1);
            }
        }
    }
    dp
}

fn main() {
    input!{
      n: usize,
      aa: [u64; n],
    }

    let dp = count(&aa, n);
    let mut aa = aa;
    aa.reverse();
    let dp2 = count(&aa, n);

    let mut ans: usize = 1 << 60;
    for i in 0..n+1 {
        let c1 = dp[i][0] * 2;
        let c2 = dp2[n-i][0] * 2 + i;
        ans = min(c1+c2, ans);
    }
    println!("{}", ans);
}

use std::io::Read;

fn calc(a: &Vec<u64>) -> Vec<usize> {
    let n = a.len();
    let m = 15;
    let mut dp = vec![vec![0; n]; m + 1];
    for i in 0..(m + 1) {
        dp[i][n - 1] = 2 * i;
    }
    for i in (0..(n - 1)).rev() {
        let mut x = a[i];
        let mut y = a[i + 1];
        let mut k = 0;
        for j in 0..m {
            while x > y {
                k += 1;
                y *= 4;
            }
            if k <= m {
                dp[j][i] = dp[k][i + 1] + 2 * j;
            } else {
                dp[j][i] = dp[m][i + 1] + 2 * j + 2 * (k - m) * (n - 1 - i);
            }
            x *= 4;
        }
    }
    dp[0].clone()
}

fn run() {
