// How many operations are necessary to make a >= b?
// Or how many operations can you tolerate?
fn delta(a: i64, b: i64) -> i64 {
    if a < b {
        let mut a = a;
        let mut cnt = 0;
        while a < b { a *= 4; cnt += 1; }
        return cnt;
    }
    let mut b = b;
    let mut cnt = 0;
    while a >= b { b *= 4; cnt += 1; }
    return - (cnt - 1);
}

// dec
fn calc(a: &[i64]) -> Vec<i64> {
    let n = a.len();
    let mut dec = vec![0; n + 1];
    dec[1] = 0;
    let mut tot = 0;
    let mut block = vec![(0, -1i64 << 40)];
    for i in 1 .. n {
        //eprintln!("a[{}] = {} comes, prev tot = {}, block = {:?}", i, a[i], tot, block);
        let diff = delta(a[i - 1], a[i]);
        //eprintln!("diff = {}", diff);
        if diff < 0 {
            block.push((i, diff));
        } else {
            for _ in 0 .. diff {
                let (x, mut rem) = block.pop().unwrap();
                tot += (i - x) as i64;
                rem += 1;
                if rem < 0 { block.push((x, rem)); }
            }
        }
        dec[i + 1] = tot;
    }
    dec
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($format:expr) => (write!(out,$format).unwrap());
        ($format:expr, $($args:expr),+) => (write!(out,$format,$($args),*).unwrap())
    }
    input! {
        n: usize,
        a: [i64; n],
    }
    let mut a = a;
    // [0,i)
    let dec = calc(&a);
    a.reverse();
    // [i,n)
    let mut inc = calc(&a);
    inc.reverse();
    /*
    eprintln!("inc = {:?}", inc);
    eprintln!("dec = {:?}", dec);
     */
    let mut mi: i64 = 1 << 62;
    for i in 0 .. n {
        let tmp = i as i64 + 2 * (inc[i] + dec[i]);
        mi = min(mi, tmp);
    }
    puts!("{}\n", mi);
}

