fn f(a: usize, b: usize) -> (u32, u32) {
    if a <= b {
        let mut p = 0;
        while a*4usize.pow(p+1) <= b {
            p += 1;
        }
        (p, 0)
    } else {
        let mut p = 0;
        while a > b*4usize.pow(p) {
            p += 1;
        }
        (0, p)
    }
}

