fn do_neg(A: &[i64]) -> usize {
    let mut A = Vec::from(A);
    let mut k = 0;

    for a in A.iter_mut() {
        if *a > 0 {
            *a *= -2;
            k += 1;
        }
    }

    k
}

fn do_pos(A: &[i64]) -> usize {
    let mut prev = 0;
    let mut k = 0;
    for mut a in A.iter().cloned() {
        if a >= prev {
            prev = a;
            continue;
        }

        let mut h = 0;
        while a < prev {
            h += 2;
            a *= 4;
        }

        k += h;
        prev = a;
    }
    k
}

