fn calc(a: &Vec<u64>) -> Vec<usize> {
    let n = a.len();
    let m = 15;
    let mut dp = vec![vec![0; n]; m + 1];
    for i in 0..(m + 1) {
        dp[i][n - 1] = i;
    }
    for i in (0..(n - 1)).rev() {
        let mut x = a[i];
        let mut y = a[i + 1];
        let mut k = 0;
        for j in 0..m {
            while x > y {
                k += 1;
                y *= 4;
            }
            if j + k <= m {
                dp[j][i] = dp[j + k][i + 1] + k;
            } else {
                dp[j][i] = dp[m][i + 1] + (j + k - m) * (n - 1 - i);
            }
            x *= 4;
        }
    }
    dp[0].clone()
}

