fn construct_dp(a: &Vec<u64>) -> Vec<Vec<usize>> {
    let mut dp = vec![vec![0; 16]; a.len()];
    for i in 0..16 {
        dp[a.len() - 1][i] = i;
    }

    for i in (1..a.len()).rev() {
        for j in 0..16 {
            dp[i - 1][j] = j;

            let a1 = a[i - 1] * 4u64.pow(j as u32);
            let mut a2 = a[i];
            let mut inc: usize = 0;
            while a2 < a1 {
                inc += 1;
                a2 *= 4;
            }
            if inc > 15 {
                dp[i - 1][j] += (inc - 15) * (a.len() - i);
                inc = 15;
            }
            dp[i - 1][j] += dp[i][inc];
        }
    }
    dp
}

