#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn main() {
    input! {
        n: usize,
        a: [i64; n],
    }

    let fa = a.iter().map(|v| (*v as f64).log(4.0)).collect::<Vec<_>>();

    let mut lo = 0;
    let mut hi = n - 1;

    while (hi - lo) > 3 {
        let m1 = (lo * 2 + hi) / 3;
        let m2 = (lo + hi * 2) / 3;

        if calc(&fa, m1) < calc(&fa, m2) {
            hi = m2;
        } else {
            lo = m1;
        }
    }

    let mut ans = calc(&fa, lo);
    if lo + 1 < n {
        ans = std::cmp::min(ans, calc(&fa, lo + 1))
    }
    if lo + 2 < n {
        ans = std::cmp::min(ans, calc(&fa, lo + 2))
    }
    if lo + 3 < n {
        ans = std::cmp::min(ans, calc(&fa, lo + 3))
    }

    println!("{}", ans);
}

fn calc(fa: &[f64], i: usize) -> i64 {
    let n = fa.len();

    let mut ans = 0;

    let mut cur = fa[i];
    let mut minus = false;
    for j in (0..i).rev() {
        if !minus {
            if cur >= fa[j] {
                cur = fa[j];
                continue;
            }

            ans += 1;
            cur = fa[j] + 0.5;
            minus = true;
            continue;
        }

        ans += 1;
        let nn = fa[j] + 0.5;

        if cur <= nn {
            cur = nn;
            continue;
        }

        let inc = (cur - nn).ceil() as i64;
        ans += inc * 2;
        cur = nn + inc as f64;
    }

    let mut cur = fa[i];
    for j in (i + 1)..n {
        // println!("{}: {}", j, cur);

        if cur <= fa[j] {
            cur = fa[j];
            continue;
        }

        let inc = (cur - fa[j]).ceil() as i64;
        ans += inc * 2;
        cur = fa[j] + inc as f64;

        // println!("{}: inc = {}, cur = {}", j, inc, cur);
    }

    // println!("*** {}: {}", i, ans);

    ans
}

use std::io::Read;

fn calc(a: &Vec<u64>) -> Vec<usize> {
    let n = a.len();
    let m = 15;
    let mut dp = vec![vec![0; n]; m + 1];
    for i in 0..(m + 1) {
        dp[i][n - 1] = 2 * i;
    }
    for i in (0..(n - 1)).rev() {
        let mut x = a[i];
        let mut y = a[i + 1];
        let mut k = 0;
        for j in 0..(m + 1) {
            while x > y {
                k += 1;
                y *= 4;
            }
            if k <= m {
                dp[j][i] = dp[k][i + 1] + 2 * j;
            } else {
                dp[j][i] = dp[m][i + 1] + 2 * j + 2 * (k - m) * (n - 1 - i);
            }
            x *= 4;
        }
    }
    dp[0].clone()
}

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let mut a: Vec<u64> = (0..n).map(|_| it.next().unwrap().parse().unwrap()).collect();
    let x = calc(&a);
    a.reverse();
    let y = calc(&a);
    let mut ans = x[0];
    for i in 1..n {
        ans = std::cmp::min(ans, x[i] + y[n - i] + i);
    }
    println!("{}", ans);
}

fn main() {
    run();
}

