fn count1(x: usize, y: usize, base: usize) -> usize {
    let mut cnt = 0;
    let mut x = x;
    while x * base <= y {
        x *= base;
        cnt += 1;
    }
    cnt
}
fn count2(y: usize, x: usize, base: usize) -> usize {
    let mut cnt = 0;
    let mut x = x;
    while x < y {
        x *= base;
        cnt += 1;
    }
    cnt
}
