    for i in (0..n - 1).rev() {
        b[i] = b[i + 1];
        let k = count1(a[i], a[i + 1], 4) as i64;
        let m = stack.last().unwrap().0;
        if k > 0 {
            stack.push((m - k, 1));
        } else {
            let l = count2(a[i], a[i + 1], 4) as i64;
            let mut t = (m + l, 1);
            while let Some(u) = stack.pop() {
