        if !minus {
            if cur >= fa[j] {
                cur = fa[j];
            } else {
                ans += 1;
                cur = fa[j] + 0.5;
                minus = true;
            }
        } else {
            ans += 1;
            let nn = fa[j] + 0.5;

            if cur <= nn {
                cur = nn;
            } else {
                let inc = (cur - nn).ceil() as i64;
                ans += inc * 2;
                cur = nn + inc as f64;
            }
        }
    }

    let mut cur = fa[i];
    for j in (i + 1)..n {
        // println!("{}: {}", j, cur);

        if cur <= fa[j] {
            cur = fa[j];
        } else {
            let inc = (cur - fa[j]).ceil() as i64;
            ans += inc * 2;
            cur = fa[j] + inc as f64;
        }

        // println!("{}: inc = {}, cur = {}", j, inc, cur);
    }

    // println!("*** {}: {}", i, ans);

    ans
