    a.reverse();
    let dp_backward = construct_dp(&a);
    let mut ans = std::cmp::min(dp_forward[0][0] * 2, dp_backward[0][0] * 2 + a.len());

    for i in 1..n-1 {
        // println!("{:?}", dp_forward[i]);
        let tmp_ans = dp_forward[i][0] * 2 + i + dp_backward[n - i - 1][0] * 2;
        // println!("i {0} dp_forward[i][0] {1} dp_backward[n - i - 1][0] {2} {3}",
        //          i, dp_forward[i][0] * 2, dp_backward[n - i - 1][0] * 2, tmp_ans);
        ans = std::cmp::min(ans, tmp_ans);
    }

    println!("{:?}", ans);
}

use std::cmp;

const L: usize = 16;
const MAX_A: u64 = 1 << 32;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let n: usize = sc.read();
    let mut a: Vec<usize> = sc.vec(n);

    let dp1 = solve(&a);
    a.reverse();
    let dp2 = solve(&a);

    let mut cost = 1 << 50;
    for prefix in 0..(n + 1) {
        let prefix_cost = if prefix > 0 {
            dp1[prefix - 1][0] * 2 + prefix
        } else {
            0
        };
        let suffix_cost = if prefix < n {
            dp2[n - 1 - prefix][0] * 2
        } else {
            0
        };
        cost = cmp::min(prefix_cost + suffix_cost, cost);
    }

    println!("{}", cost);
}

fn solve(a: &Vec<usize>) -> Vec<Vec<usize>> {
    let n = a.len();
    let mut dp = vec![vec![0; L]; n];
    for i in 0..L {
        dp[0][i] = i;
    }
    for i in 1..n {
        let mut cur = 1;
        let mut prev_l = 0;
        let mut prev_a = a[i - 1];
        for l in 0..L {
            let cur_a = cur * a[i];
            while prev_a < cur_a {
                prev_a *= 4;
                prev_l += 1;
            }
            if prev_l >= L {
                dp[i][l] = dp[i - 1][L - 1] + i * (prev_l - (L - 1)) + l;
            } else {
                dp[i][l] = dp[i - 1][prev_l] + l;
            }
            cur *= 4;
        }
    }
    dp
}

